var ND=Object.assign(typeof ND==="undefined"?{}:ND,{"2610-21":{"voc":[{"q":"…consider what the rate of interest does to people's <u>perception</u> of time.","ask":"perception의 뜻으로 알맞은 것은?","ch":["이자, 이율","위험, 위기","상환, 갚음","소비, 지출","인식, 지각"],"a":4,"why":"perception = 인식, 지각 (어떤 것을 받아들여 이해하는 일). 동사 perceive(인식하다)의 명사형.\n지문: people's perception of time = 시간에 대한 사람들의 인식.\n이자율이 사람들이 시간을 바라보는 눈을 바꾼다는 글의 출발점.","e":"같은 1년인데 돈을 빌린 사람과 빌려준 사람이 서로 다르게 느끼는 것.","tr":"돈을 빌리고 빌려주는 일이 어떻게 한 사람의 세계관을 바꾸는지 알아보기 위해, 이자율이 시간에 대한 사람들의 인식에 무슨 일을 하는지 생각해 보라.","alt":"awareness (인식), understanding (이해)"},{"q":"This rate tells us that the money lent has a cost that <u>reflects</u> the risk of you not being repaid…","ask":"reflects의 뜻으로 알맞은 것은?","ch":["거부하다","빌려주다","계산을 틀리다","줄이다","반영하다, 나타내다"],"a":4,"why":"reflect = 반영하다, 나타내다 (거울처럼 어떤 모습을 그대로 보여 주다). 지문의 reflects는 3인칭 단수 -s가 붙은 형태.\n지문: a cost that reflects the risk = 위험을 반영하는 대가.\n이자는 ‘못 받을 위험’을 값으로 나타낸 것이라는 뜻.","e":"거울이 내 얼굴을 그대로 비추듯, 위험의 크기가 이자에 그대로 담기는 것.","tr":"이 이자율은 빌려준 돈이 여러분이 상환받지 못할 위험과 그 돈을 직접 소비하지 않는 기회비용을 반영하는 대가를 가진다는 것을 우리에게 말해 준다.","alt":"show (보여 주다), mirror (반영하다) / 반의어 hide (숨기다)"},{"q":"In order to make this <u>worthwhile</u> for the lender, money has to have a price…","ask":"worthwhile과 바꿔 쓸 수 있는 말은?","ch":["careless","harmful","temporary","impossible","valuable"],"a":4,"why":"worthwhile = 가치 있는, 할 만한 (= valuable). 시간·돈을 들일 만하다는 뜻.\n지문: make this worthwhile for the lender = 빌려준 사람에게 이것을 가치 있게 만들다.\ncareless = 부주의한, harmful = 해로운, temporary = 일시적인, impossible = 불가능한이라 뜻이 다름.","e":"공부한 만큼 점수가 나와서 시간을 쓴 보람이 있는 상태.","tr":"돈을 빌려준 사람에게 이것을 가치 있게 만들기 위해서, 빌린 사람에게는 대가이고 빌려준 사람에게는 수입인 비용을 돈이 가져야만 한다.","alt":"rewarding (보람 있는), beneficial (이로운)"},{"q":"…further into the future ― which by definition is <u>unknowable</u> ―…","ask":"unknowable의 뜻으로 알맞은 것은?","ch":["믿을 수 없는","알 수 없는","용서할 수 없는","피할 수 없는","셀 수 없는"],"a":1,"why":"unknowable = know(알다) + able(~할 수 있는) 앞에 un-(아니다)이 붙어 ‘알 수 없는’.\n지문: the future, which by definition is unknowable = 정의상 알 수 없는 미래.\n미래는 아직 안 일어났으니 확실히 알 수 없다는 말.","e":"내일 시험 문제를 오늘 미리 알 수 없는 것과 같음.","tr":"대출 기간이 길어질수록, 상환을 못 받을 가능성이 더 높아지는데, 정의상 알 수 없는 더 먼 미래의 일이 되기 때문이며, 여러분이 그 돈을 직접 소비하기 전까지 더 오래 기다려야 할 것이다.","alt":"unpredictable (예측할 수 없는) / 반의어 knowable (알 수 있는)"},{"q":"…money has to have a price ― a cost to the borrower and <u>income</u> to the lender.","ask":"income의 반의어로 알맞은 것은?","ch":["salary (월급)","profit (이익)","expense (지출)","earnings (소득)","revenue (수입)"],"a":2,"why":"income = 수입, 소득 ↔ expense = 지출, 비용.\nsalary = 월급, profit = 이익, earnings = 소득, revenue = 수입이라 모두 ‘들어오는 돈’ 쪽의 말.\n지문: a cost to the borrower and income to the lender = 빌린 사람에게는 비용, 빌려준 사람에게는 수입.","e":"용돈으로 들어오는 돈이 income, 쓰고 나가는 돈이 expense.","tr":"돈을 빌려준 사람에게 이것을 가치 있게 만들기 위해서, 빌린 사람에게는 대가이고 빌려준 사람에게는 수입인 비용을 돈이 가져야만 한다.","alt":"earnings (소득), revenue (수입) / 반의어 expense, expenditure (지출)"},{"q":"“the possibility that something bad will happen”","ask":"위 영영풀이에 해당하는 단어는?","ch":["income","price","term","risk","value"],"a":3,"why":"risk = 위험 (나쁜 일이 일어날 가능성).\n지문: the risk of you not being repaid = 여러분이 상환받지 못할 위험.\nincome = 수입, price = 가격, term = 기간, value = 가치라 풀이와 맞지 않음.","e":"돈을 빌려줬는데 못 돌려받을 수도 있다는 걱정.","tr":"이 이자율은 빌려준 돈이 여러분이 상환받지 못할 위험과 그 돈을 직접 소비하지 않는 기회비용을 반영하는 대가를 가진다는 것을 우리에게 말해 준다.","alt":"danger (위험), chance (가능성), hazard (위험 요소)"},{"q":"The longer the <u>term</u> of the loan, the higher the chance you won't be paid back…","ask":"이 글에서 밑줄 친 term의 뜻으로 가장 알맞은 것은?","ch":["기간","용어","학기","조건","관계"],"a":0,"why":"term은 다의어. 여기서는 ‘기간’ (the term of the loan = 대출 기간).\n다른 뜻: 용어(a technical term), 학기(school term), 조건(terms and conditions).\n지문: The longer the term of the loan = 대출 기간이 길수록.","e":"‘학기’ 말고 ‘돈을 빌린 기간’을 뜻함.","tr":"대출 기간이 길어질수록, 상환을 못 받을 가능성이 더 높아지는데, 정의상 알 수 없는 더 먼 미래의 일이 되기 때문이며, 여러분이 그 돈을 직접 소비하기 전까지 더 오래 기다려야 할 것이다.","alt":"period (기간), duration (지속 기간) / 다의어 용어, 학기, 조건"}],"find":[{"s":"The writer asks you to imagine lending money at an interest rate of 10 percent per year for five years.","a":true,"why":"2문장: 연 10퍼센트의 이자율로 5년 동안 돈을 빌려준다고 상상해 보라고 함.","e":"숫자를 넣어서 쉽게 상상해 보게 하는 예."},{"s":"The interest rate reflects only the risk of not being repaid.","a":false,"why":"3문장: 이자는 상환받지 못할 위험과 기회비용, 이 두 가지를 반영함. ‘only(오직)’는 틀림.","e":"위험만이 아니라 ‘그 돈을 내가 못 쓰는 손해’도 값에 들어 있음."},{"s":"The money you lend has an opportunity cost because you cannot spend it yourself.","a":true,"why":"3문장: the opportunity cost of not spending that money yourself (그 돈을 직접 소비하지 않는 기회비용).","e":"빌려주면 그 돈으로 내가 뭔가를 사지 못함."},{"s":"The shorter the term of the loan, the higher the chance you won't be paid back.","a":false,"why":"4문장: The longer the term(기간이 길수록) 못 받을 가능성이 높아짐. 짧을수록이라는 말은 반대.","e":"먼 미래일수록 무슨 일이 생길지 더 모름."},{"s":"A longer loan means you must wait longer before spending the money yourself.","a":true,"why":"4문장: the longer you will have to wait before spending the money yourself (돈을 직접 쓰기 전까지 더 오래 기다려야 함).","e":"빌려준 기간만큼 내 돈을 못 씀."},{"s":"For the lender to benefit, money has to have a price.","a":true,"why":"5문장: In order to make this worthwhile for the lender, money has to have a price (빌려준 사람에게 가치 있게 만들려면 돈에 값이 있어야 함).","e":"값이 없으면 빌려줄 이유가 없음."},{"s":"The price of money is income to the borrower and a cost to the lender.","a":false,"why":"5문장: a cost to the borrower and income to the lender. 빌린 사람에게는 비용, 빌려준 사람에게는 수입이라 반대로 말함.","e":"이자는 빌린 사람이 내고, 빌려준 사람이 받음."},{"s":"The price of money takes the value of time into account.","a":true,"why":"6문장: This price factors in the value of time (이 비용은 시간의 가치를 감안함).","e":"기다린 시간이 값으로 계산되어 있음."},{"s":"The future is easy to know, so lending for a long time carries no risk.","a":false,"why":"4문장: further into the future ― which by definition is unknowable (미래는 정의상 알 수 없음). 그래서 오래 빌려줄수록 위험이 커짐.","e":"알 수 없는 미래에는 위험이 있음."},{"s":"The writer says a bird in the bush is worth more than a bird in the hand.","a":false,"why":"7문장: a bird in the hand is worth two in the bush (손 안의 새 한 마리가 덤불 속 두 마리만큼의 가치). 지금 가진 것이 더 확실하다는 뜻이라 반대로 말함.","e":"지금 손에 쥔 것이 더 믿을 만하다는 속담."}],"eob":[{"s":"This rate tells us that the money ( ______ ) has a cost that reflects the risk of you not being repaid.","ch":["lending","lent"],"a":1,"why":"the money와 lend(빌려주다)는 “돈이 빌려주어지다”라는 수동 관계이므로 과거분사 lent. 현재분사 lending은 ‘돈이 스스로 빌려준다’는 뜻이 되어 어색함.","tr":"이 이자율은 빌려준 돈이 여러분이 상환받지 못할 위험과 그 돈을 직접 소비하지 않는 기회비용을 반영하는 대가를 가진다는 것을 우리에게 말해 준다.","g":"명사 뒤에서 “~된, ~해진”이라고 꾸밀 때 수동 관계면 과거분사(-ed)를 써요. 능동이면 -ing를 써요.\n여기서 돈은 빌려주어지는 쪽이니 lent예요.\n예) the book written by him (그가 쓴 책)"},{"s":"This rate tells us that the money lent has a cost that reflects the risk of you not ( ______ ) repaid.","ch":["being","been"],"a":0,"why":"‘상환받지 못할 위험’은 of 뒤의 동명사 수동태 not being repaid. 부정은 동명사 앞에 not을 둠. been은 have 뒤에서만 쓰이므로 여기서는 안 됨.","tr":"이 이자율은 빌려준 돈이 여러분이 상환받지 못할 위험과 그 돈을 직접 소비하지 않는 기회비용을 반영하는 대가를 가진다는 것을 우리에게 말해 준다.","g":"전치사 뒤에는 동명사(-ing)를 써요. 수동이면 being + 과거분사, 부정이면 앞에 not을 붙여요.\n예) I'm afraid of not being invited. (나는 초대받지 못할까 봐 걱정이다.)"},{"s":"The longer the term of the loan, the ( ______ ) the chance you won't be paid back.","ch":["highest","higher"],"a":1,"why":"‘The 비교급 ~, the 비교급 ~’ (~할수록 더 …하다) 구문이라 둘 다 비교급. 앞이 the longer이므로 뒤도 the higher. 최상급 highest는 안 됨.","tr":"대출 기간이 길어질수록, 상환을 못 받을 가능성이 더 높아지는데, 정의상 알 수 없는 더 먼 미래의 일이 되기 때문이며, 여러분이 그 돈을 직접 소비하기 전까지 더 오래 기다려야 할 것이다.","g":"‘~할수록 더 …하다’는 The + 비교급 ~, the + 비교급 … 모양이에요. 두 곳 모두 비교급이어야 해요.\n예) The more you read, the smarter you become. (더 많이 읽을수록 더 똑똑해진다.)"},{"s":"…and the longer you will have to wait before ( ______ ) the money yourself.","ch":["spend","spending"],"a":1,"why":"before는 전치사로도 쓰여 뒤에 동명사(-ing)가 옴. 그래서 before spending. 동사원형 spend는 올 수 없음.","tr":"대출 기간이 길어질수록, 상환을 못 받을 가능성이 더 높아지는데, 정의상 알 수 없는 더 먼 미래의 일이 되기 때문이며, 여러분이 그 돈을 직접 소비하기 전까지 더 오래 기다려야 할 것이다.","g":"before, after, without 같은 전치사 뒤에는 동사원형이 아니라 동명사(-ing)를 써요.\n예) Wash your hands before eating. (먹기 전에 손을 씻어라.)"}],"awk":[{"t":"Imagine you are [[1|lending]] to somebody at an interest rate of 10 percent per year for five years. This rate tells us that the money lent has a [[2|cost]] that reflects the [[3|safety]] of you not being repaid and the [[4|opportunity]] cost of not [[5|spending]] that money yourself.","a":3,"fix":"risk","why":"원문은 risk (위험). 상환받지 못할 ‘위험’을 이자가 반영한다는 흐름이다.\nsafety (안전)이면 ‘상환받지 못할 안전’이 되어 말이 안 되고, 이자가 붙는 이유도 설명되지 않는다.","sp":[{"b":"lending","m":"빌려주는 중인","n":"you are lending = 현재진행형","y":"맞음. 누군가에게 돈을 빌려주는 상황을 상상하는 문장.","e":"내가 친구에게 돈을 빌려주는 장면."},{"b":"cost","m":"대가, 비용","n":"a cost = 돈을 빌려준 것에 붙는 값","y":"맞음. 이자가 곧 돈의 대가다.","e":"물건에 가격이 붙는 것처럼 돈에도 값이 붙음."},{"b":"safety","m":"안전","n":"","y":"어색함. 원문은 risk. 상환받지 못할 ‘안전’이라는 말은 성립하지 않는다.","e":"못 받을 위험이 있으니 이자를 받는 것."},{"b":"opportunity","m":"기회","n":"opportunity cost = 기회비용","y":"맞음. 그 돈을 직접 쓰지 못해 놓치는 기회의 값.","e":"돈을 빌려줘서 내가 뭘 못 사게 되는 손해."},{"b":"spending","m":"쓰는 것","n":"not spending = 전치사 of 뒤 동명사의 부정","y":"맞음. 그 돈을 직접 쓰지 않는 것.","e":"빌려줬으니 내가 쓸 수 없는 상태."}]},{"t":"The [[1|longer]] the term of the loan, the [[2|lower]] the chance you won't be paid back because it is further into the [[3|future]] ― which by definition is [[4|unknowable]] ― and the longer you will have to [[5|wait]] before spending the money yourself.","a":2,"fix":"higher","why":"원문은 higher (더 높은). 기간이 길수록 먼 미래가 되어 알 수 없으므로, 상환받지 못할 가능성이 ‘더 높아진다’는 흐름이다.\nlower (더 낮은)이면 뒤의 because 이유(먼 미래는 알 수 없다)와 모순된다.","sp":[{"b":"longer","m":"더 긴","n":"The longer ~, the 비교급 ~ 구문","y":"맞음. 대출 기간이 길수록이라는 뜻.","e":"오래 빌려줄수록."},{"b":"lower","m":"더 낮은","n":"","y":"어색함. 원문은 higher. 먼 미래는 알 수 없어서 오히려 못 받을 가능성이 높아진다.","e":"먼 약속일수록 지켜질지 더 불안함."},{"b":"future","m":"미래","n":"further into the future = 더 먼 미래로","y":"맞음. 기간이 길면 그만큼 먼 미래가 된다.","e":"내일보다 10년 뒤가 더 불확실."},{"b":"unknowable","m":"알 수 없는","n":"which = 앞 내용 전체(미래)를 받는 관계대명사","y":"맞음. 정의상 미래는 알 수 없다.","e":"아직 일어나지 않은 일."},{"b":"wait","m":"기다리다","n":"have to wait = 기다려야 한다","y":"맞음. 돈을 쓰기까지 더 오래 기다린다.","e":"내 돈이 돌아올 때까지 참는 것."}]},{"t":"In order to make this [[1|worthwhile]] for the lender, money has to have a [[2|price]] ― a cost to the borrower and [[3|loss]] to the lender. This price [[4|factors]] in the [[5|value]] of time.","a":3,"fix":"income","why":"원문은 income (수입). 빌려준 사람에게 가치가 있으려면 그에게는 ‘수입’이 되어야 한다.\nloss (손해)이면 앞의 worthwhile for the lender(빌려준 사람에게 가치 있게)와 모순된다.","sp":[{"b":"worthwhile","m":"가치 있는","n":"make A worthwhile = A를 가치 있게 만들다","y":"맞음. 빌려준 사람에게 보람이 있어야 한다는 뜻.","e":"빌려주고도 이득이 있어야 함."},{"b":"price","m":"값, 대가","n":"money has a price = 돈에 값이 있다","y":"맞음. 돈을 빌리는 대가가 이자다.","e":"물건 값처럼 돈에도 값."},{"b":"loss","m":"손해","n":"","y":"어색함. 원문은 income. 빌려준 사람이 손해를 본다면 ‘가치 있게’ 만든다는 앞말과 맞지 않는다.","e":"이자는 빌려준 사람의 수입."},{"b":"factors","m":"감안하다","n":"factor in = 요소로 넣어 계산하다 (3인칭 단수 -s)","y":"맞음. 값에 시간의 가치를 넣어 계산한다.","e":"기다린 시간을 값에 더함."},{"b":"value","m":"가치","n":"the value of time = 시간의 가치","y":"맞음. 이 글의 핵심 어구.","e":"시간도 돈처럼 값이 있음."}]}],"und":[{"q":"<u>a bird in the hand is worth two in the bush</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["새를 기르는 사람은 돈을 더 잘 번다","지금 확실히 가진 돈이 나중에 받을지 모르는 돈보다 가치가 크다","덤불 속에서 새를 찾는 것이 가장 쉬운 투자다","나중에 받는 돈은 항상 두 배로 불어난다","빌려준 돈은 많이 빌려줄수록 안전해진다"],"a":1,"why":"앞 내용: 돈에는 값이 있고, 그 값에는 시간의 가치가 들어 있음.\n속담: 손 안의 새 한 마리 = 지금 확실히 가진 것, 덤불 속 두 마리 = 나중에 얻을지 모르는 것.\n결론: 확실한 지금의 돈이 불확실한 미래의 돈보다 낫다는 뜻.","e":"오늘 받는 용돈 1만 원이 내년에 받을지도 모르는 1만 원보다 믿을 만한 것.","tr":"달리 말하면, 손 안의 새 한 마리가 덤불 속의 두 마리만큼의 가치가 있다."},{"q":"<u>This price factors in the value of time.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["돈의 값은 시간이 지나면 저절로 사라진다","돈의 값(이자)에는 기다려야 하는 시간의 가치까지 들어 있다","이자는 시간과 상관없이 정해진다","시간이 길수록 빌려준 사람이 돈을 더 쓰게 된다","시간을 파는 사람은 돈을 빌릴 수 없다"],"a":1,"why":"앞 내용: 빌려준 사람에게 가치가 있으려면 돈에 값(이자)이 있어야 함.\nfactor in = 요소로 넣어 계산하다.\n결론: 이자에는 오래 기다리는 시간의 값도 포함됨.","e":"택배를 오래 기다릴수록 배송료를 더 내는 것처럼 시간이 값에 들어간다는 느낌.","tr":"이 비용은 시간의 가치를 감안한다."},{"q":"<u>the opportunity cost of not spending that money yourself</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["그 돈을 쓰지 않아서 생기는 세금","빌린 사람이 돈을 쓰면서 지는 책임","그 돈을 내가 쓰지 못해서 놓치게 되는 이익이나 즐거움","돈을 아껴서 저금통에 모으는 즐거움","그 돈을 잃어버릴 위험"],"a":2,"why":"앞 내용: 이자는 상환받지 못할 위험과 또 하나의 대가를 반영함.\nopportunity cost = 어떤 것을 선택해서 포기하게 되는 다른 기회의 값.\n결론: 빌려주는 동안 내가 그 돈으로 할 수 있었던 일을 못 하는 손해.","e":"빌려준 돈으로 갖고 싶던 게임을 못 사게 되는 아쉬움.","tr":"이 이자율은 빌려준 돈이 여러분이 상환받지 못할 위험과 그 돈을 직접 소비하지 않는 기회비용을 반영하는 대가를 가진다는 것을 우리에게 말해 준다."},{"q":"<u>which by definition is unknowable</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["미래는 정의를 내리면 누구나 알 수 있다","먼 미래는 계산하면 정확히 알 수 있다","과거는 정의하기 어려워서 알 수 없다","미래를 아는 사람은 정의상 존재하지 않는다고 단정할 수 있다","미래는 아직 일어나지 않았으므로 그 자체로 미리 알 수가 없다"],"a":4,"why":"앞 내용: 기간이 길수록 더 먼 미래가 됨.\nby definition = 정의상, 그 말 자체로.\n결론: ‘미래’라는 말의 뜻 자체가 아직 일어나지 않은 일이라 알 수 없음. 그래서 위험이 커짐.","e":"내일 로또 번호는 말뜻 그대로 오늘 알 수 없는 것과 같음.","tr":"대출 기간이 길어질수록, 상환을 못 받을 가능성이 더 높아지는데, 정의상 알 수 없는 더 먼 미래의 일이 되기 때문이며, 여러분이 그 돈을 직접 소비하기 전까지 더 오래 기다려야 할 것이다."}]},"2610-22":{"voc":[{"q":"This includes <u>addressing</u> topics such as climate change, social justice, and ethical consumerism…","ask":"이 글에서 밑줄 친 address의 뜻으로 가장 알맞은 것은?","ch":["주소를 쓰다","거절하다","숨기다","무시하다","(문제·주제를) 다루다"],"a":4,"why":"address는 다의어. 여기서는 ‘(문제·주제를) 다루다’. 지문의 addressing은 동사 address에 -ing가 붙은 동명사.\n다른 뜻: 주소, 연설하다.\n지문: addressing topics such as climate change = 기후 변화 같은 주제를 다루는 것.","e":"시험 문제를 피하지 않고 정면으로 다루는 것.","tr":"이것은 그들의 콘텐츠에서 기후 변화, 사회 정의, 그리고 윤리적 소비주의와 같은 주제들을 다루는 것을 포함한다.","alt":"deal with (다루다), tackle (맞붙어 해결하다) / 다의어 주소, 연설하다"},{"q":"As global <u>awareness</u> of social, environmental, and sustainability issues grows…","ask":"awareness의 뜻으로 알맞은 것은?","ch":["책임","인식, 의식","지속","영향","평등"],"a":1,"why":"awareness = 인식, 의식 (어떤 일을 알고 있는 상태). 형용사 aware(알고 있는)의 명사형.\n지문: global awareness of ~ issues = ~ 문제들에 대한 전 세계적인 인식.\n이 인식이 커져서 제작자들에게 책임이 요구된다는 흐름.","e":"쓰레기 문제가 심각하다는 걸 많은 사람이 알게 되는 것.","tr":"사회적, 환경적, 그리고 지속가능성 문제들에 대한 전 세계적인 인식이 커짐에 따라, 많은 콘텐츠 제작자들은 자신의 작업의 더 폭넓은 영향력을 고려하도록 요구받고 있다.","alt":"consciousness (의식), recognition (인식) / 반의어 ignorance (무지)"},{"q":"…a platform that can <u>influence</u> their audience's attitudes and behaviors…","ask":"influence와 바꿔 쓸 수 있는 말(동사)은?","ch":["ignore","protect","affect","repeat","escape"],"a":2,"why":"influence = 영향을 미치다 (= affect).\n지문: influence their audience's attitudes = 청중의 태도에 영향을 미치다.\nignore = 무시하다, protect = 보호하다, repeat = 반복하다, escape = 달아나다라 뜻이 다름.","e":"인기 유튜버가 쓴 물건이 갑자기 유행하는 것처럼 남에게 영향을 주는 일.","tr":"콘텐츠 제작자들은 자신의 청중의 태도와 행동에 영향을 미칠 수 있는 플랫폼을 가지고 있으며, 그들은 그 플랫폼을 긍정적인 변화를 위해 사용할 책임을 지닌다.","alt":"affect (영향을 주다), sway (좌우하다)"},{"q":"<u>Promoting</u> environmentally sustainable products… can help raise awareness…","ask":"promote의 뜻으로 알맞은 것은?","ch":["포기하다","홍보하다, 촉진하다","금지하다","비교하다","빌려주다"],"a":1,"why":"promote = 홍보하다, 촉진하다 (더 많이 알려지고 퍼지게 하다). 지문의 Promoting은 동명사.\n지문: Promoting environmentally sustainable products = 환경적으로 지속가능한 제품을 홍보하는 것.\n좋은 것을 널리 알려 인식을 높이는 행동.","e":"좋은 책을 친구들에게 널리 소개하는 것.","tr":"예를 들어, 환경적으로 지속가능한 제품들을 홍보하거나 평등과 정의에 관련된 대의명분을 지지하는 것은 인식을 높이고 의미 있는 사회적 영향을 이끌어 내는 것을 도울 수 있다.","alt":"advertise (광고하다), publicize (알리다), encourage (장려하다)"},{"q":"…<u>environmentally sustainable</u> products…","ask":"sustainable의 뜻으로 알맞은 것은?","ch":["가격이 싼","지속 가능한","위험한","유행하는","일시적인"],"a":1,"why":"sustainable = 지속 가능한 (환경을 해치지 않고 오래 이어 갈 수 있는). 동사 sustain(유지하다)에서 온 말.\n지문: environmentally sustainable products = 환경적으로 지속 가능한 제품.\n글 앞부분의 sustainability(지속가능성)와 같은 계열의 낱말.","e":"한 번 쓰고 버리지 않고 오래 쓸 수 있는 텀블러 같은 것.","tr":"예를 들어, 환경적으로 지속가능한 제품들을 홍보하거나 평등과 정의에 관련된 대의명분을 지지하는 것은 인식을 높이고 의미 있는 사회적 영향을 이끌어 내는 것을 도울 수 있다.","alt":"eco-friendly (친환경적인), renewable (재생 가능한) / 반의어 unsustainable (지속 불가능한)"},{"q":"…supporting causes related to <u>equality</u> and justice…","ask":"equality의 반의어로 알맞은 것은?","ch":["justice (정의)","fairness (공정함)","inequality (불평등)","balance (균형)","harmony (조화)"],"a":2,"why":"equality = 평등 ↔ inequality = 불평등.\njustice = 정의, fairness = 공정함, balance = 균형, harmony = 조화라 모두 좋은 쪽의 말.\n지문: causes related to equality and justice = 평등과 정의에 관련된 대의명분.","e":"모두에게 같은 기회가 주어지는 것이 equality.","tr":"예를 들어, 환경적으로 지속가능한 제품들을 홍보하거나 평등과 정의에 관련된 대의명분을 지지하는 것은 인식을 높이고 의미 있는 사회적 영향을 이끌어 내는 것을 도울 수 있다.","alt":"fairness (공정함), parity (동등함) / 반의어 inequality, discrimination (차별)"},{"q":"…ensuring that their content <u>aligns</u> with their social and environmental principles.","ask":"align의 뜻으로 알맞은 것은?","ch":["싸우다","떠나다","숨기다","일치하다, 나란히 맞추다","앞서다"],"a":3,"why":"align (with) = ~와 일치하다, 나란히 맞추다. 지문의 aligns는 3인칭 단수 -s가 붙은 형태.\n지문: content aligns with principles = 콘텐츠가 원칙과 일치하다.\n말하는 것과 믿는 가치가 어긋나지 않게 맞춘다는 뜻.","e":"줄을 반듯하게 맞춰 서듯이 행동과 가치관을 같은 방향에 두는 것.","tr":"윤리적인 콘텐츠 제작자들은 자신의 제품이나 서비스를 홍보하는 데만 초점을 맞추는 것이 아니라, 자신이 지지하는 가치와 대의명분도 고려하며, 자신의 콘텐츠가 자신의 사회적 그리고 환경적 원칙과 반드시 일치하게 한다.","alt":"match (일치하다), agree (맞다) / 반의어 conflict (충돌하다)"},{"q":"Content creators have a <u>platform</u> that can influence their audience's attitudes and behaviors…","ask":"이 글에서 밑줄 친 platform의 뜻으로 가장 알맞은 것은?","ch":["기차 승강장","신발 굽","컴퓨터 부품","(생각을 널리 알리는) 발표의 장, 매체","연료 저장소"],"a":3,"why":"platform은 다의어. 여기서는 ‘생각이나 콘텐츠를 많은 사람에게 알리는 장, 매체’.\n다른 뜻: 기차 승강장, 높은 단.\n지문: a platform that can influence their audience = 청중에게 영향을 줄 수 있는 매체.","e":"구독자 수만 명이 보는 채널 자체가 큰 무대인 셈.","tr":"콘텐츠 제작자들은 자신의 청중의 태도와 행동에 영향을 미칠 수 있는 플랫폼을 가지고 있으며, 그들은 그 플랫폼을 긍정적인 변화를 위해 사용할 책임을 지닌다.","alt":"stage (무대), outlet (표현 수단) / 다의어 승강장, 연단"}],"find":[{"s":"Social and environmental responsibility has become more important for content creators.","a":true,"why":"1문장: 사회적·환경적 책임이 콘텐츠 제작자들에게 점점 더 중요한 윤리적 고려 사항이 되어 옴.","e":"책임이 갈수록 큰 숙제가 되는 중."},{"s":"As global awareness of these issues grows, creators feel less pressure to think about their impact.","a":false,"why":"2문장: 인식이 커짐에 따라 제작자들은 작업의 영향을 고려하도록 ‘요구받고’ 있음. 압박이 줄어든다는 말은 반대.","e":"사람들이 더 알수록 제작자에게 더 많이 요구함."},{"s":"Many content creators are being asked to consider the broader impact of their work.","a":true,"why":"2문장: are being called upon to consider the broader impact of their work (작업의 더 폭넓은 영향력을 고려하도록 요구받고 있음).","e":"내 영상이 세상에 끼치는 영향까지 생각하라는 요구."},{"s":"The topics creators should address are limited to entertainment trends.","a":false,"why":"3문장: 기후 변화, 사회 정의, 윤리적 소비주의 같은 주제를 다루는 것을 포함함. 연예·유행에 한정되지 않음.","e":"사회와 환경 이야기까지 포함됨."},{"s":"Content creators have a platform that can influence their audience.","a":true,"why":"4문장: a platform that can influence their audience's attitudes and behaviors (청중의 태도와 행동에 영향을 줄 수 있는 플랫폼).","e":"영상 하나가 사람들의 생각을 바꿀 수 있음."},{"s":"Creators have a platform but no responsibility to use it for positive change.","a":false,"why":"4문장: they have a responsibility to use that platform for positive change (그 플랫폼을 긍정적인 변화에 쓸 책임이 있음).","e":"영향력이 있는 만큼 책임도 있음."},{"s":"Promoting environmentally sustainable products can help raise awareness.","a":true,"why":"5문장: promoting environmentally sustainable products ~ can help raise awareness (환경적으로 지속가능한 제품을 홍보하는 것이 인식을 높이는 데 도움이 될 수 있음).","e":"친환경 제품을 널리 알리면 사람들이 더 알게 됨."},{"s":"Supporting causes related to equality and justice cannot create meaningful social impact.","a":false,"why":"5문장: supporting causes related to equality and justice can help ~ drive meaningful social impact (평등과 정의에 관련된 대의명분을 지지하는 것은 의미 있는 사회적 영향을 이끌어 내는 것을 도울 수 있음).","e":"대의명분을 지지하면 사회가 달라질 수 있음."},{"s":"Ethical content creators also consider the values and causes they support.","a":true,"why":"6문장: not only focus on promoting their products ~ but also consider the values and causes they support (제품 홍보에만 집중하지 않고 자신이 지지하는 가치와 대의명분도 고려함).","e":"판매만이 아니라 ‘무엇을 지지하는가’도 생각함."},{"s":"Ethical creators keep their content separate from their social and environmental principles.","a":false,"why":"6문장: ensuring that their content aligns with their social and environmental principles (콘텐츠가 원칙과 일치하도록 함). 분리한다는 말은 반대.","e":"말과 행동이 같아야 윤리적."}],"eob":[{"s":"Content creators have a platform ( ______ ) can influence their audience's attitudes and behaviors.","ch":["that","what"],"a":0,"why":"앞의 a platform(선행사)을 꾸미고 뒤에 동사 can influence의 주어가 없으므로 주격 관계대명사 that. what은 선행사를 포함하는 관계대명사라 앞에 명사(platform)가 있을 때는 쓸 수 없음.","tr":"콘텐츠 제작자들은 자신의 청중의 태도와 행동에 영향을 미칠 수 있는 플랫폼을 가지고 있으며, 그들은 그 플랫폼을 긍정적인 변화를 위해 사용할 책임을 지닌다.","g":"명사 뒤에서 그 명사를 꾸미는 관계대명사는 who, which, that이에요. what은 앞에 꾸밀 명사가 없을 때만 써요.\n예) I have a friend that lives in Busan. (나는 부산에 사는 친구가 있다.)"},{"s":"As global awareness of social, environmental, and sustainability issues ( ______ ), many content creators are being called upon to consider the broader impact of their work.","ch":["grows","grow"],"a":0,"why":"주어는 awareness(단수)이고 of ~ issues는 수식어. 그래서 단수 동사 grows. 바로 앞의 issues(복수)에 끌려 grow를 쓰면 틀림.","tr":"사회적, 환경적, 그리고 지속가능성 문제들에 대한 전 세계적인 인식이 커짐에 따라, 많은 콘텐츠 제작자들은 자신의 작업의 더 폭넓은 영향력을 고려하도록 요구받고 있다.","g":"주어와 동사 사이에 of ~ 같은 수식어가 끼어도 동사는 진짜 주어에 맞춰요.\n예) The noise of the cars is loud. (차들의 소음은 크다.)"},{"s":"…promoting environmentally sustainable products or ( ______ ) causes related to equality and justice can help raise awareness…","ch":["support","supporting"],"a":1,"why":"or로 연결된 두 주어가 같은 모양이어야 하는 병렬구조. 앞이 동명사 promoting이므로 뒤도 동명사 supporting.","tr":"예를 들어, 환경적으로 지속가능한 제품들을 홍보하거나 평등과 정의에 관련된 대의명분을 지지하는 것은 인식을 높이고 의미 있는 사회적 영향을 이끌어 내는 것을 도울 수 있다.","g":"and, or로 이어진 것들은 같은 모양으로 맞춰야 해요(병렬).\n앞이 -ing면 뒤도 -ing예요.\n예) Swimming or running is good exercise. (수영이나 달리기는 좋은 운동이다.)"},{"s":"Ethical content creators not only focus on promoting their products or services but also ( ______ ) the values and causes they support.","ch":["consider","considering"],"a":0,"why":"not only A but also B에서 A(focus)와 B는 같은 모양이어야 하는 병렬구조. focus가 동사이므로 B도 동사 consider. considering은 동사 자리에 올 수 없음.","tr":"윤리적인 콘텐츠 제작자들은 자신의 제품이나 서비스를 홍보하는 데만 초점을 맞추는 것이 아니라, 자신이 지지하는 가치와 대의명분도 고려하며, 자신의 콘텐츠가 자신의 사회적 그리고 환경적 원칙과 반드시 일치하게 한다.","g":"not only A but also B에서는 A와 B의 모양을 같게 해요.\n동사에는 동사, 명사에는 명사를 맞춰요.\n예) She not only sings but also dances. (그녀는 노래할 뿐 아니라 춤도 춘다.)"}],"awk":[{"t":"Social and environmental responsibility has become an [[1|increasingly]] important [[2|ethical]] consideration for content creators. As global awareness of social, environmental, and [[3|sustainability]] issues [[4|grows]], many content creators are being called upon to [[5|ignore]] the broader impact of their work.","a":5,"fix":"consider","why":"원문은 consider (고려하다). 인식이 커질수록 제작자들은 자기 작업의 더 폭넓은 영향을 ‘고려하도록’ 요구받는다.\nignore (무시하다)이면 첫 문장의 책임이 중요해졌다는 내용과 모순된다.","sp":[{"b":"increasingly","m":"점점 더","n":"increasingly important = 점점 더 중요한","y":"맞음. 책임의 중요성이 커지고 있다.","e":"갈수록 더 중요해지는 흐름."},{"b":"ethical","m":"윤리적인","n":"an ethical consideration = 윤리적 고려 사항","y":"맞음. 옳고 그름과 관련된 고려라는 뜻.","e":"도덕적으로 생각해야 할 일."},{"b":"sustainability","m":"지속가능성","n":"sustainability issues = 지속가능성 문제","y":"맞음. 앞의 social, environmental과 나란히 나열됨.","e":"환경을 오래 지키는 문제."},{"b":"grows","m":"커지다","n":"주어 awareness가 단수라 grows","y":"맞음. 인식이 커진다는 뜻.","e":"관심이 점점 늘어남."},{"b":"ignore","m":"무시하다","n":"","y":"어색함. 원문은 consider. 책임이 중요해졌다는 글의 흐름에서 영향을 무시하라는 말은 모순이다.","e":"책임을 말하는 글인데 영향을 무시하라고 하면 어색함."}]},{"t":"Content creators have a platform that can [[1|influence]] their [[2|audience's]] attitudes and behaviors, and they have a [[3|responsibility]] to use that platform for [[4|negative]] [[5|change]].","a":4,"fix":"positive","why":"원문은 positive (긍정적인). 영향력이 있는 만큼 그것을 ‘긍정적인’ 변화에 쓸 책임이 있다는 흐름이다.\nnegative (부정적인)이면 ‘책임’이라는 말과 어울리지 않고, 글 전체의 주제와도 모순된다.","sp":[{"b":"influence","m":"영향을 미치다","n":"can influence = 조동사 뒤 동사원형","y":"맞음. 청중의 태도와 행동에 영향을 줄 수 있다.","e":"영상이 사람들의 생각을 움직임."},{"b":"audience","m":"청중, 시청자","n":"their audience's attitudes = 청중의 태도","y":"맞음. 콘텐츠를 보는 사람들.","e":"구독자와 시청자."},{"b":"responsibility","m":"책임","n":"have a responsibility to V = ~할 책임이 있다","y":"맞음. 영향력에 따르는 책임.","e":"힘이 큰 만큼 따르는 숙제."},{"b":"negative","m":"부정적인","n":"","y":"어색함. 원문은 positive. 책임을 갖고 플랫폼을 쓴다는 말과 부정적인 변화는 맞지 않는다.","e":"좋은 방향으로 바꿔야 책임을 다하는 것."},{"b":"change","m":"변화","n":"for positive change = 긍정적인 변화를 위해","y":"맞음. 사회를 더 좋게 바꾸는 일.","e":"세상이 나아지는 쪽으로의 변화."}]},{"t":"For example, [[1|promoting]] environmentally sustainable products or supporting causes related to [[2|equality]] and justice can help [[3|reduce]] awareness and drive [[4|meaningful]] social [[5|impact]].","a":3,"fix":"raise","why":"원문은 raise (높이다). 제품을 홍보하고 대의를 지지하면 사람들의 인식을 ‘높이는’ 데 도움이 된다.\nreduce (줄이다)이면 뒤의 drive meaningful social impact(의미 있는 사회적 영향을 이끌다)와 모순된다.","sp":[{"b":"promoting","m":"홍보하는 것","n":"동명사 주어","y":"맞음. 지속가능한 제품을 알리는 일.","e":"좋은 제품을 널리 소개."},{"b":"equality","m":"평등","n":"causes related to equality = 평등에 관련된 대의명분","y":"맞음. 정의와 나란히 쓰이는 가치.","e":"모두가 같은 대우를 받는 것."},{"b":"reduce","m":"줄이다","n":"","y":"어색함. 원문은 raise. 인식을 줄이는 일은 사회적 영향을 이끈다는 뒤 내용과 맞지 않는다.","e":"좋은 활동은 인식을 높임."},{"b":"meaningful","m":"의미 있는","n":"meaningful social impact = 의미 있는 사회적 영향","y":"맞음. 가치 있는 변화라는 뜻.","e":"실제로 도움이 되는 변화."},{"b":"impact","m":"영향","n":"drive ~ impact = ~한 영향을 이끌어 내다","y":"맞음. 사회에 미치는 영향.","e":"세상에 남는 결과."}]},{"t":"Ethical content creators not only focus on promoting their products or services but also [[1|consider]] the values and causes they support, [[2|ensuring]] that their content [[3|conflicts]] with their [[4|social]] and [[5|environmental]] principles.","a":3,"fix":"aligns","why":"원문은 aligns (일치하다). 윤리적인 제작자는 자기 콘텐츠가 자신의 원칙과 ‘일치하도록’ 한다.\nconflicts (충돌하다)이면 ensuring(반드시 ~하게 하다)과 모순되고, 윤리적이라는 말과도 맞지 않는다.","sp":[{"b":"consider","m":"고려하다","n":"not only ~ but also consider = 병렬 동사","y":"맞음. 지지하는 가치도 고려한다.","e":"무엇을 지지하는지도 생각함."},{"b":"ensuring","m":"반드시 ~하게 하다","n":"분사구문 ensuring that ~","y":"맞음. 확실히 보장한다는 뜻.","e":"빠짐없이 챙기는 것."},{"b":"conflicts","m":"충돌하다","n":"","y":"어색함. 원문은 aligns. 원칙과 충돌하게 한다면 윤리적이라는 말과 모순된다.","e":"말과 행동이 같아야 윤리적."},{"b":"social","m":"사회적인","n":"social and environmental principles","y":"맞음. 사회적 원칙.","e":"사회에 관한 가치."},{"b":"environmental","m":"환경적인","n":"social and environmental principles","y":"맞음. 환경에 관한 원칙.","e":"환경을 지키려는 가치."}]}],"und":[{"q":"<u>many content creators are being called upon to consider the broader impact of their work</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["많은 제작자가 전화로 직접 사과하도록 요구받고 있다","많은 제작자가 자기 작업이 사회에 미치는 더 넓은 영향을 생각하도록 요구받고 있다","제작자들이 작업량을 더 넓은 범위로 늘려야 한다는 요구를 받고 있다","제작자들이 자기 작품의 수입을 넓게 나누라는 요구를 받고 있다","제작자들이 청중의 전화에 즉시 답하라고 요구받고 있다"],"a":1,"why":"앞 내용: 사회·환경·지속가능성에 대한 전 세계의 인식이 커지고 있음.\nbe called upon to V = ~하도록 요구받다.\nthe broader impact = 더 넓은 영향.\n결론: 제작자들은 자기 콘텐츠가 사회에 미치는 영향까지 생각해야 함.","e":"내 영상이 친구들에게 어떤 영향을 줄지까지 생각하라는 부탁.","tr":"사회적, 환경적, 그리고 지속가능성 문제들에 대한 전 세계적인 인식이 커짐에 따라, 많은 콘텐츠 제작자들은 자신의 작업의 더 폭넓은 영향력을 고려하도록 요구받고 있다."},{"q":"<u>Content creators have a platform that can influence their audience's attitudes and behaviors</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["제작자는 많은 사람이 보는 매체를 갖고 있어 그들의 생각과 행동을 바꿀 수 있다","제작자는 청중의 태도를 평가하는 시험을 만들 수 있다","제작자는 승강장에서 사람들을 줄 세울 수 있다","제작자의 청중은 그의 행동만 그대로 따라 한다","제작자는 청중에게 돈을 받고 태도를 바꿔 준다"],"a":0,"why":"앞 내용: 제작자는 사회적 책임을 고려해야 함.\nplatform = 생각을 알리는 장, 매체. influence = 영향을 주다.\n결론: 큰 영향력이 있기 때문에 책임도 따른다는 이유를 제시함.","e":"구독자가 많은 채널의 한마디가 친구들의 유행을 바꾸는 것.","tr":"콘텐츠 제작자들은 자신의 청중의 태도와 행동에 영향을 미칠 수 있는 플랫폼을 가지고 있으며, 그들은 그 플랫폼을 긍정적인 변화를 위해 사용할 책임을 지닌다."},{"q":"<u>ensuring that their content aligns with their social and environmental principles</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["콘텐츠를 만든 뒤에 원칙을 새로 바꾼다","콘텐츠를 가능한 한 조용히 숨겨 둔다","콘텐츠가 원칙보다 더 많은 수익을 내도록 한다","자신의 콘텐츠가 자신이 믿는 사회적·환경적 가치와 어긋나지 않도록 확실히 한다","콘텐츠에서 사회적 문제는 빼고 환경 문제만 다룬다"],"a":3,"why":"앞 내용: 윤리적 제작자는 홍보만이 아니라 자신이 지지하는 가치도 고려함.\nensure = 확실히 ~하게 하다. align with = ~와 일치하다.\n결론: 말하는 가치와 만드는 콘텐츠가 같은 방향이어야 함.","e":"환경을 지키자고 말한 사람이 쓰레기를 함부로 버리지 않는 것.","tr":"윤리적인 콘텐츠 제작자들은 자신의 제품이나 서비스를 홍보하는 데만 초점을 맞추는 것이 아니라, 자신이 지지하는 가치와 대의명분도 고려하며, 자신의 콘텐츠가 자신의 사회적 그리고 환경적 원칙과 반드시 일치하게 한다."},{"q":"<u>drive meaningful social impact</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["의미 없는 사회적 소문을 퍼뜨리다","사회 속에서 자동차를 운전하게 만들다","실제로 가치 있는 사회적 변화를 이끌어 내다","정해진 의미를 사회에 강요하다","사회의 영향을 최소한으로 줄이다"],"a":2,"why":"앞 내용: 지속가능한 제품 홍보와 대의명분 지지가 인식을 높임.\ndrive = (변화 등을) 이끌어 내다. meaningful = 의미 있는.\n결론: 인식을 넘어 사회에 실제 변화를 만들어 낸다는 뜻.","e":"캠페인이 끝난 뒤 사람들의 생활이 정말로 달라지는 것.","tr":"예를 들어, 환경적으로 지속가능한 제품들을 홍보하거나 평등과 정의에 관련된 대의명분을 지지하는 것은 인식을 높이고 의미 있는 사회적 영향을 이끌어 내는 것을 도울 수 있다."}]},"2610-23":{"voc":[{"q":"…suggests that an octopus <u>possesses</u> roughly five hundred million neurons.","ask":"possess와 바꿔 쓸 수 있는 말은?","ch":["lose","borrow","imagine","own","produce"],"a":3,"why":"possess = 소유하다, 가지고 있다 (= own, have). 지문의 possesses는 3인칭 단수 -es가 붙은 형태.\n지문: an octopus possesses roughly five hundred million neurons = 문어는 대략 5억 개의 뉴런을 가지고 있다.\nlose = 잃다, borrow = 빌리다, imagine = 상상하다, produce = 만들어 내다라 뜻이 다름.","e":"내 방에 책상과 침대를 가지고 있는 것.","tr":"두족류 동물 신경 생물학에 관한 연구는 문어가 대략 5억 개의 뉴런을 가지고 있다는 것을 시사한다.","alt":"have (가지다), own (소유하다) / 반의어 lack (부족하다)"},{"q":"…an octopus possesses <u>roughly</u> five hundred million neurons.","ask":"roughly와 바꿔 쓸 수 있는 말은?","ch":["exactly","rarely","barely","approximately","finally"],"a":3,"why":"roughly = 대략, 약 (= approximately).\n지문: roughly five hundred million = 대략 5억 개.\nexactly = 정확히, rarely = 드물게, barely = 간신히, finally = 마침내라 뜻이 다름.","e":"정확한 숫자 대신 ‘한 5억쯤’이라고 말하는 것.","tr":"두족류 동물 신경 생물학에 관한 연구는 문어가 대략 5억 개의 뉴런을 가지고 있다는 것을 시사한다.","alt":"about (약), around (대략) / 반의어 exactly (정확히)"},{"q":"“a nerve cell that carries messages in the body”","ask":"위 영영풀이에 해당하는 단어는?","ch":["sucker","neuron","grip","surface","signal"],"a":1,"why":"neuron = 뉴런, 신경 세포 (몸 안에서 신호를 전달하는 세포).\n지문: five hundred million neurons = 5억 개의 뉴런.\nsucker = 빨판, grip = 붙잡는 힘, surface = 표면, signal = 신호라 풀이와 맞지 않음.","e":"뇌와 몸을 이어 주는 전깃줄 같은 세포.","tr":"두족류 동물 신경 생물학에 관한 연구는 문어가 대략 5억 개의 뉴런을 가지고 있다는 것을 시사한다.","alt":"nerve cell (신경 세포)"},{"q":"…<u>concentrated</u> entirely in the central brain.","ask":"concentrated의 반의어로 알맞은 것은?","ch":["scattered (흩어진)","gathered (모인)","focused (집중된)","packed (빽빽이 채운)","centered (중심에 둔)"],"a":0,"why":"concentrated = 집중된, 한곳에 모인 ↔ scattered = 흩어진, 분산된.\ngathered, focused, packed, centered는 모두 ‘한곳에 모인’ 쪽의 말.\n지문: distributed throughout the arms rather than concentrated entirely in the central brain = 뇌에만 집중되어 있기보다 다리 전체에 분포되어 있다.","e":"한 교실에 몰려 있는 것(concentrated)과 여러 교실에 흩어져 있는 것(scattered)의 차이.","tr":"절반 이상은 중앙의 뇌에 전적으로 집중되어 있기보다는 다리들 전체에 걸쳐 분포되어 있다.","alt":"focused (집중된) / 반의어 scattered, dispersed (분산된)"},{"q":"…networks of nerve cells <u>capable</u> of controlling complex movements…","ask":"capable의 뜻으로 알맞은 것은?","ch":["~을 두려워하는","~에 반대하는","~할 필요가 없는","~할 능력이 있는","~할 의무가 있는"],"a":3,"why":"capable of ~ing = ~할 능력이 있는 (= able to). 명사형은 capability(능력).\n지문: nerve cells capable of controlling complex movements = 복잡한 움직임을 통제할 수 있는 신경 세포들.\n다리의 신경만으로도 움직임을 조절할 능력이 있다는 말.","e":"혼자서 자전거를 탈 능력이 있는 아이.","tr":"각각의 다리는 복잡한 움직임들을 통제하고 감각적 입력에 국소적으로 반응할 수 있는 신경 세포들의 네트워크를 갖고 있다.","alt":"able (할 수 있는), competent (능숙한) / 반의어 incapable (할 수 없는)"},{"q":"…responding to <u>sensory</u> input locally.","ask":"sensory의 뜻으로 알맞은 것은?","ch":["화학의","중앙의","복잡한","전체의","감각의"],"a":4,"why":"sensory = 감각의, 감각 기관과 관련된. 명사 sense(감각)에서 온 형용사.\n지문: sensory input = 감각을 통해 들어오는 정보.\n눈·귀·피부 같은 감각으로 받아들이는 신호를 말함.","e":"뜨거운 컵을 만졌을 때 느끼는 촉각 같은 정보.","tr":"각각의 다리는 복잡한 움직임들을 통제하고 감각적 입력에 국소적으로 반응할 수 있는 신경 세포들의 네트워크를 갖고 있다.","alt":"sense (감각), sensation (느낌)"},{"q":"…responding to sensory input <u>locally</u>.","ask":"이 글에서 밑줄 친 locally의 뜻으로 가장 알맞은 것은?","ch":["멀리서","동시에 모든 곳에서","가끔씩","뇌를 거쳐서","그 부위에서 바로, 국소적으로"],"a":4,"why":"locally = 그 자리에서, 국소적으로 (형용사 local ‘지역의’에서 온 부사).\n지문: responding to sensory input locally = 감각 정보에 그 부위에서 바로 반응하다.\n뇌의 명령을 기다리지 않고 다리 자체가 처리한다는 뜻.","e":"뜨거운 걸 만지면 뇌에 묻기 전에 손이 먼저 빼지는 것과 비슷함.","tr":"각각의 다리는 복잡한 움직임들을 통제하고 감각적 입력에 국소적으로 반응할 수 있는 신경 세포들의 네트워크를 갖고 있다.","alt":"on the spot (그 자리에서) / 반의어 remotely (멀리서)"},{"q":"These structures provide strong <u>grip</u> but also detect chemical signals…","ask":"이 글에서 grip의 뜻으로 가장 알맞은 것은?","ch":["달리는 속도","내는 소리","풍기는 냄새","느끼는 온도","꽉 붙잡는 힘"],"a":4,"why":"grip = 꽉 붙잡는 힘, 쥐는 것. 동사로도 ‘꽉 잡다’.\n지문: provide strong grip = 강한 붙잡는 힘을 제공하다.\n빨판이 물건에 단단히 달라붙는 힘을 말함.","e":"철봉에 매달릴 때 손바닥으로 꽉 잡는 힘.","tr":"이 구조들은 강한 붙잡는 힘을 제공하지만 또한 그것들이 접촉하는 표면의 화학적 신호들도 탐지한다.","alt":"hold (쥐기), clasp (움켜쥐기)"}],"find":[{"s":"Research suggests that an octopus has roughly five hundred million neurons.","a":true,"why":"1문장: 두족류 신경 생물학 연구는 문어가 대략 5억 개의 뉴런을 가진다고 시사함.","e":"문어의 신경 세포는 약 5억 개."},{"s":"Most of an octopus's neurons are concentrated entirely in its central brain.","a":false,"why":"3문장: 절반 이상이 중앙의 뇌에 전적으로 집중된 것이 아니라 다리 전체에 분포되어 있음.","e":"뉴런이 뇌에만 있는 것이 아님."},{"s":"More than half of the neurons are spread throughout the arms.","a":true,"why":"3문장: More than half are distributed throughout the arms (절반 이상은 다리들 전체에 분포되어 있음).","e":"신경 세포의 과반이 다리에 있음."},{"s":"Each arm has networks of nerve cells that can control complex movements.","a":true,"why":"4문장: networks of nerve cells capable of controlling complex movements (복잡한 움직임을 통제할 수 있는 신경 세포들의 네트워크).","e":"다리마다 작은 ‘제어실’이 있는 셈."},{"s":"Every action of the arms needs detailed instructions from the brain.","a":false,"why":"5문장: many actions do not require detailed instructions from the brain itself (많은 행동은 뇌의 상세한 지시를 필요로 하지 않음).","e":"다리가 스스로 움직이는 경우가 많음."},{"s":"The arms work as capable extensions of the nervous system that interact with the environment directly.","a":true,"why":"6문장: highly capable extensions of the nervous system that interact with the environment directly (환경과 직접 상호 작용하는 유능한 신경계의 연장선).","e":"다리가 신경계의 연장선처럼 일함."},{"s":"The suckers on the arms only give a strong grip and cannot detect anything.","a":false,"why":"8문장: These structures provide strong grip but also detect chemical signals (강한 붙잡는 힘을 주지만 화학적 신호도 탐지함).","e":"붙잡는 일 말고도 하는 일이 있음."},{"s":"The suckers can detect chemical signals on the surfaces they touch.","a":true,"why":"8문장: detect chemical signals on surfaces they contact (그들이 접촉하는 표면의 화학적 신호를 탐지함).","e":"닿은 곳의 화학 성분을 알아챔."},{"s":"Marine biologists have shown that the animal gathers chemical information through sight.","a":false,"why":"9문장: gather chemical information through touch (접촉을 통해 화학적 정보를 수집함). 시각이 아니라 촉각.","e":"눈이 아니라 닿아서 알아냄."},{"s":"In practical terms, an octopus can effectively taste what it touches.","a":true,"why":"10문장: an octopus can effectively taste what it touches (문어는 사실상 접촉하는 것을 맛볼 수 있음).","e":"만지는 것이 곧 맛보는 것."}],"eob":[{"s":"What makes this system unusual ( ______ ) where many of those neurons are located.","ch":["is","are"],"a":0,"why":"What makes this system unusual은 하나의 명사절(‘~하게 만드는 것’) 주어이므로 단수 취급해서 is. 바로 뒤 neurons(복수)에 끌려 are를 쓰면 틀림.","tr":"이 체계를 특이하게 만드는 것은 그 뉴런들 중 다수가 어디에 위치해 있는가이다.","g":"what이 이끄는 명사절이 주어이면 단수로 취급해서 동사는 is/has/does를 써요.\n예) What I need is some rest. (내가 필요한 것은 약간의 휴식이다.)"},{"s":"Each arm contains networks of nerve cells capable of ( ______ ) complex movements and responding to sensory input locally.","ch":["control","controlling"],"a":1,"why":"capable of 뒤에는 전치사 of의 목적어로 동명사가 옴. 그래서 controlling. 뒤의 responding과도 병렬. 동사원형 control은 올 수 없음.","tr":"각각의 다리는 복잡한 움직임들을 통제하고 감각적 입력에 국소적으로 반응할 수 있는 신경 세포들의 네트워크를 갖고 있다.","g":"capable of, afraid of, good at 같은 표현 뒤에는 동사원형이 아니라 동명사(-ing)를 써요.\n예) He is capable of running fast. (그는 빨리 달릴 능력이 있다.)"},{"s":"The suckers ( ______ ) each arm play an important role in this process.","ch":["lining","lined"],"a":0,"why":"빨판이 팔을 따라 늘어서 있다는 능동 관계(빨판이 줄을 이룸)이고 뒤에 목적어 each arm이 있으므로 현재분사 lining. 목적어를 바로 취하는 수동 lined는 안 됨.","tr":"각각의 다리를 따라 늘어서 있는 빨판들은 이 과정에서 중요한 역할을 한다.","g":"명사 뒤에서 꾸밀 때 뒤에 목적어가 바로 이어지면 능동이므로 -ing를 써요.\n예) the boy playing the guitar (기타를 치고 있는 소년)"},{"s":"…the arms function as highly capable extensions of the nervous system that ( ______ ) with the environment directly.","ch":["interact","interacts"],"a":0,"why":"관계대명사 that의 선행사는 복수 extensions이므로 동사도 복수형 interact. 바로 앞 단수 the nervous system에 끌려 interacts를 쓰면 틀림.","tr":"대신에, 그 다리들은 환경과 직접적으로 상호 작용하는 대단히 유능한 신경계의 연장선으로서 작동한다.","g":"관계대명사절의 동사는 선행사의 수에 맞춰요. 가까이 있는 명사가 아니라 꾸밈을 받는 명사가 기준이에요.\n예) I know the girls who live next door. (나는 옆집에 사는 소녀들을 안다.)"},{"s":"…have shown that this allows the animal ( ______ ) chemical information through touch.","ch":["gather","to gather"],"a":1,"why":"allow + 목적어 + to V (목적어가 ~하도록 허락하다/가능하게 하다) 구조라 to gather. 동사원형 gather를 바로 쓰면 틀림.","tr":"문어의 행동을 연구하는 해양 생물학자들은 이것이 그 동물이 접촉을 통해 화학적 정보를 수집할 수 있게 한다는 것을 보여 주었다.","g":"allow, enable, want, ask 뒤에는 ‘목적어 + to 동사원형’이 와요. 동사원형만 쓰지 않아요.\n예) My mom allowed me to stay up late. (엄마는 내가 늦게까지 깨어 있도록 허락하셨다.)"}],"awk":[{"t":"What makes this system [[1|ordinary]] is where many of those neurons are [[2|located]]. More than half are [[3|distributed]] throughout the arms rather than [[4|concentrated]] [[5|entirely]] in the central brain.","a":1,"fix":"unusual","why":"원문은 unusual (특이한). 뉴런이 뇌에만 있지 않고 절반 이상이 다리에 퍼져 있어서 ‘특이하다’는 흐름이다.\nordinary (평범한)이면 뒤의 설명(절반 이상이 다리에 분포)과 맞지 않는다.","sp":[{"b":"ordinary","m":"평범한","n":"","y":"어색함. 원문은 unusual. 뉴런 대부분이 다리에 있다는 내용은 평범한 게 아니라 특이한 점이다.","e":"뇌에만 신경이 있는 것이 평범한 동물."},{"b":"located","m":"위치한","n":"be located = 위치해 있다 (수동)","y":"맞음. 뉴런이 어디에 있는지를 말함.","e":"어디에 자리 잡고 있는가."},{"b":"distributed","m":"분포된","n":"be distributed throughout = 전체에 퍼져 있다","y":"맞음. 다리 전체에 퍼져 있다.","e":"여기저기 골고루 흩어져 있음."},{"b":"concentrated","m":"집중된","n":"rather than 뒤 과거분사","y":"맞음. 뇌에만 몰려 있기보다 퍼져 있다는 대비.","e":"한곳에 몰려 있음."},{"b":"entirely","m":"전적으로","n":"entirely = 완전히","y":"맞음. 뇌에 전적으로 몰려 있지는 않다는 뜻.","e":"뇌에만 몽땅 있는 것은 아님."}]},{"t":"The [[1|suckers]] lining each arm play an [[2|important]] role in this process. These structures provide strong grip but also [[3|ignore]] chemical signals on [[4|surfaces]] they [[5|contact]].","a":3,"fix":"detect","why":"원문은 detect (탐지하다). 빨판은 붙잡는 일뿐 아니라 닿은 표면의 화학 신호도 ‘탐지한다’.\nignore (무시하다)이면 뒤 문장의 ‘접촉으로 화학적 정보를 모은다’는 내용과 모순된다.","sp":[{"b":"suckers","m":"빨판","n":"the suckers lining each arm","y":"맞음. 다리를 따라 늘어선 빨판.","e":"문어 다리에 줄지어 붙은 둥근 부분."},{"b":"important","m":"중요한","n":"play an important role = 중요한 역할을 하다","y":"맞음. 이 과정에서 중요한 역할.","e":"큰 몫을 함."},{"b":"ignore","m":"무시하다","n":"","y":"어색함. 원문은 detect. 화학 신호를 무시한다면 맛을 본다는 마지막 문장과 모순된다.","e":"신호를 알아채야 맛을 알 수 있음."},{"b":"surface","m":"표면","n":"surfaces = 표면들 (복수)","y":"맞음. 문어가 닿는 물체의 겉면.","e":"바위나 먹이의 겉면."},{"b":"contact","m":"접촉하다","n":"they contact = 접촉하는 (관계대명사 생략)","y":"맞음. 빨판이 닿는 표면.","e":"살짝 닿는 것."}]},{"t":"Instead, the arms [[1|function]] as highly [[2|capable]] [[3|extensions]] of the nervous system that [[4|interact]] with the environment [[5|indirectly]].","a":5,"fix":"directly","why":"원문은 directly (직접적으로). 다리가 뇌를 거치지 않고 환경과 ‘직접’ 상호 작용한다는 흐름이다.\nindirectly (간접적으로)이면 앞 문장(뇌의 상세한 지시가 필요 없다)과 모순된다.","sp":[{"b":"function","m":"작동하다","n":"function as = ~로서 작동하다","y":"맞음. 다리가 신경계의 연장선으로 작동한다.","e":"제 역할을 하는 것."},{"b":"capable","m":"유능한","n":"highly capable = 대단히 유능한","y":"맞음. 스스로 처리할 능력이 큼.","e":"혼자서 척척 해내는 느낌."},{"b":"extensions","m":"연장선, 확장","n":"extensions of the nervous system = 신경계의 연장","y":"맞음. 다리가 신경계가 뻗어 나간 부분처럼 일한다는 뜻.","e":"뇌에서 뻗어 나온 팔 같은 것."},{"b":"interact","m":"상호 작용하다","n":"that의 선행사가 복수라 interact","y":"맞음. 환경과 서로 영향을 주고받는다.","e":"주변과 직접 주고받음."},{"b":"indirectly","m":"간접적으로","n":"","y":"어색함. 원문은 directly. 뇌를 거치지 않고 환경과 직접 만난다는 흐름과 모순된다.","e":"다리가 바로 닿아서 알아냄."}]},{"t":"Marine biologists studying octopus behavior have [[1|shown]] that this allows the animal to [[2|gather]] chemical [[3|information]] through [[4|touch]]. In practical terms, an octopus can effectively [[5|see]] what it touches.","a":5,"fix":"taste","why":"원문은 taste (맛보다). 접촉으로 화학적 정보를 모으므로 문어는 만지는 것을 ‘맛볼’ 수 있다.\nsee (보다)이면 앞 문장의 through touch(접촉을 통해)와 맞지 않는다.","sp":[{"b":"shown","m":"보여 주었다","n":"have shown = 현재완료","y":"맞음. 연구가 증명했다는 뜻.","e":"실험으로 밝혀낸 것."},{"b":"gather","m":"수집하다","n":"allow the animal to gather = 동물이 수집하게 하다","y":"맞음. 정보를 모은다.","e":"정보를 모으는 것."},{"b":"information","m":"정보","n":"chemical information = 화학적 정보","y":"맞음. 닿은 곳에서 얻는 정보.","e":"물질의 성분에 대한 정보."},{"b":"touch","m":"접촉","n":"through touch = 접촉을 통해","y":"맞음. 만져서 얻는다는 뜻.","e":"닿는 것."},{"b":"see","m":"보다","n":"","y":"어색함. 원문은 taste. 접촉으로 화학 정보를 얻는다는 흐름에서 ‘본다’는 말은 맞지 않는다.","e":"만져서 맛을 알아내는 것."}]}],"und":[{"q":"<u>What makes this system unusual is where many of those neurons are located.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["이 체계가 특이한 이유는 뉴런의 수가 너무 적다는 점이다","이 체계가 특이한 이유는 뉴런이 모두 한곳의 뇌에 모여 있다는 점이다","이 체계가 특이한 이유는 뉴런이 바다 밑에서만 만들어진다는 점이다","이 체계가 특이한 이유는 많은 뉴런이 뇌가 아니라 다리에 있다는 점이다","이 체계가 특이한 이유는 뉴런이 시간에 따라 위치를 바꾼다는 점이다"],"a":3,"why":"앞 내용: 문어는 약 5억 개의 뉴런을 가짐.\nwhere ~ are located = 어디에 위치해 있는가.\n뒤 내용: 절반 이상이 중앙의 뇌가 아니라 다리 전체에 분포.\n결론: 특이한 점은 뉴런의 ‘위치’.","e":"학교 서버가 본관에만 있지 않고 반마다 따로 있는 구조.","tr":"이 체계를 특이하게 만드는 것은 그 뉴런들 중 다수가 어디에 위치해 있는가이다."},{"q":"<u>many actions do not require detailed instructions from the brain itself</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["다리는 뇌가 없으면 아무 행동도 할 수 없다","뇌는 다리에 아무 지시도 내리지 않기로 선택했다","다리는 뇌의 세세한 지시가 없어도 스스로 많은 행동을 할 수 있다","다리의 행동은 뇌의 지시를 받아 더 정교해진다","문어의 뇌는 지시를 내리는 방법을 모르고 있다"],"a":2,"why":"앞 내용: 각 다리에는 움직임을 통제하고 감각에 반응하는 신경 세포 네트워크가 있음.\nrequire = 필요로 하다. detailed instructions = 상세한 지시.\n결론: 뇌의 지시를 일일이 받지 않고도 다리가 스스로 움직임.","e":"작은 심부름은 선생님께 묻지 않고 학생이 바로 처리하는 것.","tr":"이것은 많은 행동들이 뇌 자체로부터 상세한 지시들을 필요로 하지 않는다는 것을 의미한다."},{"q":"<u>the arms function as highly capable extensions of the nervous system</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["다리는 신경계를 대신하는 장식품일 뿐이다","다리는 신경계가 뻗어 나온 부분처럼 스스로 능숙하게 일한다","다리는 뇌보다 훨씬 약한 도구로만 쓰인다","다리는 신경계와 분리되어 따로 움직인다","다리는 신경계를 가장 쉽게 다치게 하는 부분이다"],"a":1,"why":"앞 내용: 다리에 많은 뉴런이 있고 뇌의 상세한 지시가 필요 없음.\nextension = 연장선, 뻗어 나온 부분. highly capable = 대단히 유능한.\n결론: 다리는 신경계의 일부처럼 환경과 직접 상호 작용하는 유능한 부분.","e":"뇌의 지시를 기다리지 않는 똑똑한 손.","tr":"대신에, 그 다리들은 환경과 직접적으로 상호 작용하는 대단히 유능한 신경계의 연장선으로서 작동한다."},{"q":"<u>an octopus can effectively taste what it touches</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["문어는 닿기만 해도 그 물체의 화학 성분을 알아채므로 사실상 맛을 보는 셈이다","문어는 입에 넣은 물체만 맛을 알 수 있다","문어는 접촉한 물체를 눈으로 보고 맛을 판단한다","문어는 접촉한 물체의 소리를 듣고 맛을 알아낸다","문어는 맛을 느끼지 못하지만 먹이를 잘 잡는다"],"a":0,"why":"앞 내용: 빨판은 붙잡는 힘과 함께 표면의 화학적 신호를 탐지함.\n그 결과: 접촉을 통해 화학적 정보를 수집함.\n결론: 만지기만 해도 맛을 보는 것과 같은 효과.","e":"손끝으로 만졌는데 맛까지 아는 것 같은 느낌.","tr":"실질적으로 말해서, 문어는 사실상 그것이 접촉하는 것을 맛볼 수 있다."}]},"2610-24":{"voc":[{"q":"<u>Consistent</u> though he may be, some of Aristotle's ideas meet us today as strange.","ask":"consistent의 반의어로 알맞은 것은?","ch":["steady (꾸준한)","regular (규칙적인)","constant (변함없는)","inconsistent (일관되지 않은)","stable (안정된)"],"a":3,"why":"consistent = 일관된, 변함없는 ↔ inconsistent = 일관되지 않은, 모순되는.\nsteady, regular, constant, stable은 모두 ‘변함없는’ 쪽의 말이라 반의어가 아님.\n지문: Consistent though he may be = 그는 일관적일지 모르지만.","e":"말과 행동이 늘 같은 사람은 consistent.","tr":"비록 아리스토텔레스가 일관적일지라도, 그의 생각들 중 일부는 오늘날 우리에게 낯설게 다가온다.","alt":"constant (변함없는), steady (꾸준한) / 반의어 inconsistent, contradictory (모순된)"},{"q":"He had no difficulty <u>justifying</u> slavery, for example…","ask":"justify의 뜻으로 알맞은 것은?","ch":["금지하다","정당화하다","비판하다","폐지하다","기록하다"],"a":1,"why":"justify = 정당화하다 (옳은 일이라고 이유를 대어 말하다). 지문의 justifying은 have difficulty (in) ~ing 뒤의 동명사.\n지문: no difficulty justifying slavery = 노예 제도를 정당화하는 데 어려움이 없었다.\n명사형은 justification(정당화).","e":"숙제를 안 한 이유를 그럴듯하게 설명하며 ‘괜찮다’고 말하는 것.","tr":"예를 들어, 그는 노예 제도를 정당화하는 데 아무런 어려움이 없었고, 그의 시대에 철학자들은 높은 특권과 영향력이 있는 지위를 누렸다.","alt":"defend (옹호하다), excuse (변명하다) / 반의어 condemn (비난하다)"},{"q":"…philosophers enjoyed positions of high <u>privilege</u> and influence.","ask":"privilege의 뜻으로 알맞은 것은?","ch":["의무","특권","위험","비용","책임"],"a":1,"why":"privilege = 특권 (특정한 사람에게만 주어지는 특별한 이익이나 권리). 지문의 privileged는 ‘특권을 가진’이라는 형용사.\n지문: positions of high privilege = 높은 특권이 있는 지위.\n철학자들이 사회에서 특별한 대우를 받았다는 말.","e":"줄을 서지 않고 먼저 들어가도 되는 특별한 자격.","tr":"예를 들어, 그는 노예 제도를 정당화하는 데 아무런 어려움이 없었고, 그의 시대에 철학자들은 높은 특권과 영향력이 있는 지위를 누렸다.","alt":"advantage (이점), right (권리)"},{"q":"Because of their practice of <u>contemplation</u> for the highest human good…","ask":"contemplation의 뜻으로 알맞은 것은?","ch":["노동","사색, 깊은 생각","경쟁","여행","거래"],"a":1,"why":"contemplation = 사색, 깊이 생각함. 동사 contemplate(곰곰이 생각하다)의 명사형.\n지문: the practice of contemplation for the highest human good = 인간의 최고선을 위한 사색의 실천.\n철학자들이 자신을 특별하다고 여긴 이유가 되는 활동.","e":"조용히 앉아 ‘나는 어떻게 살아야 할까’ 오래 생각하는 시간.","tr":"그들의 인간의 최고선에 대한 사유의 실천 때문에, 철학자들은 삶에서 모든 최고의 것들을 가질 만하다고 여겨졌다.","alt":"meditation (명상), reflection (숙고)"},{"q":"…philosophers were considered <u>worthy</u> to have all the best things in life.","ask":"이 글에서 worthy의 뜻으로 가장 알맞은 것은?","ch":["~을 두려워하는","~에 무관심한","~할 능력이 없는","~할 만한 자격이 있는","~와 비슷한"],"a":3,"why":"worthy = 가치 있는, ~할 자격이 있는 (worthy to V = ~할 만한). 명사 worth(가치)에서 온 형용사.\n지문: considered worthy to have all the best things = 모든 최고의 것을 가질 자격이 있다고 여겨졌다.\n철학자들이 자신들은 그럴 자격이 있다고 믿었다는 말.","e":"열심히 한 사람이 상을 받을 만하다고 말할 때의 ‘자격’.","tr":"그들의 인간의 최고선에 대한 사유의 실천 때문에, 철학자들은 삶에서 모든 최고의 것들을 가질 만하다고 여겨졌다.","alt":"deserving (받을 자격이 있는) / 반의어 unworthy (자격이 없는)"},{"q":"Somehow that <u>assertion</u> seems oddly self-serving.","ask":"assertion과 바꿔 쓸 수 있는 말은?","ch":["question (질문)","rule (규칙)","secret (비밀)","mistake (실수)","claim (주장)"],"a":4,"why":"assertion = 주장, 단언 (동사 assert ‘주장하다’의 명사형, = claim).\n지문: that assertion = 철학자들이 최고의 것을 가질 만하다는 그 주장.\nquestion = 질문, rule = 규칙, secret = 비밀, mistake = 실수라 뜻이 다름.","e":"‘내가 맞다’고 강하게 말하는 것.","tr":"왠지 그 주장은 이상하게도 자기 잇속만 차리는 것처럼 보인다.","alt":"claim (주장), statement (진술)"},{"q":"Somehow that assertion seems oddly <u>self-serving</u>.","ask":"self-serving의 뜻으로 알맞은 것은?","ch":["자기 잇속만 차리는","자신을 희생하는","스스로 반성하는","솔직하게 말하는","남의 말을 잘 듣는"],"a":0,"why":"self-serving = 자기 잇속만 차리는, 자기에게만 이로운 (self ‘자기’ + serve ‘이바지하다’).\n지문: oddly self-serving = 이상하게도 자기 잇속만 차리는 것 같은.\n철학자가 ‘철학자는 최고의 것을 가질 만하다’고 말하는 것은 자기 자신에게만 좋은 말이라는 비판.","e":"반장이 ‘반장은 간식을 두 개 먹어야 해’라고 하는 것.","tr":"왠지 그 주장은 이상하게도 자기 잇속만 차리는 것처럼 보인다.","alt":"selfish (이기적인) / 반의어 selfless (사심 없는)"},{"q":"“a person or thing that is not included in a general rule or statement”","ask":"위 영영풀이에 해당하는 단어는?","ch":["assertion","exception","privilege","indicator","contemplation"],"a":1,"why":"exception = 예외 (일반적인 규칙에 포함되지 않는 사람이나 것).\n지문: Aristotle is no exception = 아리스토텔레스도 예외는 아니다.\nassertion = 주장, privilege = 특권, indicator = 지표, contemplation = 사색이라 풀이와 맞지 않음.","e":"‘모두 줄 서세요’에서 줄을 서지 않아도 되는 한 사람.","tr":"그것은 ‘우리’가 모든 위대한 사상가는 그들 자신만의 시대에 속해 있고 특정한 청중들에게 말한다는 것을 기억하는 데 도움이 되며, 확실히 아리스토텔레스도 예외는 아니다.","alt":"exclusion (제외) / 관용구 with the exception of (~을 제외하고)"},{"q":"…for all it does well, it is also deeply <u>flawed</u>.","ask":"flawed의 반의어로 알맞은 것은?","ch":["faulty (결함이 있는)","damaged (손상된)","flawless (흠 없는)","broken (부서진)","defective (결함이 있는)"],"a":2,"why":"flawed = 결함이 있는 ↔ flawless = 흠 없는, 완벽한 (flaw ‘결함’ + -less ‘없는’).\nfaulty, damaged, broken, defective는 모두 ‘문제가 있는’ 쪽의 말.\n지문: deeply flawed = 심각하게 결함이 있는.","e":"화면에 금이 간 휴대폰이 flawed, 흠집 하나 없는 새 폰이 flawless.","tr":"그 결과, 그것의 장점에도 불구하고, 그것은 또한 심각하게 결함이 있다.","alt":"imperfect (불완전한), defective (결함 있는) / 반의어 flawless, perfect (완벽한)"}],"find":[{"s":"Some of Aristotle's ideas seem strange to us today.","a":true,"why":"1문장: some of Aristotle's ideas meet us today as strange (그의 생각 중 일부는 오늘날 우리에게 낯설게 다가옴).","e":"현대의 우리가 보면 이상한 생각이 섞여 있음."},{"s":"Aristotle found it very hard to justify slavery.","a":false,"why":"2문장: He had no difficulty justifying slavery (노예 제도를 정당화하는 데 아무런 어려움이 없었음). 어려웠다는 말은 반대.","e":"그는 아무렇지 않게 정당화했음."},{"s":"In his era, philosophers enjoyed positions of high privilege and influence.","a":true,"why":"2문장: philosophers enjoyed positions of high privilege and influence (철학자들은 높은 특권과 영향력이 있는 지위를 누림).","e":"철학자는 당시 높은 대접을 받았음."},{"s":"Philosophers were considered worthy of the best things because of their physical strength.","a":false,"why":"3문장: Because of their practice of contemplation (사유의 실천 때문에). 이유는 체력이 아니라 사색.","e":"힘이 아니라 생각이 이유."},{"s":"Philosophers were thought worthy to have all the best things because of their contemplation for the highest human good.","a":true,"why":"3문장: because of their practice of contemplation for the highest human good, philosophers were considered worthy to have all the best things (최고선을 위한 사색 때문에 최고의 것들을 가질 만하다고 여겨짐).","e":"생각하는 일이 가장 높은 일이라고 봄."},{"s":"The writer finds the philosophers' assertion oddly self-serving.","a":true,"why":"4문장: that assertion seems oddly self-serving (그 주장은 이상하게도 자기 잇속만 차리는 것처럼 보임).","e":"철학자가 철학자를 위한 주장을 한 셈."},{"s":"The writer says Aristotle is an exception who was not tied to his time.","a":false,"why":"5문장: certainly Aristotle is no exception (확실히 아리스토텔레스도 예외는 아님). 그도 자기 시대에 속함.","e":"위대해도 시대의 영향을 받음."},{"s":"Every great thinker speaks to a particular audience.","a":true,"why":"5문장: every great thinker is of her own time and speaks to a particular audience (모든 위대한 사상가는 자기 시대에 속하고 특정한 청중에게 말함).","e":"누구도 시대와 청중을 벗어나지 못함."},{"s":"Aristotle's idea of human flourishing was probably more inclusive than ours today.","a":false,"why":"6문장: probably would not be nearly as inclusive as we would want it to be today (오늘날 우리가 원하는 만큼 포용적이지는 않았을 것임). 더 포용적이라는 말은 반대.","e":"지금 기준으로는 포용성이 모자람."},{"s":"His view of right and good shows how the privileged elite of ancient Greece tended to think.","a":true,"why":"7문장: best taken to be an indicator of how the privileged elite of ancient Greek society tended to understand right and good (고대 그리스 특권 엘리트가 옳음과 선을 이해하던 경향의 척도).","e":"한 사람의 생각이 그 계층의 생각을 보여 줌."},{"s":"The writer concludes that Aristotle's ethics has no flaws.","a":false,"why":"8문장: for all it does well, it is also deeply flawed (장점에도 불구하고 심각하게 결함이 있음). 결함이 없다는 말은 반대.","e":"좋은 점도 있지만 큰 약점도 있음."}],"eob":[{"s":"( ______ ) their practice of contemplation for the highest human good, philosophers were considered worthy to have all the best things in life.","ch":["Because","Because of"],"a":1,"why":"뒤에 their practice of contemplation이라는 명사구만 오고 ‘주어 + 동사’가 없으므로 전치사구 Because of. 접속사 Because는 뒤에 절(주어 + 동사)이 와야 함.","tr":"그들의 인간의 최고선에 대한 사유의 실천 때문에, 철학자들은 삶에서 모든 최고의 것들을 가질 만하다고 여겨졌다.","g":"because 뒤에는 절(주어 + 동사), because of 뒤에는 명사(구)가 와요.\n예) We stayed home because of the rain. (비 때문에 우리는 집에 머물렀다.)\n예) We stayed home because it rained. (비가 와서 우리는 집에 머물렀다.)"},{"s":"…philosophers were considered ( ______ ) to have all the best things in life.","ch":["worthy","worth"],"a":0,"why":"‘~할 만한 자격이 있는’은 worthy to V. worth는 뒤에 명사나 -ing가 오며 worth to have의 형태는 쓰지 않음.","tr":"그들의 인간의 최고선에 대한 사유의 실천 때문에, 철학자들은 삶에서 모든 최고의 것들을 가질 만하다고 여겨졌다.","g":"worth는 뒤에 명사나 -ing가 와요(worth reading). worthy는 형용사라서 worthy of ~나 worthy to V 모양으로 써요.\n예) The book is worth reading. (그 책은 읽을 가치가 있다.)\n예) He is worthy to receive the prize. (그는 그 상을 받을 자격이 있다.)"},{"s":"It serves us to remember that every great thinker ( ______ ) of her own time and speaks to a particular audience.","ch":["is","are"],"a":0,"why":"every + 단수 명사는 단수 취급하므로 동사는 is. 뒤의 speaks도 단수 동사로 같은 흐름.","tr":"그것은 ‘우리’가 모든 위대한 사상가는 그들 자신만의 시대에 속해 있고 특정한 청중들에게 말한다는 것을 기억하는 데 도움이 되며, 확실히 아리스토텔레스도 예외는 아니다.","g":"every, each가 붙은 명사는 단수로 취급해서 동사도 단수형(is, has, speaks)으로 써요.\n예) Every student has a book. (모든 학생이 책 한 권을 가지고 있다.)"},{"s":"Human flourishing as he understood it probably would not be nearly as inclusive ( ______ ) we would want it to be today.","ch":["as","than"],"a":0,"why":"‘as + 형용사 + as’ 원급 비교 구문이라 뒤에 as. than은 비교급(more ~ than)에 쓰므로 여기서는 안 됨.","tr":"그가 이해했던 대로의 인간 번영은 아마도 결코 오늘날 우리가 그것이 그러하기를 원하는 만큼 포용적이지는 않을 것이다.","g":"‘~만큼 …한’은 as + 형용사 + as 모양이에요. 앞의 as와 짝을 이루는 뒤의 as를 than으로 바꾸면 안 돼요.\n예) She is as tall as her sister. (그녀는 언니만큼 키가 크다.)"},{"s":"How he understood right and good is best ( ______ ) to be an indicator of how the privileged elite of ancient Greek society tended to understand right and good.","ch":["taking","taken"],"a":1,"why":"‘~로 받아들여지다’는 수동으로 is best taken to be. 주어(How he understood ~)가 ‘받아들여지는’ 쪽이므로 과거분사 taken. taking은 능동이라 맞지 않음.","tr":"그가 옳음과 선을 어떻게 이해했는가는 고대 그리스 사회의 특권 엘리트 계층이 옳음과 선을 어떻게 이해하는 경향이 있었는가에 대한 척도로 가장 잘 여겨진다.","g":"take A to be B = A를 B로 여기다. 수동으로 바꾸면 A is taken to be B (A는 B로 여겨진다).\n예) He is taken to be a doctor. (그는 의사로 여겨진다.)"}],"awk":[{"t":"[[1|Consistent]] though he may be, some of Aristotle's ideas meet us today as [[2|familiar]]. He had no [[3|difficulty]] justifying slavery, for example, and in his [[4|era]], philosophers enjoyed positions of high [[5|privilege]] and influence.","a":2,"fix":"strange","why":"원문은 strange (낯선). 노예 제도를 정당화한 예처럼 오늘날 우리에게 ‘낯설게’ 다가오는 생각이 있다는 흐름이다.\nfamiliar (익숙한)이면 뒤의 for example(예를 들어) 내용과 모순된다.","sp":[{"b":"consistent","m":"일관된","n":"Consistent though he may be = 양보 도치 (형용사 + though + 주어 + may be)","y":"맞음. 그가 일관적일지라도라는 양보의 뜻.","e":"말이 앞뒤가 맞는 것."},{"b":"familiar","m":"익숙한","n":"","y":"어색함. 원문은 strange. 노예 제도를 정당화한 것이 오늘날 익숙할 리 없으므로 뒤의 예와 모순된다.","e":"지금 보면 이상한 생각."},{"b":"difficulty","m":"어려움","n":"have no difficulty (in) ~ing = ~하는 데 어려움이 없다","y":"맞음. 정당화하는 데 어려움이 없었다는 뜻.","e":"아무렇지 않게 할 수 있었음."},{"b":"era","m":"시대","n":"in his era = 그의 시대에","y":"맞음. 아리스토텔레스가 살던 시대.","e":"그 당시."},{"b":"privilege","m":"특권","n":"positions of high privilege = 높은 특권의 지위","y":"맞음. 철학자가 누린 특별한 대우.","e":"높은 대접."}]},{"t":"Because of their practice of contemplation for the highest human good, philosophers were considered [[1|worthy]] to have all the best things in life. Somehow that [[2|assertion]] seems [[3|oddly]] [[4|selfless]]. It [[5|serves]] us to remember that every great thinker is of her own time.","a":4,"fix":"self-serving","why":"원문은 self-serving (자기 잇속만 차리는). 철학자가 철학자는 최고의 것을 가질 만하다고 주장하는 것은 자기에게만 좋은 말이라는 비판이다.\nselfless (사심 없는)이면 oddly(이상하게도)와 어울리지 않고, 뒤에 시대의 한계를 말하는 비판적인 흐름과 모순된다.","sp":[{"b":"worthy","m":"자격이 있는","n":"considered worthy to V = ~할 만하다고 여겨지다","y":"맞음. 최고의 것을 가질 만하다는 평가.","e":"받을 자격이 있다는 생각."},{"b":"assertion","m":"주장","n":"that assertion = 앞 내용을 받는 ‘그 주장’","y":"맞음. 철학자가 최고를 가질 만하다는 주장.","e":"강하게 한 말."},{"b":"oddly","m":"이상하게","n":"oddly + 형용사","y":"맞음. 이상하게도라는 뜻.","e":"어딘가 어색하게."},{"b":"selfless","m":"사심 없는","n":"","y":"어색함. 원문은 self-serving. 철학자들이 자기에게 좋은 주장을 한다는 비판의 흐름과 모순된다.","e":"남을 위한 게 아니라 자기를 위한 말."},{"b":"serves","m":"도움이 되다","n":"It serves us to V = ~하는 것이 우리에게 도움이 된다","y":"맞음. 기억해 두면 이롭다는 뜻.","e":"알아 두면 이득."}]},{"t":"It serves us to [[1|remember]] that every great thinker is of her own [[2|time]] and speaks to a [[3|universal]] audience, and [[4|certainly]] Aristotle is no [[5|exception]].","a":3,"fix":"particular","why":"원문은 particular (특정한). 위대한 사상가도 자기 시대에 속하고 ‘특정한’ 청중에게 말한다는 흐름이다.\nuniversal (보편적인, 모두의)이면 앞의 of her own time(자기 시대에 속함)과 모순된다.","sp":[{"b":"remember","m":"기억하다","n":"serves us to remember = 기억하는 것이 도움이 된다","y":"맞음. 기억해 둘 가치가 있다는 말.","e":"잊지 말아야 할 것."},{"b":"time","m":"시대","n":"of her own time = 자기 시대에 속한","y":"맞음. 사상가는 자기가 살던 시대의 사람.","e":"그 시대의 사람."},{"b":"universal","m":"보편적인","n":"","y":"어색함. 원문은 particular. 자기 시대에 속하므로 특정한 청중에게 말한다는 뜻이어야 한다.","e":"모두가 아니라 그 시대 사람들에게."},{"b":"certainly","m":"확실히","n":"certainly = 틀림없이","y":"맞음. 아리스토텔레스도 확실히 예외가 아니다.","e":"당연히."},{"b":"exception","m":"예외","n":"no exception = 예외가 아니다","y":"맞음. 그도 시대의 한계에서 벗어나지 못함.","e":"특별 대우를 받는 한 사람."}]},{"t":"Human flourishing as he understood it probably would not be nearly as [[1|exclusive]] as we would want it to be today. How he understood right and good is best taken to be an [[2|indicator]] of how the [[3|privileged]] elite of ancient Greek society [[4|tended]] to understand right and good. As a result, for all it does well, it is also deeply [[5|flawed]].","a":1,"fix":"inclusive","why":"원문은 inclusive (포용적인). 오늘날 우리가 원하는 만큼 ‘포용적이지’ 않았을 것이라는 비판이다.\nexclusive (배타적인)이면 not nearly as ~ as(결코 ~만큼은 아니다)와 결합해 ‘우리가 원하는 만큼 배타적이지 않다’가 되어, 뒤의 특권 엘리트의 시각이라는 설명과 모순된다.","sp":[{"b":"exclusive","m":"배타적인","n":"","y":"어색함. 원문은 inclusive. ‘우리가 원하는 만큼 배타적이지 않다’는 말은 특권 엘리트의 좁은 시각이라는 비판과 맞지 않는다.","e":"모두를 품는 쪽이 inclusive."},{"b":"indicator","m":"지표","n":"an indicator of = ~의 지표","y":"맞음. 당시 엘리트 계층의 생각을 보여 주는 표지.","e":"생각을 알려 주는 신호."},{"b":"privileged","m":"특권을 가진","n":"the privileged elite = 특권 엘리트","y":"맞음. 높은 지위를 누린 계층.","e":"특별한 대우를 받은 사람들."},{"b":"tended","m":"경향이 있었다","n":"tend to V = ~하는 경향이 있다","y":"맞음. 옳음과 선을 그렇게 이해하는 경향.","e":"그렇게 생각하기 쉬웠음."},{"b":"flawed","m":"결함이 있는","n":"be deeply flawed = 심각하게 결함이 있다","y":"맞음. 좋은 점에도 불구하고 약점이 크다는 뜻.","e":"금이 간 상태."}]}],"und":[{"q":"<u>Somehow that assertion seems oddly self-serving.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["철학자의 주장은 모든 사람에게 공평하게 이익이 된다","철학자의 주장은 너무 어려워서 이해하기 힘들다","철학자가 최고의 것을 가질 만하다는 주장은 철학자 자신에게만 유리한 말처럼 보인다","철학자의 주장은 하나도 틀린 데가 없다","철학자의 주장은 노예의 이익을 위한 것이다"],"a":2,"why":"앞 내용: 철학자들은 사색을 실천한다는 이유로 삶의 모든 최고의 것을 가질 만하다고 여겨짐.\nself-serving = 자기 잇속만 차리는.\n결론: 철학자가 자기 자신에게 이로운 주장을 한 셈이라는 비판.","e":"반장이 ‘반장은 간식을 더 먹을 자격이 있다’고 말하는 것.","tr":"왠지 그 주장은 이상하게도 자기 잇속만 차리는 것처럼 보인다."},{"q":"<u>every great thinker is of her own time and speaks to a particular audience</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["위대한 사상가는 어느 시대에나 모든 사람에게 똑같이 통한다","위대한 사상가는 자기 시대를 무시하고 먼 미래만 이야기한다","위대한 사상가도 자기 시대에 속해 있고 특정한 사람들을 향해 말한다","위대한 사상가는 오직 여성 청중에게만 말한다","위대한 사상가는 청중이 없어도 혼자서 연구한다"],"a":2,"why":"앞 내용: 아리스토텔레스의 생각이 오늘날 낯선 부분이 있음.\nof her own time = 자기 시대에 속한. particular audience = 특정한 청중.\n결론: 그의 생각도 시대와 청중의 한계 안에 있었음.","e":"옛날 교과서가 그 시대 학생들을 위해 쓰인 것과 같은 이치.","tr":"그것은 ‘우리’가 모든 위대한 사상가는 그들 자신만의 시대에 속해 있고 특정한 청중들에게 말한다는 것을 기억하는 데 도움이 되며, 확실히 아리스토텔레스도 예외는 아니다."},{"q":"<u>How he understood right and good is best taken to be an indicator of how the privileged elite of ancient Greek society tended to understand right and good.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["그의 생각은 모든 그리스 시민의 생각과 똑같았다","그의 생각은 상류층의 생각과 정반대였다","그의 생각은 현대 사회가 이미 완전히 받아들였다","그의 생각은 상류층을 비판하려고 만든 것이다","그의 옳고 그름에 대한 생각은 당시 상류층이 어떻게 생각했는지를 잘 보여 주는 단서이다"],"a":4,"why":"앞 내용: 그의 인간 번영 개념은 오늘날만큼 포용적이지 않았을 것임.\nindicator = 지표, 단서. privileged elite = 특권 엘리트.\n결론: 그의 윤리는 특권 계층의 시각을 반영함.","e":"한 사람의 일기를 보고 그 시대 상류층의 생활을 짐작하는 것.","tr":"그가 옳음과 선을 어떻게 이해했는가는 고대 그리스 사회의 특권 엘리트 계층이 옳음과 선을 어떻게 이해하는 경향이 있었는가에 대한 척도로 가장 잘 여겨진다."},{"q":"<u>for all it does well, it is also deeply flawed</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["그것은 잘하는 점이 많으므로 결함이 전혀 없다","그것이 잘하는 점이 많은데도 큰 결함 또한 가지고 있다","그것은 잘하는 점이 하나도 없고 결함만 가득하다","그것은 결함이 있기 때문에 잘하는 점도 모두 사라졌다","그것은 결함을 고치려고 일부러 잘하는 일을 했다"],"a":1,"why":"앞 내용: 그의 윤리는 특권 엘리트의 이해를 반영하는 면이 있음.\nfor all ~ = ~에도 불구하고. deeply flawed = 심각하게 결함이 있는.\n결론: 장점은 있지만 시대와 계급의 한계라는 큰 약점이 있음.","e":"시험 점수는 좋은데 풀이 과정에 큰 오류가 있는 답안지 같은 것.","tr":"그 결과, 그것의 장점에도 불구하고, 그것은 또한 심각하게 결함이 있다."}]},"2610-29":{"voc":[{"q":"The early hurdles were once very high, and many people fell before <u>clearing</u> the first few.","ask":"이 글에서 clearing의 뜻으로 가장 알맞은 것은?","ch":["(장애물을) 넘다, 통과하다","청소하다","치우다","설명하다","지우다"],"a":0,"why":"clear는 ‘깨끗한’ 말고도 ‘(장애물을) 뛰어넘다, 통과하다’의 뜻이 있음.\n지문: before clearing the first few = 처음 몇 개를 넘기 전에.\n앞의 hurdle(허들)과 연결해 보면 ‘허들을 넘다’가 자연스러움.","e":"육상 선수가 허들을 걸리지 않고 넘는 것.","tr":"초기의 허들은 한때 매우 높았고, 많은 사람들은 처음 몇 개를 넘기 전에 넘어졌다.","alt":"get over (넘다), jump (뛰어넘다) / clear the table (식탁을 치우다)"},{"q":"<u>Demographically</u>, humankind was living close to a state of nature…","ask":"demographically의 뜻으로 알맞은 것은?","ch":["지리학적으로","경제적으로","역사적으로","도덕적으로","인구 통계학적으로"],"a":4,"why":"demographic = 인구(통계)의, demographically = 인구 통계학적으로 (인구의 수, 나이, 출생, 사망 등을 따지는 관점).\n지문: Demographically, humankind was living close to a state of nature = 인구 면에서 보면 인류는 자연 상태에 가깝게 살았다.\n뒤에 나오는 유아 사망률 이야기와 이어짐.","e":"인구가 몇 명이고 몇 살이 많은지 숫자로 따지는 것.","tr":"인구 통계학적으로, 인류는 자연 상태에 가깝게 살았었고, 자연은 생명을 극도로 낭비한다.","alt":"demography (인구학)"},{"q":"…nature is extremely <u>wasteful</u> of life.","ask":"wasteful의 뜻으로 알맞은 것은?","ch":["낭비하는","아끼는","보호하는","키우는","나누는"],"a":0,"why":"wasteful = 낭비하는 (waste ‘낭비하다’ + -ful ‘~이 가득한’).\n지문: nature is extremely wasteful of life = 자연은 생명을 극도로 낭비한다.\n씨앗이 많아도 나무가 되는 것은 하나뿐이라는 예가 이어짐.","e":"음식을 많이 사서 대부분 버리는 것.","tr":"인구 통계학적으로, 인류는 자연 상태에 가깝게 살았었고, 자연은 생명을 극도로 낭비한다.","alt":"extravagant (낭비하는) / 반의어 thrifty (절약하는)"},{"q":"Almost a quarter of baboons born in the wild die before they are a year old, which is fairly <u>typical</u> for primates.","ask":"typical의 반의어로 알맞은 것은?","ch":["common (흔한)","normal (보통의)","ordinary (평범한)","standard (표준적인)","unusual (특이한)"],"a":4,"why":"typical = 전형적인, 흔한 ↔ unusual = 특이한, 드문.\ncommon, normal, ordinary, standard는 모두 ‘보통’의 뜻이라 반의어가 아님.\n지문: fairly typical for primates = 영장류에게 꽤 전형적임.","e":"누구나 다 그렇다고 할 만한 흔한 일이 typical.","tr":"야생에서 태어난 개코원숭이의 거의 4분의 1이 한 살이 되기 전에 죽는데, 이것은 영장류에게 꽤 전형적이다.","alt":"usual (평소의), characteristic (특징적인) / 반의어 unusual, rare (드문)"},{"q":"<u>Infant</u> mortality rates for humans in pre-modern agricultural societies were similar to…","ask":"infant의 뜻으로 알맞은 것은?","ch":["노인","청소년","환자","농부","유아, 갓난아기"],"a":4,"why":"infant = 유아, 갓난아기. 뒤의 mortality(사망률)와 합쳐 infant mortality = 유아 사망률.\n지문: Infant mortality rates = 유아 사망률.\n글의 앞쪽에서 ‘한 살이 되기 전에 죽는다’고 한 내용과 이어짐.","e":"이제 막 태어난 아기를 부르는 말.","tr":"전근대 농업 사회에서 인간의 유아 사망률은 유인원의 그것과 비슷했고, 때로는 더 높았다.","alt":"baby (아기), newborn (신생아)"},{"q":"Infant <u>mortality</u> rates for humans in pre-modern agricultural societies were similar to…","ask":"mortality의 뜻으로 알맞은 것은?","ch":["출산율","성장률","실업률","생존율","사망률, 죽음"],"a":4,"why":"mortality = 사망률, 죽음. (형용사 mortal은 ‘죽을 운명의’.)\n지문: infant mortality rates = 유아 사망률.\n출산율(birth rate)이나 생존율(survival rate)과 헷갈리지 않기.","e":"‘몇 명이 죽었나’를 숫자로 나타낸 것.","tr":"전근대 농업 사회에서 인간의 유아 사망률은 유인원의 그것과 비슷했고, 때로는 더 높았다.","alt":"death rate (사망률) / 반의어 survival (생존)"},{"q":"…a quarter of whom failed to reach their first birthday, while another quarter didn't live long enough to <u>reproduce</u>…","ask":"reproduce의 뜻으로 알맞은 것은?","ch":["복사하다","자손을 낳다, 번식하다","사라지다","이동하다","경쟁하다"],"a":1,"why":"reproduce = 번식하다, 자손을 낳다. (‘복제하다, 재현하다’의 뜻도 있음.)\n지문: didn't live long enough to reproduce = 자손을 낳을 만큼 오래 살지 못했다.\n생물이 이야기라서 ‘번식’의 뜻.","e":"동물이 새끼를 낳아 수를 늘리는 것.","tr":"우리의 수렵 채집 조상들에게도 사정은 별로 나을 것이 없었는데, 그들 중 4분의 1이 자신들의 첫 번째 생일에 이르지 못했고, 19세기까지 거의 모든 곳에서 또 다른 4분의 1은 자손을 낳을 만큼 충분히 오래 살지 못했다.","alt":"breed (번식하다) / reproduction (번식, 복제)"},{"q":"Things were little better for our hunter-gatherer <u>ancestors</u>…","ask":"ancestor의 반의어로 알맞은 것은?","ch":["forefather (조상)","descendant (후손)","predecessor (선조)","elder (연장자)","founder (설립자)"],"a":1,"why":"ancestor = 조상 ↔ descendant = 후손, 자손.\nforefather, predecessor, elder, founder는 모두 앞선 사람을 가리켜 반의어가 아님.\n지문: our hunter-gatherer ancestors = 우리의 수렵 채집 조상들.","e":"할머니의 할머니는 ancestor, 내 손주는 descendant.","tr":"우리의 수렵 채집 조상들에게도 사정은 별로 나을 것이 없었는데, 그들 중 4분의 1이 자신들의 첫 번째 생일에 이르지 못했고, 19세기까지 거의 모든 곳에서 또 다른 4분의 1은 자손을 낳을 만큼 충분히 오래 살지 못했다.","alt":"forefather (조상) / 반의어 descendant, offspring (자손)"}],"find":[{"s":"The writer compares survival to a race with a hurdle each year.","a":true,"why":"1문장: survival as a race in which a hurdle has to be jumped every year (생존을 매년 하나의 허들을 뛰어넘어야 하는 경주로).","e":"허들 경주 비유로 시작함."},{"s":"The early hurdles were low, so most people cleared them easily.","a":false,"why":"2문장: The early hurdles were once very high, and many people fell (초기 허들은 매우 높았고 많은 사람이 넘어짐). 낮았다는 말은 반대.","e":"처음 몇 개에서 많이 쓰러졌음."},{"s":"Humankind once lived close to a state of nature.","a":true,"why":"3문장: humankind was living close to a state of nature (인류는 자연 상태에 가깝게 살았음).","e":"문명이 발달하기 전 이야기."},{"s":"The writer says nature takes great care to protect life.","a":false,"why":"3문장: nature is extremely wasteful of life (자연은 생명을 극도로 낭비함). 아낀다는 말은 반대.","e":"자연은 많이 만들고 많이 잃음."},{"s":"Only one of many fig seeds is likely to become a fig tree.","a":true,"why":"4문장: From only a very small number of figs will even one of many seeds become a fig tree (극소수의 무화과에서 나온 씨앗들 중 단 하나만이 나무가 됨).","e":"씨앗은 많아도 나무는 적음."},{"s":"Almost a quarter of wild baboons die before they are one year old.","a":true,"why":"5문장: Almost a quarter of baboons born in the wild die before they are a year old (야생 개코원숭이의 거의 4분의 1이 한 살 전에 죽음).","e":"영장류에게 흔한 일."},{"s":"Human infant mortality in pre-modern farming societies was much lower than that of apes.","a":false,"why":"6문장: similar to, and sometimes higher than those of apes (유인원과 비슷하거나 때로는 더 높음). 훨씬 낮았다는 말은 반대.","e":"사람도 유인원과 비슷한 수준."},{"s":"About a quarter of hunter-gatherer babies did not reach their first birthday.","a":true,"why":"7문장: a quarter of whom failed to reach their first birthday (수렵 채집 조상 중 4분의 1이 첫 생일에 이르지 못함).","e":"그다음 4분의 1은 자손을 낳기 전에 죽음."},{"s":"Until the nineteenth century, almost everyone lived long enough to reproduce.","a":false,"why":"7문장: another quarter didn't live long enough to reproduce just about everywhere until the nineteenth century (19세기까지 거의 모든 곳에서 또 다른 4분의 1이 자손을 낳을 만큼 살지 못함). 거의 모두가 살았다는 말은 반대.","e":"절반 가까이가 어른이 되기 전에 죽었음."},{"s":"If infant death had been lower, the growth in human population would have happened much earlier.","a":true,"why":"8문장: Had it been otherwise, the huge recent growth in human population would have occurred much earlier (그렇지 않았다면 최근의 인구 증가는 훨씬 더 일찍 일어났을 것임).","e":"옛날에는 사망률이 높아 인구가 천천히 늘었음."}],"eob":[{"s":"You might think of survival as a race in which a hurdle ( ______ ) to be jumped every year.","ch":["has","have"],"a":0,"why":"관계대명사 which 뒤에서 주어는 a hurdle (단수)이므로 동사는 has. a hurdle has to be jumped = 허들이 뛰어넘어져야 한다(수동).","tr":"여러분은 생존을 매년 하나의 허들을 뛰어넘어야 하는 경주라고 생각할지도 모른다.","g":"a race in which ~ 처럼 전치사 + 관계대명사 뒤에는 완전한 문장이 와요. 동사의 수는 그 문장의 주어에 맞춰요.\n예) This is the room in which a girl sleeps. (여기는 한 소녀가 자는 방이다.)"},{"s":"Many people fell ( ______ ) clearing the first few.","ch":["during","before"],"a":1,"why":"‘처음 몇 개를 넘기 전에 넘어졌다’이므로 before. during은 뒤에 기간을 나타내는 명사가 와야 하고 ‘~하는 동안’의 뜻이라 맞지 않음.","tr":"초기의 허들은 한때 매우 높았고, 많은 사람들은 처음 몇 개를 넘기 전에 넘어졌다.","g":"before + ~ing = ~하기 전에. during은 뒤에 명사(during the war)가 와요.\n예) Wash your hands before eating. (먹기 전에 손을 씻어라.)"},{"s":"From only a very small number of figs ( ______ ) even one of many seeds become a fig tree.","ch":["will","is"],"a":0,"why":"‘only + 부사구’가 문장 맨 앞에 오면 주어와 동사가 도치되어 will even one of many seeds become의 어순이 됨. will은 미래의 조동사로 뒤에 동사원형 become이 옴.","tr":"극소수의 무화과로부터 나오는 많은 씨앗들 중 단 하나만이 무화과 나무가 될 것이다.","g":"only가 붙은 부사(구)가 문장 맨 앞에 나오면 조동사가 주어 앞으로 가요 (도치).\n예) Only then did I understand it. (그때서야 나는 그것을 이해했다.)"},{"s":"Almost a quarter of baboons born in the wild die before they ( ______ ) a year old.","ch":["are","were being"],"a":0,"why":"‘한 살이 되기 전에’는 시간 부사절이므로 현재 시제 are. 뒤에 a year old(형용사구)가 와서 be동사 are가 필요함.","tr":"야생에서 태어난 개코원숭이의 거의 4분의 1이 한 살이 되기 전에 죽는데, 이것은 영장류에게 꽤 전형적이다.","g":"before, after, when 같은 시간 부사절에서는 미래의 뜻이어도 현재 시제를 써요.\n예) Call me before you leave. (떠나기 전에 나에게 전화해라.)"},{"s":"( ______ ) it been otherwise, the huge recent growth in human population would have occurred much earlier.","ch":["Has","Had"],"a":1,"why":"if가 생략되어 도치된 가정법 과거완료. If it had been otherwise = Had it been otherwise. 결과절에 would have occurred가 오므로 Had.","tr":"만약 그렇지 않았더라면, 최근의 엄청난 인구 증가는 훨씬 더 일찍 일어났었을 것이다.","g":"가정법 과거완료의 if를 생략하면 Had + 주어 + p.p.가 돼요.\n예) Had I known, I would have helped. (내가 알았더라면 도왔을 것이다.)"}],"awk":[{"t":"You might think of survival as a race in which a hurdle has to be [[1|jumped]] every year. The early hurdles were [[2|once]] very [[3|low]], and many people [[4|fell]] before [[5|clearing]] the first few.","a":3,"fix":"high","why":"원문은 high (높은). 허들이 매우 높았기 때문에 많은 사람이 넘어졌다는 흐름이다.\nlow (낮은)이면 뒤의 many people fell(많은 사람이 넘어짐)과 모순된다.","sp":[{"b":"jumped","m":"뛰어넘어진","n":"has to be jumped = 뛰어넘어져야 한다 (수동)","y":"맞음. 허들은 뛰어넘는 것.","e":"허들을 넘음."},{"b":"once","m":"한때","n":"once = 한때, 예전에","y":"맞음. 과거 어느 시기를 가리킴.","e":"옛날에."},{"b":"low","m":"낮은","n":"","y":"어색함. 원문은 high. 허들이 낮았다면 많은 사람이 넘어졌다는 내용과 모순된다.","e":"높아야 넘어지기 쉬움."},{"b":"fell","m":"넘어졌다","n":"fall (fell, fallen) = 넘어지다","y":"맞음. 허들에 걸려 넘어졌다는 비유.","e":"생존하지 못했다는 뜻."},{"b":"clearing","m":"넘기","n":"before clearing = 넘기 전에","y":"맞음. 처음 몇 개를 통과하기 전.","e":"장애물을 지나가는 것."}]},{"t":"Demographically, humankind was living close to a state of nature, and nature is extremely [[1|wasteful]] of life. From only a very [[2|small]] number of figs will even one of many seeds become a fig [[3|tree]]. Almost a quarter of baboons [[4|born]] in the wild [[5|survive]] before they are a year old.","a":5,"fix":"die","why":"원문은 die (죽다). 야생 개코원숭이의 거의 4분의 1이 한 살이 되기 전에 죽는다는 뜻이다.\nsurvive (살아남다)이면 ‘자연은 생명을 낭비한다’는 글의 흐름과 모순된다.","sp":[{"b":"wasteful","m":"낭비하는","n":"wasteful of = ~을 낭비하는","y":"맞음. 생명을 아끼지 않고 잃는 자연.","e":"많이 만들고 많이 잃음."},{"b":"small","m":"적은","n":"a small number of = 적은 수의","y":"맞음. 극소수의 무화과.","e":"아주 적은 수."},{"b":"tree","m":"나무","n":"become a fig tree = 무화과 나무가 되다","y":"맞음. 씨앗 중 하나만 나무가 됨.","e":"싹이 터서 자란 모습."},{"b":"born","m":"태어난","n":"born in the wild = 야생에서 태어난","y":"맞음. 과거분사가 baboons를 꾸밈.","e":"야생에서 태어난 개코원숭이."},{"b":"survive","m":"살아남다","n":"","y":"어색함. 원문은 die. 글의 흐름이 ‘자연은 생명을 낭비한다’이므로 살아남는다는 말은 모순이다.","e":"죽는 비율이 높다는 이야기."}]},{"t":"Infant [[1|mortality]] rates for humans in pre-modern agricultural societies were [[2|similar]] to, and sometimes higher than, those of apes. Things were little [[3|worse]] for our hunter-gatherer [[4|ancestors]], a quarter of whom [[5|failed]] to reach their first birthday.","a":3,"fix":"better","why":"원문은 little better (별로 나을 것이 없었다). 농업 사회처럼 수렵 채집 사회도 유아 사망률이 높았다는 흐름이다.\nlittle worse이면 ‘별로 나쁘지 않았다’가 되어 뒤의 4분의 1이 첫 생일에 이르지 못했다는 내용과 모순된다.","sp":[{"b":"mortality","m":"사망률","n":"infant mortality = 유아 사망률","y":"맞음. 아기의 죽음 비율.","e":"죽는 비율."},{"b":"similar","m":"비슷한","n":"similar to = ~와 비슷한","y":"맞음. 유인원과 비슷한 수준.","e":"거의 같음."},{"b":"worse","m":"더 나쁜","n":"","y":"어색함. 원문은 better. little better = 별로 나을 게 없는. little worse로 바꾸면 뒤의 높은 사망률 설명과 모순된다.","e":"사정이 낫지 않았다는 뜻."},{"b":"ancestors","m":"조상","n":"our ancestors = 우리의 조상","y":"맞음. 수렵 채집 시대의 사람들.","e":"옛날 사람들."},{"b":"failed","m":"못했다","n":"fail to V = ~하지 못하다","y":"맞음. 첫 생일에 이르지 못함.","e":"도달하지 못함."}]},{"t":"Things were little better for our hunter-gatherer ancestors, a quarter of whom failed to reach their first birthday, while another quarter didn't live long enough to [[1|reproduce]] just about everywhere until the nineteenth century. Had it been [[2|otherwise]], the [[3|huge]] recent [[4|growth]] in human population would have occurred much [[5|later]].","a":5,"fix":"earlier","why":"원문은 earlier (더 일찍). 사망률이 낮았다면 인구 증가가 훨씬 더 일찍 일어났을 것이라는 가정이다.\nlater (더 늦게)이면 ‘사망률이 낮았는데 증가가 더 늦다’가 되어 논리가 맞지 않는다.","sp":[{"b":"reproduce","m":"자손을 낳다","n":"live long enough to V = ~할 만큼 오래 살다","y":"맞음. 자손을 낳을 나이까지 못 살았다는 뜻.","e":"아이를 낳는 것."},{"b":"otherwise","m":"그렇지 않다면","n":"Had it been otherwise = 그렇지 않았다면","y":"맞음. 사망률이 그렇게 높지 않았다면.","e":"반대의 경우."},{"b":"huge","m":"엄청난","n":"the huge recent growth = 최근의 엄청난 증가","y":"맞음. 최근 인구가 크게 늘었다는 사실.","e":"아주 큰."},{"b":"growth","m":"증가","n":"growth in population = 인구 증가","y":"맞음. 사람 수가 늘어난 것.","e":"커지는 것."},{"b":"later","m":"더 늦게","n":"","y":"어색함. 원문은 earlier. 사망률이 낮았다면 인구 증가가 더 일찍 일어났을 것이므로 later는 모순이다.","e":"그렇지 않았다면 더 빨리 늘었을 것."}]}],"und":[{"q":"<u>Almost a quarter of baboons born in the wild die before they are a year old, which is fairly typical for primates.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["개코원숭이는 다른 영장류보다 훨씬 오래 산다","야생 개코원숭이는 한 살이 되기 전에 꽤 많이 죽으며, 이는 영장류에게 드문 일이 아니다","개코원숭이만 유독 아기가 많이 죽는다","야생 개코원숭이는 한 살이 되면 모두 죽는다","영장류의 아기는 대부분 한 살을 넘기지 못한다"],"a":1,"why":"앞 내용: 자연은 생명을 극도로 낭비한다.\ntypical for primates = 영장류에게 전형적인(흔한).\n결론: 어린 개체가 많이 죽는 일이 자연에서는 흔하다는 예.","e":"10마리 중 2~3마리가 첫 해에 죽는 것이 보통이라는 것.","tr":"야생에서 태어난 개코원숭이의 거의 4분의 1이 한 살이 되기 전에 죽는데, 이것은 영장류에게 꽤 전형적이다."},{"q":"<u>Things were little better for our hunter-gatherer ancestors</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["수렵 채집 조상들은 농업 사회보다 훨씬 안전하게 살았다","수렵 채집 조상들은 유인원보다 훨씬 형편이 나빴다","수렵 채집 조상들은 농업을 하지 않아 모두 굶어 죽었다","수렵 채집 조상들은 오늘날과 같은 환경에서 살았다","수렵 채집 조상들의 형편도 농업 사회보다 크게 나을 것이 없었다"],"a":4,"why":"앞 내용: 농업 사회의 유아 사망률은 유인원과 비슷하거나 더 높았음.\nlittle better = 별로 나을 것이 없는.\n결론: 수렵 채집 사회도 유아 사망률이 높았음.","e":"한 곳이 어려웠는데 다른 곳도 별 차이 없이 어려웠다는 것.","tr":"우리의 수렵 채집 조상들에게도 사정은 별로 나을 것이 없었는데, 그들 중 4분의 1이 자신들의 첫 번째 생일에 이르지 못했고, 19세기까지 거의 모든 곳에서 또 다른 4분의 1은 자손을 낳을 만큼 충분히 오래 살지 못했다."},{"q":"<u>Had it been otherwise, the huge recent growth in human population would have occurred much earlier.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["옛날에는 사망률이 낮아서 인구가 일찍 늘었다","옛날에도 인구가 지금처럼 빠르게 늘었다","옛날에 아기들이 지금처럼 잘 살아남았다면 인구는 훨씬 일찍 크게 늘었을 것이다","인구 증가는 사망률과 아무 관계가 없다","사망률이 높아져야 인구가 일찍 늘어난다"],"a":2,"why":"앞 내용: 옛날에는 4분의 1은 첫 생일 전에, 또 4분의 1은 어른이 되기 전에 죽었음.\notherwise = 그렇지 않았다면 (사망률이 낮았다면).\n결론: 사망률이 높았기 때문에 인구 증가가 늦게 일어났다.","e":"물이 새는 양동이는 천천히 차오르는 것.","tr":"만약 그렇지 않았더라면, 최근의 엄청난 인구 증가는 훨씬 더 일찍 일어났었을 것이다."}]},"2610-30":{"voc":[{"q":"A study by Eva McMahan… confirmed the <u>dominance</u> of nonverbal signals.","ask":"dominance의 뜻으로 알맞은 것은?","ch":["약함","우위, 지배적임","평등","부족","다양성"],"a":1,"why":"dominance = 우위, 지배 (동사 dominate ‘지배하다’의 명사형).\n지문: the dominance of nonverbal signals = 비언어적 신호의 우위.\n말보다 표정, 몸짓이 더 큰 힘을 가진다는 뜻.","e":"반에서 가장 목소리가 큰 아이가 분위기를 이끄는 것.","tr":"발화 의사소통 교수인 Eva McMahan의 한 연구는 비언어적 신호들의 우위를 확인했다.","alt":"superiority (우세) / 형용사 dominant (지배적인)"},{"q":"The phenomenon, however, was especially <u>pronounced</u>…","ask":"이 글에서 pronounced의 뜻으로 가장 알맞은 것은?","ch":["발음된","숨겨진","약한","금지된","뚜렷한, 두드러진"],"a":4,"why":"pronounced는 ‘발음된’ 말고도 ‘뚜렷한, 두드러진’의 뜻이 있음.\n지문: especially pronounced = 특히 두드러진.\n그 현상이 모순된 메시지 상황에서 더 크게 드러났다는 말.","e":"한눈에 확 눈에 띄는 차이.","tr":"그러나, 그 현상은 성인들이 모순되는 메시지들이 있는 상황, 즉 언어적 메시지와 비언어적 메시지의 내용들이 일치하지 않는 상황에 처해 있는 자신을 발견했을 때 특히 두드러졌다.","alt":"noticeable (눈에 띄는), marked (현저한) / 동사 pronounce (발음하다)"},{"q":"…situations with <u>conflicting</u> messages (i.e., situations in which the contents of the verbal and nonverbal messages differ).","ask":"conflicting의 뜻으로 알맞은 것은?","ch":["서로 일치하는","새로운","서로 모순되는, 충돌하는","반복되는","친절한"],"a":2,"why":"conflicting = 서로 충돌하는, 모순되는 (conflict ‘충돌’에서 온 말).\n지문: conflicting messages = 모순되는 메시지. 바로 뒤에 ‘내용이 다른(differ)’이라는 설명이 옴.","e":"말은 ‘좋아’인데 얼굴은 ‘싫어’인 상황.","tr":"그러나, 그 현상은 성인들이 모순되는 메시지들이 있는 상황, 즉 언어적 메시지와 비언어적 메시지의 내용들이 일치하지 않는 상황에 처해 있는 자신을 발견했을 때 특히 두드러졌다.","alt":"contradictory (모순되는) / 반의어 consistent (일치하는)"},{"q":"Attempts to <u>manipulate</u> another person verbally are therefore likely to fail…","ask":"manipulate의 뜻으로 알맞은 것은?","ch":["(교묘하게) 조종하다","도와주다","가르치다","칭찬하다","위로하다"],"a":0,"why":"manipulate = (사람이나 상황을) 교묘하게 조종하다.\n지문: manipulate another person verbally = 다른 사람을 말로 조종하다.\n좋은 뜻이 아니라 상대를 자기 뜻대로 움직이려는 것.","e":"말솜씨로 친구가 내 부탁을 들어주게 만들려는 것.","tr":"그러므로 만약 동반되는 비언어적 의사소통이 발화된 메시지와 일치하지 않는다면 다른 사람을 언어적으로 조종하려는 시도는 실패할 가능성이 있다.","alt":"control (통제하다), influence (영향을 주다)"},{"q":"Attempts to manipulate another person verbally are therefore likely to <u>fail</u> if the accompanying nonverbal communication does not <u>match</u> the spoken message.","ask":"match와 바꿔 쓸 수 있는 말은?","ch":["agree with (~와 일치하다)","differ from (~와 다르다)","depend on (~에 달려 있다)","apply to (~에 적용되다)","object to (~에 반대하다)"],"a":0,"why":"match = ~와 일치하다, 어울리다 (= agree with, fit).\n지문: does not match the spoken message = 말한 메시지와 일치하지 않는다.\ndiffer from은 반대의 뜻이라 알맞지 않음.","e":"신발 한 켤레가 짝이 맞는 것.","tr":"그러므로 만약 동반되는 비언어적 의사소통이 발화된 메시지와 일치하지 않는다면 다른 사람을 언어적으로 조종하려는 시도는 실패할 가능성이 있다.","alt":"correspond to (일치하다) / 반의어 differ from, conflict with"},{"q":"Attempts to manipulate another person verbally are therefore <u>likely</u> to fail…","ask":"이 글에서 likely의 뜻으로 알맞은 것은?","ch":["~할 수 없는","~하고 싶어 하는","~해야만 하는","~하기로 약속한","~할 가능성이 높은"],"a":4,"why":"be likely to V = ~할 가능성이 높다, ~할 것 같다.\n지문: are likely to fail = 실패할 가능성이 높다.\n같은 뜻의 말: probably (아마도).","e":"하늘이 컴컴하면 ‘비가 올 것 같다’.","tr":"그러므로 만약 동반되는 비언어적 의사소통이 발화된 메시지와 일치하지 않는다면 다른 사람을 언어적으로 조종하려는 시도는 실패할 가능성이 있다.","alt":"probable (있음직한) / 반의어 unlikely (가능성이 낮은)"},{"q":"When somebody tells you that they enjoy spending time with you, but you notice how they are looking away and are forcing a smile, you are probably less <u>inclined</u> to believe their words.","ask":"inclined의 뜻으로 알맞은 것은?","ch":["~할 수 있는","~하고 싶은 마음이 드는","~해야 하는","~을 두려워하는","~에서 벗어난"],"a":1,"why":"be inclined to V = ~하는 경향이 있다, ~하고 싶은 마음이 들다.\n지문: less inclined to believe = 믿고 싶은 마음이 덜 드는.\n앞에 less(덜)가 있어 ‘덜 믿게 된다’가 됨.","e":"마음이 그쪽으로 기울어 있는 상태.","tr":"누군가가 여러분에게 그들이 여러분과 시간을 보내는 것을 즐긴다고 말하지만 그들이 눈길을 돌리고 억지웃음을 짓고 있는 모습을 여러분이 알아차리면 여러분은 아마도 그들의 말을 덜 믿게 될 것이다.","alt":"tend (~하는 경향이 있다) / 명사 inclination (경향)"},{"q":"…you notice how they are looking away and are <u>forcing</u> a smile…","ask":"force a smile의 뜻으로 알맞은 것은?","ch":["활짝 웃다","몰래 웃다","크게 웃다","소리 내어 웃다","억지로 웃다"],"a":4,"why":"force = 억지로 ~하게 하다. force a smile = 억지웃음을 짓다.\n지문: forcing a smile = 억지로 웃음을 지으며.\n진짜 즐거운 것이 아니라 일부러 웃는 모습.","e":"사진 찍을 때 기분이 안 좋은데 억지로 웃는 얼굴.","tr":"누군가가 여러분에게 그들이 여러분과 시간을 보내는 것을 즐긴다고 말하지만 그들이 눈길을 돌리고 억지웃음을 짓고 있는 모습을 여러분이 알아차리면 여러분은 아마도 그들의 말을 덜 믿게 될 것이다.","alt":"fake a smile (거짓으로 웃다)"}],"find":[{"s":"A study confirmed that nonverbal signals have a dominant role.","a":true,"why":"1문장: confirmed the dominance of nonverbal signals (비언어적 신호의 우위를 확인함).","e":"말보다 몸짓과 표정이 더 큰 힘을 가짐."},{"s":"The study was done by a professor of speech communication.","a":true,"why":"1문장: Eva McMahan, professor of speech communication (발화 의사소통 교수).","e":"연구자의 직업이 소개됨."},{"s":"The phenomenon was weakest when verbal and nonverbal messages conflicted.","a":false,"why":"2문장: especially pronounced when adults found themselves in situations with conflicting messages (모순되는 메시지 상황에서 특히 두드러짐). 가장 약했다는 말은 반대.","e":"메시지가 어긋날 때 더 뚜렷했음."},{"s":"Conflicting messages are situations in which the verbal and nonverbal contents differ.","a":true,"why":"2문장: situations in which the contents of the verbal and nonverbal messages differ (언어적, 비언어적 메시지의 내용이 다른 상황).","e":"말과 몸짓이 따로 노는 상황."},{"s":"Verbal manipulation is likely to succeed when the nonverbal message does not match.","a":false,"why":"3문장: likely to fail if the accompanying nonverbal communication does not match the spoken message (비언어적 의사소통이 일치하지 않으면 실패할 가능성이 큼). 성공한다는 말은 반대.","e":"어긋나면 말로 조종하기 어려움."},{"s":"People trust nonverbal messages more than verbal ones.","a":true,"why":"4문장: people trust nonverbal messages more than verbal ones (사람들은 비언어적 메시지를 언어적인 것보다 더 신뢰함).","e":"그래서 말이 통하지 않음."},{"s":"Someone says they enjoy your company while looking away, and you tend to believe the words more.","a":false,"why":"5문장: you are probably less inclined to believe their words (그들의 말을 덜 믿게 됨). 더 믿는다는 말은 반대.","e":"눈을 피하면 말의 힘이 약해짐."},{"s":"Forcing a smile is given as a sign that makes us doubt someone's words.","a":true,"why":"5문장: you notice how they are looking away and are forcing a smile, you are probably less inclined to believe their words (눈길을 돌리고 억지웃음을 지으면 말을 덜 믿게 됨).","e":"억지웃음은 거짓 신호로 읽힘."},{"s":"In the second example, the colleague showed a displeased expression while saying they were happy to take over the workload.","a":true,"why":"6문장: your colleague tells you with a displeased expression that they were happy to take over your workload (언짢은 표정으로 업무를 떠맡게 되어 즐거웠다고 말함).","e":"표정과 말이 모순됨."},{"s":"In the second example, you believe your colleague enjoyed replacing you.","a":false,"why":"7문장: You might not believe that they enjoyed replacing you (그들이 대신하기를 즐거워했다는 것을 믿지 않을 것임). 믿는다는 말은 반대.","e":"언짢은 표정 때문에 말이 의심스러움."}],"eob":[{"s":"A study by Eva McMahan, professor of speech communication, ( ______ ) the dominance of nonverbal signals.","ch":["confirmed","confirming"],"a":0,"why":"문장의 주어는 A study이고 이 문장에 동사가 없으므로 과거 시제 동사 confirmed가 필요함. confirming은 동사 역할을 할 수 없음.","tr":"발화 의사소통 교수인 Eva McMahan의 한 연구는 비언어적 신호들의 우위를 확인했다.","g":"한 문장에는 주어에 맞는 동사(정동사)가 꼭 하나 있어야 해요. -ing형만 쓰면 동사가 되지 못해요.\n예) The study showed a result. (그 연구는 결과를 보여 주었다.)"},{"s":"…situations in ( ______ ) the contents of the verbal and nonverbal messages differ.","ch":["which","what"],"a":0,"why":"앞에 선행사 situations가 있고, 뒤는 완전한 문장(the contents ~ differ)이므로 전치사 + 관계대명사 in which. what은 선행사를 포함하므로 앞에 선행사가 있으면 쓰지 않음.","tr":"그러나, 그 현상은 성인들이 모순되는 메시지들이 있는 상황, 즉 언어적 메시지와 비언어적 메시지의 내용들이 일치하지 않는 상황에 처해 있는 자신을 발견했을 때 특히 두드러졌다.","g":"선행사가 있고 뒤에 완전한 문장이 오면 전치사 + which를 써요. what은 선행사가 필요 없는 관계대명사예요.\n예) This is the house in which I live. (이곳이 내가 사는 집이다.)"},{"s":"Attempts to manipulate another person verbally ( ______ ) likely to fail if the accompanying nonverbal communication does not match the spoken message.","ch":["is","are"],"a":1,"why":"주어는 복수 Attempts (to manipulate ~는 Attempts를 꾸미는 부분)이므로 동사는 are. 가까이 있는 another person(단수)에 속지 않기.","tr":"그러므로 만약 동반되는 비언어적 의사소통이 발화된 메시지와 일치하지 않는다면 다른 사람을 언어적으로 조종하려는 시도는 실패할 가능성이 있다.","g":"주어가 복수 명사이면 뒤의 수식어구에 상관없이 복수 동사를 써요.\n예) The books on the desk are mine. (책상 위의 책들은 내 것이다.)"},{"s":"This is ( ______ ) people trust nonverbal messages more than verbal ones.","ch":["because","because of"],"a":0,"why":"뒤에 people trust nonverbal messages라는 절(주어 + 동사)이 오므로 접속사 because. because of는 뒤에 명사(구)가 와야 함.","tr":"이는 사람들이 비언어적 메시지들을 언어적인 것들보다 더 많이 신뢰하기 때문이다.","g":"because + 절(주어 + 동사), because of + 명사(구).\n예) We stayed home because it rained. (비가 와서 집에 있었다.)\n예) We stayed home because of the rain. (비 때문에 집에 있었다.)"},{"s":"…you notice how they are looking away and ( ______ ) a smile…","ch":["are forcing","forcing"],"a":0,"why":"and가 연결하는 것은 are looking away와 같은 형태의 현재진행형이므로 are forcing. 병렬 구조는 같은 형태끼리 연결함.","tr":"누군가가 여러분에게 그들이 여러분과 시간을 보내는 것을 즐긴다고 말하지만 그들이 눈길을 돌리고 억지웃음을 짓고 있는 모습을 여러분이 알아차리면 여러분은 아마도 그들의 말을 덜 믿게 될 것이다.","g":"and로 연결되는 말은 문법 형태가 같아야 해요 (병렬 구조).\n예) He is reading and (is) listening to music. (그는 책을 읽으며 음악을 듣고 있다.)"}],"awk":[{"t":"A study by Eva McMahan, professor of speech communication, [[1|confirmed]] the [[2|dominance]] of nonverbal signals. The phenomenon, however, was especially [[3|pronounced]] when adults found themselves in situations with [[4|consistent]] messages (i.e., situations in which the contents of the verbal and nonverbal messages [[5|differ]]).","a":4,"fix":"conflicting","why":"원문은 conflicting (모순되는). 바로 뒤에서 ‘언어적 메시지와 비언어적 메시지의 내용이 다르다(differ)’고 풀이한다.\nconsistent (일관된, 일치하는)이면 뒤의 differ와 모순된다.","sp":[{"b":"confirmed","m":"확인했다","n":"confirm = 확인하다","y":"맞음. 연구가 확인한 내용.","e":"사실임을 밝힘."},{"b":"dominance","m":"우위","n":"the dominance of ~ = ~의 우위","y":"맞음. 비언어적 신호가 더 강하다는 뜻.","e":"더 큰 힘."},{"b":"pronounced","m":"두드러진","n":"especially pronounced = 특히 두드러진","y":"맞음. 그 현상이 더 뚜렷했다는 뜻.","e":"눈에 띄게."},{"b":"consistent","m":"일관된","n":"","y":"어색함. 원문은 conflicting. 뒤에서 내용이 differ(다르다)라고 풀이하므로 ‘일치하는’ 메시지는 모순이다.","e":"말과 몸짓이 다른 상황."},{"b":"differ","m":"다르다","n":"differ = 다르다","y":"맞음. 두 메시지의 내용이 다름.","e":"서로 어긋남."}]},{"t":"Attempts to [[1|manipulate]] another person verbally are therefore likely to [[2|succeed]] if the accompanying nonverbal communication does not [[3|match]] the spoken message. This is because people [[4|trust]] nonverbal messages [[5|more]] than verbal ones.","a":2,"fix":"fail","why":"원문은 fail (실패하다). 비언어적 의사소통이 말과 일치하지 않으면 말로 조종하려는 시도는 실패한다는 뜻이다.\nsucceed (성공하다)이면 뒤의 ‘사람들은 비언어적 메시지를 더 믿는다’는 이유와 모순된다.","sp":[{"b":"manipulate","m":"조종하다","n":"manipulate = 교묘하게 조종하다","y":"맞음. 말로 상대를 움직이려는 시도.","e":"상대를 내 뜻대로 움직이려는 것."},{"b":"succeed","m":"성공하다","n":"","y":"어색함. 원문은 fail. 말과 몸짓이 어긋나면 사람들은 몸짓을 더 믿으므로 성공할 수 없다.","e":"어긋나면 믿지 않음."},{"b":"match","m":"일치하다","n":"match = 일치하다","y":"맞음. 말과 몸짓이 같은 내용일 때.","e":"짝이 맞는 것."},{"b":"trust","m":"신뢰하다","n":"trust = 신뢰하다","y":"맞음. 사람들이 믿는 쪽은 비언어적 메시지.","e":"믿는 것."},{"b":"more","m":"더","n":"trust A more than B = B보다 A를 더 신뢰하다","y":"맞음. 비언어적 메시지가 더 큰 신뢰를 받음.","e":"더 많이 믿음."}]},{"t":"When somebody tells you that they enjoy spending time with you, but you notice how they are looking away and are forcing a smile, you are probably [[1|more]] inclined to [[2|believe]] their words. The same is probably [[3|true]] when your colleague tells you with a [[4|displeased]] expression that they were [[5|happy]] to take over your workload.","a":1,"fix":"less","why":"원문은 less (덜). 눈길을 돌리고 억지웃음을 짓는 모습을 보면 상대의 말을 덜 믿게 된다는 뜻이다.\nmore (더)이면 말과 행동이 어긋나는 상황에서 오히려 더 믿는다는 뜻이 되어, 글의 주제(비언어적 신호를 더 신뢰한다)와 모순된다.","sp":[{"b":"more","m":"더","n":"","y":"어색함. 원문은 less. 말과 표정이 어긋나면 말을 덜 믿게 되므로 more inclined는 모순이다.","e":"표정이 어색하면 말이 덜 믿김."},{"b":"believe","m":"믿다","n":"be inclined to believe = 믿고 싶은 마음이 들다","y":"맞음. less와 함께 ‘덜 믿다’.","e":"믿는 것."},{"b":"true","m":"사실인","n":"The same is true = 마찬가지이다","y":"맞음. 앞의 경우와 같은 상황이라는 뜻.","e":"똑같이 적용됨."},{"b":"displeased","m":"언짢은","n":"a displeased expression = 언짢은 표정","y":"맞음. 말(즐거웠다)과 어긋나는 표정.","e":"불쾌한 얼굴."},{"b":"happy","m":"즐거운","n":"were happy to V = ~해서 즐거웠다","y":"맞음. 동료가 한 말의 내용.","e":"기뻤다는 말."}]}],"und":[{"q":"<u>Attempts to manipulate another person verbally are therefore likely to fail if the accompanying nonverbal communication does not match the spoken message.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["말하는 내용과 몸짓, 표정이 어긋나면 말로 상대를 움직이려는 시도는 실패하기 쉽다","말만 잘하면 몸짓이 달라도 상대를 움직일 수 있다","몸짓이 말과 같으면 상대를 움직이는 것은 불가능하다","상대를 움직이려면 말을 하지 말고 몸짓만 써야 한다","말과 몸짓이 어긋나면 상대가 더 쉽게 속는다"],"a":0,"why":"앞 내용: 모순되는 메시지 상황에서 비언어적 신호의 우위가 특히 두드러짐.\nlikely to fail = 실패하기 쉬움.\n결론: 표정과 몸짓이 말과 다르면 사람들은 말을 믿지 않는다.","e":"‘미안해’라고 하면서 웃으면 사과가 통하지 않는 것.","tr":"그러므로 만약 동반되는 비언어적 의사소통이 발화된 메시지와 일치하지 않는다면 다른 사람을 언어적으로 조종하려는 시도는 실패할 가능성이 있다."},{"q":"<u>you are probably less inclined to believe their words</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["그들의 말을 더욱 믿게 될 것이다","그들의 말을 이해하지 못할 것이다","그들의 말을 아예 듣지 않을 것이다","그들의 말을 믿고 싶은 마음이 덜 들 것이다","그들의 말을 반드시 따라야 할 것이다"],"a":3,"why":"앞 내용: 상대가 눈길을 돌리고 억지웃음을 지으며 시간을 보내는 것을 즐긴다고 말함.\nless inclined to V = ~하고 싶은 마음이 덜한.\n결론: 말과 표정이 어긋나서 말이 덜 믿긴다.","e":"말은 ‘좋아’인데 눈이 딴 곳을 보면 믿기 어려움.","tr":"누군가가 여러분에게 그들이 여러분과 시간을 보내는 것을 즐긴다고 말하지만 그들이 눈길을 돌리고 억지웃음을 짓고 있는 모습을 여러분이 알아차리면 여러분은 아마도 그들의 말을 덜 믿게 될 것이다."},{"q":"<u>You might not believe that they enjoyed replacing you while you were gone.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["동료가 대신 일한 것이 사실이 아니라고 생각한다","언짢은 표정을 본 여러분은 동료가 정말로 즐거웠다고는 믿지 않을 수 있다","동료가 즐거워한 것을 확실히 믿는다","동료가 여러분 없이 지낸 것을 부러워한다","동료가 여러분에게 일을 돌려주기 싫어한다고 믿는다"],"a":1,"why":"앞 내용: 동료가 언짢은 표정으로 업무를 떠맡게 되어 즐거웠다고 말함.\nreplace = 대신하다.\n결론: 말(즐거웠다)과 표정(언짢음)이 어긋나서 말을 믿기 어렵다.","e":"‘괜찮아’라고 하면서 얼굴을 찡그리는 친구.","tr":"여러분은 아마도 그들이 여러분이 없는 동안 여러분을 대신하기를 즐거워했다는 것을 믿지 않을 것이다."}]},"2610-31":{"voc":[{"q":"…the <u>overwhelming</u> majority of the behaviour packed into them…","ask":"overwhelming의 뜻으로 알맞은 것은?","ch":["아주 적은","평범한","불확실한","일시적인","압도적인"],"a":4,"why":"overwhelming = 압도적인, 엄청난. overwhelming majority = 압도적 다수.\n지문: the overwhelming majority of the behaviour = 행동의 압도적인 다수.\n거의 대부분이라는 뜻.","e":"시험에서 반 친구 대부분이 같은 답을 고른 상황.","tr":"80년을 사는 사람은 약 2만 9천 일을 살고, 그 속에 빽빽이 들어 있는 행동의 압도적인 다수는 대부분이 수십 년 전에 정해져서 그 이후로는 거의 점검되지 않은 설정들에 따라 작동한다.","alt":"huge (엄청난), great (대단한) / 동사 overwhelm (압도하다)"},{"q":"…the behaviour <u>packed</u> into them runs on settings laid down, most of them, decades earlier…","ask":"이 글에서 packed의 뜻으로 가장 알맞은 것은?","ch":["빽빽이 채워진","포장된","버려진","나누어진","사라진"],"a":0,"why":"pack = 짐을 싸다, 빽빽이 채우다. packed into them = 그 안에 빽빽이 들어 있는.\n지문: the behaviour packed into them (= 2만 9천 일) = 그 날들 속에 빽빽이 들어 있는 행동.\n하루하루에 수많은 행동이 들어 있다는 말.","e":"가방에 짐을 가득 넣은 모습.","tr":"80년을 사는 사람은 약 2만 9천 일을 살고, 그 속에 빽빽이 들어 있는 행동의 압도적인 다수는 대부분이 수십 년 전에 정해져서 그 이후로는 거의 점검되지 않은 설정들에 따라 작동한다.","alt":"crowded (붐비는), filled (가득 찬)"},{"q":"…settings <u>laid down</u>, most of them, decades earlier and rarely <u>inspected</u> since.","ask":"inspected의 뜻으로 알맞은 것은?","ch":["점검된, 살펴본","수정된","무시된","금지된","칭찬받은"],"a":0,"why":"inspect = 자세히 살피다, 점검하다. rarely inspected = 거의 점검되지 않은.\n지문: rarely inspected since = 그 이후로 거의 점검되지 않은.\n오래전에 정해진 습관을 다시 따져 보지 않는다는 뜻.","e":"선생님이 숙제가 제대로 되었는지 꼼꼼히 확인하는 것.","tr":"80년을 사는 사람은 약 2만 9천 일을 살고, 그 속에 빽빽이 들어 있는 행동의 압도적인 다수는 대부분이 수십 년 전에 정해져서 그 이후로는 거의 점검되지 않은 설정들에 따라 작동한다.","alt":"examine (조사하다), check (확인하다)"},{"q":"This need not be a <u>hopeless</u> thought.","ask":"hopeless의 반의어로 알맞은 것은?","ch":["helpless (무력한)","useless (쓸모없는)","careless (부주의한)","hopeful (희망적인)","endless (끝없는)"],"a":3,"why":"hopeless = 희망이 없는 ↔ hopeful = 희망적인 (hope ‘희망’ + -less ‘없는’ / -ful ‘가득한’).\nhelpless, useless, careless, endless는 모두 -less로 끝나지만 ‘희망’과는 관계가 없음.\n지문: need not be a hopeless thought = 절망적인 생각일 필요는 없다.","e":"-less는 ‘없는’, -ful은 ‘가득한’. hopeless ↔ hopeful.","tr":"이것이 꼭 절망적인 생각일 필요는 없다.","alt":"desperate (절망적인) / 반의어 hopeful, promising (유망한)"},{"q":"In one light it is a <u>triumph</u> of engineering.","ask":"triumph의 뜻으로 알맞은 것은?","ch":["실패","위험","큰 성공, 승리","비용","논쟁"],"a":2,"why":"triumph = 큰 성공, 승리. 지문: a triumph of engineering = 설계(공학)의 승리.\n앞 문장이 ‘절망적일 필요는 없다’여서 그 반대의 좋은 평가가 나옴.\n실패나 위험이 아니라 훌륭한 성과를 뜻함.","e":"축구 결승에서 이긴 순간의 기쁨.","tr":"어떤 관점에서 그것은 설계의 승리이다.","alt":"victory (승리), success (성공) / 반의어 failure (실패)"},{"q":"If you had to <u>consciously</u> decide every footstep and every fork-grip and every word…","ask":"consciously의 뜻으로 알맞은 것은?","ch":["자동으로","우연히","몰래","의식적으로","억지로"],"a":3,"why":"consciously = 의식적으로, 알고서 (conscious ‘의식하는’ + -ly). 반의어는 unconsciously (무의식적으로).\n지문: consciously decide every footstep = 모든 발걸음을 의식적으로 결정하다.\n글의 핵심인 ‘자동화’와 반대되는 방식.","e":"한 걸음씩 ‘오른발, 왼발’ 생각하며 걷는 것.","tr":"만약 여러분이 발걸음 하나하나와, 포크를 쥐는 동작 하나하나와, 말 한마디 한마디를 의식적으로 결정해야 한다면 여러분은 침대에서 결코 빠져나오지 못할 것인데, 왜냐하면 신중한 사고는 너무 느리고 대가가 너무 커서 삶 전체를 실시간으로 운영할 수 없고, 그렇게 하려고 하는 모든 생명체는 그렇게 하지 않는 생명체에게 패배할 것이기 때문이다.","alt":"deliberately (일부러) / 반의어 unconsciously, automatically"},{"q":"…the <u>deliberate</u> mind is far too slow and too costly to run a whole life in real time…","ask":"이 글에서 deliberate의 뜻으로 가장 알맞은 것은?","ch":["우연한","신중한, 의도적인","자동적인","난폭한","흐릿한"],"a":1,"why":"deliberate (형용사) = 신중한, 의도적인. (동사 deliberate는 ‘숙고하다’.)\n지문: the deliberate mind = 일일이 따져서 생각하는 마음.\n앞의 consciously와 이어지며, 자동 설정과 반대되는 쪽.","e":"하나하나 따져 보며 천천히 고르는 마음.","tr":"만약 여러분이 발걸음 하나하나와, 포크를 쥐는 동작 하나하나와, 말 한마디 한마디를 의식적으로 결정해야 한다면 여러분은 침대에서 결코 빠져나오지 못할 것인데, 왜냐하면 신중한 사고는 너무 느리고 대가가 너무 커서 삶 전체를 실시간으로 운영할 수 없고, 그렇게 하려고 하는 모든 생명체는 그렇게 하지 않는 생명체에게 패배할 것이기 때문이다.","alt":"intentional (의도적인), careful (조심스러운) / 반의어 accidental (우연한)"},{"q":"…any creature that tried would be <u>outcompeted</u> by a creature that didn't.","ask":"outcompeted의 뜻으로 알맞은 것은?","ch":["경쟁에서 이긴","경쟁을 피한","경쟁에서 밀린, 패배한","경쟁을 시작한","경쟁에 무관심한"],"a":2,"why":"outcompete = 경쟁에서 이기다. be outcompeted = 경쟁에서 밀리다, 패배하다 (수동).\n지문: would be outcompeted by a creature that didn't = 그렇게 하지 않는 생명체에게 경쟁에서 밀릴 것이다.\nout- (~보다 더) + compete (경쟁하다).","e":"달리기에서 나보다 빠른 친구에게 지는 것.","tr":"만약 여러분이 발걸음 하나하나와, 포크를 쥐는 동작 하나하나와, 말 한마디 한마디를 의식적으로 결정해야 한다면 여러분은 침대에서 결코 빠져나오지 못할 것인데, 왜냐하면 신중한 사고는 너무 느리고 대가가 너무 커서 삶 전체를 실시간으로 운영할 수 없고, 그렇게 하려고 하는 모든 생명체는 그렇게 하지 않는 생명체에게 패배할 것이기 때문이다.","alt":"be beaten (패배하다) / 능동형 outperform (더 잘하다)"},{"q":"The automation is precisely what frees the captain to come up on deck for the few problems that actually <u>require</u> him.","ask":"require의 뜻으로 알맞은 것은?","ch":["허락하다","피하다","필요로 하다","제공하다","용서하다"],"a":2,"why":"require = 필요로 하다, 요구하다 (= need). 명사 requirement = 필요 조건.\n지문: problems that actually require him = 그를 정말로 필요로 하는 문제들.\n선장이 꼭 필요한 일에만 나서게 된다는 뜻.","e":"시험에 신분증이 필요하다는 규칙.","tr":"자동화는 정확히 선장을 정말로 필요로 하는 몇 안 되는 문제들을 위해 그가 갑판 위로 올라올 수 있게 해방해 주는 것이다.","alt":"need (필요로 하다), demand (요구하다)"}],"find":[{"s":"A person who lives eighty years lives about twenty-nine thousand days.","a":true,"why":"1문장: A person who lives eighty years lives some twenty-nine thousand days (80년을 사는 사람은 약 2만 9천 일을 삶).","e":"약 29,000일."},{"s":"Most of our behaviour runs on settings that were laid down only recently.","a":false,"why":"1문장: settings laid down, most of them, decades earlier (대부분 수십 년 전에 정해진 설정). 최근이라는 말은 반대.","e":"오래전에 만들어진 설정."},{"s":"Those settings are rarely inspected after they are laid down.","a":true,"why":"1문장: rarely inspected since (그 이후로 거의 점검되지 않음).","e":"한 번 정해지면 다시 따져 보지 않음."},{"s":"The writer says the fact in the first sentence must be a hopeless thought.","a":false,"why":"2문장: This need not be a hopeless thought (이것이 꼭 절망적인 생각일 필요는 없음). 반드시 절망적이라는 말은 반대.","e":"좋게 볼 수도 있다는 뜻."},{"s":"The writer sees the settings as a triumph of engineering in one light.","a":true,"why":"3문장: In one light it is a triumph of engineering (어떤 관점에서 그것은 설계의 승리).","e":"관점에 따라 장점으로 보임."},{"s":"If you decided every footstep consciously, you would hardly get out of bed.","a":true,"why":"4문장: you would never make it out of bed (침대에서 결코 빠져나오지 못할 것임).","e":"모든 것을 의식적으로 결정하면 시작도 못함."},{"s":"The deliberate mind is fast and cheap enough to run a whole life in real time.","a":false,"why":"4문장: the deliberate mind is far too slow and too costly (신중한 사고는 너무 느리고 대가가 너무 커서). 빠르고 싸다는 말은 반대.","e":"의식적 사고는 느리고 비쌈."},{"s":"A creature that decided everything consciously would be outcompeted by a creature that did not.","a":true,"why":"4문장: any creature that tried would be outcompeted by a creature that didn't (그렇게 하려는 생명체는 그렇지 않은 생명체에게 밀림).","e":"자동화한 쪽이 유리."},{"s":"Automation frees the captain to come up on deck for the few problems that really need him.","a":true,"why":"5문장: The automation is precisely what frees the captain to come up on deck for the few problems that actually require him (자동화는 선장이 정말 필요한 몇 문제를 위해 갑판 위로 올라올 수 있게 해 줌).","e":"선장은 중요한 일에만 집중."},{"s":"The writer argues that the default is a flaw in the human design.","a":false,"why":"6문장: The default is not a flaw in the human design (기본 설정은 인간 설계의 결함이 아님). 결함이라는 말은 반대.","e":"오히려 핵심 장점."},{"s":"The default makes a complex life affordable.","a":true,"why":"7문장: the thing that makes a complex life affordable at all (복잡한 삶을 감당할 수 있게 만드는 것).","e":"자동 설정 덕분에 삶이 가능함."}],"eob":[{"s":"A person ( ______ ) lives eighty years lives some twenty-nine thousand days.","ch":["which","who"],"a":1,"why":"선행사가 사람(A person)이고 뒤에 동사 lives가 바로 오므로 주격 관계대명사 who. which는 사물 선행사에 씀.","tr":"80년을 사는 사람은 약 2만 9천 일을 살고, 그 속에 빽빽이 들어 있는 행동의 압도적인 다수는 대부분이 수십 년 전에 정해져서 그 이후로는 거의 점검되지 않은 설정들에 따라 작동한다.","g":"관계대명사는 선행사가 사람이면 who, 사물이면 which를 써요.\n예) The girl who sings is my sister. (노래하는 소녀는 내 여동생이다.)"},{"s":"…the behaviour ( ______ ) into them runs on settings laid down decades earlier…","ch":["packing","packed"],"a":1,"why":"behaviour와 pack(채우다)은 ‘행동이 채워진’ 수동 관계이므로 과거분사 packed. packing은 능동의 뜻이라 맞지 않음.","tr":"80년을 사는 사람은 약 2만 9천 일을 살고, 그 속에 빽빽이 들어 있는 행동의 압도적인 다수는 대부분이 수십 년 전에 정해져서 그 이후로는 거의 점검되지 않은 설정들에 따라 작동한다.","g":"꾸밈을 받는 명사와 동사가 수동 관계이면 과거분사(p.p.), 능동 관계이면 현재분사(-ing)를 써요.\n예) a book written by him (그가 쓴 책)\n예) a boy writing a letter (편지를 쓰고 있는 소년)"},{"s":"If you had to consciously decide every footstep and every fork-grip and every word, you ( ______ ) never make it out of bed.","ch":["would","will"],"a":0,"why":"if절이 had to (가정법 과거)이므로 주절은 would + 동사원형. will은 현재 사실이나 미래를 말할 때 쓰여 짝이 맞지 않음.","tr":"만약 여러분이 발걸음 하나하나와, 포크를 쥐는 동작 하나하나와, 말 한마디 한마디를 의식적으로 결정해야 한다면 여러분은 침대에서 결코 빠져나오지 못할 것인데, 왜냐하면 신중한 사고는 너무 느리고 대가가 너무 커서 삶 전체를 실시간으로 운영할 수 없고, 그렇게 하려고 하는 모든 생명체는 그렇게 하지 않는 생명체에게 패배할 것이기 때문이다.","g":"가정법 과거: If + 주어 + 과거형, 주어 + would + 동사원형.\n예) If I were rich, I would travel the world. (내가 부자라면 세계를 여행할 텐데.)"},{"s":"The deliberate mind is far too slow and too costly ( ______ ) run a whole life in real time.","ch":["to","for"],"a":0,"why":"too ~ to V = 너무 ~해서 V할 수 없다. to run이 알맞음. for 뒤에는 동사원형이 올 수 없음.","tr":"만약 여러분이 발걸음 하나하나와, 포크를 쥐는 동작 하나하나와, 말 한마디 한마디를 의식적으로 결정해야 한다면 여러분은 침대에서 결코 빠져나오지 못할 것인데, 왜냐하면 신중한 사고는 너무 느리고 대가가 너무 커서 삶 전체를 실시간으로 운영할 수 없고, 그렇게 하려고 하는 모든 생명체는 그렇게 하지 않는 생명체에게 패배할 것이기 때문이다.","g":"too + 형용사 + to V = 너무 ~해서 V할 수 없다.\n예) He is too tired to walk. (그는 너무 피곤해서 걸을 수 없다.)"},{"s":"The automation is precisely ( ______ ) frees the captain to come up on deck for the few problems that actually require him.","ch":["that","what"],"a":1,"why":"is 뒤에서 frees의 주어가 필요하고 ‘~하는 것’이라는 뜻의 선행사 포함 관계대명사 what이 알맞음. that은 선행사가 필요하며 보어 자리에서는 쓸 수 없음.","tr":"자동화는 정확히 선장을 정말로 필요로 하는 몇 안 되는 문제들을 위해 그가 갑판 위로 올라올 수 있게 해방해 주는 것이다.","g":"what = the thing that. ‘~하는 것’이라는 뜻으로 명사절을 이끌어요.\n예) What I need is time. (내가 필요한 것은 시간이다.)"}],"awk":[{"t":"This need not be a [[1|hopeless]] thought. In one light it is a [[2|failure]] of engineering. If you had to consciously decide every footstep and every fork-grip and every word, you would never [[3|make]] it out of bed; the [[4|deliberate]] mind is far too slow and too [[5|costly]] to run a whole life in real time.","a":2,"fix":"triumph","why":"원문은 triumph (승리). 앞 문장이 ‘절망적일 필요는 없다’이고 뒤가 자동화의 이점을 설명하므로 ‘설계의 승리’가 알맞다.\nfailure (실패)이면 ‘절망적일 필요가 없다’는 앞 문장과 모순된다.","sp":[{"b":"hopeless","m":"절망적인","n":"need not be = ~일 필요는 없다","y":"맞음. ‘절망적인 생각일 필요는 없다’.","e":"희망이 없는."},{"b":"failure","m":"실패","n":"","y":"어색함. 원문은 triumph. 앞에서 절망적일 필요는 없다고 했으므로 ‘실패’는 모순된다.","e":"좋게 보는 관점."},{"b":"make","m":"빠져나오다","n":"make it out of bed = 침대에서 빠져나오다","y":"맞음. 하루도 시작하지 못한다는 과장.","e":"침대에서 일어나다."},{"b":"deliberate","m":"신중한","n":"the deliberate mind = 신중하게 따지는 마음","y":"맞음. 의식적으로 생각하는 마음.","e":"하나하나 따지는."},{"b":"costly","m":"대가가 큰","n":"too costly = 너무 대가가 큰","y":"맞음. 에너지가 많이 든다는 뜻.","e":"힘이 많이 드는."}]},{"t":"If you had to consciously decide every footstep and every word, you would never get out of bed; the [[1|deliberate]] mind is far too [[2|slow]] and too costly to run a whole life, and any creature that tried would be [[3|outcompeted]] by a creature that didn't. The automation is precisely what [[4|traps]] the captain [[5|below]] deck.","a":4,"fix":"frees","why":"원문은 frees (해방해 주다). 자동화 덕분에 선장이 갑판 위로 올라올 수 있다는 뜻이다.\ntraps (가두다)이면 자동화가 선장을 갑판 아래에 가둔다는 뜻이 되어, 뒤에 나오는 ‘올라온다(come up on deck)’ 뜻과 모순된다.","sp":[{"b":"deliberate","m":"신중한","n":"the deliberate mind","y":"맞음. 의식적 사고.","e":"하나하나 따지는 마음."},{"b":"slow","m":"느린","n":"too slow = 너무 느린","y":"맞음. 의식적 사고의 약점.","e":"빠르지 않음."},{"b":"outcompeted","m":"경쟁에서 밀린","n":"be outcompeted by = ~에게 경쟁에서 지다","y":"맞음. 자동화하지 않은 쪽이 불리.","e":"더 잘하는 쪽에게 밀림."},{"b":"traps","m":"가두다","n":"","y":"어색함. 원문은 frees. 자동화가 선장을 갑판 위로 올라오게 해 준다는 문장과 모순된다.","e":"풀어 주는 쪽이 맞음."},{"b":"below","m":"아래에","n":"below deck = 갑판 아래","y":"맞음. 선장의 원래 자리.","e":"아래쪽."}]},{"t":"The automation is precisely what frees the captain to come up on deck for the [[1|few]] problems that actually [[2|require]] him. The default is not a [[3|flaw]] in the human design. It is arguably the [[4|marginal]] feature, the thing that makes a complex life [[5|affordable]] at all.","a":4,"fix":"central","why":"원문은 central (핵심적인). 기본 설정이 복잡한 삶을 감당할 수 있게 만드는 ‘핵심 특징’이라는 뜻이다.\nmarginal (주변적인)이면 ‘삶을 가능하게 하는 것’이라는 뒤의 설명과 모순된다.","sp":[{"b":"few","m":"몇 안 되는","n":"the few problems = 몇 안 되는 문제","y":"맞음. 정말 필요한 문제는 적음.","e":"적은 수."},{"b":"require","m":"필요로 하다","n":"require = 필요로 하다","y":"맞음. 선장이 꼭 필요한 문제.","e":"꼭 필요한."},{"b":"flaw","m":"결함","n":"a flaw in ~ = ~의 결함","y":"맞음. 기본 설정은 결함이 아니라는 말.","e":"흠."},{"b":"marginal","m":"주변적인","n":"","y":"어색함. 원문은 central. 복잡한 삶을 감당 가능하게 만드는 것이라고 했으므로 ‘주변적’이라는 말은 모순된다.","e":"핵심이 아니라 가장자리라는 뜻."},{"b":"affordable","m":"감당할 수 있는","n":"affordable = 감당할 수 있는","y":"맞음. 복잡한 삶을 유지할 수 있다는 뜻.","e":"부담이 크지 않은."}]}],"und":[{"q":"<u>the overwhelming majority of the behaviour packed into them runs on settings laid down, most of them, decades earlier and rarely inspected since</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["우리의 행동 대부분은 매일 새로 계획한 결과이다","우리의 행동 대부분은 오래전에 굳어져 거의 다시 따져 보지 않은 습관을 따른다","우리의 행동 대부분은 최근에 배운 것을 따른다","우리의 행동 대부분은 남이 정해 준 일정을 따른다","우리의 행동은 거의 대부분 우연히 이루어진다"],"a":1,"why":"앞 내용: 80년을 사는 사람은 약 2만 9천 일을 삶.\nsettings laid down decades earlier = 수십 년 전에 정해진 설정.\nrarely inspected = 거의 점검되지 않음.\n결론: 행동의 대부분은 오래된 습관(기본값)으로 움직인다.","e":"양치할 때 어떻게 칫솔을 잡을지 매번 생각하지 않는 것.","tr":"80년을 사는 사람은 약 2만 9천 일을 살고, 그 속에 빽빽이 들어 있는 행동의 압도적인 다수는 대부분이 수십 년 전에 정해져서 그 이후로는 거의 점검되지 않은 설정들에 따라 작동한다."},{"q":"<u>you would never make it out of bed</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["침대가 너무 편해서 계속 누워 있을 것이다","잠이 부족해서 침대에서 못 나올 것이다","모든 것을 일일이 결정하다가는 하루를 시작하지도 못할 것이다","침대에서 나오는 방법을 배우지 못할 것이다","침대에서 나오는 일이 가장 쉬운 일일 것이다"],"a":2,"why":"앞 내용: 발걸음, 포크 쥐는 법, 말 한마디까지 의식적으로 결정해야 한다면.\nmake it out of bed = 침대에서 빠져나오다 (과장 표현).\n결론: 의식적 결정은 너무 많아서 감당할 수 없다.","e":"일어날 때 ‘왼발부터? 오른발부터?’ 따지다 한참 걸리는 것.","tr":"만약 여러분이 발걸음 하나하나와, 포크를 쥐는 동작 하나하나와, 말 한마디 한마디를 의식적으로 결정해야 한다면 여러분은 침대에서 결코 빠져나오지 못할 것인데, 왜냐하면 신중한 사고는 너무 느리고 대가가 너무 커서 삶 전체를 실시간으로 운영할 수 없고, 그렇게 하려고 하는 모든 생명체는 그렇게 하지 않는 생명체에게 패배할 것이기 때문이다."},{"q":"<u>The automation is precisely what frees the captain to come up on deck for the few problems that actually require him.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["습관처럼 자동으로 처리되는 일이 많아서 의식적인 생각은 꼭 필요한 문제에만 쓸 수 있다","자동으로 처리되는 일 때문에 의식적인 생각이 필요 없어진다","의식적인 생각은 모든 일에 똑같이 쓰여야 한다","선장은 배 위의 모든 문제를 혼자 해결해야 한다","자동화는 선장의 일을 모두 빼앗는다"],"a":0,"why":"앞 내용: 의식적 사고는 느리고 비싸서 삶 전체를 운영할 수 없음.\n선장 = 의식적인 마음, 자동화 = 습관.\n결론: 습관이 일상을 맡아 주니 의식적인 마음은 중요한 문제에 집중할 수 있다.","e":"청소는 자동으로 하고 시험 공부에만 집중하는 것.","tr":"자동화는 정확히 선장을 정말로 필요로 하는 몇 안 되는 문제들을 위해 그가 갑판 위로 올라올 수 있게 해방해 주는 것이다."},{"q":"<u>It is arguably the central feature, the thing that makes a complex life affordable at all.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["기본 설정은 삶을 복잡하게 만드는 가장 큰 원인이다","기본 설정은 복잡한 삶을 가능하게 해 주는 핵심 장점이라고 볼 수 있다","기본 설정은 삶에서 없어도 되는 부분이다","기본 설정 때문에 삶의 비용이 올라간다","기본 설정은 한 번 정하면 절대 바꿀 수 없다"],"a":1,"why":"앞 내용: 기본 설정은 인간 설계의 결함이 아님.\ncentral feature = 핵심 특징. affordable = 감당할 수 있는.\n결론: 자동 설정이 있어서 복잡한 삶도 감당 가능하다.","e":"복잡한 일을 처리하게 해 주는 자동 기능.","tr":"그것은 거의 틀림없이 핵심적인 특징, 즉 복잡한 삶을 조금이라도 감당할 수 있게 만드는 것이다."}]},"2610-32":{"voc":[{"q":"…the cultural ties that <u>unite</u> people to their traditions…","ask":"unite의 뜻으로 알맞은 것은?","ch":["결속시키다, 하나로 묶다","갈라놓다","잊게 하다","비교하다","가르치다"],"a":0,"why":"1문장: ...the cultural ties that unite people to their traditions (사람들을 자신들의 전통에 결속시키는 문화적 유대감)\n쉽게 말해 사람들을 전통과 한 덩어리로 묶어 주는 끈이라는 뜻이다.\nunite = 하나로 묶다, 결속시키다. 비슷한 말: join (연결하다), combine (합치다). 반대말은 divide (나누다).\n이 단어를 모르면 '문화적 유대감'이 무엇을 하는 것인지 놓친다. 이 글은 이 유대감이 약해진다는 데서 출발한다.\n오답 함정: '갈라놓다'는 unite의 반대 뜻이라 낚이기 쉽다.\n본문 포인트: 전통과 사람을 묶어 주는 끈이 약해지면 가족·학교 같은 제도도 약해진다.","e":"반 친구들이 한마음으로 응원해서 한 팀으로 묶이는 것.","tr":"…사람들을 자신들의 전통에 결속시키는 문화적 유대감…","alt":"join, combine, bind"},{"q":"…mass culture weakens the intermediary institutions in society, <u>diminishing</u> their role…","ask":"diminishing과 바꿔 쓸 수 있는 말은?","ch":["reducing","expanding","protecting","explaining","repeating"],"a":0,"why":"1문장: ...diminishing their role (그것들의 역할을 줄어들게 하면서)\n쉽게 말해 가족이나 학교가 맡던 일이 점점 작아진다는 뜻이다.\ndiminish = 줄이다, 줄어들다 (= reduce, lessen). 반대말은 expand (넓히다).\n여기서 -ing는 '~하면서'를 뜻하는 분사구문이다.\n오답 함정: expanding (넓히는)은 반대 뜻이다. 글은 역할이 '줄어든다'고 말한다.\n본문 포인트: 대중문화가 커질수록 제도의 역할은 작아진다.","e":"방학이 끝나 가면서 점점 줄어드는 남은 날 수.","tr":"…그것들의 역할을 축소시키면서…","alt":"reduce, lessen, decrease"},{"q":"…important for the normal and <u>harmonious</u> functioning of collective life.","ask":"harmonious의 뜻으로 알맞은 것은?","ch":["조화로운, 어울리는","시끄러운","위험한","낡은","비밀스러운"],"a":0,"why":"2문장: ...important for the normal and harmonious functioning of collective life. (집단 생활의 정상적이고 조화로운 기능에 중요하다)\n쉽게 말해 법정이 있어야 사람들이 부딪치지 않고 잘 어울려 살아간다는 뜻이다.\nharmonious = 조화로운. 명사는 harmony (조화). 반대 뜻은 conflicting (충돌하는).\n앞 문장에서 대중문화가 제도를 약하게 한다고 했다. 법정은 그 예로 나온 중요한 제도이다.\n오답 함정: '시끄러운'은 harmony를 '화음'으로만 알고 소리와 연결할 때 낚인다. 여기서는 사람들 사이가 어울린다는 뜻이다.\n본문 포인트: 법정은 사회가 조화롭게 돌아가게 하는 중요한 제도이다.","e":"합창단이 서로 소리를 맞춰 아름답게 노래하는 모습.","tr":"…집단 생활의 정상적이고 조화로운 기능에 중요하다.","alt":"harmony (명사), peaceful, balanced"},{"q":"…this practice puts pressure on <u>judicial</u> decisions…","ask":"judicial의 뜻으로 알맞은 것은?","ch":["사법의, 재판의","경제의","교육의","의학의","예술의"],"a":0,"why":"3문장: ...to put pressure on judicial decisions (사법적 결정에 압박을 가하기 위해)\n쉽게 말해 법원이 내리는 판결에 압력을 넣는다는 뜻이다.\njudicial = 사법의, 재판의. 명사 judge (판사, 판단하다), justice (정의, 재판)와 한 가족이다.\n이 단어를 모르면 3문장이 무엇에 압박을 가한다는 건지 모른다. 결국 이 글의 걱정은 '재판이 여론에 흔들리는 것'이다.\n오답 함정: 나머지 넷은 judicial과 모양도 뜻도 다르다.\n본문 포인트: 소셜 네트워크의 압박이 재판 결과를 흔들까 걱정하는 글이다.","e":"판사가 법정에서 판결을 내리는 일과 관련된 것.","tr":"…사법적 결정에 압박을 가하기 위해…","alt":"legal, court-related"},{"q":"…becomes a <u>habitual</u> form of culture, which is harmful.","ask":"habitual의 뜻으로 알맞은 것은?","ch":["습관적인, 몸에 밴","일시적인","희귀한","불가능한","공식적인"],"a":0,"why":"3문장: ...becomes a habitual form of culture, which is harmful. (습관적인 문화의 형태가 되며, 이는 해롭다)\n쉽게 말해 처음엔 가끔이던 일이 매번 하는 버릇처럼 굳어진다는 뜻이다.\nhabitual = 습관적인. 명사는 habit (습관). 비슷한 말: customary (관례적인), regular (규칙적인).\n핵심은 뒤의 which is harmful (이는 해롭다)이다. 글쓴이는 그 버릇이 해롭다고 판단한다.\n오답 함정: '일시적인'은 반대 느낌이다. 습관은 한 번이 아니라 반복이다.\n본문 포인트: 압박이 버릇처럼 굳어지는 것이 문제이다.","e":"숙제를 미루는 일이 매번 반복되어 버릇이 된 것.","tr":"…습관적인 문화의 형태가 되며, 이는 해롭다.","alt":"habit (명사), customary, regular"},{"q":"…the social networks, which today is <u>converted</u> into a virtual dimension.","ask":"converted의 뜻으로 알맞은 것은?","ch":["바뀐, 전환된","지워진","허락된","도착한","확인된"],"a":0,"why":"4문장: ...which today is converted into a virtual dimension (그것은 오늘날 가상의 차원으로 전환된다)\n쉽게 말해 사람들이 모이던 광장이 인터넷 속 가상 공간으로 바뀌었다는 뜻이다.\nconvert A into B = A를 B로 바꾸다. is converted는 수동태라 '바뀐다·바뀌어 있다'로 읽는다.\n명사는 conversion (전환). 비슷한 말: change, transform.\n오답 함정: is와 -ed가 보여서 '허락된'처럼 아무 수동 뜻이나 고르지 않는다. 뒤의 into가 '바뀜'을 알려 준다.\n본문 포인트: 옛 광장이 소셜 네트워크가 되었다. 그곳에서 재판하면 안 된다는 주장이다.","e":"종이 책을 전자책으로 바꾸는 것.","tr":"…그것은 오늘날 가상의 차원, 즉 소셜 네트워크로 전환된다.","alt":"change, transform, turn"},{"q":"…the <u>appropriate</u> place to judge and make justice is the court…","ask":"appropriate와 바꿔 쓸 수 있는 말은?","ch":["suitable","optional","enormous","ordinary","ancient"],"a":0,"why":"5문장: ...the appropriate place to judge and make justice is the court (재판하고 정의를 실현하기에 적절한 장소는 법정이다)\n쉽게 말해 재판은 법정에서 해야 맞다는 뜻이다.\nappropriate = 적절한 (= suitable, proper). 반대말은 inappropriate (부적절한).\n글쓴이의 주장이 가장 분명히 드러나는 문장이라 시험에서 이 단어가 정답의 열쇠로 쓰인다.\n오답 함정: ordinary (평범한)는 '맞다'는 느낌과 거리가 멀다.\n본문 포인트: 재판의 적절한 자리는 소셜 네트워크가 아니라 법정이다.","e":"운동할 때는 교복 대신 체육복이 적절한 것.","tr":"…재판하고 정의를 실현하기에 적절한 장소는 법정이다…","alt":"suitable, proper, fitting"},{"q":"…in a way that is <u>immune</u> to popular pressure.","ask":"여기서 immune의 뜻으로 알맞은 것은?","ch":["영향을 받지 않는","면역 주사를 맞은","영향을 쉽게 받는","나이가 든","유명해진"],"a":0,"why":"5문장: ...in a way that is immune to popular pressure. (대중의 압박에 영향을 받지 않는 방식으로)\n쉽게 말해 사람들이 아무리 몰아붙여도 흔들리지 않는다는 뜻이다.\nimmune은 다의어이다. ① 면역이 있는(의학) ② ~의 영향을 받지 않는. immune to A = A에 영향받지 않는.\n이 글에서는 ②번 뜻이다. '면역'으로만 외우면 문장이 이상해진다.\n오답 함정: '면역 주사를 맞은'은 아는 뜻이라 낚이기 쉽다. '영향을 쉽게 받는'은 정반대이다.\n본문 포인트: 법정은 대중의 압박에서 독립되어야 한다. immune이 그 핵심 낱말이다.","e":"비가 와도 젖지 않는 방수 옷처럼 바깥 영향에 안 흔들리는 것.","tr":"…대중의 압박에 영향을 받지 않는 방식으로…","alt":"unaffected by, safe from; 반의어: vulnerable"}],"find":[{"s":"Mass culture can weaken institutions such as the family and the school.","a":true,"why":"1문장: mass culture weakens the intermediary institutions in society (e.g. the family or the school) (대중문화는 예를 들어 가족이나 학교 같은 사회 속 매개 제도를 약화시킨다)\n쉽게 말해 대중문화가 커지면 가족·학교의 힘이 줄어든다는 말이다.\n문제의 can weaken은 본문 weakens를 부드럽게 바꾼 것이다. 뜻이 같으면 참이다.\n본문 포인트: 글은 대중문화가 제도를 약하게 만든다는 데서 출발한다.","e":"학교 규칙이 SNS 유행에 밀려 힘을 잃는 것."},{"s":"The author says mass culture makes the family and the school stronger.","a":false,"why":"1문장: mass culture weakens the intermediary institutions (대중문화는 매개 제도를 약화시킨다)\n쉽게 말해 강해지는 게 아니라 약해진다는 말이다.\n함정: weakens(약화시킨다)를 strong(강한)으로 뒤집은 문장이다. 핵심 동사 하나가 뒤집혔다.\n본문 포인트: 대중문화는 제도를 약하게 한다.","e":"시소 한쪽이 올라가면 다른 쪽이 내려가는 것."},{"s":"Courts are traditional social institutions that matter for the harmonious functioning of collective life.","a":true,"why":"2문장: courts are traditional social institutions and important for the normal and harmonious functioning of collective life (법정은 전통적인 사회 기관이며 집단 생활의 정상적이고 조화로운 기능을 위해 중요하다)\n쉽게 말해 법정은 사회가 잘 굴러가게 하는 오래된 제도라는 말이다.\nmatter = 중요하다. important와 같은 뜻으로 바꾼 것이다.\n본문 포인트: 법정은 For example(예를 들어)로 소개된 중요한 제도이다.","e":"동네를 지키는 오래된 파출소 같은 것."},{"s":"The text explains that courts are new institutions created by social networks.","a":false,"why":"2문장: courts are traditional social institutions (법정은 전통적인 사회 기관이다)\n쉽게 말해 법정은 소셜 네트워크보다 훨씬 오래된 제도이다.\n함정: traditional(전통적인)을 new(새로운)로 바꾸고, 원인을 social networks로 끼워 넣었다.\n본문 포인트: 법정은 전통 제도이고 소셜 네트워크는 그것을 흔드는 쪽이다.","e":"오래된 시장을 새로 생긴 앱이 만들었다고 하는 격."},{"s":"When people use social networks to pressure judicial decisions, the practice can become a habitual form of culture.","a":true,"why":"3문장: when people turn to social networks to put pressure on judicial decisions ..., this practice is popularized and becomes a habitual form of culture (사람들이 소셜 네트워크에 의존해 사법적 결정에 압박을 가할 때, 이 관행은 대중화되고 습관적인 문화의 형태가 된다)\n쉽게 말해 한두 번이던 압박이 버릇처럼 굳어진다는 말이다.\n본문 포인트: 문제는 압박이 일상 문화로 자리 잡는다는 점이다.","e":"단톡방에서 한 명을 몰아붙이는 일이 매번 반복되어 버릇이 되는 것."},{"s":"The author thinks that pressuring courts through social networks is a harmless habit.","a":false,"why":"3문장: ...a habitual form of culture, which is harmful. (습관적인 문화의 형태가 되며, 이는 해롭다)\n쉽게 말해 글쓴이는 그 버릇을 '해롭다'고 본다.\n함정: harmful(해로운)을 harmless(해롭지 않은)로 바꾼 문장이다. 글쓴이의 평가 단어를 뒤집었다.\n본문 포인트: 글쓴이의 태도는 비판이다.","e":"담배를 '해롭지 않은 버릇'이라고 말하는 격."},{"s":"According to the text, justice must not be done in the public square, which today has turned into the social networks.","a":true,"why":"4문장: Justice must not be done in the public square, which today is converted into a virtual dimension, the social networks. (재판은 대중 광장에서 집행되어서는 안 되며, 그것은 오늘날 가상의 차원, 즉 소셜 네트워크로 전환된다)\n쉽게 말해 옛 광장은 이제 소셜 네트워크이고, 거기서 재판하면 안 된다는 말이다.\n문제의 has turned into는 is converted into를 쉬운 말로 바꾼 것이다.\n본문 포인트: 글의 핵심 주장이 이 문장에 나온다.","e":"운동장 대신 온라인 투표창에서 판결을 정하면 안 된다는 것."},{"s":"The text claims that the social networks are the best place to judge and make justice.","a":false,"why":"4·5문장: Justice must not be done in the public square (재판은 대중 광장에서 집행되어서는 안 된다) / the appropriate place ... is the court (적절한 장소는 법정이다)\n쉽게 말해 소셜 네트워크가 아니라 법정이 맞는 곳이다.\n함정: 적절한 장소를 법정에서 social networks로 바꿨다.\n본문 포인트: 재판의 자리는 법정이다.","e":"시험 채점을 학생 투표로 하자고 하는 격."},{"s":"In a democratic state of law, the court should judge in a way that is immune to popular pressure.","a":true,"why":"5문장: In a democratic state of law, the appropriate place to judge and make justice is the court and in a way that is immune to popular pressure. (민주적인 법치 국가에서, 재판하고 정의를 실현하기에 적절한 장소는 법정이며 대중의 압박에 영향을 받지 않는 방식이어야 한다)\n쉽게 말해 법정은 사람들의 압력에 휘둘리지 않고 판단해야 한다는 말이다.\n본문 포인트: 법정의 독립성이 이 글의 제목이자 결론이다.","e":"심판이 관중 환호에 따라 판정을 바꾸면 안 되는 것."},{"s":"In a democratic state of law, the court should follow popular opinion on social networks when it judges.","a":false,"why":"5문장: ...in a way that is immune to popular pressure (대중의 압박에 영향을 받지 않는 방식으로)\n쉽게 말해 여론을 따르는 게 아니라 여론의 압박에서 벗어나야 한다.\n함정: immune to(영향받지 않는)를 follow(따르다)로 뒤집었다.\n본문 포인트: 법정은 여론에서 독립되어야 한다.","e":"시험 문제를 학생 인기투표로 정답 정하는 격."}],"eob":[{"s":"However, when people turn to social networks to put pressure on judicial decisions in certain mediated and politicized processes, this practice is popularized and ( ______ ) a habitual form of culture, which is harmful.","ch":["becomes","become"],"a":0,"why":"3문장: ...this practice is popularized and becomes a habitual form of culture (이 관행은 대중화되고 습관적인 문화의 형태가 된다)\n주어는 this practice (이 관행)로 하나이다. 그래서 is popularized와 짝을 이루는 동사도 단수형 becomes여야 한다.\n함정: 앞에 social networks, decisions, processes 같은 복수 명사가 많아서 become을 고르기 쉽다. 하지만 동사의 주어는 this practice뿐이다.\n본문 포인트: 이 관행이 버릇이 된다는 것이 글의 걱정이다.","tr":"그러나 사람들이 어떤 조정되고 정치화되는 과정에서 사법적 결정에 압박을 가하기 위해 소셜 네트워크에 의존할 때, 이 관행은 대중화되고 습관적인 문화의 형태가 되며, 이는 해롭다.","g":"주어가 단수이면 and로 이어진 동사도 단수로 맞춘다. 사이에 복수 명사가 끼어도 주어만 본다.\n예) The habit spreads and grows. (그 습관은 퍼지고 커진다.)"},{"s":"Justice must not ( ______ ) in the public square, which today is converted into a virtual dimension, the social networks.","ch":["be done","do"],"a":0,"why":"4문장: Justice must not be done in the public square (재판은 대중 광장에서 집행되어서는 안 된다)\n주어 Justice (재판, 정의)는 스스로 하는 게 아니라 사람들에 의해 '집행되는' 대상이다. 그래서 수동태 be done이 맞다.\n조동사 must not 뒤에는 동사원형이 오고, 수동태는 be + 과거분사이다.\n함정: do가 동사원형이라 형태만 보면 맞아 보이지만, 뜻이 능동(정의가 ~을 한다)이 되어 어색하다.\n본문 포인트: 재판이 광장에서 이루어지면 안 된다는 주장이다.","tr":"재판은 대중 광장에서 집행되어서는 안 되며, 그것은 오늘날 가상의 차원, 즉 소셜 네트워크로 전환된다.","g":"주어가 행동을 '당하는' 대상이면 수동태 be + 과거분사를 쓴다.\n예) The homework must be done today. (숙제는 오늘 끝내져야 한다.)"},{"s":"In a democratic state of law, the appropriate place to judge and make justice ( ______ ) the court and in a way that is immune to popular pressure.","ch":["is","are"],"a":0,"why":"5문장: ...the appropriate place to judge and make justice is the court (재판하고 정의를 실현하기에 적절한 장소는 법정이다)\n주어는 the appropriate place (적절한 장소) 하나라서 단수 동사 is를 쓴다.\n함정: to judge and make justice처럼 and가 보여서 복수로 착각하기 쉽다. 하지만 to judge and make는 place를 꾸며 주는 덩어리일 뿐 주어가 아니다. 뒤의 the court는 보어이다.\n본문 포인트: 장소는 하나, 곧 법정이다.","tr":"민주적인 법치 국가에서, 재판하고 정의를 실현하기에 적절한 장소는 법정이며 대중의 압박에 영향을 받지 않는 방식이어야 한다.","g":"주어를 꾸미는 말에 and가 있어도 주어가 하나이면 단수 동사를 쓴다.\n예) The place to eat and rest is the cafe. (먹고 쉴 곳은 카페이다.)"},{"s":"If we understand mass culture as a weakening factor of the cultural ties that unite people to their traditions, mass culture weakens the intermediary institutions in society, ( ______ ) their role and overlapping these institutions.","ch":["diminishing","diminished"],"a":0,"why":"1문장: ...mass culture weakens the intermediary institutions in society, diminishing their role (대중문화는 사회 내의 매개 제도를 약화시켜, 그것들의 역할을 축소시킨다)\n앞 절의 주어 mass culture가 '역할을 줄이는' 쪽이다. 능동의 뜻이라 현재분사 diminishing (줄이면서)이 맞다.\n뒤의 overlapping과 and로 연결되므로 둘 다 -ing 모양으로 맞춘다.\n함정: diminished (줄어든)는 '역할이 줄어든 상태'로 읽혀 and overlapping과 모양이 어긋난다.\n본문 포인트: 대중문화가 제도의 역할을 줄인다.","tr":"만약 우리가 대중문화를 전통에 사람들을 결속시키는 문화적 유대감을 약화시키는 요인으로 이해한다면, 대중문화는 사회 내의 매개 제도를 약화시켜 그것들의 역할을 축소시키고 이 제도들과 중첩된다.","g":"주절의 주어가 직접 하는 동작을 덧붙일 때는 현재분사(-ing)를 쓴다.\n예) She left the room, closing the door. (그녀는 문을 닫으면서 방을 나갔다.)"}],"awk":[{"t":"Justice must [[1|not]] be done in the public square, which today is [[2|converted]] into a virtual dimension, the social networks. In a democratic state of law, the [[3|appropriate]] place to judge and make justice is the court and in a way that is [[4|vulnerable]] to popular [[5|pressure]].","a":4,"fix":"immune","why":"원문은 immune to popular pressure (대중의 압박에 영향을 받지 않는)이다.\n정답은 4번 vulnerable (영향을 받기 쉬운)이다.\n글쓴이는 법정이 대중 압박에서 독립되어야 한다고 한다. vulnerable이면 '압박에 약한 방식'이 되어 4문장·5문장의 주장과 모순된다.\n함정: pressure (압박)는 원문 그대로이다. 그 앞의 형용사 하나가 방향을 정한다.\n본문 포인트: 법정은 압박에 흔들리지 않아야 한다.","sp":[{"b":"not","m":"~하지 않다","n":"must not = ~해서는 안 된다","y":"맞음. 광장에서 재판하면 안 된다는 주장.","e":"교실에서 뛰면 안 된다는 규칙."},{"b":"converted","m":"바뀐","n":"is converted into = ~로 바뀌다","y":"맞음. 광장이 가상의 장소로 바뀌었다.","e":"종이 지도가 앱 지도로 바뀐 것."},{"b":"appropriate","m":"적절한","n":"형용사. place를 꾸밈","y":"맞음. 재판에 맞는 곳은 법정이라는 뜻.","e":"체육복이 운동에 적절한 것."},{"b":"vulnerable","m":"영향을 받기 쉬운","n":"be vulnerable to = ~에 약하다","y":"어색함. 원문은 immune. 법정이 압박에 약하다면 글쓴이의 주장과 모순.","e":"감기에 쉽게 걸리는 약한 몸."},{"b":"pressure","m":"압박","n":"명사. popular pressure = 대중의 압박","y":"맞음. 원문 그대로. 법정이 벗어나야 할 대상.","e":"시험 직전 친구들의 재촉."}]},{"t":"[[1|However]], when people [[2|turn]] to social networks to put pressure on judicial decisions in certain mediated and politicized processes, this practice is [[3|popularized]] and becomes a [[4|habitual]] form of culture, which is [[5|beneficial]].","a":5,"fix":"harmful","why":"원문은 which is harmful (이는 해롭다)이다.\n정답은 5번 beneficial (이로운)이다.\n바로 다음 문장에서 글쓴이는 Justice must not be done in the public square (재판은 광장에서 집행되어서는 안 된다)라고 반대한다. 이로운 일이라면 반대할 이유가 없다.\n또 앞 문장은 법정이 중요하다고 했고, However (하지만)로 그 법정을 압박하는 일을 비판한다.\n본문 포인트: 글쓴이는 압박이 버릇이 되는 것을 해롭다고 본다.","sp":[{"b":"However","m":"하지만","n":"문장 맨 앞 연결어","y":"맞음. 법정은 중요하다는 앞 내용과 반대되는 내용이 이어짐.","e":"'좋아. 하지만…' 하고 반대 이야기를 꺼내는 말."},{"b":"turn","m":"의존하다","n":"turn to = ~에 의지하다","y":"맞음. 소셜 네트워크에 의지해 압박을 가함.","e":"궁금하면 인터넷에 의지하는 것."},{"b":"popularized","m":"대중화된","n":"is popularized = 수동태","y":"맞음. 이 관행이 널리 퍼짐.","e":"유행어가 널리 퍼지는 것."},{"b":"habitual","m":"습관적인","n":"형용사. form을 꾸밈","y":"맞음. 버릇처럼 굳어진 문화.","e":"매일 하는 습관."},{"b":"beneficial","m":"이로운","n":"형용사","y":"어색함. 원문은 harmful. 글쓴이는 이 관행을 비판하므로 이로운이면 모순.","e":"몸에 좋다고 말하면 안 되는 야식."}]},{"t":"If we understand mass culture as a [[1|weakening]] factor of the cultural ties that [[2|unite]] people to their traditions, mass culture [[3|strengthens]] the [[4|intermediary]] institutions in society (e.g. the family or the school), [[5|diminishing]] their role and overlapping these institutions.","a":3,"fix":"weakens","why":"원문은 mass culture weakens (대중문화는 약화시킨다)이다.\n정답은 3번 strengthens (강화한다)이다.\n앞에서 대중문화를 '약화시키는 요인(weakening factor)'이라 했고, 뒤에서도 diminishing their role (그것들의 역할을 줄이면서)이라 했다. 가운데만 strengthens(강화하다)면 앞뒤가 모두 어긋난다.\n본문 포인트: 대중문화는 제도를 약하게 만든다.","sp":[{"b":"weakening","m":"약화시키는","n":"형용사처럼 factor를 꾸미는 -ing","y":"맞음. 대중문화를 '약화 요인'으로 이해하는 것.","e":"점점 힘을 빼는 요인."},{"b":"unite","m":"결속시키다","n":"관계대명사 that절의 동사","y":"맞음. 사람과 전통을 묶는 유대감.","e":"친구들을 한 팀으로 묶는 것."},{"b":"strengthens","m":"강화하다","n":"3인칭 단수 현재형","y":"어색함. 원문은 weakens. 앞뒤가 '약화·축소'라서 모순.","e":"체력이 떨어지는데 '튼튼해진다'고 하는 격."},{"b":"intermediary","m":"매개하는","n":"형용사. institutions를 꾸밈","y":"맞음. 개인과 사회 사이를 잇는 제도.","e":"학부모와 학교를 이어 주는 중간 다리."},{"b":"diminishing","m":"줄이면서","n":"분사구문","y":"맞음. 역할을 줄이는 결과.","e":"점점 줄어드는 용돈."}]},{"t":"For example, courts are [[1|traditional]] social institutions and [[2|unnecessary]] for the [[3|normal]] and [[4|harmonious]] functioning of [[5|collective]] life.","a":2,"fix":"important","why":"원문은 important for the normal and harmonious functioning of collective life (집단 생활의 정상적이고 조화로운 기능에 중요하다)이다.\n정답은 2번 unnecessary (불필요한)이다.\n이 문장은 For example (예를 들어)로 '대중문화가 약하게 만드는 중요한 제도'의 예를 든다. 법정이 불필요하다면 약해져도 문제가 없어서 글의 걱정이 사라진다.\n또 다음 문장 However 이하의 비판과도 이어지지 않는다.\n본문 포인트: 법정은 사회에 꼭 필요한 제도이다.","sp":[{"b":"traditional","m":"전통적인","n":"형용사","y":"맞음. 오래된 사회 기관.","e":"오래된 마을 규칙."},{"b":"unnecessary","m":"불필요한","n":"형용사. important의 반대","y":"어색함. 원문은 important. 법정은 사회에 꼭 필요한 제도.","e":"꼭 있어야 하는 소방서를 '필요 없다'고 하는 격."},{"b":"normal","m":"정상적인","n":"형용사. functioning을 꾸밈","y":"맞음. 사회가 평소처럼 돌아가는 것.","e":"평소처럼 수업이 진행되는 것."},{"b":"harmonious","m":"조화로운","n":"형용사","y":"맞음. 사람들이 어울려 사는 것.","e":"화음이 맞는 합창."},{"b":"collective","m":"집단의","n":"형용사. life를 꾸밈","y":"맞음. 여럿이 함께하는 생활.","e":"학급 전체가 함께하는 생활."}]}],"und":[{"q":"<u>mass culture weakens the intermediary institutions in society</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["대중문화가 가족이나 학교처럼 사람과 사회를 이어 주는 제도들의 힘을 약하게 만든다","대중문화가 가족이나 학교를 새로 만들어 낸다","대중문화가 사회 속 제도들을 더 튼튼하게 이어 준다","대중문화가 법정만 예외로 약하게 만든다","대중문화가 전통을 되살려 제도를 대신한다"],"a":0,"why":"1문장: ...mass culture weakens the intermediary institutions in society (대중문화는 사회 내의 매개 제도를 약화시킨다)\nintermediary institutions = 개인과 사회 사이를 잇는 제도. 괄호 안에 예로 가족과 학교가 나온다.\n정답은 weakens (약화시킨다)를 쉬운 말로 푼 것이다.\n'더 튼튼하게 이어 준다'는 strengthen (강화)으로 뒤집은 것이다. '법정만 예외'라는 말은 글에 없다. '전통을 되살린다'와 '새로 만들어 낸다'도 글에 없다.\n본문 포인트: 대중문화 때문에 제도의 역할이 줄어든다.","e":"가족·학교의 역할이 SNS 유행에 밀려 작아지는 것.","tr":"대중문화는 …사회 내의 매개하는 제도들을 약화시킨다."},{"q":"<u>Justice must not be done in the public square</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["재판은 여론이 모이는 소셜 네트워크 같은 공개된 곳에서 정해져서는 안 된다","재판은 광장에서 공개적으로 열려야만 한다","재판은 대중이 직접 투표해서 결과를 정해야 한다","재판은 법정 안에서 비밀로만 진행되어야 한다","재판은 광장이 아니라 학교에서 해야 한다"],"a":0,"why":"4문장: Justice must not be done in the public square, which today is converted into a virtual dimension, the social networks. (재판은 대중 광장에서 집행되어서는 안 되며, 그것은 오늘날 소셜 네트워크로 전환된다)\npublic square = 대중 광장. 오늘날은 소셜 네트워크가 그 자리를 대신한다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'광장에서 열려야만 한다'는 must not (~해서는 안 된다)을 반대로 읽은 것이다. '투표로 정한다'는 말은 글에 없다. '비밀로만'은 지나친 말이고, '학교에서'는 글과 무관하다.\n본문 포인트: 재판의 자리는 소셜 네트워크가 아니라 법정이다.","e":"반 반장을 뽑듯 투표로 판결을 정하면 안 된다는 것.","tr":"재판은 대중 광장에서 집행되어서는 안 된다."},{"q":"in a way that is <u>immune to popular pressure</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["사람들이 몰아붙여도 그 압력에 휘둘리지 않는","사람들의 압박에 맞춰 판결을 바꾸는","사람들의 박수를 받을 때만 효력이 생기는","사람들에게 압박을 가할 수 있는","사람들의 압박을 이해하려고 애쓰는"],"a":0,"why":"5문장: ...the court and in a way that is immune to popular pressure. (…법정이며 대중의 압박에 영향을 받지 않는 방식이어야 한다)\nimmune to = ~에 영향을 받지 않는. popular pressure = 대중의 압박.\n정답은 이 뜻을 풀어 쓴 것이다.\n'압박에 맞춰 판결을 바꾸는'은 immune (영향받지 않는)를 반대로 읽은 것이다. '박수를 받을 때만'과 '압박을 가할 수 있는'은 글에 없는 내용이다. '이해하려고 애쓰는'도 글에 없다.\n본문 포인트: 법정의 독립성은 여론의 압박에서 벗어나는 것이다.","e":"심판이 관중의 야유에도 판정을 바꾸지 않는 것.","tr":"…대중의 압박에 영향을 받지 않는 방식으로."}]},"2610-33":{"voc":[{"q":"Human development is now increasingly understood as an <u>ongoing</u>, flexible, and evolving process…","ask":"ongoing의 뜻으로 알맞은 것은?","ch":["계속 진행 중인","이미 끝난","시작도 안 한","한 번뿐인","비밀스러운"],"a":0,"why":"1문장: ...an ongoing, flexible, and evolving process (계속 진행 중이고, 유연하며, 서서히 발전하는 과정)\n쉽게 말해 사람의 발달은 어느 나이에 멈추는 게 아니라 계속 이어진다는 뜻이다.\nongoing = 계속 진행 중인 (on + going, 계속 가고 있는). 비슷한 말: continuing.\n이 글은 발달이 '고정된 단계'가 아니라 '이어지는 과정'이라는 말로 시작한다. ongoing이 그 핵심 낱말이다.\n오답 함정: '이미 끝난'은 반대 뜻이다.\n본문 포인트: 발달은 평생 이어지는 과정이다.","e":"방학 동안 계속 이어지는 독서 챌린지.","tr":"인간 발달은 이제 점점 더 계속 진행 중이고 유연하며 서서히 발전하는 과정으로 이해된다.","alt":"continuing, in progress"},{"q":"Plasticity refers to the human <u>capacity</u> to change, adapt, and reorganize…","ask":"이 문장에서 capacity의 뜻으로 알맞은 것은?","ch":["능력, 역량","크기, 부피","수업, 교실","습관, 버릇","이유, 원인"],"a":0,"why":"3문장: Plasticity refers to the human capacity to change, adapt, and reorganize ... (가소성은 변화하고, 적응하고, 재구성하는 인간의 능력을 지칭한다)\n쉽게 말해 사람이 스스로 바뀔 수 있는 힘이라는 뜻이다.\ncapacity는 다의어이다. ① 능력, 역량 ② 수용력, 용량 (예: a stadium's capacity = 경기장의 수용 인원).\n여기서는 to change (변화하는)가 뒤따라 ①번 능력이다.\n오답 함정: ②번 뜻이 먼저 떠올라 '크기, 부피'를 고르기 쉽다. 뒤에 to + 동사가 오면 '~할 수 있는 힘'으로 읽는다.\n본문 포인트: 가소성은 변화할 수 있는 능력이다.","e":"체육관 정원이 500명이라는 말과, 달리기 능력이 뛰어나다는 말 두 가지로 쓰이는 것.","tr":"가소성은 …변화시키고 적응시키며 재구성하는 인간의 능력을 지칭한다.","alt":"ability, capability; 다른 뜻: 수용력"},{"q":"…reorganize <u>cognitive</u>, emotional, and behavioural patterns…","ask":"cognitive의 뜻으로 알맞은 것은?","ch":["인지의, 생각하고 이해하는","신체의","예술의","경제의","법적인"],"a":0,"why":"3문장: ...cognitive, emotional, and behavioural patterns (인지적, 정서적, 행동적 패턴)\n쉽게 말해 생각하는 방식, 느끼는 방식, 행동하는 방식을 가리킨다.\ncognitive = 인지의, 생각·이해·기억과 관련된. 명사 cognition (인지)과 같은 가족이다.\n세 낱말 cognitive, emotional, behavioural은 각각 생각·감정·행동이라고 짝지어 외워 두면 좋다.\n오답 함정: '신체의'는 behavioural(행동)과 헷갈리지 않게 구분한다.\n본문 포인트: 가소성은 생각·감정·행동 모두에 해당한다.","e":"문제를 풀 때 머리로 생각하고 이해하는 활동.","tr":"…인지적, 정서적, 그리고 행동적 패턴들…","alt":"mental; 짝: emotional (정서의), behavioural (행동의)"},{"q":"…individuals are not merely <u>passive</u> recipients of development…","ask":"passive의 반의어로 알맞은 것은?","ch":["active","fixed","distant","ancient","heavy"],"a":0,"why":"4문장: ...individuals are not merely passive recipients of development but active agents capable of growth (개인은 단순히 발달의 수동적인 수용자가 아니라 성장이 가능한 능동적인 주체이다)\n쉽게 말해 사람은 가만히 받기만 하는 존재가 아니라 스스로 움직이는 존재라는 뜻이다.\npassive = 수동적인. 반대말은 active (능동적인). 바로 뒤에 active agents가 나와서 짝을 이룬다.\nnot A but B (A가 아니라 B) 구조에서 A와 B는 반대 뜻이다. passive와 active가 정확히 그 짝이다.\n오답 함정: fixed (고정된)는 1문장에 나온 낱말이라 헷갈리지만 passive의 반대가 아니다.\n본문 포인트: 사람은 스스로 성장하는 주체이다.","e":"숙제를 시켜야만 하는 학생과 스스로 하는 학생의 차이.","tr":"…개인들이 단순히 발달의 수동적인 수용자가 아니라…","alt":"반의어: active; 파생: passively (수동적으로)"},{"q":"…with adulthood seen as a period of stability and old age as a phase of <u>decline</u>.","ask":"이 문장에서 decline의 뜻으로 알맞은 것은?","ch":["쇠퇴, 감소","거절하다","발전","도착","설명"],"a":0,"why":"5문장: ...old age as a phase of decline (노년기는 쇠퇴의 단계로)\n쉽게 말해 나이가 들면 점점 약해지는 시기라고 여겼다는 뜻이다.\ndecline은 다의어이다. ① 명사: 쇠퇴, 감소 ② 동사: 거절하다 (= refuse), 줄어들다.\n여기서는 a phase of decline이라 명사 ①번이다. 앞의 stability (안정)와 대비되는 말이다.\n오답 함정: '거절하다'는 동사 뜻이라 여기서는 맞지 않다. '발전'은 정반대 뜻이다.\n본문 포인트: 옛 관점에서는 노년기를 쇠퇴로만 보았고, 이 글은 그 생각을 반박한다.","e":"초대를 거절할 때도 쓰고, 인구가 줄 때도 쓰는 낱말.","tr":"…노년기는 쇠퇴의 단계로 간주되었다.","alt":"명사: decrease, drop; 동사: refuse, turn down"},{"q":"The concept of plasticity challenges this <u>rigid</u> outlook…","ask":"rigid의 뜻으로 알맞은 것은?","ch":["경직된, 융통성 없는","유연한","따뜻한","새로운","재미있는"],"a":0,"why":"6문장: The concept of plasticity challenges this rigid outlook (가소성의 개념은 이러한 경직된 사고방식에 이의를 제기한다)\n쉽게 말해 '사람은 어릴 때만 변하고 그 뒤로는 안 변한다'는 딱딱한 생각을 반박한다는 뜻이다.\nrigid = 경직된, 딱딱한. 반대말은 flexible (유연한)이고 1문장에 나왔다.\n1문장의 flexible (유연한)과 6문장의 rigid가 서로 반대로 쓰여 글의 대립 구도를 보여 준다.\n오답 함정: '유연한'은 바로 반대 뜻이다.\n본문 포인트: 유연한 발달관 vs 경직된 발달관. 이 글은 유연한 쪽이다.","e":"한 번 정해지면 절대 바꾸지 않는 학교 규칙.","tr":"…가소성의 개념은 이러한 경직된 사고방식에 이의를 제기한다.","alt":"stiff, inflexible; 반의어: flexible"},{"q":"…by <u>emphasizing</u> that development continues across the entire lifespan.","ask":"emphasizing과 바꿔 쓸 수 있는 말은?","ch":["stressing","ignoring","delaying","avoiding","doubting"],"a":0,"why":"6문장: ...by emphasizing that development continues across the entire lifespan (발달이 전 생애에 걸쳐 계속된다는 점을 강조함으로써)\n쉽게 말해 '평생 발달한다'는 점을 크게 내세운다는 뜻이다.\nemphasize = 강조하다 (= stress, highlight). 4문장의 highlights와도 같은 뜻이다.\nby -ing = ~함으로써. 가소성의 개념이 무엇으로 반박하는지 알려 주는 부분이다.\n오답 함정: ignoring (무시하는)은 정반대이다.\n본문 포인트: 이 글은 평생 발달이라는 점을 강조한다.","e":"중요한 부분에 형광펜을 크게 칠하는 것.","tr":"…발달이 전 생애에 걸쳐 계속된다는 점을 강조함으로써…","alt":"stress, highlight, underline"},{"q":"Although the <u>extent</u> of change may vary at different stages…","ask":"extent의 뜻으로 알맞은 것은?","ch":["정도, 범위","이유","속도","순서","방향"],"a":0,"why":"7문장: Although the extent of change may vary at different stages (비록 변화의 정도가 서로 다른 단계에서 다를지라도)\n쉽게 말해 변하는 크기는 나이마다 다를 수 있다는 뜻이다.\nextent = 정도, 범위. to some extent = 어느 정도는.\nvary (다르다, 달라지다)와 함께 쓰이면 '정도가 다르다'로 읽는다.\n오답 함정: '속도'는 speed, '순서'는 order이다. extent는 크기·범위를 가리킨다.\n본문 포인트: 정도는 달라도 모든 단계에 변화의 여지가 있다.","e":"같은 문제집도 학생마다 이해하는 정도가 다른 것.","tr":"비록 변화의 정도가 서로 다른 단계들에서 다를지라도…","alt":"degree, scale, range"}],"find":[{"s":"Human development is now increasingly understood as an ongoing and flexible process.","a":true,"why":"1문장: Human development is now increasingly understood as an ongoing, flexible, and evolving process (인간 발달은 이제 점점 더 계속 진행 중이고 유연하며 서서히 발전하는 과정으로 이해된다)\n쉽게 말해 발달은 계속 이어지는 유연한 과정이라는 말이다.\n본문 포인트: 글은 발달을 고정된 틀이 아닌 과정으로 본다.","e":"레고처럼 계속 바꿔 끼울 수 있는 것."},{"s":"Human development is now understood as a fixed sequence of stages.","a":false,"why":"1문장: ...rather than a fixed sequence of stages (고정된 순서의 단계들이라기보다는)\n쉽게 말해 '고정된 단계'가 아니라 '계속 이어지는 과정'이다.\n함정: rather than (~이라기보다) 뒤의 내용을 본문의 주장으로 착각하게 만든 문장이다.\n본문 포인트: 고정된 단계는 글이 부정하는 쪽이다.","e":"정해진 계단을 한 칸씩만 올라가는 것."},{"s":"The concept of plasticity lies at the core of this perspective.","a":true,"why":"2문장: At the core of this perspective lies the concept of plasticity. (이러한 관점의 핵심에는 가소성의 개념이 있다)\n쉽게 말해 이 관점의 중심 낱말은 가소성이다.\n문제 문장은 도치된 본문 문장의 순서를 바로잡은 것이다.\n본문 포인트: 글의 핵심어는 plasticity이다.","e":"사과 한가운데에 있는 씨 같은 것."},{"s":"Plasticity refers to the human capacity to change, adapt, and reorganize patterns in response to life experiences.","a":true,"why":"3문장: Plasticity refers to the human capacity to change, adapt, and reorganize cognitive, emotional, and behavioural patterns in response to life experiences ... (가소성은 삶의 경험에 반응하여 인지적, 정서적, 행동적 패턴을 변화시키고 적응시키며 재구성하는 인간의 능력을 지칭한다)\n쉽게 말해 경험에 따라 생각·감정·행동 방식을 바꿀 수 있는 힘이다.\n본문 포인트: 가소성은 변화하는 능력이다.","e":"새 학교에 가면 말투와 습관이 조금 달라지는 것."},{"s":"Plasticity refers to the ability to keep our patterns unchanged regardless of life experiences.","a":false,"why":"3문장: ...change, adapt, and reorganize ... patterns in response to life experiences (삶의 경험에 반응하여 패턴을 변화시키고 적응시키고 재구성하는)\n쉽게 말해 경험에 따라 '바꾸는' 능력이다.\n함정: 변화(change)를 정반대인 '그대로 유지'로 바꾼 문장이다.\n본문 포인트: 가소성의 핵심은 변화이다.","e":"한번 구운 도자기처럼 절대 안 변하는 것."},{"s":"Individuals are described as active agents capable of growth throughout their lives.","a":true,"why":"4문장: ...individuals are not merely passive recipients of development but active agents capable of growth throughout their lives (개인은 단순히 발달의 수동적인 수용자가 아니라 평생에 걸쳐 성장이 가능한 능동적인 주체이다)\n쉽게 말해 사람은 스스로 자라는 주체라는 말이다.\n본문 포인트: 가소성은 사람을 능동적인 존재로 본다.","e":"스스로 운동 계획을 세워 실천하는 학생."},{"s":"According to the text, individuals are passive recipients of development.","a":false,"why":"4문장: ...not merely passive recipients of development but active agents (단순히 발달의 수동적인 수용자가 아니라 능동적인 주체)\n쉽게 말해 수동적인 수용자는 글이 부정하는 쪽이다.\n함정: not A but B (A가 아니라 B)에서 A를 본문의 주장으로 착각하게 만든 문장이다.\n본문 포인트: 정답은 B인 active agents이다.","e":"시키는 것만 받아 적는 학생이라는 설명은 틀린 것."},{"s":"In earlier views, development was believed to occur mainly during childhood.","a":true,"why":"5문장: In earlier views, development was believed to occur mainly during childhood (이전의 관점에서는 발달이 주로 아동기에 일어난다고 믿어졌다)\n쉽게 말해 옛날에는 어릴 때만 자란다고 생각했다.\n본문 포인트: 이 옛 관점을 6문장이 반박한다.","e":"키가 어릴 때만 자란다고 믿는 것."},{"s":"In earlier views, adulthood was seen as a period of rapid change.","a":false,"why":"5문장: ...with adulthood seen as a period of stability (성인기는 안정의 시기로 간주되었다)\n쉽게 말해 어른은 안정된 시기라고 봤다.\n함정: stability (안정)를 rapid change (빠른 변화)로 바꿨다. 이전 관점은 어른은 안 변한다는 쪽이다.\n본문 포인트: 이전 관점은 성인기를 변하지 않는 시기로 보았다.","e":"어른이 되면 성격이 고정된다는 생각."},{"s":"The concept of plasticity challenges the rigid outlook by emphasizing that development continues across the entire lifespan.","a":true,"why":"6문장: The concept of plasticity challenges this rigid outlook by emphasizing that development continues across the entire lifespan. (가소성의 개념은 발달이 전 생애에 걸쳐 계속된다는 점을 강조함으로써 이러한 경직된 사고방식에 이의를 제기한다)\n쉽게 말해 평생 발달한다고 말해서 옛 생각을 반박한다.\n본문 포인트: 이 문장이 글의 주제를 가장 잘 보여 준다.","e":"'어릴 때만 큰다'는 말을 '평생 큰다'로 고쳐 주는 것."},{"s":"The extent of change is exactly the same at every stage of life.","a":false,"why":"7문장: Although the extent of change may vary at different stages (변화의 정도가 서로 다른 단계에서 다를지라도)\n쉽게 말해 변하는 정도는 단계마다 다를 수 있다.\n함정: may vary (다를 수 있다)를 exactly the same (정확히 같다)으로 바꿨다. 본문은 Although (비록 ~일지라도)로 '다르다'를 인정한다.\n본문 포인트: 정도는 달라도 변화 가능성은 모든 단계에 있다.","e":"같은 과목이라도 학생마다 늘어나는 속도가 다른 것."},{"s":"According to the text, every phase of life allows room for adaptation and transformation.","a":true,"why":"7문장: ...every phase of life allows room for adaptation and transformation (삶의 각각의 단계는 적응과 변화를 위한 여지를 허용한다)\n쉽게 말해 어느 나이든 바뀔 수 있는 여지가 있다는 말이다.\nroom for = ~을 위한 여지, 공간.\n본문 포인트: 이 글의 결론이다. 평생 바뀔 수 있다.","e":"고3이어도 영어 실력이 늘 수 있다는 말."}],"eob":[{"s":"At the core of this perspective ( ______ ) the concept of plasticity.","ch":["lies","lie"],"a":0,"why":"2문장: At the core of this perspective lies the concept of plasticity. (이러한 관점의 핵심에는 가소성의 개념이 있다)\n장소 표현이 앞에 나와 주어와 동사 순서가 바뀐 도치 문장이다. 진짜 주어는 뒤의 the concept of plasticity (가소성의 개념)이다.\nconcept가 단수이므로 동사는 lies이다.\n함정: 앞에 perspective (관점)가 먼저 보이지만 주어가 아니다. 도치 문장에서는 동사 뒤의 명사를 주어로 본다.\n본문 포인트: 핵심은 가소성의 개념이다.","tr":"이러한 관점의 핵심에는 가소성의 개념이 있다.","g":"장소 표현이 앞에 나오면 주어와 동사의 순서가 바뀐다. 동사는 뒤의 주어에 맞춘다.\n예) On the table lie two books. (탁자 위에 책 두 권이 놓여 있다.)"},{"s":"Plasticity refers to the human capacity to change, adapt, and ( ______ ) cognitive, emotional, and behavioural patterns in response to life experiences…","ch":["reorganize","reorganizing"],"a":0,"why":"3문장: ...the human capacity to change, adapt, and reorganize cognitive ... patterns (패턴을 변화시키고, 적응시키고, 재구성하는 인간의 능력)\nand로 이어진 세 동사 change, adapt, reorganize는 모두 to 뒤에 오는 동사원형이다. 병렬 구조는 모양을 똑같이 맞춘다.\n함정: reorganizing (재구성하는)을 고르면 앞의 change, adapt와 모양이 어긋난다.\n본문 포인트: 세 동사가 가소성의 내용이다.","tr":"가소성은 삶의 경험에 반응하여 인지적, 정서적, 행동적 패턴을 변화시키고, 적응시키며, 재구성하는 인간의 능력을 지칭한다.","g":"A, B, and C로 이어진 말은 모양을 맞춘다. to change, (to) adapt, and (to) reorganize처럼 동사원형끼리 맞춘다.\n예) I want to sing, dance, and play. (나는 노래하고, 춤추고, 연주하고 싶다.)"},{"s":"It highlights ( ______ ) individuals are not merely passive recipients of development but active agents capable of growth throughout their lives.","ch":["that","what"],"a":0,"why":"4문장: It highlights that individuals are not merely passive recipients ... (그것은 개인들이 단순히 발달의 수동적인 수용자가 아니라는 점을 강조한다)\nhighlight (강조하다)의 목적어로 완전한 문장(individuals are ...)이 이어진다. 완전한 절을 이끄는 접속사는 that이다.\nwhat은 뒤에 주어나 목적어가 빠진 불완전한 절 앞에 온다. 이 문장은 individuals가 주어이고 are의 보어도 있어서 빠진 게 없다.\n본문 포인트: that절이 강조하는 내용이 핵심이다.","tr":"그것은 개인들이 단순히 발달의 수동적인 수용자가 아니라 평생에 걸쳐 성장이 가능한 능동적인 주체들이라는 점을 강조한다.","g":"뒤에 완전한 문장이 오면 that (~라는 것), 주어나 목적어가 빠지면 what (~하는 것)을 쓴다.\n예) I know that she is kind. (나는 그녀가 친절하다는 것을 안다.)"},{"s":"In earlier views, development was believed ( ______ ) mainly during childhood.","ch":["to occur","occurring"],"a":0,"why":"5문장: In earlier views, development was believed to occur mainly during childhood (이전의 관점에서는 발달이 주로 아동기에 일어난다고 믿어졌다)\nbelieve A to V (A가 ~한다고 믿다)의 수동태는 A is believed to V이다. 그래서 was believed 뒤에 to occur가 온다.\n함정: was believed 뒤에는 to부정사가 와야 하고, -ing 형태는 이런 구조에 쓰이지 않는다.\n본문 포인트: 옛날 사람들의 믿음을 소개하는 문장이다.","tr":"이전의 관점들에서는 발달이 주로 아동기에 일어난다고 믿어졌다.","g":"'~라고 믿어진다'는 be believed to + 동사원형으로 쓴다.\n예) He is said to be kind. (그는 친절하다고 한다.)"},{"s":"( ______ ) the extent of change may vary at different stages, every phase of life allows room for adaptation and transformation.","ch":["Although","Despite"],"a":0,"why":"7문장: Although the extent of change may vary at different stages, every phase of life allows room... (비록 변화의 정도가 서로 다른 단계에서 다를지라도, 삶의 각 단계는 여지를 허용한다)\n뒤에 the extent of change may vary (주어 + 동사)가 이어지는 절이 온다. 절 앞에는 접속사 Although (비록 ~일지라도)를 쓴다.\nDespite는 전치사라서 뒤에 명사만 온다. Despite the extent...처럼 명사구만 이어져야 한다.\n본문 포인트: 정도는 다르지만 변화의 여지는 모든 단계에 있다.","tr":"비록 변화의 정도가 서로 다른 단계들에서 다를지라도, 삶의 각각의 단계는 적응과 변화를 위한 여지를 허용한다.","g":"절(주어+동사) 앞에는 Although, 명사 앞에는 Despite를 쓴다.\n예) Although it rained, we played. / Despite the rain, we played. (비가 왔지만 우리는 놀았다.)"}],"awk":[{"t":"Human development is now increasingly understood as an [[1|ongoing]], [[2|rigid]], and [[3|evolving]] process [[4|rather than]] a [[5|fixed]] sequence of stages.","a":2,"fix":"flexible","why":"원문은 an ongoing, flexible, and evolving process (계속 진행 중이고 유연하며 서서히 발전하는 과정)이다.\n정답은 2번 rigid (경직된)이다.\n뒤에서 rather than a fixed sequence of stages (고정된 순서의 단계라기보다는)라고 했다. 발달이 고정되어 있지 않다는 뜻인데 rigid (딱딱한)이면 '고정'과 같은 말이 되어 모순이다.\n함정: ongoing과 evolving은 '계속 변한다'는 같은 방향의 말이다. 가운데 하나만 방향이 다르다.\n본문 포인트: 발달은 유연하게 계속 이어진다.","sp":[{"b":"ongoing","m":"계속 진행 중인","n":"형용사. process를 꾸밈","y":"맞음. 발달이 이어진다는 뜻.","e":"끝나지 않는 챌린지."},{"b":"rigid","m":"경직된","n":"형용사","y":"어색함. 원문은 flexible. 뒤의 rather than a fixed sequence (고정된 순서라기보다)와 모순.","e":"딱딱하게 굳은 규칙."},{"b":"evolving","m":"서서히 발전하는","n":"현재분사형 형용사","y":"맞음. 조금씩 변해 가는 과정.","e":"조금씩 자라는 식물."},{"b":"rather than","m":"~라기보다","n":"rather than A = A라기보다","y":"맞음. 뒤의 fixed sequence를 부정하는 표현.","e":"'A 말고 B'라고 말하는 방식."},{"b":"fixed","m":"고정된","n":"형용사. sequence를 꾸밈","y":"맞음. 원문 그대로. 글이 부정하는 옛 관점.","e":"바꿀 수 없게 정해 둔 시간표."}]},{"t":"It highlights that individuals are not [[1|merely]] passive recipients of development but [[2|inactive]] agents [[3|capable]] of [[4|growth]] throughout their [[5|lives]].","a":2,"fix":"active","why":"원문은 not merely passive recipients ... but active agents capable of growth (단순히 수동적인 수용자가 아니라 성장이 가능한 능동적인 주체)이다.\n정답은 2번 inactive (활동하지 않는)이다.\nnot A but B 구조에서 A(passive recipients)와 B는 반대 뜻이어야 한다. inactive는 passive와 같은 방향이라 B 자리에 올 수 없다.\n또 뒤의 capable of growth (성장이 가능한)와도 어긋난다.\n본문 포인트: 사람은 스스로 성장하는 능동적인 주체이다.","sp":[{"b":"merely","m":"단지","n":"부사. not merely = 단지 ~만은 아닌","y":"맞음. not merely A but B 구조.","e":"'그냥 구경만 하는 건 아니고' 하고 덧붙이는 말."},{"b":"inactive","m":"활동하지 않는","n":"형용사. agents를 꾸밈","y":"어색함. 원문은 active. passive와 같은 방향이라 but 뒤에 올 수 없고, capable of growth와도 모순.","e":"가만히 누워 있는 사람."},{"b":"capable","m":"가능한, 할 수 있는","n":"be capable of = ~할 수 있는","y":"맞음. 성장할 수 있다는 뜻.","e":"수영할 수 있는 사람."},{"b":"growth","m":"성장","n":"명사. of 뒤에 옴","y":"맞음. 평생에 걸친 성장.","e":"키와 실력이 자라는 것."},{"b":"lives","m":"삶","n":"명사 life의 복수형","y":"맞음. 개인들 각자의 삶이라 복수형.","e":"사람마다 다른 인생."}]},{"t":"In earlier views, development was [[1|believed]] to occur [[2|mainly]] during [[3|childhood]], with adulthood seen as a period of [[4|change]] and old age as a phase of [[5|decline]].","a":4,"fix":"stability","why":"원문은 adulthood seen as a period of stability (성인기는 안정의 시기로 간주되었다)이다.\n정답은 4번 change (변화)이다.\n앞에서 옛 관점은 발달이 '주로 아동기에' 일어난다고 믿었다. 그러면 어른은 더 이상 크게 변하지 않는 시기라고 본 것이다. change (변화)이면 이 믿음과 모순된다.\n또 뒤의 decline (쇠퇴)과 묶여 '안정 → 쇠퇴'의 흐름을 이룬다.\n본문 포인트: 옛 관점은 어릴 때만 변하고 어른은 안정적이라고 보았다.","sp":[{"b":"believed","m":"믿어진","n":"was believed = 수동태","y":"맞음. 옛 사람들의 믿음.","e":"'그땐 그렇다고 다들 믿었다'는 식의 말."},{"b":"mainly","m":"주로","n":"부사","y":"맞음. 아동기에 가장 많이 일어난다는 뜻.","e":"'주로 아침에 공부해요'처럼 가장 많다는 뜻."},{"b":"childhood","m":"어린 시절","n":"명사","y":"맞음. 옛 관점이 발달이 일어난다고 본 시기.","e":"어릴 때."},{"b":"change","m":"변화","n":"명사. a period of ~","y":"어색함. 원문은 stability. 옛 관점은 어른을 변하지 않는 시기로 봄.","e":"다 자란 뒤에는 키가 안 크는 것."},{"b":"decline","m":"쇠퇴","n":"명사. a phase of ~","y":"맞음. 노년기를 약해지는 시기로 봄.","e":"체력이 점점 떨어지는 것."}]},{"t":"The concept of plasticity [[1|challenges]] this [[2|rigid]] outlook by [[3|emphasizing]] that development [[4|stops]] across the entire [[5|lifespan]].","a":4,"fix":"continues","why":"원문은 development continues across the entire lifespan (발달이 전 생애에 걸쳐 계속된다)이다.\n정답은 4번 stops (멈춘다)이다.\n앞에서 가소성의 개념이 '경직된 사고방식에 이의를 제기한다(challenges)'고 했다. 옛 관점은 어른이 되면 발달이 멈춘다는 것이므로, 그걸 반박하려면 '계속된다'고 강조해야 한다.\nstops이면 옛 관점을 그대로 따라가게 되어 모순이다.\n본문 포인트: 가소성은 평생 발달을 강조한다.","sp":[{"b":"challenges","m":"이의를 제기하다","n":"3인칭 단수 현재형","y":"맞음. 옛 관점을 반박함.","e":"'그건 아니야' 하고 반박하는 것."},{"b":"rigid","m":"경직된","n":"형용사. outlook을 꾸밈","y":"맞음. 원문 그대로. 반박 대상이 되는 딱딱한 생각.","e":"굳어 버린 생각."},{"b":"emphasizing","m":"강조하는","n":"by + -ing","y":"맞음. 무엇으로 반박하는지 알려 줌.","e":"중요한 점을 크게 말하는 것."},{"b":"stops","m":"멈춘다","n":"3인칭 단수 현재형","y":"어색함. 원문은 continues. 평생 발달을 강조하는 맥락과 모순.","e":"멈춘 시계."},{"b":"lifespan","m":"수명, 일생","n":"명사","y":"맞음. 전 생애라는 뜻.","e":"태어나서 죽을 때까지의 기간."}]}],"und":[{"q":"<u>the human capacity to change, adapt, and reorganize cognitive, emotional, and behavioural patterns</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["경험이나 환경이 달라지면 생각, 감정, 행동의 방식을 바꾸고 맞출 수 있는 사람의 힘","생각, 감정, 행동의 방식을 평생 똑같이 유지하는 사람의 고집","어린 시절에 정해진 성격을 나이가 들어서도 지켜 내는 힘","다른 사람의 생각과 감정을 그대로 따라 하는 능력","몸이 약해져도 아무것도 바꾸지 않고 버티는 능력"],"a":0,"why":"3문장: ...the human capacity to change, adapt, and reorganize cognitive, emotional, and behavioural patterns (인지적, 정서적, 행동적 패턴을 변화시키고 적응시키며 재구성하는 인간의 능력)\n세 동사 change, adapt, reorganize는 모두 '바꾸고 맞춘다'는 방향이다. 세 가지 patterns는 생각·감정·행동이다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'똑같이 유지하는'과 '지켜 내는'과 '버티는'은 change (변화)와 반대 방향이다. '다른 사람을 따라 하는'은 글에 없는 내용이다.\n본문 포인트: 가소성은 사람이 바뀔 수 있는 능력이다.","e":"전학을 가서 새 친구들에게 맞춰 말투와 습관이 조금씩 바뀌는 것.","tr":"…인지적, 정서적, 그리고 행동적 패턴들을 변화시키고, 적응시키며, 재구성하는 인간의 능력…"},{"q":"<u>active agents capable of growth throughout their lives</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["스스로 움직이며 평생 성장해 나갈 수 있는 주체적인 존재","남이 이끄는 대로 따라가며 어릴 때만 자라는 존재","특정한 나이가 되면 성장을 멈추도록 정해진 존재","다른 사람의 성장을 대신 맡아 주는 존재","일을 맡아서 처리해 주는 대리인"],"a":0,"why":"4문장: ...but active agents capable of growth throughout their lives (평생에 걸쳐 성장이 가능한 능동적인 주체)\nagent는 여기서 '행위자, 주체'이다. '대리인'이라는 뜻으로 읽으면 틀린다.\nactive agents = 스스로 움직이는 주체. capable of growth throughout their lives = 평생 성장할 수 있는.\n정답은 이 뜻을 풀어 쓴 것이다.\n'남이 이끄는 대로'는 앞의 passive (수동적인)와 같은 뜻이라 글이 부정하는 쪽이다. '성장을 멈추도록'은 throughout their lives와 모순이다. '남의 성장을 대신'은 글에 없다. '대리인'은 agent의 다른 뜻에 낚인 것이다.\n본문 포인트: 사람은 스스로 평생 자라는 주체이다.","e":"누가 시키지 않아도 스스로 목표를 세워 공부하는 학생.","tr":"…평생에 걸쳐 성장이 가능한 능동적인 주체들…"},{"q":"<u>this rigid outlook</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["사람의 발달이 어린 시절에만 일어나고 어른이 된 뒤에는 안정과 쇠퇴뿐이라는 굳어진 생각","사람의 발달이 평생 계속되고 유연하게 변한다는 생각","발달은 어린 시절에는 일어나지 않고 노년기에 시작된다는 생각","사람마다 발달 속도가 다르다는 열린 생각","환경의 영향으로 사람이 쉽게 바뀐다는 생각"],"a":0,"why":"5·6문장: In earlier views, development was believed to occur mainly during childhood (이전의 관점에서는 발달이 주로 아동기에 일어난다고 믿어졌다) → The concept of plasticity challenges this rigid outlook (가소성의 개념은 이러한 경직된 사고방식에 이의를 제기한다)\nthis rigid outlook은 바로 앞 5문장의 옛 관점을 가리킨다. 지시어는 앞 문장에서 찾는다.\n정답은 5문장 내용(아동기에 발달, 성인기 안정, 노년기 쇠퇴)을 풀어 쓴 것이다.\n'평생 계속되고 유연하게'는 오히려 글쓴이의 입장이라 정반대이다. '노년기에 시작'은 글에 없다. '열린 생각'과 '쉽게 바뀐다'는 rigid (경직된)와 반대이다.\n본문 포인트: 경직된 사고방식은 글이 반박하는 옛 관점이다.","e":"어릴 때 못하면 평생 못한다는 식의 딱딱한 생각.","tr":"가소성의 개념은 …이러한 경직된 사고방식에 이의를 제기한다."},{"q":"a <u>fixed sequence of stages</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["정해진 순서대로 한 번 지나가면 끝나는 발달의 단계들","상황에 맞게 계속 바뀌는 발달의 과정","순서 없이 마음대로 오가는 발달의 방식","평생 한 단계에 머무르는 발달의 모습","여러 사람이 함께 겪는 발달의 경험"],"a":0,"why":"1문장: ...rather than a fixed sequence of stages (고정된 순서의 단계들이라기보다는)\nfixed = 고정된, sequence = 순서, stages = 단계들. '정해진 순서의 단계들'이라는 뜻이다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'계속 바뀌는 과정'은 이 글이 말하는 올바른 발달관이라 정반대이다. '순서 없이 마음대로'는 sequence (순서)와 맞지 않다. '한 단계에 머무르는'과 '함께 겪는 경험'은 글에 없다.\n본문 포인트: 글은 단계가 아닌 과정으로 발달을 본다.","e":"계단처럼 한 칸씩만 올라가고 되돌아가지 못하는 길.","tr":"…고정된 순서의 단계들…"}]},"2610-34":{"voc":[{"q":"Social media has altered business, politics, and friendships, making going viral a <u>household</u> term.","ask":"이 문장에서 household의 뜻으로 알맞은 것은?","ch":["누구나 아는, 일상적인","집을 빌려주는","청소를 하는","값이 매우 비싼","외국에서 온"],"a":0,"why":"1문장: ...making going viral a household term (‘입소문이 나다’를 일상적인 용어로 만들었다)\n쉽게 말해 예전엔 낯선 말이던 going viral을 이제 누구나 쓰게 되었다는 뜻이다.\nhousehold는 원래 '가정의, 가구'라는 뜻이다. 집집마다 쓰는 말이라는 데서 household term = 누구나 아는 말이 되었다.\n2문장의 households (가정들)와 같은 낱말이지만 뜻이 넓어진 쓰임이다.\n오답 함정: '집을 빌려주는', '청소를 하는'처럼 집과 엮은 뜻은 글에 근거가 없다.\n본문 포인트: 소셜 미디어가 우리 생활을 이만큼 바꿨다는 예이다.","e":"‘먹방’처럼 모르는 사람이 없는 말.","tr":"소셜 미디어는 …‘입소문이 나다’를 일상적인 용어로 만들었다.","alt":"familiar, common; household name = 누구나 아는 이름"},{"q":"…making us <u>vulnerable</u> to human error taking place on the other side of the world.","ask":"vulnerable의 뜻으로 알맞은 것은?","ch":["취약한, 상처받기 쉬운","강력한","무관심한","유명한","편안한"],"a":0,"why":"2문장: ...making us vulnerable to human error taking place on the other side of the world (세계의 다른 곳에서 발생한 인간의 오류에 우리를 취약하게 만들었다)\n쉽게 말해 지구 반대편의 실수에도 우리가 피해를 입기 쉬워졌다는 뜻이다.\nvulnerable = 취약한 (be vulnerable to A = A에 약하다). 반대말은 immune (영향받지 않는), strong (강한).\n9문장의 vulnerabilities (취약점들)는 이 낱말의 명사형이다. 글의 결론이 이 낱말에 모여 있다.\n오답 함정: '강력한'은 반대 뜻이다.\n본문 포인트: 연결될수록 우리는 더 취약해진다.","e":"감기가 도는 철에 면역이 약해 쉽게 아픈 상태.","tr":"…세계의 다른 곳에서 발생한 인간의 오류에 우리를 취약하게 만들었다.","alt":"weak, exposed; 명사: vulnerability"},{"q":"…most of our institutions were separate and thereby <u>buffered</u> from the effects of errors outside their walls.","ask":"buffered의 뜻으로 알맞은 것은?","ch":["충격이 막혀 보호된","크게 흔들린","새로 지어진","잊혀진","더 빨라진"],"a":0,"why":"3문장: ...separate and thereby buffered from the effects of errors outside their walls (분리되어 있었고, 따라서 그것들의 장벽 밖에 있는 오류의 영향으로부터 보호되었다)\n쉽게 말해 바깥에서 사고가 나도 충격이 안쪽까지 오지 않게 막혀 있었다는 뜻이다.\nbuffer = 완충하다, 충격을 줄여 주다. 명사 buffer는 완충 장치이다.\n분리되어 있던 것이 장점이 되는 이유가 buffered에 담겨 있다.\n오답 함정: '크게 흔들린'은 반대 뜻이다.\n본문 포인트: 옛날에는 분리 덕분에 보호받았다. 지금은 아니다.","e":"택배 상자 안의 에어캡이 충격을 막아 주는 것.","tr":"…그것들의 장벽 밖에 있는 오류들의 영향으로부터 보호되었다.","alt":"protected, cushioned, shielded"},{"q":"The digitization of <u>massive</u> amounts of information has continued to grow enormously…","ask":"massive와 바꿔 쓸 수 있는 말은?","ch":["enormous","tiny","private","modern","careful"],"a":0,"why":"5문장: The digitization of massive amounts of information has continued to grow enormously (방대한 양의 정보의 디지털화는 계속해서 엄청나게 증가해 왔다)\n쉽게 말해 컴퓨터로 옮겨지는 정보의 양이 정말 많다는 뜻이다.\nmassive = 거대한, 방대한 (= enormous, huge). 같은 문장의 enormously와 같은 가족이다.\n디지털화(digitization)와 정보의 양이 클수록 서로 연결되는 범위도 커진다는 것이 글의 흐름이다.\n오답 함정: tiny (아주 작은)는 반대 뜻이다.\n본문 포인트: 정보가 아주 많이 연결되어 있다.","e":"도서관 전체가 스마트폰 하나에 들어가는 정도의 방대한 양.","tr":"컴퓨팅 능력의 비용이 감소함에 따라 방대한 양의 정보의 디지털화는 계속해서 엄청나게 증가해 왔다.","alt":"huge, enormous, vast"},{"q":"The development of smart systems that communicate <u>autonomously</u>…","ask":"autonomously의 뜻으로 알맞은 것은?","ch":["스스로, 자율적으로","천천히","큰 소리로","비밀리에","마지못해"],"a":0,"why":"6문장: ...smart systems that communicate autonomously (자율적으로 소통하는 스마트 시스템)\n쉽게 말해 사람이 시키지 않아도 기계끼리 알아서 주고받는다는 뜻이다.\nautonomous = 자율적인, 스스로 움직이는. 부사형이 autonomously이다. 자율주행차 autonomous car를 떠올리면 쉽다.\n사람 손을 거치지 않으니 예측하기 어렵다는 8문장 내용과 이어진다.\n오답 함정: '비밀리에'는 secretly이다. autonomously는 비밀이 아니라 '스스로'이다.\n본문 포인트: 기계끼리 알아서 소통하니 고장도 퍼지기 쉽다.","e":"운전자가 없어도 알아서 달리는 자율주행차.","tr":"…자율적으로 소통하는 스마트 시스템의 발달은…","alt":"independently, by itself"},{"q":"The development of smart systems … <u>gave rise to</u> an infinite variety of potential breakdowns.","ask":"gave rise to의 뜻으로 알맞은 것은?","ch":["~을 초래했다, 불러일으켰다","~을 막았다","~을 이겼다","~에서 벗어났다","~을 설명했다"],"a":0,"why":"6문장: ...gave rise to an infinite variety of potential breakdowns (무한히 다양한 잠재적 고장들을 초래했다)\n쉽게 말해 스마트 시스템이 생기자 온갖 고장 가능성이 생겨났다는 뜻이다.\ngive rise to = ~을 낳다, 초래하다 (= cause, lead to). 과거형은 gave rise to이다.\n원인 → 결과를 묻는 시험 문제에서 자주 쓰이는 표현이다.\n오답 함정: '막았다'는 반대 뜻이다. rise (오르다)를 떠올려 '벗어났다' 같은 엉뚱한 뜻을 고르지 않는다.\n본문 포인트: 스마트 시스템의 발달이 새로운 위험을 낳았다.","e":"작은 불씨가 큰 산불을 일으키는 것.","tr":"…무한히 다양한 잠재적 고장들을 초래했다.","alt":"cause, lead to, bring about"},{"q":"…gave rise to an <u>infinite</u> variety of potential breakdowns.","ask":"infinite의 뜻으로 알맞은 것은?","ch":["무한한, 끝이 없는","아주 작은","한정된","불가능한","비어 있는"],"a":0,"why":"6문장: ...an infinite variety of potential breakdowns (무한히 다양한 잠재적 고장들)\n쉽게 말해 생길 수 있는 고장의 종류가 끝없이 많다는 뜻이다.\ninfinite = 무한한 (in = not + finite 끝이 있는). 반대말은 finite (한정된)이다.\n앞의 infinite와 뒤의 potential (잠재적인)이 함께 '가능성이 한없이 많다'는 분위기를 만든다.\n오답 함정: '한정된'은 finite의 뜻이다. infinite는 그 반대이다.\n본문 포인트: 연결된 시스템에서는 고장 경로가 셀 수 없이 많다.","e":"우주의 끝이 보이지 않는 것처럼 끝이 없는 것.","tr":"…무한히 다양한 잠재적 고장들…","alt":"endless, limitless; 반의어: finite"},{"q":"This interdependence is a <u>breeding ground</u> for complex failure.","ask":"breeding ground의 뜻으로 알맞은 것은?","ch":["(나쁜 것이) 생겨나기 쉬운 환경, 온상","동물 사육장 이름","안전한 피난처","학교 운동장","새로운 기술의 시험장"],"a":0,"why":"7문장: This interdependence is a breeding ground for complex failure. (이러한 상호 의존성은 복합적 실패의 온상이다)\n쉽게 말해 서로 얽혀 있으면 복잡한 실패가 자라나기 쉽다는 뜻이다.\nbreeding ground = 번식지, 온상. 곰팡이가 습한 곳에서 잘 자라듯, 안 좋은 일이 잘 생겨나는 환경을 비유한다.\n그래서 글에서는 복잡한 실패의 '근원지'로 읽는다.\n오답 함정: '동물 사육장 이름'은 글자 그대로만 읽은 것이다. 비유로 읽어야 한다.\n본문 포인트: 상호 의존성은 복합적 실패의 온상이다.","e":"습한 욕실에서 곰팡이가 잘 피는 것.","tr":"이러한 상호 의존성은 복합적 실패의 온상이다.","alt":"hotbed, source, nest"},{"q":"…interconnectedness <u>instantly</u> spreads the impact of small failures.","ask":"instantly와 바꿔 쓸 수 있는 말은?","ch":["immediately","gradually","rarely","carefully","partly"],"a":0,"why":"9문장: ...interconnectedness instantly spreads the impact of small failures (상호 연결성이 작은 실패들의 영향을 즉각적으로 확산시킨다)\n쉽게 말해 작은 실수가 순식간에 번진다는 뜻이다.\ninstantly = 즉시 (= immediately). 반대말은 gradually (서서히)이다.\n이 부사가 '작은 실패도 막을 시간이 없다'는 위험을 보여 준다.\n오답 함정: gradually (서서히)는 반대 뜻이다.\n본문 포인트: 연결이 많을수록 영향이 순식간에 퍼진다.","e":"단톡방에 올린 소문이 몇 초 만에 퍼지는 것.","tr":"…상호 연결성이 작은 실패들의 영향을 즉각적으로 확산시키기 때문이다.","alt":"immediately, at once, right away"}],"find":[{"s":"Social media has changed business, politics, and friendships.","a":true,"why":"1문장: Social media has altered business, politics, and friendships (소셜 미디어는 비즈니스, 정치, 친목을 변화시켰다)\n쉽게 말해 세 분야가 모두 바뀌었다.\nalter = change. 같은 뜻으로 바꾼 문장이다.\n본문 포인트: 연결이 세상을 바꿨다는 도입이다.","e":"SNS 때문에 친구와 연락하는 방식도 달라진 것."},{"s":"Social media has changed only business, and politics and friendships remain the same.","a":false,"why":"1문장: ...altered business, politics, and friendships (비즈니스, 정치, 친목을 변화시켰다)\n쉽게 말해 세 가지 모두이다.\n함정: only (오직)를 넣어 범위를 좁혔다. 시험에서 only, always, never 같은 말이 들어가면 의심한다.\n본문 포인트: 변화는 비즈니스에만 그치지 않는다.","e":"한 반만 바뀌었다고 하는 격."},{"s":"The global financial industry links banks and countless households around the world.","a":true,"why":"2문장: The global financial industry links every bank and countless households in every country (세계 금융 산업은 모든 은행과 전 세계 각국의 수많은 가정을 연결한다)\n쉽게 말해 금융이 은행과 집들을 하나로 이어 놓았다.\n본문 포인트: 금융이 전 세계를 연결한다.","e":"한 나라의 은행 문제가 다른 나라 가정에도 영향을 주는 것."},{"s":"The global financial industry protects us from human error that takes place far away.","a":false,"why":"2문장: ...making us vulnerable to human error taking place on the other side of the world (세계의 다른 곳에서 발생한 인간의 오류에 취약하게 만든다)\n쉽게 말해 보호가 아니라 오히려 취약해졌다.\n함정: vulnerable (취약한)을 protects (보호한다)로 뒤집었다.\n본문 포인트: 연결은 편리하지만 취약점도 만든다.","e":"방패가 아니라 약점이 되는 것."},{"s":"Years ago most institutions were separate and protected from the effects of errors outside their walls.","a":true,"why":"3문장: ...years ago most of our institutions were separate and thereby buffered from the effects of errors outside their walls (수년 전 우리의 기관들 중 대부분은 분리되어 있었고 따라서 장벽 밖 오류의 영향으로부터 보호되었다)\n쉽게 말해 옛날엔 서로 분리되어 있어서 바깥 사고가 번지지 않았다.\nbuffered = protected. 같은 뜻으로 바꾼 문장이다.\n본문 포인트: '예전에는 이랬다'가 4문장 That is no longer the case의 바탕이다.","e":"칸막이가 있어 한 칸의 불이 옆 칸으로 번지지 않는 것."},{"s":"Years ago most institutions were closely connected and easily affected by outside errors.","a":false,"why":"3문장: ...most of our institutions were separate and thereby buffered (대부분의 기관은 분리되어 있었고 따라서 보호되었다)\n쉽게 말해 옛날엔 '분리'였고 지금이 '연결'이다.\n함정: separate (분리된)를 closely connected (밀접하게 연결된)로 바꿔 지금의 모습을 옛날에 붙였다.\n본문 포인트: 옛날과 지금의 대비를 헷갈리지 않는다.","e":"옛날 이야기에 지금 모습을 넣는 격."},{"s":"The digitization of massive amounts of information has continued to grow as the cost of computing power has decreased.","a":true,"why":"5문장: The digitization of massive amounts of information has continued to grow enormously as the cost of computing power has decreased. (컴퓨팅 능력의 비용이 감소함에 따라 방대한 양의 정보의 디지털화는 계속해서 엄청나게 증가해 왔다)\n쉽게 말해 컴퓨터 쓰는 값이 싸지니 디지털 정보가 많아졌다.\n본문 포인트: 비용이 내려가서 연결이 늘었다.","e":"저렴해진 저장 장치 덕분에 사진을 마구 찍어 저장하게 된 것."},{"s":"The digitization of information has grown because the cost of computing power has increased.","a":false,"why":"5문장: ...as the cost of computing power has decreased (컴퓨팅 능력의 비용이 감소함에 따라)\n쉽게 말해 비용이 '줄어서'이다.\n함정: decreased (감소했다)를 increased (증가했다)로 바꿨다. 비용이 오르면 디지털화가 늘어날 이유가 없다.\n본문 포인트: 값이 싸져서 널리 퍼졌다.","e":"비싸졌는데 더 많이 사는 모순."},{"s":"Smart systems that communicate autonomously gave rise to an infinite variety of potential breakdowns.","a":true,"why":"6문장: The development of smart systems that communicate autonomously gave rise to an infinite variety of potential breakdowns. (자율적으로 소통하는 스마트 시스템의 발달은 무한히 다양한 잠재적 고장들을 초래했다)\n쉽게 말해 스마트 시스템이 늘자 고장 가능성도 한없이 늘었다.\n본문 포인트: 기술 발전이 새로운 위험을 낳았다.","e":"기계끼리 연결되면 한 곳의 고장이 여러 곳에 번지는 것."},{"s":"This interdependence is a breeding ground for complex failure.","a":true,"why":"7문장: This interdependence is a breeding ground for complex failure. (이러한 상호 의존성은 복합적 실패의 온상이다)\n쉽게 말해 서로 얽혀 있으면 복잡한 실패가 생기기 쉽다.\n본문 포인트: 이 문장이 글의 핵심 주장 중 하나이다.","e":"서로 줄이 엉킨 이어폰이 잘 꼬이는 것."},{"s":"Rita says that when separate things bump up against each other, it becomes easier to predict what will happen next.","a":false,"why":"8문장: ...it becomes far more difficult to predict what's going to happen next (다음에 무슨 일이 일어날지를 예측하는 것은 훨씬 더 어려워진다)\n쉽게 말해 예측이 어려워진다.\n함정: far more difficult (훨씬 더 어려운)를 easier (더 쉬운)로 바꿨다.\n본문 포인트: 연결될수록 결과를 예측하기 어렵다.","e":"변수가 많아질수록 시험 결과를 예측하기 어려운 것."},{"s":"Information technology creates new vulnerabilities because interconnectedness instantly spreads the impact of small failures.","a":true,"why":"9문장: Information technology creates new vulnerabilities because interconnectedness instantly spreads the impact of small failures. (정보 기술은 새로운 취약성을 만들어 내는데, 왜냐하면 상호 연결성이 작은 실패들의 영향을 즉각적으로 확산시키기 때문이다)\n쉽게 말해 작은 실수도 순식간에 크게 번진다.\n본문 포인트: 이 문장이 글의 결론이다.","e":"한 명의 실수가 단체 메시지로 순식간에 모두에게 퍼지는 것."}],"eob":[{"s":"Social media has altered business, politics, and friendships, ( ______ ) going viral a household term.","ch":["making","made"],"a":0,"why":"1문장: ...friendships, making going viral a household term (친목을 변화시켰으며, ‘입소문이 나다’를 일상적인 용어로 만들었다)\n콤마 뒤에서 앞 문장의 결과를 덧붙이는 분사구문이다. 주어(Social media)가 '만드는' 쪽이라 능동의 현재분사 making이 맞다.\nmake A B = A를 B로 만들다. 여기서는 going viral이 A, a household term이 B이다.\n함정: made로 쓰면 앞 문장에 접속사 없이 동사가 이어져 문장이 어긋난다.\n본문 포인트: 소셜 미디어가 용어까지 일상으로 만들었다.","tr":"소셜 미디어는 비즈니스, 정치, 친목을 변화시켰으며, ‘입소문이 나다’를 일상적인 용어로 만들었다.","g":"앞 문장의 결과를 덧붙일 때는 콤마 뒤에 현재분사(-ing)를 쓴다.\n예) The rain fell, making the road slippery. (비가 내려서 길이 미끄러워졌다.)"},{"s":"The global financial industry links every bank and countless households in every country, making us vulnerable to human error ( ______ ) place on the other side of the world.","ch":["taking","taken"],"a":0,"why":"2문장: ...human error taking place on the other side of the world (세계의 다른 곳에서 발생한 인간의 오류)\n앞의 human error를 뒤에서 꾸며 주는 분사이다. take place (일어나다)는 목적어를 받지 않는 동사라서 '오류가 일어나는'이라는 능동이고, 현재분사 taking이 맞다.\n함정: taken (취해진)은 수동의 뜻인데, take place는 수동태로 쓰지 않는다.\n본문 포인트: 지구 반대편에서 일어나는 오류도 우리에게 영향을 준다.","tr":"세계 금융 산업은 모든 은행과 전 세계 각국의 수많은 가정을 연결하여, 우리를 세계의 다른 곳에서 발생한 인간의 오류에 취약해지게 만들었다.","g":"명사를 뒤에서 꾸미는 분사는 능동이면 -ing, 수동이면 -ed를 쓴다. take place (일어나다)는 능동이다.\n예) The event taking place today is big. (오늘 열리는 행사는 크다.)"},{"s":"Years ago most of our institutions ( ______ ) separate and thereby buffered from the effects of errors outside their walls.","ch":["were","was"],"a":0,"why":"3문장: ...years ago most of our institutions were separate and thereby buffered (수년 전 우리의 기관들 중 대부분은 분리되어 있었고 따라서 보호되었다)\nmost of our institutions에서 most of 뒤의 명사가 복수(institutions)라서 동사도 복수형 were이다.\nmost of + 명사에서는 뒤 명사에 동사를 맞춘다.\n함정: most(대부분)를 단수처럼 느껴 was를 고르기 쉽다. 하지만 most of 뒤의 institutions (기관들)가 복수이므로 were이다.\n본문 포인트: 옛날에는 분리되어 있었다.","tr":"수년 전 우리의 기관들 중 대부분은 서로 분리되어 있었고, 따라서 그것들의 장벽 밖에 있는 오류들의 영향으로부터 보호되었다.","g":"most of + 복수 명사 → 복수 동사. most of + 단수 명사 → 단수 동사.\n예) Most of the students are here. (학생들 대부분이 여기 있다.)"},{"s":"The digitization of massive amounts of information ( ______ ) continued to grow enormously as the cost of computing power has decreased.","ch":["has","have"],"a":0,"why":"5문장: The digitization of massive amounts of information has continued to grow enormously (방대한 양의 정보의 디지털화는 계속해서 엄청나게 증가해 왔다)\n주어는 The digitization (디지털화)이다. 단수라서 has이다.\n함정: 바로 앞의 massive amounts of information (방대한 양의 정보)이 복수처럼 보여서 have를 고르기 쉽다. of 뒤의 말은 주어를 꾸미는 말이다.\n본문 포인트: 디지털화가 계속 커지고 있다.","tr":"컴퓨팅 능력의 비용이 감소함에 따라 방대한 양의 정보의 디지털화는 계속해서 엄청나게 증가해 왔다.","g":"주어 뒤에 'of + 명사'가 붙으면 핵심은 앞의 주어이다.\n예) The size of the rooms is small. (그 방들의 크기는 작다.)"},{"s":"The development of smart systems that communicate autonomously ( ______ ) rise to an infinite variety of potential breakdowns.","ch":["gave","give"],"a":0,"why":"6문장: The development of smart systems ... gave rise to an infinite variety of potential breakdowns (스마트 시스템의 발달은 무한히 다양한 잠재적 고장들을 초래했다)\n주어는 The development (발달)로 단수이다. 과거의 일을 이야기하므로 과거형 gave가 맞다.\n함정: 중간의 smart systems that communicate (소통하는 스마트 시스템들)가 복수라서 give를 고르기 쉽다. 그것은 development를 꾸미는 말이다.\n본문 포인트: 발달이 고장 가능성을 늘렸다.","tr":"자율적으로 소통하는 스마트 시스템의 발달은 무한히 다양한 잠재적 고장들을 초래했다.","g":"주어는 수식어를 건너뛰고 찾는다. 단수이면 단수 동사, 과거 이야기면 과거형.\n예) The boy who has two dogs lives here. (개 두 마리를 키우는 그 소년은 여기 산다.)"}],"awk":[{"t":"The global financial industry [[1|links]] every bank and [[2|countless]] households in every country, making us [[3|immune]] to human error [[4|taking]] place on the [[5|other]] side of the world.","a":3,"fix":"vulnerable","why":"원문은 making us vulnerable to human error (우리를 인간의 오류에 취약하게 만든다)이다.\n정답은 3번 immune (영향받지 않는)이다.\n세계가 연결될수록 지구 반대편의 실수가 우리에게 영향을 준다는 것이 글의 주제이다. immune이면 연결의 위험이 사라져 글 전체와 모순이다.\n9문장에서도 새로운 vulnerabilities (취약성)를 만든다고 결론짓는다.\n본문 포인트: 연결은 취약성을 만든다.","sp":[{"b":"links","m":"연결하다","n":"3인칭 단수 현재형","y":"맞음. 금융 산업이 은행과 가정을 이어 놓음.","e":"여러 곳을 이어 주는 다리."},{"b":"countless","m":"수많은","n":"형용사. households를 꾸밈","y":"맞음. 셀 수 없이 많은 가정.","e":"셀 수 없는 별."},{"b":"immune","m":"영향받지 않는","n":"be immune to = ~에 영향받지 않다","y":"어색함. 원문은 vulnerable. 연결의 위험을 말하는 글의 주제와 모순.","e":"면역이 있어 감기에 안 걸리는 사람."},{"b":"taking","m":"일어나는","n":"현재분사. error를 뒤에서 꾸밈","y":"맞음. take place = 일어나다.","e":"멀리서 일어나는 일."},{"b":"other","m":"반대쪽의","n":"the other side = 반대편","y":"맞음. 지구 반대편이라는 뜻.","e":"우리나라 반대편 나라."}]},{"t":"As Columbia University strategy professor Rita McGrath explains, years ago most of our institutions were [[1|connected]] and [[2|thereby]] [[3|buffered]] from the effects of errors [[4|outside]] their [[5|walls]].","a":1,"fix":"separate","why":"원문은 most of our institutions were separate and thereby buffered (대부분의 기관은 분리되어 있었고 따라서 보호되었다)이다.\n정답은 1번 connected (연결된)이다.\n서로 연결되어 있으면 바깥의 오류가 번지기 쉬워 '보호되지(buffered)' 못한다. 또 다음 문장 That is no longer the case (더 이상은 그렇지 않다)는 옛날에는 분리, 지금은 연결이라는 대비가 있어야 이어진다.\n본문 포인트: 옛날 = 분리 = 보호, 지금 = 연결 = 취약.","sp":[{"b":"connected","m":"연결된","n":"형용사","y":"어색함. 원문은 separate. 연결되어 있으면 보호받지 못해 buffered와 모순.","e":"서로 줄로 묶인 인형."},{"b":"thereby","m":"그렇게 함으로써","n":"부사. 앞의 결과를 이어 줌","y":"맞음. 분리된 덕분에 보호된다는 인과.","e":"'그 덕분에'라는 말."},{"b":"buffered","m":"보호된","n":"과거분사","y":"맞음. 충격이 완화된 상태.","e":"에어캡으로 감싼 택배."},{"b":"outside","m":"바깥의","n":"전치사. outside their walls","y":"맞음. 기관의 벽 밖.","e":"교문 밖."},{"b":"walls","m":"벽, 장벽","n":"명사. wall의 복수형","y":"맞음. 기관들의 장벽.","e":"교실 벽."}]},{"t":"The [[1|digitization]] of [[2|massive]] amounts of information has [[3|continued]] to grow [[4|enormously]] as the cost of computing power has [[5|increased]].","a":5,"fix":"decreased","why":"원문은 as the cost of computing power has decreased (컴퓨팅 능력의 비용이 감소함에 따라)이다.\n정답은 5번 increased (증가했다)이다.\n정보의 디지털화가 늘어난 이유는 컴퓨터 쓰는 비용이 싸졌기 때문이다. 비용이 올랐다면 디지털화가 더 늘어날 이유가 없다.\n본문 포인트: 값이 내려가서 연결이 늘었다.","sp":[{"b":"digitization","m":"디지털화","n":"명사. 단수 주어","y":"맞음. 정보가 디지털로 바뀌는 것.","e":"종이 사진을 파일로 바꾸는 것."},{"b":"massive","m":"방대한","n":"형용사. amounts를 꾸밈","y":"맞음. 엄청나게 많은 양.","e":"도서관 전체."},{"b":"continued","m":"계속했다","n":"has continued to = 계속 ~해 오다","y":"맞음. 현재완료.","e":"멈추지 않고 계속 자라는 것."},{"b":"enormously","m":"엄청나게","n":"부사","y":"맞음. grow를 꾸밈.","e":"어마어마하게."},{"b":"increased","m":"증가했다","n":"현재완료 has increased","y":"어색함. 원문은 decreased. 비용이 오르는 것은 디지털화 증가의 이유가 못 됨.","e":"가격이 올랐는데 더 많이 사는 모순."}]},{"t":"[[1|Information]] technology [[2|creates]] new vulnerabilities because interconnectedness instantly [[3|blocks]] the [[4|impact]] of [[5|small]] failures.","a":3,"fix":"spreads","why":"원문은 interconnectedness instantly spreads the impact of small failures (상호 연결성이 작은 실패들의 영향을 즉각적으로 확산시킨다)이다.\n정답은 3번 blocks (막는다)이다.\n앞 절은 '새로운 취약성을 만든다'이다. 그 이유를 밝히는 because 절에서 영향이 막힌다고 하면 취약성이 생길 이유가 없다. 영향이 '퍼지기' 때문에 취약해지는 것이다.\n본문 포인트: 연결 때문에 작은 실패도 순식간에 퍼진다.","sp":[{"b":"Information","m":"정보","n":"명사. Information technology = 정보 기술","y":"맞음. 글이 말하는 기술.","e":"스마트폰의 기술."},{"b":"creates","m":"만들어 내다","n":"3인칭 단수 현재형","y":"맞음. 새로운 취약성을 만든다.","e":"새 게임을 만드는 것."},{"b":"blocks","m":"막다","n":"3인칭 단수 현재형","y":"어색함. 원문은 spreads. 영향이 퍼져서 취약해진다는 인과와 모순.","e":"물길을 막는 둑."},{"b":"impact","m":"영향","n":"명사","y":"맞음. 실패가 미치는 영향.","e":"충격의 크기."},{"b":"small","m":"작은","n":"형용사. failures를 꾸밈","y":"맞음. 작은 실패도 크게 번진다는 뜻.","e":"작은 불씨."}]}],"und":[{"q":"This interdependence is <u>a breeding ground for complex failure</u>.","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["서로 얽혀 있어서 복잡한 실패가 생기기 쉬운 환경이다","복잡한 실패를 막아 주는 안전한 장치이다","실패한 사람에게 새로 배울 기회를 주는 곳이다","동물이 자라는 데 알맞은 환경이다","서로 의존하면 실패가 절대 일어나지 않는다는 믿음이다"],"a":0,"why":"7문장: This interdependence is a breeding ground for complex failure. (이러한 상호 의존성은 복합적 실패의 온상이다)\nbreeding ground = 온상. 나쁜 것이 잘 자라는 환경이다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'막아 주는 안전한 장치'는 정반대이다. '새로 배울 기회'는 글에 없다. '동물이 자라는'은 글자 그대로만 읽은 것이다. '절대 일어나지 않는다'도 글과 반대이다.\n본문 포인트: 얽힘이 복합적 실패를 낳는다.","e":"서로 줄이 얽혀 하나가 당기면 모두 끌려오는 상태.","tr":"이러한 상호 의존성은 복합적 실패의 온상이다."},{"q":"most of our institutions were separate and thereby <u>buffered from the effects of errors outside their walls</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["바깥에서 생긴 오류의 영향이 안쪽까지 오지 않도록 막혀 있었다","바깥에서 생긴 오류를 직접 찾아내어 고쳤다","바깥의 오류 때문에 계속 피해를 입었다","오류가 없는 환경에서 만들어졌다","바깥의 오류를 일부러 안으로 들여왔다"],"a":0,"why":"3문장: ...buffered from the effects of errors outside their walls (그것들의 장벽 밖에 있는 오류들의 영향으로부터 보호되었다)\nbuffered from = ~로부터 보호된. effects of errors outside their walls = 벽 밖 오류의 영향.\n정답은 이 뜻을 풀어 쓴 것이다.\n'직접 찾아내어 고쳤다'는 글에 없다. '계속 피해를 입었다'는 반대 뜻이다. '오류가 없는 환경에서 만들어졌다'와 '일부러 들여왔다'도 글에 없다.\n본문 포인트: 분리된 덕분에 옛날에는 보호받았다.","e":"방화벽이 불을 막아 옆 방으로 번지지 않게 하는 것.","tr":"…그것들의 장벽 밖에 있는 오류들의 영향으로부터 보호되었다."},{"q":"<u>That is no longer the case.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["기관들이 분리되어 있어서 바깥 오류의 영향으로부터 보호되던 상황이 이제는 아니다","우리의 기관들이 분리되어 있다는 것은 사실이 아니었다","수년 전에도 오류가 번지는 일은 없었다","기관들이 더 이상 존재하지 않는다","오류의 영향이 예전보다 줄어들었다"],"a":0,"why":"4문장: That is no longer the case. (더 이상은 그렇지 않다)\nthat은 바로 앞 3문장의 상황(분리되어 있어서 바깥 오류에서 보호됨)을 가리킨다. the case = 사실, 상황. no longer = 더 이상 ~않다.\n정답은 '예전엔 그랬지만 지금은 아니다'를 풀어 쓴 것이다.\n'사실이 아니었다'는 시제가 틀렸다. '수년 전에도 번지는 일은 없었다'와 '더 이상 존재하지 않는다'는 글에 없다. '영향이 줄어들었다'는 정반대이다.\n본문 포인트: 지금은 연결되어 영향이 퍼진다.","e":"예전엔 교실 문이 따로 있었지만 지금은 하나로 뚫려 있다는 말.","tr":"더 이상은 그렇지 않다."},{"q":"an <u>infinite variety of potential breakdowns</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["앞으로 생길 수 있는 끝없이 다양한 고장들","이미 모두 일어난 한정된 몇 가지 고장들","해결하기 쉬운 단순한 고장들","새로 만든 시스템만 겪는 고장들","사람이 일부러 일으키는 고장들"],"a":0,"why":"6문장: ...gave rise to an infinite variety of potential breakdowns (무한히 다양한 잠재적 고장들을 초래했다)\ninfinite variety = 끝없는 다양함. potential = 잠재적인, 아직 일어나지 않았지만 일어날 수 있는. breakdowns = 고장들.\n정답은 이 뜻을 풀어 쓴 것이다.\n'이미 모두 일어난', '한정된'은 potential, infinite와 반대이다. '해결하기 쉬운 단순한'은 7문장의 complex failure (복합적 실패)와 모순된다. '새로 만든 시스템만'과 '일부러'는 글에 없다.\n본문 포인트: 연결 때문에 고장 가능성이 한없이 늘었다.","e":"스마트폰 하나가 고장 날 수 있는 이유가 수없이 많다는 것.","tr":"…무한히 다양한 잠재적 고장들…"}]},"2610-35":{"voc":[{"q":"…brought us enormous progress in the treatment and prevention of <u>infectious</u> diseases.","ask":"infectious의 뜻으로 알맞은 것은?","ch":["전염성의, 옮는","유전되는","치료가 필요 없는","오래 가는","피부에만 생기는"],"a":0,"why":"1문장: ...progress in the treatment and prevention of infectious diseases (전염병의 치료와 예방에서의 진보)\n쉽게 말해 다른 사람에게 옮는 병이다.\ninfectious = 전염성의. 명사 infection (감염)과 함께 외운다.\n오답 함정: '유전되는'은 hereditary이다. infectious는 사람이나 물건을 통해 옮는 병이다.\n본문 포인트: 이 글의 주제는 전염병과 싸운 역사이다.","e":"독감처럼 옆 사람에게 옮는 병.","tr":"…전염병의 치료와 예방에서 엄청난 진보를 가져다주었다.","alt":"contagious; 명사: infection"},{"q":"…enormous progress in the treatment and <u>prevention</u> of infectious diseases.","ask":"prevention의 뜻으로 알맞은 것은?","ch":["예방, 막는 것","치료","발견","전달","악화"],"a":0,"why":"1문장: ...the treatment and prevention of infectious diseases (전염병의 치료와 예방)\n쉽게 말해 병에 걸리기 전에 막는 것이다.\nprevent = 막다. 명사가 prevention이다. 치료 (treatment)는 걸린 뒤에 고치는 것이라 구별된다.\n오답 함정: '치료'는 바로 앞의 treatment이다. 짝으로 나온 두 낱말은 뜻이 다르다.\n본문 포인트: 치료와 예방 둘 다에서 진보가 있었다.","e":"손 씻기로 감기를 막는 것.","tr":"…전염병의 치료와 예방에서…","alt":"protection; 동사: prevent"},{"q":"…was one of the biggest <u>breakthroughs</u> in the battle against infectious diseases.","ask":"breakthroughs와 가장 가까운 뜻은?","ch":["중요한 발전, 획기적 성과","실패","경고","사고","습관"],"a":0,"why":"2문장: ...one of the biggest breakthroughs in the battle against infectious diseases (전염병과의 싸움에서 가장 큰 획기적 발전들 중 하나)\n쉽게 말해 큰 벽을 뚫고 나아간 성과이다.\nbreakthrough = break (부수다) + through (통과). 막힌 벽을 뚫는 발전이다.\n오답 함정: '실패'는 반대이다. biggest (가장 큰)와 어울리는 긍정적 뜻을 고른다.\n본문 포인트: 페니실린은 전염병 싸움에서 아주 중요한 성과였다.","e":"풀리지 않던 문제를 마침내 푼 것.","tr":"…전염병과의 싸움에서 가장 큰 획기적 발전들 중 하나…","alt":"major advance, discovery"},{"q":"…after <u>exposure</u> to the cowpox virus, which is harmless to humans.","ask":"exposure의 뜻으로 알맞은 것은?","ch":["(위험이나 영향에) 노출됨","제거","관리","회복","보호"],"a":0,"why":"3문장: ...after exposure to the cowpox virus (우두 바이러스에 노출된 후에)\n쉽게 말해 바이러스에 몸이 닿는 일이다.\nexpose = 드러내다. exposure to A = A에 노출됨. 햇빛에 피부를 드러내는 것도 exposure이다.\n오답 함정: '보호'는 글 앞의 protected와 헷갈린 것이다. 보호는 결과이고, exposure는 원인이다.\n본문 포인트: 우두 바이러스에 노출된 뒤 천연두로부터 보호되었다.","e":"햇빛에 피부가 드러나는 것.","tr":"…우두 바이러스에 노출된 후에…","alt":"contact, being exposed; 동사: expose"},{"q":"…the cowpox virus, which is <u>harmless</u> to humans.","ask":"harmless의 반대말로 알맞은 것은?","ch":["harmful","useful","careless","friendly","helpless"],"a":0,"why":"3문장: ...the cowpox virus, which is harmless to humans (인간들에게 무해한 우두 바이러스)\n쉽게 말해 사람에게 해를 주지 않는다.\n-less는 '~가 없는'이라는 뜻이다. harm (해) + less = 해가 없는. 반대말은 harmful (해로운)이다.\n오답 함정: helpless (무력한), careless (부주의한)처럼 -less가 붙은 낱말을 비슷하게 보지 않도록 한다.\n본문 포인트: 해가 없는 바이러스가 해가 큰 바이러스를 막아 주었다.","e":"먹어도 탈이 나지 않는 음식.","tr":"…인간들에게 무해한 우두 바이러스.","alt":"safe, not dangerous; 반의어: harmful"},{"q":"…have contributed enormously to the reduction of the <u>burden</u> of bacterial and viral diseases…","ask":"burden의 뜻으로 알맞은 것은?","ch":["부담, 짐","이익","순서","원인","기록"],"a":0,"why":"4문장: ...the reduction of the burden of bacterial and viral diseases (세균성 질병과 바이러스성 질병의 부담의 감소)\n쉽게 말해 병 때문에 사람들이 지는 짐과 피해이다.\nburden = 무거운 짐, 부담. 병이 가져오는 고통과 비용을 짐에 비유했다.\n오답 함정: '이익'은 반대 느낌이다. reduction (감소)과 함께 쓰이므로 줄이고 싶은 나쁜 것이 와야 한다.\n본문 포인트: 백신이 병의 부담을 크게 줄였다.","e":"어깨를 누르는 무거운 가방.","tr":"…세균성 질병과 바이러스성 질병의 부담의 감소에 엄청나게 기여했으며…","alt":"load, weight, heavy duty"},{"q":"…have <u>contributed</u> enormously to the reduction of the burden…","ask":"contributed to의 뜻으로 알맞은 것은?","ch":["~에 기여했다","~을 반대했다","~을 숨겼다","~에서 벗어났다","~을 따라 했다"],"a":0,"why":"4문장: ...have contributed enormously to the reduction of the burden (부담의 감소에 엄청나게 기여했다)\n쉽게 말해 백신이 큰 도움이 되었다.\ncontribute to A = A에 기여하다. 이때 to는 전치사라서 뒤에 명사(reduction)가 온다.\n오답 함정: '반대했다'는 반대 뜻이다.\n본문 포인트: 백신은 질병 부담 감소에 크게 이바지했다.","e":"학급 행사에 힘을 보태는 것.","tr":"…부담의 감소에 엄청나게 기여했으며…","alt":"help, add to, lead to"},{"q":"…treatment therapies turned viral diseases that were deadly into <u>chronic</u> manageable diseases.","ask":"chronic의 뜻으로 알맞은 것은?","ch":["오래 계속되는, 만성적인","갑작스러운","가벼운","전염되지 않는","치료가 끝난"],"a":0,"why":"5문장: ...turned viral diseases that were deadly into chronic manageable diseases (치명적이었던 바이러스성 질병들을 만성적인 관리 가능한 질병들로 바꾸었다)\n쉽게 말해 목숨을 위협하던 병을 약으로 오래 관리하며 사는 병으로 바꿨다.\nchronic = 오래 계속되는, 만성의. 반대말은 acute (급성의)이다.\n오답 함정: '갑작스러운'은 acute에 가깝다. '치료가 끝난'은 낫는다는 뜻이라 글과 다르다.\n본문 포인트: 치명적이던 병이 관리 가능한 병이 되었다.","e":"고혈압처럼 약으로 오래 관리하는 병.","tr":"…치명적이었던 바이러스성 질병들을 만성적인 관리 가능한 질병들로 바꾸었다.","alt":"long-lasting; 반의어: acute"}],"find":[{"s":"Medical technology has brought us enormous progress in treating and preventing infectious diseases.","a":true,"why":"1문장: Scientific developments and technologies in medical practice have brought us enormous progress in the treatment and prevention of infectious diseases. (의료 행위에서의 과학적 발전들과 기술들은 전염병의 치료와 예방에서 엄청난 진보를 가져다주었다)\n쉽게 말해 의료 기술 덕분에 전염병을 치료하고 막는 일이 크게 나아졌다.\n본문 포인트: 글 전체의 주제 문장이다.","e":"의학 덕분에 예전엔 어려웠던 병을 이제 고칠 수 있게 된 것."},{"s":"Alexander Fleming discovered penicillin in 1928 and later received the Nobel Prize for it.","a":true,"why":"2문장: The discovery of penicillin in 1928 by Alexander Fleming, for which he later received the Nobel Prize (1928년 Alexander Fleming에 의한 페니실린의 발견, 그것에 대해 그는 후에 노벨상을 받았다)\n쉽게 말해 페니실린 발견으로 노벨상을 받았다.\nfor which = for the discovery. 관계대명사로 앞 내용을 받는다.\n본문 포인트: 페니실린은 가장 큰 획기적 발전 중 하나이다.","e":"큰 발견을 해서 상을 받은 것."},{"s":"Fleming's discovery of penicillin was the only breakthrough in the battle against infectious diseases.","a":false,"why":"2문장: ...one of the biggest breakthroughs in the battle against infectious diseases (전염병과의 싸움에서 가장 큰 획기적 발전들 중 하나)\n쉽게 말해 여러 큰 발전 중 하나이다.\n함정: one of the biggest (가장 큰 것들 중 하나)를 the only (유일한)로 바꿨다. 시험에서 only가 보이면 의심한다.\n본문 포인트: 페니실린 외에도 백신 등 다른 발전이 이어서 나온다.","e":"한 명만 우승한 대회로 바꿔 말한 것."},{"s":"Penicillin was discovered earlier than the cowpox virus finding by Jenner.","a":false,"why":"2문장: The discovery of penicillin in 1928 (1928년의 페니실린 발견)\n3문장: Edward Jenner discovered around 1796 (Edward Jenner는 1796년경에 발견했다)\n쉽게 말해 Jenner가 약 130년 더 먼저이다.\n함정: 글에 나온 순서(2문장이 먼저)와 실제 연도를 헷갈리게 한다. 연도를 비교해야 한다.\n본문 포인트: 연도 정보는 시험에서 비교 문제로 자주 나온다.","e":"글에 먼저 나왔다고 먼저 일어난 일은 아니다."},{"s":"Jenner found that people exposed to the cowpox virus were protected against the smallpox virus.","a":true,"why":"3문장: Edward Jenner discovered around 1796 that humans were protected against the deadly smallpox virus after exposure to the cowpox virus (Edward Jenner는 1796년경에 우두 바이러스에 노출된 후 인간들이 치명적인 천연두 바이러스로부터 보호된다는 것을 발견했다)\n쉽게 말해 우두에 노출되면 천연두를 막을 수 있다는 발견이다.\n본문 포인트: 백신 발견의 시작이다.","e":"가벼운 병을 한 번 겪으면 심한 병을 막아 주는 원리."},{"s":"The cowpox virus is deadly to humans.","a":false,"why":"3문장: ...the cowpox virus, which is harmless to humans (인간들에게 무해한 우두 바이러스)\n쉽게 말해 사람에게 해가 없다.\n함정: 치명적(deadly)인 것은 smallpox virus (천연두 바이러스)이다. 두 바이러스를 바꿔 썼다.\n본문 포인트: 무해한 우두 바이러스가 치명적인 천연두를 막아 주었다.","e":"이름이 비슷한 두 대상을 서로 바꿔 쓴 것."},{"s":"Vaccines developed in laboratories have helped reduce the burden of bacterial and viral diseases.","a":true,"why":"4문장: Vaccines developed in laboratories have contributed enormously to the reduction of the burden of bacterial and viral diseases (실험실에서 개발된 백신은 세균성 질병과 바이러스성 질병의 부담의 감소에 엄청나게 기여했다)\n쉽게 말해 백신 덕분에 병의 부담이 줄었다.\ncontribute to the reduction = help reduce. 같은 뜻으로 바꾼 문장이다.\n본문 포인트: 백신의 공이 크다.","e":"예방접종 덕분에 독감 환자가 줄어든 것."},{"s":"Vaccines have reduced the burden of viral diseases only, not bacterial diseases.","a":false,"why":"4문장: ...the burden of bacterial and viral diseases (세균성 질병과 바이러스성 질병의 부담)\n쉽게 말해 두 종류 모두이다.\n함정: bacterial and viral (세균성과 바이러스성)을 viral ... only (바이러스성 질병만)로 좁혔다.\n본문 포인트: 백신의 효과는 두 종류의 병에 모두 미쳤다.","e":"두 개 중 한 개만 말한 것."},{"s":"Control and hygiene management measures have reduced the burden of some infectious diseases such as cholera and malaria.","a":true,"why":"5문장: For other infectious diseases (for example cholera and malaria), control and hygiene management measures have reduced their burden (다른 전염병들의 경우에는 (예를 들어 콜레라와 말라리아), 통제와 위생 관리 조치들이 그것들의 부담을 줄였다)\n쉽게 말해 콜레라와 말라리아는 통제와 위생 관리로 부담이 줄었다.\n본문 포인트: 백신 외의 방법도 소개한다.","e":"손 씻기와 깨끗한 물 관리로 병이 줄어든 것."},{"s":"Treatment therapies have turned some deadly viral diseases into chronic manageable diseases.","a":true,"why":"5문장: ...treatment therapies turned viral diseases that were deadly into chronic manageable diseases (치료법들이 치명적이었던 바이러스성 질병들을 만성적인 관리 가능한 질병들로 바꾸었다)\n쉽게 말해 치료법 덕분에 목숨을 위협하던 병도 관리할 수 있게 되었다.\n본문 포인트: 마지막 문장은 치료의 성과를 정리한다.","e":"치명적이던 병이 약으로 관리하는 병으로 바뀐 것."}],"eob":[{"s":"The discovery of penicillin in 1928 by Alexander Fleming, for ( ______ ) he later received the Nobel Prize, was one of the biggest breakthroughs…","ch":["which","what"],"a":0,"why":"2문장: ...Alexander Fleming, for which he later received the Nobel Prize (Alexander Fleming, 그것에 대해 그는 후에 노벨상을 받았다)\nfor 뒤에 앞의 명사(the discovery)를 대신하는 말이 필요하고, 뒤에 he later received the Nobel Prize라는 완전한 문장이 이어진다. 그래서 전치사 + 관계대명사 which가 맞다.\n함정: what은 선행사를 품고 있어 '~하는 것'이라는 뜻이다. 앞에 받을 명사가 이미 있어서 쓸 수 없다.\n본문 포인트: 페니실린 발견으로 상을 받았다.","tr":"1928년에 Alexander Fleming에 의한 페니실린의 발견은 가장 큰 획기적 발전들 중 하나였으며, 그것에 대해 그는 후에 노벨상을 받았다.","g":"앞 명사를 설명하고 뒤에 완전한 문장이 오면 '전치사 + which'를 쓴다.\n예) This is the book for which I paid. (이것이 내가 값을 낸 책이다.)"},{"s":"…the cowpox virus, ( ______ ) is harmless to humans.","ch":["which","what"],"a":0,"why":"3문장: ...the cowpox virus, which is harmless to humans (인간들에게 무해한 우두 바이러스)\n콤마 뒤에서 the cowpox virus를 보충 설명하는 관계대명사 which가 맞다. 뒤에 주어가 없는 is harmless ...가 이어지므로 주어 역할도 한다.\n함정: what은 앞에 설명할 명사가 있을 때 쓰지 않는다. that도 콤마 뒤에서는 쓰지 않는다.\n본문 포인트: 우두 바이러스는 해가 없다.","tr":"인간들에게 무해한 우두 바이러스에 노출된 후에…","g":"콤마(,) 뒤에서 앞 명사를 설명하는 관계대명사는 which (사물), who (사람)이다.\n예) I have a dog, which is cute. (나는 개가 있는데, 그 개는 귀엽다.)"},{"s":"Vaccines developed in laboratories have contributed enormously to the ( ______ ) of the burden of bacterial and viral diseases","ch":["reduction","reduce"],"a":0,"why":"4문장: ...contributed enormously to the reduction of the burden (부담의 감소에 엄청나게 기여했다)\ncontribute to에서 to는 전치사이다. 전치사 뒤에는 명사가 오므로 reduction이 맞다. 앞의 the와도 어울린다.\n함정: reduce는 동사라서 the 뒤에 올 수 없다.\n본문 포인트: 백신이 병의 부담을 줄였다.","tr":"실험실에서 개발된 백신은 세균성 질병과 바이러스성 질병의 부담의 감소에 엄청나게 기여했다.","g":"to가 전치사이면 뒤에 명사 또는 동명사가 온다. to부정사의 to와 구별한다.\n예) contribute to the success (성공에 기여하다)"},{"s":"…for others treatment therapies ( ______ ) viral diseases that were deadly into chronic manageable diseases.","ch":["turned","turning"],"a":0,"why":"5문장: ...while for others treatment therapies turned viral diseases that were deadly into chronic manageable diseases (반면 또 다른 것들의 경우에는 치료법들이 치명적이었던 바이러스성 질병들을 만성적인 관리 가능한 질병들로 바꾸었다)\nwhile 뒤의 절에서 주어는 treatment therapies이다. 문장이 완성되려면 진짜 동사가 필요하므로 과거형 turned가 맞다. 앞 절의 have reduced와 같은 과거 쪽 시제로 이어진다.\n함정: turning은 동사 역할을 못 한다. 동사 없이는 문장이 완성되지 않는다.\n본문 포인트: 치료법은 병의 성격을 바꾸었다.","tr":"또 다른 것들의 경우에는 치료법이 치명적이었던 바이러스성 질병을 만성적인 관리 가능한 질병으로 바꾸었다.","g":"절 안에는 진짜 동사가 하나 꼭 있어야 한다. -ing만 쓰면 동사가 되지 못한다.\n예) The rain stopped the game. (비가 경기를 멈추게 했다.)"}],"awk":[{"t":"Edward Jenner discovered around 1796 that humans were [[1|protected]] against the [[2|deadly]] smallpox virus after [[3|exposure]] to the cowpox virus, which is [[4|harmful]] to [[5|humans]].","a":4,"fix":"harmless","why":"원문은 the cowpox virus, which is harmless to humans (인간들에게 무해한 우두 바이러스)이다.\n정답은 4번 harmful (해로운)이다.\n우두 바이러스에 노출된 뒤 사람이 천연두로부터 보호된다는 것이 핵심인데, 우두가 해롭다면 그 노출 자체가 위험해서 이 발견이 의미를 잃는다.\n본문 포인트: 무해한 바이러스가 치명적인 바이러스를 막는다.","sp":[{"b":"protected","m":"보호된","n":"과거분사. be protected against = ~로부터 보호되다","y":"맞음. 노출 후 천연두를 막게 됨.","e":"백신을 맞아 병을 막는 것."},{"b":"deadly","m":"치명적인","n":"형용사. virus를 꾸밈","y":"맞음. 천연두는 치명적임.","e":"생명을 위협하는."},{"b":"exposure","m":"노출","n":"명사. exposure to = ~에 노출됨","y":"맞음. 우두 바이러스에 노출됨.","e":"햇빛에 드러난 피부."},{"b":"harmful","m":"해로운","n":"형용사","y":"어색함. 원문은 harmless. 해로운 바이러스라면 보호 효과를 말하는 글의 흐름과 모순.","e":"몸에 나쁜 음식."},{"b":"humans","m":"인간","n":"명사. 복수형","y":"맞음. 인간에게 무해하다는 뜻.","e":"사람들."}]},{"t":"Vaccines developed in laboratories have [[1|contributed]] enormously to the [[2|increase]] of the [[3|burden]] of [[4|bacterial]] and [[5|viral]] diseases and have even led to the elimination of poxvirus.","a":2,"fix":"reduction","why":"원문은 contributed enormously to the reduction of the burden (부담의 감소에 엄청나게 기여했다)이다.\n정답은 2번 increase (증가)이다.\n백신이 병의 부담을 늘렸다면 긍정적인 contributed enormously와 뒤의 elimination (퇴치)와 모순된다. 백신은 병을 줄이는 것이다.\n본문 포인트: 백신은 질병의 부담을 줄인다.","sp":[{"b":"contributed","m":"기여했다","n":"현재완료. contribute to = ~에 기여하다","y":"맞음. 큰 도움이 됨.","e":"힘을 보태다."},{"b":"increase","m":"증가","n":"명사","y":"어색함. 원문은 reduction. 백신의 역할은 병을 줄이는 것이라 글과 모순.","e":"병이 늘어나는 상황."},{"b":"burden","m":"부담","n":"명사","y":"맞음. 병이 주는 짐.","e":"무거운 짐."},{"b":"bacterial","m":"세균성의","n":"형용사","y":"맞음. 세균에 의한 병.","e":"세균으로 생기는 병."},{"b":"viral","m":"바이러스성의","n":"형용사","y":"맞음. 바이러스에 의한 병.","e":"바이러스로 생기는 병."}]},{"t":"For other infectious diseases, control and hygiene management measures have [[1|reduced]] their burden, while for others treatment therapies turned [[2|viral]] diseases that were [[3|harmless]] into [[4|chronic]] [[5|manageable]] diseases.","a":3,"fix":"deadly","why":"원문은 viral diseases that were deadly (치명적이었던 바이러스성 질병들)이다.\n정답은 3번 harmless (무해한)이다.\n무해한 병이었다면 '치료로 관리할 수 있는 병으로 바꾼다'는 이야기가 필요하지 않다. 치명적이었기 때문에 관리 가능한 병으로 바뀐 것이 성과이다.\n본문 포인트: 치명적 병 → 관리 가능한 병.","sp":[{"b":"reduced","m":"줄였다","n":"현재완료","y":"맞음. 부담을 줄임.","e":"줄어든 수."},{"b":"viral","m":"바이러스성의","n":"형용사","y":"맞음. 바이러스에 의한 병.","e":"바이러스로 생기는 병."},{"b":"harmless","m":"무해한","n":"형용사","y":"어색함. 원문은 deadly. 무해한 병은 성과로 말할 이유가 없고 chronic 변화의 의미가 사라짐.","e":"해가 없는 것."},{"b":"chronic","m":"만성적인","n":"형용사","y":"맞음. 오래 가는 병.","e":"오래 가는 병."},{"b":"manageable","m":"관리 가능한","n":"형용사","y":"맞음. 치료로 관리할 수 있음.","e":"약으로 관리하는 병."}]}],"und":[{"q":"…was one of the biggest <u>breakthroughs in the battle against infectious diseases</u>.","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["전염병과 싸우는 일에서 큰 진전을 이룬 중요한 성과","전염병이 더 많이 퍼지게 된 사건","전염병 환자끼리 싸우게 된 일","새로운 병원이 세워진 일","전염병이 원인이 되어 전쟁이 난 일"],"a":0,"why":"2문장: ...one of the biggest breakthroughs in the battle against infectious diseases (전염병과의 싸움에서 가장 큰 획기적 발전들 중 하나)\nbattle은 비유이다. 사람과 병이 싸우는 것이다. breakthroughs = 큰 발전.\n정답은 이 비유를 풀어 쓴 것이다.\n'더 많이 퍼지게 된 사건'은 반대 뜻이다. '환자끼리 싸우게 된 일'과 '전쟁이 난 일'은 battle을 글자 그대로만 읽은 것이다. '새로운 병원이 세워진 일'은 글에 없다.\n본문 포인트: 페니실린은 병과의 싸움에서의 큰 성과였다.","e":"병과 싸우는 일에서 큰 승리를 거둔 것.","tr":"…전염병과의 싸움에서 가장 큰 획기적 발전들 중 하나…"},{"q":"humans were protected against the deadly smallpox virus <u>after exposure to the cowpox virus</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["우두 바이러스에 몸이 접촉된 뒤에","우두 바이러스를 완전히 없앤 뒤에","천연두에 걸려서 회복된 뒤에","우두 바이러스를 연구실에서 만든 뒤에","우두 바이러스가 해롭다는 것을 안 뒤에"],"a":0,"why":"3문장: ...after exposure to the cowpox virus (우두 바이러스에 노출된 후에)\nexposure to = ~에 노출됨, 접촉함.\n정답은 이 뜻을 풀어 쓴 것이다.\n'완전히 없앤 뒤에'와 '회복된 뒤에'는 글에 없다. '연구실에서 만든'은 4문장의 laboratories (실험실)와 헷갈린 오답이다. '해롭다는 것을 안 뒤에'는 harmless (무해한)와 반대이다.\n본문 포인트: 우두에 노출된 것이 보호의 계기가 되었다.","e":"병균에 몸이 닿았던 경험이 몸을 지켜 준 것.","tr":"…우두 바이러스에 노출된 후에…"},{"q":"treatment therapies turned viral diseases that were deadly into <u>chronic manageable diseases</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["오래 계속되지만 치료로 조절하며 살 수 있는 병","한 번 걸리면 반드시 사망하는 병","치료 없이도 저절로 낫는 병","전염되지 않는 가벼운 병","감염 후 며칠 안에 끝나는 병"],"a":0,"why":"5문장: ...turned viral diseases that were deadly into chronic manageable diseases (치명적이었던 바이러스성 질병들을 만성적인 관리 가능한 질병들로 바꾸었다)\nchronic = 오래 계속되는, manageable = 관리할 수 있는. 이 두 말을 합쳐 읽는다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'반드시 사망하는 병'은 deadly와 같은 이전 상태이다. '저절로 낫는'과 '며칠 안에 끝나는'은 chronic (오래 계속되는)과 반대이다. '전염되지 않는 가벼운 병'은 글에 없다.\n본문 포인트: 치명적이던 병이 관리하며 사는 병으로 바뀌었다.","e":"약을 먹으며 오래 관리하는 병.","tr":"…치명적이었던 바이러스성 질병들을 만성적인 관리 가능한 질병들로 바꾸었다."}]},"2610-36":{"voc":[{"q":"A simple truth that designers must <u>embrace</u> in order to create more effective products…","ask":"embrace의 뜻으로 알맞은 것은?","ch":["(생각 등을) 기꺼이 받아들이다","꼭 껴안다","피하다","비판하다","잊어버리다"],"a":0,"why":"1문장: A simple truth that designers must embrace (디자이너들이 반드시 받아들여야 하는 단순한 진리)\n쉽게 말해 불편해도 인정하고 받아들이라는 뜻이다.\nembrace는 원래 '껴안다'인데, 생각이나 사실을 기꺼이 받아들인다는 뜻으로도 쓴다.\n오답 함정: '꼭 껴안다'는 글자 그대로의 뜻이다. 진리 (truth)를 껴안을 수는 없으니 뜻이 넓어진 쓰임으로 읽는다.\n본문 포인트: 우리는 사용자가 아니라는 사실을 받아들여야 한다.","e":"틀렸다는 말을 듣고 인정하고 고쳐 가는 것.","tr":"디자이너들이 더 효과적인 제품과 경험을 만들어 내기 위해 수용해야만 하는 단순한 진리…","alt":"accept, welcome, adopt"},{"q":"We're much too close to what we build to <u>objectively</u> see it…","ask":"objectively의 뜻으로 알맞은 것은?","ch":["객관적으로, 감정 없이 있는 그대로","주관적으로","빠르게","조심스럽게","자주"],"a":0,"why":"2문장: ...to objectively see it (그것을 객관적으로 보기에는)\n쉽게 말해 내가 만든 것이라 있는 그대로 보기 어렵다는 뜻이다.\nobjective = 객관적인. 반대말은 subjective (주관적인)이다. 내 생각이나 감정이 섞이지 않고 보는 것이다.\n오답 함정: '주관적으로'는 반대 뜻이다.\n본문 포인트: 만든 사람은 자기 작품을 객관적으로 보지 못한다.","e":"내 그림을 남의 그림처럼 냉정하게 평가하는 것.","tr":"우리는 우리가 만드는 것에 너무 가까워서 그것을 객관적으로 볼 수 없다.","alt":"fairly, without bias; 반의어: subjectively"},{"q":"The best user <u>interfaces</u> are those that have been shaped by observations of real users…","ask":"interface의 뜻으로 알맞은 것은?","ch":["사용자와 제품이 만나는 화면, 접점","외부 광고","제품 가격표","제작 회사","수리 설명서"],"a":0,"why":"3문장: The best user interfaces are those that have been shaped by observations of real users (가장 좋은 사용자 인터페이스들은 실제 사용자들에 대한 관찰 결과들에 의해 만들어져 온 것들이다)\n쉽게 말해 사람이 앱이나 기계를 만지고 쓰는 화면이나 방식이다.\ninterface = inter (사이) + face (면). 사람과 제품이 맞닿는 면이다.\n오답 함정: '광고'나 '가격표'는 글에 근거가 없다.\n본문 포인트: 좋은 인터페이스는 실제 사용자를 보고 만든다.","e":"스마트폰 앱의 버튼과 화면 배치.","tr":"가장 좋은 사용자 인터페이스들은…","alt":"screen, controls, point of contact"},{"q":"…to <u>uncover</u> problems in a design, discover existing opportunities…","ask":"uncover와 가장 가까운 뜻은?","ch":["밝혀내다, 찾아내다","덮다","만들다","없애다","미루다"],"a":0,"why":"6문장: ...to uncover problems in a design (디자인상의 문제들을 밝혀 내다)\n쉽게 말해 숨어 있던 문제를 찾아낸다는 뜻이다.\nuncover = un (반대) + cover (덮다). 덮개를 벗겨 안을 드러내는 것이다.\n오답 함정: '덮다'는 cover의 뜻이다. un이 붙으면 반대가 된다.\n본문 포인트: 테스트의 첫째 목표는 문제를 찾아내는 것이다.","e":"덮어 둔 이불을 걷어 안을 보는 것.","tr":"이 방법의 목표는 디자인상의 문제들을 밝혀 내는 것이다.","alt":"discover, reveal, find out"},{"q":"…learn more about the behaviors and <u>preferences</u> of users…","ask":"preferences의 뜻으로 알맞은 것은?","ch":["선호, 더 좋아하는 것","불만","나이","직업","실수"],"a":0,"why":"6문장: ...the behaviors and preferences of users (사용자들의 행동들과 선호하는 것들)\n쉽게 말해 사용자가 무엇을 더 좋아하는지이다.\nprefer = 더 좋아하다. 명사가 preference이다. prefer A to B = B보다 A를 더 좋아하다.\n오답 함정: '불만'은 complaint이다. '실수'는 mistake이다.\n본문 포인트: 사용자의 행동과 취향을 알아낸다.","e":"급식에서 고르는 메뉴.","tr":"…사용자들의 행동들과 선호하는 것들에 대해 더 많이 학습하는 것이다.","alt":"liking, choice; 동사: prefer"},{"q":"…by asking participants to <u>engage</u> in realistic activities.","ask":"engage in의 뜻으로 알맞은 것은?","ch":["~에 참여하다","~을 거절하다","~에서 도망치다","~을 구경만 하다","~을 설명하다"],"a":0,"why":"6문장: ...by asking participants to engage in realistic activities (참가자들에게 실제적인 활동들에 참여하도록 요청함으로써)\n쉽게 말해 참가자가 실제 상황처럼 직접 해 본다는 뜻이다.\nengage in = ~에 참여하다, 몰두하다 (= take part in).\n오답 함정: '구경만 하다'는 참여와 반대이다.\n본문 포인트: 참가자가 직접 사용해 봐야 문제가 드러난다.","e":"체육 대회에 직접 나가서 뛰는 것.","tr":"…참가자들이 실제적인 활동들에 참여하도록 요청함으로써…","alt":"take part in, join, participate in"},{"q":"Designers can improve their work through <u>subsequent</u> revisions…","ask":"subsequent의 뜻으로 알맞은 것은?","ch":["그다음의, 뒤따르는","처음의","불필요한","위험한","완벽한"],"a":0,"why":"8문장: ...through subsequent revisions based on the findings from representative users (대표적인 사용자들로부터 발견한 것들에 기반한 차후의 수정들을 통해)\n쉽게 말해 테스트 뒤에 이어지는 수정이다.\nsubsequent = 그다음의 (= following, later). 반대말은 previous (이전의)이다.\n오답 함정: '처음의'는 previous나 initial의 뜻이다.\n본문 포인트: 테스트 결과를 보고 다시 고쳐 나간다.","e":"1차 시험 다음에 이어지는 2차 시험.","tr":"…대표적인 사용자들로부터 발견한 것들에 기반한 차후의 수정들을 통해…","alt":"following, later; 반의어: previous"},{"q":"…based on the findings from <u>representative</u> users.","ask":"representative의 뜻으로 알맞은 것은?","ch":["전체를 대표하는, 대표적인","유명한","특별한","허락받은","외국의"],"a":0,"why":"8문장: ...the findings from representative users (대표적인 사용자들로부터 발견한 것들)\n쉽게 말해 많은 사용자 중에서 그 집단의 특징을 잘 보여 주는 사람들이다.\nrepresent = 대표하다. 형용사가 representative이다. 반장이 반을 대표하듯, 전체를 대표하는 사용자이다.\n오답 함정: '유명한'은 famous이다. 대표는 이름난 것과 다르다.\n본문 포인트: 대표 사용자의 결과가 전체 사용자에게 도움이 된다.","e":"전교 학생을 대표해서 나온 학생 회장.","tr":"…대표적인 사용자들로부터 발견한 것들…","alt":"typical, standard; 동사: represent"}],"find":[{"s":"Designers need to accept the fact that they are not the user.","a":true,"why":"1문장: A simple truth that designers must embrace ... is the fact that we are not the user. (디자이너들이 받아들여야만 하는 단순한 진리는 우리가 사용자가 아니라는 사실이다)\n쉽게 말해 만드는 사람은 쓰는 사람과 다르다.\nembrace = accept. 같은 뜻으로 바꾼 문장이다.\n본문 포인트: 이 문장이 글의 출발점이다.","e":"만드는 사람과 쓰는 사람은 입장이 다르다는 것."},{"s":"Designers can easily and objectively see how users will interact with their products.","a":false,"why":"2문장: We're much too close to what we build to objectively see it and understand how users will interact with it. (우리는 우리가 만드는 것에 너무 가까워서 그것을 객관적으로 보고 사용자들이 그것과 어떻게 상호 작용할지 이해할 수 없다)\n쉽게 말해 쉽지 않다.\n함정: much too close (너무 가깝다)는 부정적인 말인데, easily ... objectively (쉽게 객관적으로 보다)로 정반대를 만들었다.\n본문 포인트: 만든 사람은 자기 작품을 객관적으로 보기 어렵다.","e":"내 글의 오타는 나만 못 찾는 것."},{"s":"The best user interfaces are shaped by observations of real users and their interactions.","a":true,"why":"3문장: The best user interfaces are those that have been shaped by observations of real users and their interactions with them. (가장 좋은 사용자 인터페이스들은 실제 사용자들과 그들의 상호 작용에 대한 관찰 결과들에 의해 만들어져 온 것들이다)\n쉽게 말해 실제 사용자를 관찰해서 만든 것이 가장 좋다.\n본문 포인트: 관찰이 좋은 디자인을 만든다.","e":"직접 쓰는 모습을 보고 고친 앱."},{"s":"The best user interfaces are shaped mainly by the designers' own ideas.","a":false,"why":"3문장: ...shaped by observations of real users (실제 사용자들에 대한 관찰에 의해 만들어진)\n쉽게 말해 사용자 관찰이 중심이다.\n함정: 실제 사용자의 관찰 (observations of real users)을 디자이너 자신의 생각으로 바꿨다. 글의 첫 문장(우리는 사용자가 아니다)과도 모순된다.\n본문 포인트: 디자이너의 생각이 아니라 사용자를 보고 만든다.","e":"내 생각만으로 만든 결과."},{"s":"The passage introduces usability testing as an effective way to make a design more effective.","a":true,"why":"4~5문장: So how can designers shape their work to be more effective? An incredibly effective way is with usability testing. (그러면 디자이너들은 어떻게 자신의 작업이 더 효과적일 수 있도록 만들 수 있을까? 엄청나게 효과적인 방법은 사용성 테스트를 가지고 하는 것이다)\n쉽게 말해 4문장의 질문에 5문장이 답한다.\n본문 포인트: 사용성 테스트가 이 글의 해결책이다.","e":"질문 다음에 해결책이 나오는 구조."},{"s":"Usability testing aims to find problems in a design and to discover existing opportunities.","a":true,"why":"6문장: The goal of this method is to uncover problems in a design, discover existing opportunities, and learn more about the behaviors and preferences of users (이 방법의 목표는 디자인상의 문제들을 밝혀 내고, 현재 있는 가능성들을 발견하고, 사용자들의 행동들과 선호하는 것들에 대해 더 많이 학습하는 것이다)\n쉽게 말해 문제도 찾고 기회도 찾는다.\nuncover = find. 같은 뜻으로 바꾼 문장이다.\n본문 포인트: 목표는 세 가지이다.","e":"시험을 보고 틀린 곳과 잘한 곳을 모두 찾는 것."},{"s":"In usability testing, participants are asked to watch designers work without taking part in any activities.","a":false,"why":"6문장: ...by asking participants to engage in realistic activities (참가자들에게 실제적인 활동들에 참여하도록 요청함으로써)\n쉽게 말해 참가자가 직접 해 본다.\n함정: engage in (참여하다)을 watch ... without taking part (참여 없이 지켜보다)로 뒤집었다.\n본문 포인트: 참가자가 실제처럼 활동해 봐야 한다.","e":"구경만 하는 것과 직접 해 보는 것의 차이."},{"s":"Usability testing is useful for understanding how well a design will work in the hands of real users.","a":true,"why":"7문장: This technique is effective for understanding how well a design will perform once it is in the hands of real users. (이 기술은 디자인이 실제 사용자들의 손 안에 있을 때 얼마나 잘 작동할 것인지를 이해하는 데 효과적이다)\n쉽게 말해 실제로 쓰일 때 얼마나 잘 되는지를 알 수 있다.\nperform = work. 같은 뜻으로 바꾼 문장이다.\n본문 포인트: 사용성 테스트는 실제 상황에서의 성능을 알려 준다.","e":"시판 전에 시험 사용해 보는 것."},{"s":"Usability testing can only be used before a design is created.","a":false,"why":"7~8문장: ...once it is in the hands of real users / improve their work through subsequent revisions (실제 사용자들의 손 안에 있을 때 / 차후의 수정들을 통해 작업을 개선하다)\n쉽게 말해 디자인이 만들어진 후에 사용해 보고 고친다.\n함정: before a design is created (만들기 전)에만 쓴다고 했지만, 글에서는 디자인이 있는 상태에서 테스트하고 수정한다. only가 들어간 문장은 의심한다.\n본문 포인트: 만든 뒤 테스트하고 다시 고친다.","e":"완성한 뒤에야 써 볼 수 있다는 점."},{"s":"Designers can improve their work through later revisions based on findings from representative users.","a":true,"why":"8문장: Designers can use this method to improve their work through subsequent revisions based on the findings from representative users. (디자이너들은 대표적인 사용자들로부터 발견한 것들에 기반한 차후의 수정들을 통해 자신의 작업을 개선하기 위해 이 방법을 사용할 수 있다)\n쉽게 말해 테스트 결과를 보고 다시 고친다.\nsubsequent = later. 같은 뜻으로 바꾼 문장이다.\n본문 포인트: 이 글의 마지막은 테스트 결과로 개선한다는 내용이다.","e":"시험 결과를 보고 공부법을 고치는 것."}],"eob":[{"s":"A simple truth ( ______ ) designers must embrace in order to create more effective products and experiences is the fact that we are not the user.","ch":["that","what"],"a":0,"why":"1문장: A simple truth that designers must embrace ... (디자이너들이 받아들여야만 하는 단순한 진리)\nA simple truth는 앞의 명사(선행사)이다. 뒤에 designers must embrace라고 목적어가 빠진 문장이 이어지므로 목적격 관계대명사 that이 맞다.\n함정: what은 선행사를 품고 있어서 앞에 명사가 있을 때 쓰지 않는다.\n본문 포인트: 디자이너가 받아들여야 하는 진리는 우리가 사용자가 아니라는 것이다.","tr":"디자이너들이 더 효과적인 제품과 경험을 만들어 내기 위해 수용해야만 하는 단순한 진리는 우리가 사용자가 아니라는 사실이다.","g":"앞에 명사가 있고 뒤 문장에서 목적어가 빠졌으면 관계대명사 that (목적격)이 올 수 있다.\n예) The book that I read was fun. (내가 읽은 책은 재미있었다.)"},{"s":"We're much too close to what we build to objectively see it and ( ______ ) how users will interact with it.","ch":["understand","understanding"],"a":0,"why":"2문장: ...to objectively see it and understand how users will interact with it (그것을 객관적으로 보고 사용자들이 그것과 어떻게 상호 작용할지 이해하기에)\nto see ... and ... 형태로 to 뒤에 두 동사가 and로 이어진다. 병렬이므로 see와 같은 형태인 원형 understand가 맞다.\n함정: understanding은 see와 형태가 달라 병렬이 깨진다.\n본문 포인트: 객관적으로 보고 이해하는 것 둘 다 어렵다.","tr":"우리는 우리가 만드는 것에 너무 가까워서 그것을 객관적으로 보고 사용자들이 그것과 어떻게 상호 작용할지 이해할 수 없다.","g":"and로 이어지는 말은 같은 형태로 맞춘다 (병렬).\n예) I like to read and (to) write. (나는 읽고 쓰는 것을 좋아한다.)"},{"s":"The best user interfaces are those that ( ______ ) shaped by observations of real users and their interactions with them.","ch":["have been","have"],"a":0,"why":"3문장: ...those that have been shaped by observations of real users (실제 사용자들에 대한 관찰 결과들에 의해 만들어져 온 것들)\nthose that의 that은 interfaces를 받는 주격 관계대명사이다. 인터페이스는 '만들어지는' 쪽이므로 수동태 have been shaped가 맞다. 뒤의 by observations (관찰에 의해)도 단서이다.\n함정: have shaped는 능동이라 '(인터페이스가) ~를 만들어 왔다'는 뜻이 되어 맞지 않는다.\n본문 포인트: 관찰에 의해 만들어진 인터페이스가 가장 좋다.","tr":"가장 좋은 사용자 인터페이스들은 실제 사용자들과 그들의 그것들과의 상호 작용에 대한 관찰 결과들에 의해 만들어져 온 것들이다.","g":"주어가 행위를 당하면 수동태 (be + p.p.), by가 따라오면 수동을 의심한다.\n예) The window has been broken by Tom. (그 창문은 Tom에 의해 깨졌다.)"},{"s":"The goal of this method is to uncover problems in a design … by ( ______ ) participants to engage in realistic activities.","ch":["asking","ask"],"a":0,"why":"6문장: ...by asking participants to engage in realistic activities (참가자들에게 실제적인 활동들에 참여하도록 요청함으로써)\nby는 전치사이다. 전치사 뒤에는 명사나 동명사(-ing)가 오므로 asking이 맞다. 뒤의 participants가 목적어, to engage는 목적격 보어이다.\n함정: ask는 동사 원형이라 전치사 뒤에 올 수 없다.\n본문 포인트: 참가자에게 요청하는 방식으로 문제를 찾는다.","tr":"이 방법의 목표는 참가자들이 실제적인 활동들에 참여하도록 요청함으로써 디자인상의 문제들을 밝혀 내는 것이다.","g":"전치사 뒤에는 동명사(-ing). 'by -ing' = ~함으로써.\n예) He learned by listening. (그는 들음으로써 배웠다.)"},{"s":"This technique is effective for understanding how well a design ( ______ ) once it is in the hands of real users.","ch":["will perform","will it perform"],"a":0,"why":"7문장: ...understanding how well a design will perform once it is in the hands of real users (디자인이 실제 사용자들의 손 안에 있을 때 얼마나 잘 작동할 것인지를 이해하는 데)\nhow well이 이끄는 말이 understanding의 목적어(간접의문문)이다. 간접의문문은 '의문사 + 주어 + 동사' 순서이므로 how well a design will perform이 맞다.\n함정: will it perform은 의문문 어순이다. 간접의문문에서는 주어가 먼저 온다.\n본문 포인트: 디자인이 실제로 얼마나 잘 작동하는지 알 수 있다.","tr":"이 기술은 디자인이 실제 사용자들의 손 안에 있을 때 얼마나 잘 작동할 것인지를 이해하는 데 효과적이다.","g":"문장 속에 들어간 의문문은 '의문사 + 주어 + 동사' 순서이다.\n예) I know where he lives. (나는 그가 어디 사는지 안다.)"}],"awk":[{"t":"We're much too [[1|close]] to what we build to [[2|subjectively]] see it and [[3|understand]] how users will [[4|interact]] with [[5|it]].","a":2,"fix":"objectively","why":"원문은 to objectively see it (그것을 객관적으로 보기에)이다.\n정답은 2번 subjectively (주관적으로)이다.\n'만든 것에 너무 가까워서' 못 하는 것은 거리를 두고 있는 그대로 보는 일이다. 가까우면 오히려 내 생각대로 보기 쉬우니 subjectively는 맞지 않는다.\n본문 포인트: 너무 가까워서 객관적으로 보기 어렵다.","sp":[{"b":"close","m":"가까운","n":"형용사. too close to = ~에 너무 가까운","y":"맞음. 만든 것에 너무 가까움.","e":"내 작품 바로 앞에 선 것."},{"b":"subjectively","m":"주관적으로","n":"부사. see를 꾸밈","y":"어색함. 원문은 objectively. 너무 가까워서 못 하는 것은 객관적으로 보는 일이라 문맥과 모순.","e":"내 마음대로 보는 것."},{"b":"understand","m":"이해하다","n":"동사 원형. see와 병렬","y":"맞음. 사용자의 상호 작용을 이해함.","e":"이해하는 것."},{"b":"interact","m":"상호 작용하다","n":"동사 원형. interact with = ~와 상호 작용하다","y":"맞음. 사용자가 제품과 주고받음.","e":"앱 버튼을 눌러 반응을 보는 것."},{"b":"it","m":"그것","n":"대명사. what we build를 가리킴","y":"맞음. 우리가 만드는 것을 가리킴.","e":"우리가 만든 제품."}]},{"t":"The best user interfaces are those that have been [[1|shaped]] by [[2|observations]] of [[3|imaginary]] users and their [[4|interactions]] with [[5|them]].","a":3,"fix":"real","why":"원문은 observations of real users (실제 사용자들에 대한 관찰)이다.\n정답은 3번 imaginary (상상 속의)이다.\n관찰은 눈에 보이는 실제 대상에게만 할 수 있다. 상상 속 사용자는 관찰할 수 없다. 또 이 글은 '우리는 사용자가 아니다'라며 실제 사용자를 강조한다.\n본문 포인트: 실제 사용자를 관찰해야 좋은 인터페이스가 나온다.","sp":[{"b":"shaped","m":"만들어진","n":"과거분사. have been shaped = 수동태 현재완료","y":"맞음. 관찰에 의해 만들어짐.","e":"틀에 맞춰 만든 모양."},{"b":"observations","m":"관찰 결과","n":"명사. 복수형","y":"맞음. 사용자를 관찰한 결과.","e":"관찰 일지."},{"b":"imaginary","m":"상상 속의","n":"형용사. users를 꾸밈","y":"어색함. 원문은 real. 상상 속 사용자는 관찰할 수 없어 모순.","e":"상상 속의 친구."},{"b":"interactions","m":"상호 작용","n":"명사. 복수형","y":"맞음. 사용자와 제품의 주고받음.","e":"버튼을 누르고 반응을 보는 것."},{"b":"them","m":"그것들","n":"대명사. interfaces를 가리킴","y":"맞음. 인터페이스를 가리킴.","e":"그 화면들."}]},{"t":"The goal of this method is to [[1|uncover]] problems in a design, [[2|discover]] existing opportunities, and learn more about the behaviors and preferences of users by asking participants to [[3|avoid]] [[4|realistic]] [[5|activities]].","a":3,"fix":"engage in","why":"원문은 asking participants to engage in realistic activities (참가자들에게 실제적인 활동들에 참여하도록 요청함으로써)이다.\n정답은 3번 avoid (피하다)이다.\n사용자의 행동과 선호를 알아내려면 참가자가 직접 해 봐야 한다. 활동을 피하라고 하면 배울 것이 없어져 목표와 모순이다.\n본문 포인트: 참가자가 직접 활동해 봐야 문제가 드러난다.","sp":[{"b":"uncover","m":"밝혀내다","n":"동사 원형. to uncover","y":"맞음. 문제를 찾아냄.","e":"숨은 문제를 찾는 것."},{"b":"discover","m":"발견하다","n":"동사 원형. uncover와 병렬","y":"맞음. 기회를 발견함.","e":"새 가능성을 찾는 것."},{"b":"avoid","m":"피하다","n":"동사 원형","y":"어색함. 원문은 engage in. 참가자가 활동을 피하면 행동을 관찰할 수 없어 목표와 모순.","e":"숙제를 피하는 것."},{"b":"realistic","m":"실제적인","n":"형용사. activities를 꾸밈","y":"맞음. 실제와 비슷한 활동.","e":"현실과 같은 상황."},{"b":"activities","m":"활동들","n":"명사. 복수형","y":"맞음. 참가자가 하는 활동.","e":"체험 활동."}]},{"t":"This technique is [[1|ineffective]] for [[2|understanding]] how [[3|well]] a design will [[4|perform]] once it is in the [[5|hands]] of real users.","a":1,"fix":"effective","why":"원문은 This technique is effective for understanding how well a design will perform (이 기술은 디자인이 얼마나 잘 작동할지 이해하는 데 효과적이다)이다.\n정답은 1번 ineffective (효과적이지 않은)이다.\n글 전체가 사용성 테스트를 '엄청나게 효과적인 방법 (incredibly effective way)'이라고 소개한다. ineffective이면 전체 흐름과 모순이다.\n본문 포인트: 사용성 테스트는 효과적인 방법이다.","sp":[{"b":"ineffective","m":"효과적이지 않은","n":"형용사. in-은 부정","y":"어색함. 원문은 effective. 5문장 incredibly effective와 모순.","e":"효과 없는 공부법."},{"b":"understanding","m":"이해하는 것","n":"동명사. for 뒤","y":"맞음. 전치사 뒤 동명사.","e":"이해하는 일."},{"b":"well","m":"잘","n":"부사. how well = 얼마나 잘","y":"맞음. 작동의 정도.","e":"잘 해내는 것."},{"b":"perform","m":"작동하다","n":"동사 원형. will 뒤","y":"맞음. 디자인이 제 기능을 함.","e":"기계가 잘 돌아가는 것."},{"b":"hands","m":"손","n":"명사. in the hands of = ~의 손에","y":"맞음. 실제 사용자가 사용하는 상태.","e":"사용자 손 안의 제품."}]}],"und":[{"q":"A simple truth ... is the fact that <u>we are not the user</u>.","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["디자이너인 우리는 제품을 실제로 쓰는 사람과 입장과 경험이 같지 않다","우리는 제품을 한 번도 사용해 보지 않는다","사용자는 디자이너보다 늘 앞서 있다","우리는 사용자를 도와줄 의무가 없다","우리는 사용자의 이름을 알지 못한다"],"a":0,"why":"1문장: ...the fact that we are not the user (우리가 사용자가 아니라는 사실)\n2문장이 이유를 설명한다: We're much too close to what we build (우리는 우리가 만드는 것에 너무 가깝다). 만드는 사람은 쓰는 사람과 시각이 다르다는 뜻이다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'한 번도 사용해 보지 않는다'는 글에 없다. '늘 앞서 있다'와 '의무가 없다'는 글에 없는 말이다. '이름을 알지 못한다'는 글자 그대로만 읽은 것이다.\n본문 포인트: 디자이너의 눈과 사용자의 눈은 다르다.","e":"요리사가 맛있다고 해도 손님은 짜다고 느낄 수 있는 것.","tr":"디자이너들이 수용해야만 하는 단순한 진리는 우리가 사용자가 아니라는 사실이다."},{"q":"We're <u>much too close to what we build</u> to objectively see it","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["자신이 만든 것에 너무 깊이 관여해서 거리를 두고 보기 어렵다","만든 것이 가까이에 있어서 잘 보인다","만든 것에 관심이 거의 없다","만든 것을 사용자에게 가까이 가져다 놓았다","만든 것이 너무 작아서 놓치기 쉽다"],"a":0,"why":"2문장: We're much too close to what we build to objectively see it (우리는 우리가 만드는 것에 너무 가까워서 그것을 객관적으로 볼 수 없다)\n여기서 close는 거리가 아니라 '깊이 얽혀 있다'는 비유이다. too ... to ~ = 너무 ~해서 ~할 수 없다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'가까이에 있어서 잘 보인다'는 정반대이다. '관심이 거의 없다'는 글과 반대로 이해한 것이다. '사용자에게 가까이'와 '너무 작아서'는 글에 없다.\n본문 포인트: 만든 사람은 자기 작품을 객관적으로 보기 어렵다.","e":"내 글의 오타를 내가 못 찾는 것.","tr":"우리는 우리가 만드는 것에 너무 가까워서 그것을 객관적으로 볼 수 없다."},{"q":"how well a design will perform once it is <u>in the hands of real users</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["실제 사용자들이 직접 사용하게 되었을 때","실제 사용자들이 디자인을 만들게 되었을 때","디자이너가 손으로 작업하고 있을 때","사용자들이 디자인을 사지 않기로 했을 때","실제 사용자들이 다치지 않았을 때"],"a":0,"why":"7문장: ...once it is in the hands of real users (그것이 실제 사용자들의 손 안에 있을 때)\nin the hands of = ~의 손에, ~가 쓰고 있는. 손은 '사용하는 상태'를 비유한 말이다.\n정답은 이 뜻을 풀어 쓴 것이다.\n'사용자가 디자인을 만든다'는 주체가 뒤바뀐 오답이다. '디자이너가 작업할 때'는 글의 시점(출시 후)과 다르다. '사지 않기로 했을 때'와 '다치지 않았을 때'는 글에 없다.\n본문 포인트: 실제 사용 상황에서의 성능을 이해해야 한다.","e":"신제품이 실제 손님 손에서 쓰이기 시작하는 순간.","tr":"…디자인이 실제 사용자들의 손 안에 있을 때…"},{"q":"<u>subsequent revisions based on the findings from representative users</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["대표적인 사용자들에게서 얻은 결과를 바탕으로 이어서 하는 수정","처음 만들 때 이미 끝낸 수정","디자이너의 생각만으로 하는 수정","유명한 사용자에게 보여 주려고 하는 수정","모든 사용자에게서 같은 반응을 얻기 위한 수정"],"a":0,"why":"8문장: ...through subsequent revisions based on the findings from representative users (대표적인 사용자들로부터 발견한 것들에 기반한 차후의 수정들을 통해)\nsubsequent = 그다음의. findings = 발견한 것들. representative = 전체를 대표하는.\n정답은 이 뜻을 풀어 쓴 것이다.\n'처음 만들 때 이미 끝낸'은 subsequent (그다음의)와 반대이다. '디자이너의 생각만으로'는 based on the findings (결과를 바탕으로)와 모순이다. '유명한 사용자'는 representative를 famous로 잘못 이해한 것이다. '모든 사용자에게서 같은 반응'은 글에 없다.\n본문 포인트: 대표 사용자의 결과로 수정을 이어 간다.","e":"시험 결과를 보고 오답 노트를 만들어 다시 고치는 것.","tr":"…대표적인 사용자들로부터 발견한 것들에 기반한 차후의 수정들을 통해…"}]},"2610-37":{"voc":[{"q":"Reappraisal might present a particularly effective <u>avenue</u> to regulating emotions because it transforms emotions at their root.","ask":"avenue의 뜻으로 알맞은 것은?","ch":["경쟁자","결과","장애물","기념일","방법, 수단"],"a":4,"why":"avenue = 방법, 수단 (원래는 큰 길).\n여기서는 감정을 조절하는 하나의 길, 곧 방법이라는 뜻.","e":"목표 점수에 닿는 길이 여러 개일 때, 그중 한 가지 방법.","tr":"재평가, 즉 누군가가 감정적인 상황들에 대해 생각하는 방식을 바꾸는 것은 그것이 감정을 본질적으로 변화시키기 때문에 감정을 조절하는 데 특히 효과적인 방법을 제공할지도 모른다.","alt":"way, means, approach"},{"q":"Reappraisal might be effective because it <u>transforms</u> emotions at their root.","ask":"transforms와 바꿔 쓸 수 있는 말은?","ch":["keeps","hides","changes","copies","stops"],"a":2,"why":"transform = 완전히 바꾸다 (= change).\n재평가는 감정의 뿌리부터 바꾼다는 뜻.","e":"애벌레가 나비로 모습이 싹 바뀌는 것.","tr":"재평가, 즉 누군가가 감정적인 상황들에 대해 생각하는 방식을 바꾸는 것은 그것이 감정을 본질적으로 변화시키기 때문에 감정을 조절하는 데 특히 효과적인 방법을 제공할지도 모른다.","alt":"change, convert, alter"},{"q":"This is often an <u>adverse</u> event, and yet, it can be construed in different ways.","ask":"adverse의 반의어로 알맞은 것은?","ch":["harmful","painful","sudden","favorable","rare"],"a":3,"why":"adverse = 불리한, 부정적인. 반의어는 favorable (유리한, 좋은).\n이혼은 보통 부정적인 사건이라는 뜻.","e":"소풍날 비가 오는 것은 불리한 상황, 날씨가 맑은 것은 유리한 상황.","tr":"이것은 보통 부정적인 사건이지만, 그럼에도 불구하고 그것은 다른 방식들로 해석될 수 있다.","alt":"unfavorable, negative ↔ favorable, positive"},{"q":"This is often an adverse event, and yet, it can be <u>construed</u> in different ways.","ask":"construed의 뜻으로 알맞은 것은?","ch":["건설되다","파괴되다","해석되다","소비되다","감춰지다"],"a":2,"why":"construe = 해석하다, 받아들이다 (= interpret).\nconstruct (짓다)와 모양이 비슷해 헷갈리기 쉬움.\n같은 사건도 여러 방식으로 해석될 수 있다는 뜻.","e":"같은 성적도 “망했다”로 받아들이는 친구와 “다음엔 오른다”로 받아들이는 친구가 있음.","tr":"이것은 보통 부정적인 사건이지만, 그럼에도 불구하고 그것은 다른 방식들로 해석될 수 있다.","alt":"interpret, understand, read"},{"q":"One might view it as an <u>overpowering</u> loss that will mark one's family for life.","ask":"overpowering의 뜻으로 알맞은 것은?","ch":["사소한","일시적인","예상된","무료의","압도적인, 강렬한"],"a":4,"why":"overpowering = 압도적인, 너무 강해서 견디기 힘든.\n가족에게 평생 흔적을 남길 만큼 큰 상실이라는 뜻.","e":"너무 큰 슬픔이 한꺼번에 밀려와서 숨이 막히는 느낌.","tr":"누군가는 그것을 자신의 가족에게 평생 흔적을 남길 강렬한 상실로 여길지도 모른다.","alt":"overwhelming, intense"},{"q":"<u>Alternatively</u>, one might see it as something that is painful but that might lead to positive outcomes.","ask":"Alternatively의 뜻으로 알맞은 것은?","ch":["예를 들어","그 결과로","그 대신에, 달리 보면","다시 말해서","게다가"],"a":2,"why":"alternatively = 그 대신에, 다른 방법으로는.\n앞의 해석과 반대되는 다른 해석을 꺼낼 때 쓴다.","e":"“피자 말고, 대신 치킨은 어때?” 하고 다른 선택지를 말할 때.","tr":"이와는 달리, 누군가는 그것을 고통스럽기는 하지만 개선된 관계와 같이 장기적으로는 긍정적인 결과로 이어질 수 있는 일로 여길지도 모른다.","alt":"on the other hand, instead"},{"q":"<u>Crucially</u>, it might also bring some positive emotions, such as hope, strength, or gratitude.","ask":"Crucially와 가까운 뜻은?","ch":["importantly","slightly","rarely","suddenly","equally"],"a":0,"why":"crucially = 결정적으로, 가장 중요하게 (= importantly).\n뒤에 나오는 긍정적 감정이 핵심이라는 신호.","e":"시험 직전에 “이건 꼭 외워” 하고 선생님이 강조하는 말.","tr":"결정적으로 그것은 희망, 강인함 또는 감사함과 같은 어떤 긍정적인 감정들 또한 불러올지도 모른다.","alt":"importantly, critically, most of all"},{"q":"These short-term emotional consequences might <u>accumulate</u> to shape people's psychological health.","ask":"accumulate의 뜻으로 알맞은 것은?","ch":["쌓이다, 축적되다","흩어지다","줄어들다","사라지다","나뉘다"],"a":0,"why":"accumulate = 쌓이다, 축적되다.\n반의어는 disperse (흩어지다).\n작은 감정 변화가 반복되어 쌓이면 건강을 만든다는 뜻.","e":"동전을 매일 저금통에 넣으면 점점 모이는 것.","tr":"오랫동안 반복되면, 재평가의 이러한 단기적인 감정적 결과들이 축적되어 사람들의 심리적 건강을 형성할지도 모른다.","alt":"build up, pile up, gather"},{"q":"Thereby, reappraisal might be a key to <u>resilience</u>.","ask":"resilience의 뜻으로 알맞은 것은?","ch":["무관심","의존","반항","경쟁","회복 탄력성"],"a":4,"why":"resilience = 회복 탄력성, 힘든 일을 겪고 다시 일어서는 힘.\n재평가가 그 힘을 키우는 열쇠가 될 수 있다는 뜻.","e":"시험을 망쳐도 며칠 뒤 털고 다시 공부하는 힘.","tr":"그렇게 함으로써 재평가는 회복 탄력성의 해답이 될지도 모른다.","alt":"toughness, ability to recover"}],"find":[{"s":"재평가는 감정을 뿌리에서부터 바꾸기 때문에 감정 조절에 특히 효과적일 수 있다.","a":true,"why":"1문장: 재평가는 감정을 본질(뿌리)에서 변화시켜 효과적인 방법이 될 수 있다.","e":"불을 끄려면 연기가 아니라 불씨부터 잡는 것."},{"s":"이혼은 보통 긍정적인 사건으로 받아들여진다.","a":false,"why":"3문장: 이혼은 보통 부정적인(adverse) 사건이다.\n“긍정적”으로 바꾸면 불일치.","e":"비 오는 날을 좋은 날씨라고 하는 것과 같음."},{"s":"같은 이혼도 서로 다른 방식으로 해석될 수 있다.","a":true,"why":"3문장: 부정적인 사건이지만 다른 방식으로 해석될 수 있다.","e":"같은 시험 점수도 사람마다 다르게 받아들이는 것."},{"s":"첫 번째 해석에서는 이혼을 고통스럽지만 장기적으로 좋은 결과로 이어질 일로 본다.","a":false,"why":"4~5문장: 첫 번째 해석은 평생 흔적을 남길 압도적인 상실, 두 번째 해석이 장기적으로 긍정적인 결과로 이어질 수 있는 일.\n순서가 바뀌었다.","e":"1번 해석과 2번 해석을 서로 바꿔 읽은 셈."},{"s":"두 번째 해석은 이혼을 고통스럽지만 장기적으로 긍정적인 결과로 이어질 수 있는 일로 본다.","a":true,"why":"5문장: 고통스럽지만 개선된 관계 같은 긍정적 결과로 이어질 수 있다고 본다.","e":"다쳐서 아프지만 운동 습관이 생기는 것."},{"s":"해석이 달라도 사람이 느끼는 감정은 같다.","a":false,"why":"6문장: 다른 해석의 결과로 다른 감정을 느낀다.\n“같다”로 바꾸면 불일치.","e":"같은 영화를 보고도 누구는 울고 누구는 웃는 것."},{"s":"첫 번째 해석은 강렬한 슬픔과 분노를 불러올 수 있다.","a":true,"why":"7문장: 첫 번째 해석은 강렬한 슬픔과 분노를 가져올 수 있다.","e":"큰 상처로 받아들이면 마음이 크게 아픈 것."},{"s":"두 번째 해석은 슬픔과 분노를 전혀 불러오지 않는다.","a":false,"why":"8문장: 두 번째 해석도 슬픔과 분노를 불러올 수 있지만 더 낮은 정도다.\n“전혀 없다”는 불일치.","e":"아픔이 줄어들 뿐, 완전히 사라지는 것은 아님."},{"s":"두 번째 해석은 희망, 강인함, 감사 같은 긍정적인 감정도 불러올 수 있다.","a":true,"why":"9문장: 희망, 강인함, 감사함 같은 긍정적인 감정도 가져올 수 있다.","e":"힘든 일 끝에 “그래도 고맙다”는 마음이 생기는 것."},{"s":"이 예시는 재평가가 장기적인 감정 반응만 바꿀 수 있음을 보여 준다.","a":false,"why":"10문장: 재평가가 단기적(short-term) 감정 반응을 강력하게 바꿀 수 있음을 보여 준다.\n“장기적으로만”은 불일치.","e":"당장 느끼는 기분이 먼저 바뀌는 것."},{"s":"재평가가 오랫동안 반복되면 단기적인 감정 결과가 쌓여 심리적 건강을 형성할 수 있다.","a":true,"why":"11문장: 오랫동안 반복되면 단기적 결과가 축적되어 심리적 건강을 형성할 수 있다.","e":"매일 조금씩 연습한 운동이 몸을 만드는 것."},{"s":"재평가는 회복 탄력성과 관계가 없다.","a":false,"why":"12문장: 재평가는 회복 탄력성의 열쇠가 될 수 있다.\n“관계 없다”는 불일치.","e":"넘어져도 일어서는 힘을 길러 주는 연습."}],"eob":[{"s":"Take, for example, someone who ( ______ ) going through a divorce.","ch":["is","are"],"a":0,"why":"선행사 someone은 단수(한 사람)라서 관계대명사 who 뒤 동사도 단수 is. 앞 명사 수에 맞춘다.","tr":"예를 들어, 이혼을 겪고 있는 누군가를 생각해 보자.","g":"관계대명사의 동사는 앞에 있는 명사(선행사)의 수에 맞춰요. someone은 한 사람이니 is예요.\n예) I know someone who is kind. (나는 친절한 사람을 알아.)"},{"s":"This is often an adverse event, and yet, it can ( ______ ) in different ways.","ch":["be construed","construe"],"a":0,"why":"주어 it(사건)은 해석을 ‘받는’ 쪽이라 수동태 can be construed. 뒤에 목적어가 없다는 점도 신호.","tr":"이것은 보통 부정적인 사건이지만, 그럼에도 불구하고 그것은 다른 방식들로 해석될 수 있다.","g":"조동사 뒤에 주어가 ‘~되다’라는 뜻이면 be + 과거분사 형태를 써요. 뒤에 목적어가 없으면 수동을 의심해요.\n예) The door can be opened. (문은 열릴 수 있어.)"},{"s":"One might view it as an overpowering loss ( ______ ) will mark one's family for life.","ch":["what","that"],"a":1,"why":"앞에 명사 loss가 있고 뒤에 주어 없는 동사 will mark가 이어진다. 선행사가 있으면 관계대명사 that, what은 선행사를 품고 있어 쓸 수 없다.","tr":"누군가는 그것을 자신의 가족에게 평생 흔적을 남길 강렬한 상실로 여길지도 모른다.","g":"앞에 꾸며 줄 명사가 있으면 that이나 which를 써요. what은 앞에 명사가 없을 때만 써요.\n예) This is the book that I like. (이게 내가 좋아하는 책이야.)"},{"s":"This example illustrates ( ______ ) reappraisal might powerfully transform short-term emotional responses.","ch":["what","how"],"a":1,"why":"뒤 문장이 주어(reappraisal), 동사, 목적어까지 완전하다. 완전한 절 앞에는 how, 빠진 요소가 있어야 what.","tr":"이 예시는 재평가가 어떻게 단기적인 감정적 반응들을 강력하게 변화시킬 수 있을지를 보여 준다.","g":"완전한 문장이 뒤따르면 how, 목적어나 주어가 빠져 있으면 what을 써요.\n예) I know how he solved it. (나는 그가 그것을 어떻게 풀었는지 알아.)"},{"s":"When ( ______ ) over time, these short-term emotional consequences of reappraisal might accumulate to shape people's psychological health.","ch":["repeated","repeating"],"a":0,"why":"consequences(결과들)는 ‘반복되는’ 대상이므로 수동 의미의 과거분사 repeated. 뒤에 목적어가 없는 것도 신호.","tr":"오랫동안 반복되면, 재평가의 이러한 단기적인 감정적 결과들이 축적되어 사람들의 심리적 건강을 형성할지도 모른다.","g":"분사구문에서 주어가 ‘~되는’ 관계면 과거분사, 스스로 ‘~하는’ 관계면 -ing를 써요.\n예) When asked, he said no. (질문을 받자 그는 아니라고 했어.)"}],"awk":[{"t":"This is often [[1|a pleasant]] event, and yet, it can be [[2|construed]] in different ways. One might view it as an [[3|overpowering]] loss that will [[4|mark]] one's family [[5|for life]].","a":1,"fix":"an adverse","why":"원문은 “an adverse event”(부정적인 사건). 이혼은 상실이고 평생 흔적을 남기는 일인데 즐거운(pleasant) 사건이라 하면 뒤의 loss와 모순.","sp":[{"b":"a pleasant","m":"즐거운","n":"a pleasant = 자음 소리로 시작해 a","y":"어색함. 원문은 an adverse. 이혼은 보통 부정적인 사건이라 즐겁다고 하면 loss(상실)와 맞지 않음.","e":"생일 파티를 “힘든 사건”이라 하면 어색한 것."},{"b":"construed","m":"해석되다","n":"can be + 과거분사 = 수동","y":"맞음. 같은 사건도 다르게 해석될 수 있다는 뜻.","e":"같은 점수를 다르게 받아들이는 것."},{"b":"overpowering","m":"압도적인","n":"형용사","y":"맞음. 너무 커서 견디기 힘든 상실.","e":"너무 큰 슬픔."},{"b":"mark","m":"흔적을 남기다","n":"will + 동사원형","y":"맞음. 가족에게 평생 흔적을 남긴다는 뜻.","e":"상처가 오래 남는 것."},{"b":"for life","m":"평생","n":"for life = 평생 동안","y":"맞음. 평생 남는다는 뜻.","e":"평생 간직하는 추억."}]},{"t":"The first construal may bring [[1|intense]] sadness and anger. The second construal might also bring sadness and anger but perhaps at [[2|higher]] levels. [[3|Crucially]], it might also bring some [[4|positive]] emotions, such as [[5|hope]], strength, or gratitude.","a":2,"fix":"lower","why":"원문은 “at lower levels”(더 낮은 정도). 첫 해석이 강렬한 슬픔인데 두 번째 해석이 더 높은 수준이라면, 뒤에 이어지는 긍정적 감정 이야기와 맞지 않음.","sp":[{"b":"intense","m":"강렬한","n":"형용사","y":"맞음. 첫 번째 해석은 강렬한 슬픔과 분노.","e":"아주 심한 통증."},{"b":"higher","m":"더 높은","n":"higher levels = 더 높은 수준","y":"어색함. 원문은 lower. 두 번째 해석은 감정이 더 약해지는 쪽이라 higher면 모순.","e":"상처를 덜 크게 받아들이면 아픔도 작아짐."},{"b":"Crucially","m":"결정적으로","n":"문장 전체를 꾸미는 부사","y":"맞음. 뒤의 긍정적 감정이 핵심이라는 신호.","e":"“이게 제일 중요해” 하는 말."},{"b":"positive","m":"긍정적인","n":"형용사","y":"맞음. 희망, 강인함, 감사 같은 감정.","e":"좋은 쪽의 마음."},{"b":"hope","m":"희망","n":"such as 뒤에 hope, strength, gratitude 병렬","y":"맞음. 긍정적 감정의 예.","e":"합격을 바라는 마음."}]},{"t":"This example illustrates how reappraisal might [[1|powerfully]] transform [[2|short-term]] emotional responses. When repeated over time, these short-term emotional consequences of reappraisal might [[3|disappear]] to shape people's [[4|psychological]] health. Thereby, reappraisal might be a key to [[5|resilience]].","a":3,"fix":"accumulate","why":"원문은 “accumulate to shape”(쌓여서 ~을 형성한다). disappear(사라지다)이면 건강을 ‘형성한다’는 흐름과 모순.","sp":[{"b":"powerfully","m":"강력하게","n":"부사","y":"맞음. 감정 반응을 강하게 바꾼다.","e":"강한 힘으로 방향을 바꾸는 것."},{"b":"short-term","m":"단기적인","n":"short-term = 단기의","y":"맞음. 처음에는 단기적인 감정 반응이 바뀐다.","e":"당장의 기분 변화."},{"b":"disappear","m":"사라지다","n":"to shape = ~하여 (결과)","y":"어색함. 원문은 accumulate. 사라지면 심리적 건강을 형성할 수 없음.","e":"저금이 사라지면 부자가 될 수 없는 것."},{"b":"psychological","m":"심리적인","n":"형용사","y":"맞음. 마음의 건강.","e":"마음의 건강."},{"b":"resilience","m":"회복 탄력성","n":"a key to + 명사","y":"맞음. 재평가가 회복력의 열쇠.","e":"넘어져도 다시 일어나는 힘."}]},{"t":"[[1|Alternatively]], one might see it as something that is [[2|painful]] but that might lead to [[3|negative]] outcomes in the long run, such as improved relationships. As a [[4|result]] of these [[5|different]] construals, one might feel different emotions.","a":3,"fix":"positive","why":"원문은 “positive outcomes … such as improved relationships”(개선된 관계 같은 긍정적 결과). negative(부정적인)라 하면 improved relationships(좋아진 관계)와 모순.","sp":[{"b":"Alternatively","m":"그 대신에","n":"문장 앞 연결 부사","y":"맞음. 앞의 해석과 다른 해석을 소개.","e":"“반대로 보면~” 하는 말."},{"b":"painful","m":"고통스러운","n":"but 앞뒤가 대조","y":"맞음. 아프지만 좋은 결과도 있다는 대조 구조.","e":"아프지만 효과 있는 주사."},{"b":"negative","m":"부정적인","n":"such as 뒤 예시와 일치해야 함","y":"어색함. 원문은 positive. 예시가 개선된 관계라서 부정적 결과와 모순.","e":"친해지는 일을 나쁜 결과라 하면 이상함."},{"b":"result","m":"결과","n":"as a result of = ~의 결과로","y":"맞음. 다른 해석의 결과로 다른 감정을 느낀다.","e":"원인과 결과의 결과."},{"b":"different","m":"서로 다른","n":"형용사","y":"맞음. 해석이 다르면 감정도 달라진다.","e":"다른 안경으로 보면 다르게 보이는 것."}]}],"und":[{"q":"<u>Reappraisal might present a particularly effective avenue to regulating emotions because it transforms emotions at their root.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["생긴 감정을 겉으로 드러내지 않게 눌러 주므로 조절하기 쉽다","감정이 생기는 근본 단계부터 바꿔 주므로 감정을 조절하는 데 특히 효과적일 수 있다","감정이 사라질 때까지 기다리는 것이 가장 효과적인 방법이다","다른 사람의 감정을 대신 바꿔 주기 때문에 효과적이다","감정의 뿌리를 건드리면 오히려 조절이 더 어려워진다"],"a":1,"why":"root(뿌리)는 감정이 생기는 가장 처음 단계를 뜻한다.\n처음 생각을 바꿔 감정 자체를 바꾸니 효과적이라는 설명.","e":"화분 잎을 닦는 것보다 뿌리 흙을 갈아 주는 것이 더 근본적인 것.","tr":"재평가, 즉 누군가가 감정적인 상황들에 대해 생각하는 방식을 바꾸는 것은 그것이 감정을 본질적으로 변화시키기 때문에 감정을 조절하는 데 특히 효과적인 방법을 제공할지도 모른다."},{"q":"<u>One might view it as an overpowering loss that will mark one's family for life.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["이혼을 가족에게 평생 큰 상처를 남길 감당하기 힘든 상실로 받아들일 수 있다","이혼을 가족이 금방 잊을 가벼운 일로 받아들일 수 있다","이혼을 가족에게 평생 자랑이 될 일로 받아들일 수 있다","이혼을 가족이 함께 극복해 가는 성장 기회로 받아들일 수 있다","이혼을 가족과 상관없는 개인의 선택으로만 받아들일 수 있다"],"a":0,"why":"overpowering loss = 압도적인 상실.\nmark one's family for life = 가족에게 평생 흔적을 남기다.\n이것이 첫 번째 해석이다.","e":"평생 지워지지 않는 큰 흉터처럼 받아들이는 것.","tr":"누군가는 그것을 자신의 가족에게 평생 흔적을 남길 강렬한 상실로 여길지도 모른다."},{"q":"<u>Crucially, it might also bring some positive emotions, such as hope, strength, or gratitude.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["두 번째 해석은 모든 부정적인 감정을 완전히 없애 준다","두 번째 해석은 슬픔뿐 아니라 희망 같은 긍정적인 감정도 함께 줄 수 있어서 그 점이 가장 중요하다","두 번째 해석은 희망을 가지면 안 된다고 알려 준다","두 번째 해석은 첫 번째 해석보다 감정을 더 크게 만든다","두 번째 해석은 감정이 아니라 행동만 바꾼다"],"a":1,"why":"also = 부정적인 감정에 더해 긍정적인 감정도 생긴다는 뜻.\nCrucially(결정적으로)는 이 점이 핵심이라는 신호.","e":"힘든 일을 겪고도 “그래도 힘이 생겼어” 하는 마음.","tr":"결정적으로 그것은 희망, 강인함 또는 감사함과 같은 어떤 긍정적인 감정들 또한 불러올지도 모른다."},{"q":"<u>Thereby, reappraisal might be a key to resilience.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["재평가를 하면 힘든 일이 아예 일어나지 않는다","재평가를 꾸준히 하면 힘든 일을 겪고도 다시 일어서는 힘을 기를 수 있다","재평가는 감정을 느끼지 못하게 만드는 방법이다","재평가는 타고난 성격이 있는 사람만 할 수 있다","재평가는 단기 반응에만 도움이 되고 건강과는 무관하다"],"a":1,"why":"key to resilience = 회복 탄력성의 열쇠.\nthereby(그렇게 함으로써)는 앞의 ‘쌓여서 건강을 만든다’는 내용의 결과.","e":"넘어져도 툭툭 털고 일어나는 힘이 길러지는 것.","tr":"그렇게 함으로써 재평가는 회복 탄력성의 해답이 될지도 모른다."}]},"2610-38":{"voc":[{"q":"Water quality is about following a certain set of <u>criteria</u>, or “benchmarks.”","ask":"criteria의 뜻으로 알맞은 것은?","ch":["위기","범죄","비율","증거","기준"],"a":4,"why":"criteria = 기준 (단수는 criterion).\ncrisis (위기), crime (범죄)와 모양이 비슷해서 조심.\n수질은 정해진 기준을 따르는 문제라는 뜻.","e":"시험에서 “70점 이상이면 합격”이라고 정해 둔 선.","tr":"수질은 특정한 기준들의 집합, 즉 ‘지표들’을 따르는 것에 관한 것이다.","alt":"standards, benchmarks, measures"},{"q":"These <u>guidelines</u> inform us exactly how much physical, chemical, or biological stuff can be in the water.","ask":"guidelines의 뜻으로 알맞은 것은?","ch":["위험","이익","지침","실험","증거"],"a":2,"why":"guideline = 지침, 따라야 할 방향이나 기준.\n물에 얼마나 들어 있어도 되는지 알려 주는 안내라는 뜻.","e":"학교 급식실에 붙은 “손을 씻고 줄 서기” 같은 안내.","tr":"이러한 지침들은 우리에게 정확히 얼마나 많은 물리적, 화학적, 혹은 생물학적인 것들이 물 안에 있을 수 있는지를 알려 준다.","alt":"instructions, rules, recommendations"},{"q":"These guidelines <u>inform</u> us exactly how much physical, chemical, or biological stuff can be in the water.","ask":"inform의 뜻으로 알맞은 것은?","ch":["의심하다","알려 주다","방해하다","제한하다","약속하다"],"a":1,"why":"inform = 알려 주다.\ninform A + how much … = A에게 얼마나 …인지 알려 주다.","e":"선생님이 “시험은 내일이야” 하고 알려 주는 것.","tr":"이러한 지침들은 우리에게 정확히 얼마나 많은 물리적, 화학적, 혹은 생물학적인 것들이 물 안에 있을 수 있는지를 알려 준다.","alt":"tell, notify, let know"},{"q":"These rules <u>ensure</u> the water is safe for anything we want to do with it.","ask":"ensure와 바꿔 쓸 수 있는 말은?","ch":["damage","delay","doubt","imagine","guarantee"],"a":4,"why":"ensure = 반드시 ~하도록 보장하다 (= guarantee).\n규칙이 물의 안전을 확실히 해 준다는 뜻.","e":"안전벨트가 사고에서 몸을 지켜 주는 것을 보장하는 것.","tr":"이러한 규칙들은 우리가 물로 하고 싶은 것이 집에서 물을 마시는 것이든, 농장에서 작물들에 물을 주는 것이든, 혹은 거대한 산업용 보일러를 통해 물을 흘려보내는 것이든 간에 그것에서 그 물이 안전하다고 보장한다.","alt":"guarantee, make sure, secure"},{"q":"These rules ensure the water is safe, whether that's drinking it at home, watering <u>crops</u> on a farm, or running it through a huge industrial boiler.","ask":"crops의 뜻으로 알맞은 것은?","ch":["가축","도구","폐기물","지도","농작물"],"a":4,"why":"crop = 농작물 (곡식, 채소 등).\n농장에서 작물에 물을 주는 경우라는 뜻.","e":"벼, 옥수수, 배추 같은 밭에서 기르는 것.","tr":"이러한 규칙들은 우리가 물로 하고 싶은 것이 집에서 물을 마시는 것이든, 농장에서 작물들에 물을 주는 것이든, 혹은 거대한 산업용 보일러를 통해 물을 흘려보내는 것이든 간에 그것에서 그 물이 안전하다고 보장한다.","alt":"harvest, plants"},{"q":"We can't <u>utilize</u> the same “one size fits all” rule for everyone.","ask":"utilize와 바꿔 쓸 수 있는 말은?","ch":["ignore","use","reduce","prove","avoid"],"a":1,"why":"utilize = 활용하다 (= use).\n모두에게 똑같은 하나의 규칙을 쓸 수는 없다는 뜻.","e":"도구를 쓸모 있게 이용하는 것.","tr":"우리가 물을 아주 많은 다양한 일에 사용하기 때문에 우리는 동일한 ‘일률적인’ 규칙을 모두에게 활용할 수 없다.","alt":"use, make use of, employ"},{"q":"We use water for so many <u>diverse</u> things.","ask":"diverse의 반의어로 알맞은 것은?","ch":["various","mixed","distinct","identical","separate"],"a":3,"why":"diverse = 다양한. 반의어는 identical (똑같은).\n물을 쓰는 일이 아주 다양하다는 뜻.","e":"똑같이 생긴 쌍둥이 우산이 identical한 것.","tr":"우리가 물을 아주 많은 다양한 일에 사용하기 때문에 우리는 동일한 ‘일률적인’ 규칙을 모두에게 활용할 수 없다.","alt":"various, varied ↔ identical, uniform"},{"q":"This is why groups set different “safety limits” for the water <u>dependent on</u> how it will be utilized.","ask":"dependent on의 뜻으로 알맞은 것은?","ch":["~와 무관한","~에 달려 있는, ~에 따라 달라지는","~에 반대하는","~을 대신하는","~에 놀란"],"a":1,"why":"dependent on = ~에 달려 있는, ~에 따라.\n물을 어떻게 쓰느냐에 따라 안전 허용치가 달라진다는 뜻.","e":"소풍을 가느냐는 날씨에 달려 있는 것.","tr":"이것이 물이 어떻게 활용될지에 따라 집단들이 그것에 대한 각기 다른 ‘안전 허용치’를 설정하는 이유이다.","alt":"depending on, based on"}],"find":[{"s":"물이 깨끗하다는 것은 단지 마실 물 한 잔처럼 보인다는 뜻만은 아니다.","a":true,"why":"1문장: ‘깨끗하다’는 말은 단지 마시는 물처럼 보인다는 것만을 뜻하지 않는다.","e":"눈으로 맑아 보여도 검사해 보면 아닐 수 있는 것."},{"s":"수질은 물이 겉으로 얼마나 맑아 보이는지로 정해진다.","a":false,"why":"2문장: 수질은 정해진 기준(benchmarks)을 따르는 것에 관한 것이다.\n겉모양만으로 정하는 것은 불일치.","e":"얼굴만 보고 건강을 판단하지 않고 검진 기준으로 보는 것."},{"s":"지침은 물속에 물리적, 화학적, 생물학적인 물질이 얼마나 있을 수 있는지 정확히 알려 준다.","a":true,"why":"3문장: 물리적, 화학적, 생물학적인 것이 물에 얼마나 있을 수 있는지 정확히 알려 준다.","e":"성분표에 적힌 허용 기준."},{"s":"이 규칙들은 물을 마시는 경우에만 안전을 보장한다.","a":false,"why":"4문장: 집에서 마시는 것뿐 아니라 농장에서 작물에 물 주기, 산업용 보일러에 흘려보내기에도 안전을 보장한다.\n“마시는 경우에만”은 불일치.","e":"마시는 물, 밭에 주는 물, 공장 물 모두 각각의 기준이 있음."},{"s":"물을 쓰는 일이 매우 다양해서 모두에게 똑같은 하나의 규칙을 쓸 수 없다.","a":true,"why":"5문장: 물을 매우 다양한 일에 쓰기 때문에 ‘일률적인’ 규칙을 모두에게 쓸 수 없다.","e":"운동화 한 치수로 모든 사람이 신을 수 없는 것."},{"s":"발전기를 식히는 물은 주방 수돗물보다 더 깨끗해야 한다.","a":false,"why":"6문장: 발전기를 식히는 물은 주방 수돗물만큼 깨끗할 필요가 없다.\n비교 방향이 반대라서 불일치.","e":"설거지물이 마시는 물만큼 깨끗할 필요는 없는 것."},{"s":"발전소 발전기를 식히는 물은 마시는 물만큼 깨끗할 필요가 없다.","a":true,"why":"6문장: 주방 수도꼭지의 물만큼 깨끗할 필요가 없다고 했다.","e":"용도에 따라 필요한 깨끗함이 다름."},{"s":"집단들은 물이 어떻게 활용될지에 따라 서로 다른 안전 허용치를 정한다.","a":true,"why":"7문장: 물이 활용되는 방식에 따라 각기 다른 ‘안전 허용치’를 설정한다.","e":"놀이터와 병원이 서로 다른 안전 규칙을 쓰는 것."},{"s":"모든 용도의 물에 하나의 기준을 적용하는 것이 가장 좋다고 한다.","a":false,"why":"5문장: 하나의 일률적인 규칙은 쓸 수 없다고 했다.\n“가장 좋다”는 불일치.","e":"한 가지 열쇠로 모든 문을 열 수는 없는 것."},{"s":"물의 안전 기준은 그 물을 어떤 용도로 쓸지를 고려해서 정해진다.","a":true,"why":"4문장과 7문장: 용도(마시기, 농사, 산업)에 맞게 안전을 보장하고, 용도에 따라 허용치를 달리한다.","e":"용도에 맞는 기준."}],"eob":[{"s":"Water quality is about ( ______ ) a certain set of criteria, or “benchmarks.”","ch":["to follow","following"],"a":1,"why":"전치사 about 뒤에는 동사가 직접 올 수 없고 동명사(-ing)가 와야 한다.","tr":"수질은 특정한 기준들의 집합, 즉 ‘지표들’을 따르는 것에 관한 것이다.","g":"전치사 뒤에는 동사원형이나 to부정사가 아니라 동명사(-ing)를 써요.\n예) He is good at swimming. (그는 수영을 잘해.)"},{"s":"These rules ensure the water is safe for anything we want to do with it, whether that's drinking it at home, ( ______ ) crops on a farm, or running it through a huge industrial boiler.","ch":["to water","watering"],"a":1,"why":"drinking, ( ), running이 or로 이어진 병렬 구조. 앞뒤가 모두 동명사이므로 watering.","tr":"이러한 규칙들은 우리가 물로 하고 싶은 것이 집에서 물을 마시는 것이든, 농장에서 작물들에 물을 주는 것이든, 혹은 거대한 산업용 보일러를 통해 물을 흘려보내는 것이든 간에 그것에서 그 물이 안전하다고 보장한다.","g":"and, or로 이어진 항목들은 같은 형태로 맞춰요. 앞뒤가 -ing면 가운데도 -ing예요.\n예) I like reading, singing, and dancing. (나는 읽기, 노래하기, 춤추기를 좋아해.)"},{"s":"We can't utilize the same “one size fits all” rule for everyone ( ______ ) we use water for so many diverse things.","ch":["because of","because"],"a":1,"why":"뒤에 주어(we)와 동사(use)가 있는 절이 이어지므로 접속사 because. because of 뒤에는 명사(구)가 온다.","tr":"우리가 물을 아주 많은 다양한 일에 사용하기 때문에 우리는 동일한 ‘일률적인’ 규칙을 모두에게 활용할 수 없다.","g":"because 뒤에는 문장(주어+동사), because of 뒤에는 명사(구)가 와요.\n예) I was late because it rained. (비가 와서 늦었어.)"},{"s":"The water that cools down a huge power plant generator doesn't need to be as clean ( ______ ) the water you drink from the kitchen tap.","ch":["than","as"],"a":1,"why":"원급 비교 as + 형용사 + as 구조. 앞의 as clean과 짝이 되는 것은 as.","tr":"예를 들어, 거대한 발전소의 발전기를 식히는 물은 여러분이 주방 수도꼭지로부터 마시는 물만큼 깨끗할 필요가 없다.","g":"“~만큼 …한”은 as ~ as로 써요. than은 비교급(-er, more)과 함께 써요.\n예) He is as tall as his dad. (그는 아빠만큼 키가 커.)"}],"awk":[{"t":"When we say that water is “clean,” we don't just mean that it [[1|looks]] like a glass of water. Water quality is about [[2|following]] a certain set of criteria, or “benchmarks.” These guidelines [[3|inform]] us [[4|vaguely]] how much physical, [[5|chemical]], or biological stuff can be in the water.","a":4,"fix":"exactly","why":"원문은 “inform us exactly how much”(정확히 얼마나). 기준과 지침은 정확한 양을 알려 주는 것인데 vaguely(대충)라 하면 모순.","sp":[{"b":"looks","m":"~처럼 보이다","n":"look like = ~처럼 보이다","y":"맞음. 마시는 물처럼 보이기만 하는 것은 아님.","e":"맑아 보이는 겉모습."},{"b":"following","m":"따르는 것","n":"about 뒤 동명사","y":"맞음. 기준을 따르는 것에 관한 이야기.","e":"교칙을 따르는 것."},{"b":"inform","m":"알려 주다","n":"inform A + 의문사절","y":"맞음. 허용량을 알려 주는 지침.","e":"안내문."},{"b":"vaguely","m":"대충, 모호하게","n":"부사","y":"어색함. 원문은 exactly. 지침은 정확한 양을 알려 주는 것이라 vaguely면 모순.","e":"“대충 이만큼”은 기준이 될 수 없음."},{"b":"chemical","m":"화학적인","n":"physical, chemical, or biological 병렬","y":"맞음. 물리적, 화학적, 생물학적 중 하나.","e":"물에 녹은 약품 성분."}]},{"t":"These rules [[1|ensure]] the water is [[2|safe]] for anything we want to do with it, whether that's drinking it at home, watering crops on a farm, or running it through a huge [[3|industrial]] boiler. We can't [[4|utilize]] the same “one size fits all” rule for everyone because we use water for so many [[5|similar]] things.","a":5,"fix":"diverse","why":"원문은 “so many diverse things”(매우 다양한 일). similar(비슷한)이면 하나의 같은 규칙을 못 쓴다는 이유가 되지 못해 모순.","sp":[{"b":"ensure","m":"보장하다","n":"뒤에 that절 생략","y":"맞음. 규칙이 안전을 보장한다.","e":"안전을 확실히 하는 것."},{"b":"safe","m":"안전한","n":"형용사","y":"맞음. 어떤 용도든 안전해야 한다.","e":"마셔도 탈 나지 않는 물."},{"b":"industrial","m":"산업용의","n":"형용사","y":"맞음. 거대한 산업용 보일러.","e":"공장에서 쓰는 큰 보일러."},{"b":"utilize","m":"활용하다","n":"can't + 동사원형","y":"맞음. 똑같은 규칙을 쓸 수 없다.","e":"도구를 이용하는 것."},{"b":"similar","m":"비슷한","n":"형용사","y":"어색함. 원문은 diverse. 용도가 비슷하면 하나의 규칙을 써도 되므로 문장 흐름과 모순.","e":"같은 일이라면 같은 규칙을 쓰면 됨."}]},{"t":"For instance, the water that cools down a huge power plant generator [[1|doesn't need]] to be as [[2|clean]] as the water you drink from the kitchen tap. This is why groups set [[3|identical]] “safety limits” for the water [[4|dependent]] on how it will be [[5|utilized]].","a":3,"fix":"different","why":"원문은 “set different safety limits”(서로 다른 안전 허용치). 앞에서 용도마다 깨끗함이 다르다고 했는데 identical(똑같은)이면 모순.","sp":[{"b":"doesn't need","m":"~할 필요가 없다","n":"need to + 동사원형","y":"맞음. 발전기용 물은 마시는 물만큼 깨끗할 필요가 없다.","e":"설거지물이 꼭 정수일 필요는 없음."},{"b":"clean","m":"깨끗한","n":"as clean as","y":"맞음. 마시는 물만큼 깨끗할 필요가 없다는 비교.","e":"맑은 물."},{"b":"identical","m":"똑같은","n":"형용사","y":"어색함. 원문은 different. 용도마다 기준이 다르다는 흐름이므로 identical이면 모순.","e":"교실과 운동장 규칙이 똑같을 수는 없음."},{"b":"dependent","m":"~에 달려 있는","n":"dependent on = ~에 달려 있는","y":"맞음. 어떻게 쓰이느냐에 달려 있다.","e":"날씨에 달린 소풍."},{"b":"utilized","m":"활용되는","n":"will be + 과거분사","y":"맞음. 물이 어떻게 활용될지.","e":"쓰이는 방식."}]}],"und":[{"q":"<u>When we say that water is “clean,” we don't just mean that it looks like a glass of water.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["물이 깨끗하다는 것은 눈에 맑아 보이는 것 이상의 기준을 갖춘 상태를 뜻한다","물이 깨끗하다는 것은 반드시 마시는 물처럼 투명해야 한다는 뜻이다","물이 깨끗한지는 눈으로 보고 판단하는 것이 가장 정확하다","물이 깨끗하다는 말은 아무 의미 없이 쓰이는 표현이다","물은 마시는 용도일 때에만 깨끗함이 중요하다"],"a":0,"why":"don't just mean = 단지 ~만을 뜻하지는 않는다.\n겉모습만이 아니라 정해진 기준을 따라야 한다는 뜻으로 이어진다.","e":"물이 맑아 보여도 검사를 통과해야 하는 것.","tr":"우리가 물이 ‘깨끗하다’라고 말할 때, 우리는 단지 그것이 마실 물 한 잔처럼 보인다는 것을 의미하지는 않는다."},{"q":"<u>We can't utilize the same “one size fits all” rule for everyone because we use water for so many diverse things.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["모든 사람이 같은 크기의 물만 사용할 수 있다","용도가 다양할수록 기준을 하나로 합치는 것이 쉽다","옷 크기처럼 물도 사람 몸에 맞게 나눠 써야 한다","물을 쓰는 용도가 너무 다양해서 모든 경우에 똑같은 하나의 기준을 적용할 수는 없다","다양한 용도 때문에 물 기준은 아예 필요 없다"],"a":3,"why":"one size fits all = 하나의 치수가 모두에게 맞는다는 뜻으로, ‘일률적인’이라는 의미.\n용도가 다양하다는 이유 때문에 쓸 수 없다는 흐름.","e":"발 크기가 다른 사람들에게 한 치수 신발만 주는 것이 어려운 것.","tr":"우리가 물을 아주 많은 다양한 일에 사용하기 때문에 우리는 동일한 ‘일률적인’ 규칙을 모두에게 활용할 수 없다."},{"q":"<u>The water that cools down a huge power plant generator doesn't need to be as clean as the water you drink from the kitchen tap.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["발전기 물은 마시는 물보다 더 깨끗해야 한다","발전소 물은 어떤 기준도 필요하지 않다","물이 쓰이는 용도에 따라 요구되는 깨끗함의 정도가 다르다","주방 수돗물은 가장 깨끗해야 한다는 규칙이 하나뿐이다","발전기를 식히는 물은 사람이 마셔도 안전해야 한다"],"a":2,"why":"as clean as = ~만큼 깨끗한.\n발전기용 물은 마시는 물만큼 깨끗하지 않아도 된다는 비교.\n그래서 용도마다 기준이 다르다는 결론으로 이어진다.","e":"화분에 주는 물과 마시는 물의 깨끗함 기준이 다른 것.","tr":"예를 들어, 거대한 발전소의 발전기를 식히는 물은 여러분이 주방 수도꼭지로부터 마시는 물만큼 깨끗할 필요가 없다."}]},"2610-39":{"voc":[{"q":"Like all historians, social historians draw from a variety of <u>primary sources</u>.","ask":"primary sources의 뜻으로 알맞은 것은?","ch":["후대 학자가 쓴 요약본","1차 자료(그 시대에 직접 만들어진 원자료)","번역된 교과서","잡지의 광고문","박물관 안내문"],"a":1,"why":"primary source = 1차 자료, 그 시대 사람이 직접 남긴 원자료(편지, 법 문서 등).\n역사학자는 이런 원자료를 바탕으로 연구한다는 뜻.","e":"일기장, 옛 편지처럼 그때 사람이 직접 쓴 글.","tr":"모든 역사학자들과 마찬가지로, 사회사학자들은 다양한 원자료들을 가져와 쓴다.","alt":"original sources, firsthand records"},{"q":"Social history often <u>emphasizes</u> ordinary people rather than elites.","ask":"emphasizes와 바꿔 쓸 수 있는 말은?","ch":["denies","avoids","replaces","forgets","stresses"],"a":4,"why":"emphasize = 강조하다 (= stress).\n사회사는 엘리트보다 평범한 사람들을 강조한다는 뜻.","e":"시험 전에 “이 부분이 중요해” 하고 강조하는 것.","tr":"사회사는 대개 엘리트들보다 평범한 사람들을 강조한다.","alt":"stress, highlight, underline"},{"q":"Social history often emphasizes ordinary people rather than <u>elites</u>.","ask":"elites와 대비되는 사람들을 가리키는 말은?","ch":["rulers","commoners","scholars","officials","owners"],"a":1,"why":"elite = 사회의 상류층, 지배층.\nordinary people = commoners(평범한 사람들)가 그 대비.\n사회사는 상류층보다 평범한 사람들을 다룬다는 뜻.","e":"반장, 회장 같은 높은 자리 사람과 일반 학생.","tr":"사회사는 대개 엘리트들보다 평범한 사람들을 강조한다.","alt":"the upper class, the ruling class ↔ commoners"},{"q":"Non-elites <u>lacked</u> access to education.","ask":"lacked의 뜻으로 알맞은 것은?","ch":["~을 누렸다","~이 부족했다","~을 요구했다","~을 거부했다","~을 제공했다"],"a":1,"why":"lack = ~이 부족하다, 없다.\n비엘리트는 교육에 접근할 기회가 부족했다는 뜻.","e":"필통에 연필이 없는 상태.","tr":"하지만, 대부분의 지역들과 시대들에서, 엘리트가 아닌 사람들은 교육에 대한 접근 기회가 부족했고, 따라서, 풍부한 양의 문서로 된 기록을 생산하지 못했다.","alt":"be short of, be without"},{"q":"Non-elites did not produce <u>substantial</u> amounts of documentation.","ask":"substantial과 가까운 뜻은?","ch":["considerable","tiny","accidental","expensive","official"],"a":0,"why":"substantial = 상당한, 꽤 많은 (= considerable).\n문서를 많이 남기지 못했다는 뜻.","e":"한 권 가득 채울 정도로 많은 양.","tr":"하지만, 대부분의 지역들과 시대들에서, 엘리트가 아닌 사람들은 교육에 대한 접근 기회가 부족했고, 따라서, 풍부한 양의 문서로 된 기록을 생산하지 못했다.","alt":"considerable, large, significant"},{"q":"These materials rarely ended up in <u>archives</u> where they could be preserved.","ask":"archives의 뜻으로 알맞은 것은?","ch":["운동장","병원","시장","기록 보관소","공장"],"a":3,"why":"archive = 기록 보관소, 오래된 문서를 보관하는 곳.\n문서가 보관소까지 가지 못했다는 뜻.","e":"옛 서류를 차곡차곡 모아 두는 창고.","tr":"심지어 그들이 문서로 된 기록을 정말로 생산했을 때조차도, 이러한 자료들은 그것들이 보존될 수 있고 연구자들에게 이용 가능해질 수 있는 기록 보관소들에 거의 다다르지 못했다.","alt":"records office, repository"},{"q":"Because of such <u>biases</u> in the historical record, social historians have to be very creative.","ask":"biases의 뜻으로 알맞은 것은?","ch":["편향, 치우침","증거","변화","확대","공감"],"a":0,"why":"bias = 편향, 한쪽으로 치우침.\n기록이 엘리트 쪽으로만 남은 것이 바로 편향.","e":"한쪽 팀 이야기만 듣고 판단하는 것.","tr":"역사적 기록에서의 그러한 편향들 때문에, 사회사학자들은 자신들의 작업에 있어서 매우 창의적이어야 한다.","alt":"prejudice, one-sidedness"},{"q":"Rather than simply take such sources at <u>face value</u>, they read them “against the grain.”","ask":"at face value의 뜻으로 알맞은 것은?","ch":["높은 가격에","반값에","액면 그대로, 겉으로 보이는 대로","의심하면서","눈앞에서"],"a":2,"why":"at face value = 액면 그대로, 겉으로 드러난 그대로.\n사회사학자는 자료를 그대로 믿지 않고 꼼꼼히 다르게 읽는다는 뜻.","e":"돈에 적힌 금액을 그대로 믿듯, 말을 있는 그대로 받아들이는 것.","tr":"하지만 그러한 자료들을 단순히 액면 그대로 받아들이기보다 그들은 그것들을 ‘일반적인 방식과 다르게’ 해석한다.","alt":"literally, as it appears"}],"find":[{"s":"사회사학자들도 모든 역사학자처럼 다양한 1차 자료를 활용한다.","a":true,"why":"1문장: 모든 역사학자처럼 사회사학자들도 다양한 원자료(primary sources)를 활용한다.","e":"여러 종류의 옛 기록을 모으는 것."},{"s":"사회사는 평범한 사람들보다 엘리트를 더 강조한다.","a":false,"why":"2문장: 사회사는 엘리트보다 평범한 사람들을 강조한다.\n비교 대상이 거꾸로.","e":"반장보다 평범한 학생들의 이야기를 중요하게 보는 것."},{"s":"대부분의 지역과 시대에서 비엘리트는 교육 기회가 부족해 문서 기록을 많이 남기지 못했다.","a":true,"why":"3문장: 교육 접근이 부족해서 많은 양의 문서 기록을 만들지 못했다.","e":"글을 배우지 못하면 기록을 남기기 어려운 것."},{"s":"비엘리트가 남긴 문서는 대부분 기록 보관소에 잘 보존되어 연구자들이 쉽게 이용할 수 있었다.","a":false,"why":"4문장: 문서를 만들었어도 기록 보관소에 거의 도달하지 못했다.\n“쉽게 이용”은 불일치.","e":"쓴 일기가 도서관에 가지 못하고 사라진 것."},{"s":"역사적 기록의 편향 때문에 사회사학자들은 작업에서 매우 창의적이어야 한다.","a":true,"why":"5문장: 역사적 기록의 편향 때문에 매우 창의적이어야 한다.","e":"빠진 퍼즐 조각을 상상으로 맞추는 것."},{"s":"사회사학자들은 정부 관료나 고용주가 만든 텍스트 자료는 분석하지 않는다.","a":false,"why":"6문장: 다른 역사학자처럼 정부 관료, 고용주, 엘리트가 만든 텍스트 자료를 분석한다.\n“분석하지 않는다”는 불일치.","e":"엘리트의 기록도 읽기는 읽음."},{"s":"사회사학자들은 자료를 단순히 액면 그대로 받아들이기보다 ‘일반적인 방식과 다르게’ 읽는다.","a":true,"why":"7문장: 자료를 액면 그대로 받아들이기보다 against the grain(일반적인 방식과 다르게)으로 읽는다.","e":"말 속에 숨은 뜻을 찾아 읽는 것."},{"s":"사회사학자는 법적 문서에서 노예 소유주가 제공한 사실만 읽는다.","a":false,"why":"8문장: 사실뿐 아니라 침묵, 단절, 소문 같은 세부 사항도 조사한다.\n“사실만”은 불일치.","e":"정답만 보지 않고 풀이 과정도 살피는 것."},{"s":"사회사학자는 법적 문서의 공백이나 소문 같은 세부 사항에서 노예가 된 사람들의 태도와 행동에 대한 힌트를 찾는다.","a":true,"why":"8문장: 침묵, 단절, 소문 같은 세부 사항이 노예가 된 사람들의 태도와 행동에 대한 힌트를 준다.","e":"빈칸이나 흔적에서도 단서를 찾는 것."},{"s":"비엘리트가 남긴 기록이 풍부하기 때문에 사회사학자는 창의적일 필요가 없다.","a":false,"why":"3~5문장: 기록이 부족하고 치우쳐 있어서 창의적이어야 한다.\n“풍부하다”는 불일치.","e":"자료가 없으니 머리를 더 써야 하는 것."}],"eob":[{"s":"Like all historians, social historians draw from a variety ( ______ ) primary sources.","ch":["for","of"],"a":1,"why":"“a variety of + 복수명사”는 ‘다양한 ~’이라는 정해진 표현이다.","tr":"모든 역사학자들과 마찬가지로, 사회사학자들은 다양한 원자료들을 가져와 쓴다.","g":"a variety of ~ = 다양한 ~. 뒤에는 복수명사가 와요.\n예) a variety of foods (다양한 음식들)"},{"s":"Non-elites lacked access to education and, thus, ( ______ ) not produce substantial amounts of documentation.","ch":["were","did"],"a":1,"why":"뒤에 일반동사 produce가 있으므로 부정문은 did not. were not 뒤에는 동사원형이 올 수 없다.","tr":"하지만, 대부분의 지역들과 시대들에서, 엘리트가 아닌 사람들은 교육에 대한 접근 기회가 부족했고, 따라서, 풍부한 양의 문서로 된 기록을 생산하지 못했다.","g":"일반동사 부정문은 do/does/did + not + 동사원형이에요. be동사 부정문은 be + not + 형용사·명사예요.\n예) She did not go. (그녀는 가지 않았어.)"},{"s":"Even when they did produce documentation, these materials rarely ended up in archives ( ______ ) they could be preserved and made available to researchers.","ch":["which","where"],"a":1,"why":"뒤 문장 they could be preserved는 완전한 절이다. 장소 선행사 archives 뒤에 완전한 절이 오므로 관계부사 where.","tr":"심지어 그들이 문서로 된 기록을 정말로 생산했을 때조차도, 이러한 자료들은 그것들이 보존될 수 있고 연구자들에게 이용 가능해질 수 있는 기록 보관소들에 거의 다다르지 못했다.","g":"선행사가 장소이고 뒤가 완전한 문장이면 where를 써요. which 뒤에는 주어나 목적어가 빠진 문장이 와요.\n예) This is the park where we played. (여기가 우리가 놀던 공원이야.)"},{"s":"( ______ ) such biases in the historical record, social historians have to be very creative in their work.","ch":["Because of","Because"],"a":0,"why":"뒤에 such biases라는 명사구만 있고 주어+동사가 없다. 명사(구) 앞에는 because of.","tr":"역사적 기록에서의 그러한 편향들 때문에, 사회사학자들은 자신들의 작업에 있어서 매우 창의적이어야 한다.","g":"because 뒤에는 문장(주어+동사), because of 뒤에는 명사(구)가 와요.\n예) Because of the rain, we stayed home. (비 때문에 우리는 집에 있었어.)"},{"s":"She will also examine the silences, interruptions, rumors, and other details that ( ______ ) hints about the enslaved peoples' attitudes and actions.","ch":["offer","offers"],"a":0,"why":"관계대명사 that의 선행사는 복수 details이므로 동사도 복수 offer.","tr":"그래서, 예를 들어, 어떤 사회사학자는 법적 문서들을 노예 소유주들에 의해 제공된 ‘사실들’을 얻기 위해 읽을 뿐만 아니라, 그녀는 또한 노예가 된 사람들의 태도들과 행동들에 대한 힌트들을 제공하는 공백들, 단절들, 소문들, 그리고 다른 세부 사항들을 조사할 것이다.","g":"관계대명사 뒤 동사는 선행사의 수에 맞춰요. 선행사가 복수면 -s를 붙이지 않아요.\n예) the books that help me (나를 돕는 책들)"}],"awk":[{"t":"Social history often [[1|emphasizes]] ordinary people rather than [[2|elites]]. Yet, in most places and times, non-elites [[3|enjoyed]] access to education and, thus, did not [[4|produce]] [[5|substantial]] amounts of documentation.","a":3,"fix":"lacked","why":"원문은 “lacked access to education”(교육 기회가 부족했다). enjoyed(누렸다)이면 교육을 받았는데 기록을 못 남겼다는 말이 되어 thus(따라서)의 인과와 모순.","sp":[{"b":"emphasizes","m":"강조하다","n":"3인칭 단수 -s","y":"맞음. 사회사는 평범한 사람들을 강조한다.","e":"중요한 부분에 형광펜 칠하기."},{"b":"elites","m":"엘리트","n":"복수명사","y":"맞음. 평범한 사람들과 대비되는 상류층.","e":"높은 자리의 사람들."},{"b":"enjoyed","m":"누렸다","n":"enjoy + 목적어","y":"어색함. 원문은 lacked. 교육 기회를 누렸다면 기록을 못 남긴 이유(thus)와 모순.","e":"교육을 받았다면 기록을 남길 수 있었을 것."},{"b":"produce","m":"만들어 내다","n":"did not + 동사원형","y":"맞음. 문서를 만들지 못했다.","e":"기록을 남기는 것."},{"b":"substantial","m":"상당한","n":"형용사","y":"맞음. 상당한 양의 문서.","e":"두꺼운 기록 묶음."}]},{"t":"Even when they did produce documentation, these materials [[1|often]] ended up in archives where they could be [[2|preserved]] and made available to researchers. Because of such [[3|biases]] in the historical record, social historians have to be very [[4|creative]] in their [[5|work]].","a":1,"fix":"rarely","why":"원문은 “rarely ended up in archives”(거의 보관소에 가지 못했다). often이면 기록이 잘 보존되었다는 말인데 뒤의 ‘편향 때문에 창의적이어야 한다’와 모순.","sp":[{"b":"often","m":"자주","n":"빈도부사","y":"어색함. 원문은 rarely. 자주 보관소에 간다면 기록이 충분해 창의적일 이유가 없음.","e":"기록이 많이 남았다면 고민이 줄어듦."},{"b":"preserved","m":"보존되다","n":"could be + 과거분사","y":"맞음. 보존될 수 있는 곳.","e":"오래 보관되는 것."},{"b":"biases","m":"편향","n":"복수명사","y":"맞음. 기록이 치우쳐 있다는 뜻.","e":"한쪽 이야기만 남은 상태."},{"b":"creative","m":"창의적인","n":"be creative","y":"맞음. 부족한 기록을 창의적으로 보완해야 함.","e":"문제를 새롭게 푸는 것."},{"b":"work","m":"작업, 연구","n":"in their work","y":"맞음. 사회사학자의 연구 작업.","e":"하는 일."}]},{"t":"Like other historians, social historians [[1|ignore]] textual sources produced by government officials, employers, and other [[2|elites]]. [[3|Yet]] rather than simply take such sources at [[4|face]] value, they read them “against the [[5|grain]]”.","a":1,"fix":"analyze","why":"원문은 “social historians analyze textual sources”(분석한다). ignore(무시한다)이면 뒤의 Yet 이하에서 그 자료들을 다르게 ‘읽는다’는 내용과 모순.","sp":[{"b":"ignore","m":"무시하다","n":"현재형 복수 주어","y":"어색함. 원문은 analyze. 자료를 무시하면서 그것을 다르게 읽는다는 말은 모순.","e":"읽지도 않고 다르게 읽을 수는 없음."},{"b":"elites","m":"엘리트","n":"복수명사","y":"맞음. 정부 관료, 고용주 같은 상류층.","e":"높은 자리의 사람들."},{"b":"Yet","m":"하지만","n":"문장 앞 연결 부사","y":"맞음. 앞 문장과 대조를 이끈다.","e":"“그런데”로 방향을 바꾸는 말."},{"b":"face","m":"겉모습, 액면","n":"at face value","y":"맞음. 액면 그대로라는 표현.","e":"표면에 적힌 값."},{"b":"grain","m":"결","n":"against the grain = 일반적인 방식과 다르게","y":"맞음. 관용 표현.","e":"나뭇결을 거슬러 자르는 것."}]},{"t":"So, for example, a social historian will read legal documents [[1|not only]] for the “facts” provided by slaveowners; she will also [[2|overlook]] the silences, interruptions, rumors, and other details that [[3|offer]] hints about the enslaved peoples' [[4|attitudes]] and [[5|actions]].","a":2,"fix":"examine","why":"원문은 “she will also examine the silences…”(공백, 소문 등을 조사한다). overlook(간과하다)이면 뒤의 ‘힌트를 준다’는 이유와 모순.","sp":[{"b":"not only","m":"~뿐만 아니라","n":"not only A but (also) B","y":"맞음. 사실뿐 아니라 세부 사항도 본다는 구조.","e":"A만이 아니라 B도 라는 말."},{"b":"overlook","m":"간과하다","n":"not only A but also B 구조","y":"어색함. 원문은 examine. 힌트를 주는 세부 사항을 놓친다면 not only 뒤의 also 내용과 모순.","e":"중요한 단서를 지나치는 것."},{"b":"offer","m":"제공하다","n":"that 뒤 복수 동사","y":"맞음. 세부 사항이 힌트를 제공.","e":"단서를 건네 주는 것."},{"b":"attitudes","m":"태도","n":"복수명사","y":"맞음. 노예가 된 사람들의 태도.","e":"마음가짐."},{"b":"actions","m":"행동","n":"복수명사","y":"맞음. 그들의 행동.","e":"한 일."}]}],"und":[{"q":"<u>Yet rather than simply take such sources at face value, they read them “against the grain.”</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["자료를 읽지 않고 요약본만 확인한다","자료의 가격을 따져서 가장 비싼 것만 쓴다","자료를 쓰인 그대로 믿지 않고 일반적인 읽기와 다르게 숨은 면까지 살펴본다","자료에 적힌 내용을 그대로 외워 쓴다","자료를 나뭇결 모양대로 정리해 보관한다"],"a":2,"why":"take at face value = 액면 그대로 받아들이다.\nagainst the grain = 일반적인 방식과 다르게.\n엘리트가 쓴 자료도 그대로 믿지 않고 비판적으로 본다는 뜻.","e":"시험 해설을 그대로 믿지 않고 “정말 그럴까?” 하고 다시 확인하는 것.","tr":"하지만 그러한 자료들을 단순히 액면 그대로 받아들이기보다 그들은 그것들을 ‘일반적인 방식과 다르게’ 해석한다."},{"q":"<u>Because of such biases in the historical record, social historians have to be very creative in their work.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["기록이 너무 많아서 무엇을 쓸지 고르기가 어렵다","기록이 정확해서 새로운 방법이 필요 없다","기록이 한쪽으로 치우쳐 있어서 자료를 찾고 해석하는 방법을 궁리해야 한다","기록 보관소를 직접 지어야 한다","기록이 없는 시대는 연구할 수 없다"],"a":2,"why":"biases = 편향, 치우침.\n엘리트 기록 위주로 남아 있어 평범한 사람들의 자료가 부족하니 창의적인 접근이 필요하다는 뜻.","e":"한쪽만 남은 사진첩에서 없는 장면을 상상해 채우는 것.","tr":"역사적 기록에서의 그러한 편향들 때문에, 사회사학자들은 자신들의 작업에 있어서 매우 창의적이어야 한다."},{"q":"<u>She will also examine the silences, interruptions, rumors, and other details that offer hints about the enslaved peoples' attitudes and actions.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["문서에 적힌 소문은 모두 사실로 받아들인다","노예 소유주의 주장만 믿고 내용을 정리한다","문서에 직접 적힌 사실뿐 아니라 빠진 부분이나 소문 같은 단서에서도 노예가 된 사람들의 태도를 읽어 낸다","문서에 쓰인 사실을 외우는 것으로 충분하다","빈 곳은 잘못된 부분이므로 모두 지운다"],"a":2,"why":"not only A but also B 구조.\n공백, 단절, 소문도 숨은 단서가 된다는 뜻.\n그래서 문서 밖에서도 사람들의 태도를 읽을 수 있다.","e":"친구가 말을 줄인 이유까지 생각해 보는 것.","tr":"그래서, 예를 들어, 어떤 사회사학자는 법적 문서들을 노예 소유주들에 의해 제공된 ‘사실들’을 얻기 위해 읽을 뿐만 아니라, 그녀는 또한 노예가 된 사람들의 태도들과 행동들에 대한 힌트들을 제공하는 공백들, 단절들, 소문들, 그리고 다른 세부 사항들을 조사할 것이다."}]},"2610-40":{"voc":[{"q":"Dolphins' brains have evolved specialized areas dedicated to <u>echolocation</u>.","ask":"echolocation의 뜻으로 알맞은 것은?","ch":["광합성","반향 정위(소리가 반사되어 돌아오는 것으로 위치를 알아내는 능력)","겨울잠","번식","물질대사"],"a":1,"why":"echolocation = 반향 정위.\n소리를 내서 돌아오는 반사음으로 위치와 거리를 알아내는 능력.\n돌고래의 뇌는 이를 위해 특화되었다는 뜻.","e":"산에서 “야호” 하고 외쳐서 메아리로 거리를 짐작하는 것.","tr":"돌고래들의 뇌는 반향 정위에 사용되는 특화된 구역들을 진화시켰고, 그것은 그것들이 음향 정보를 더 빠르게 그리고 더 적은 에너지로 처리하게 해 준다.","alt":"locating objects by echoes"},{"q":"Dolphins can process <u>acoustic</u> information more quickly and with less energy.","ask":"acoustic의 뜻으로 알맞은 것은?","ch":["시각의","화학적인","후각의","음향의, 소리와 관련된","촉각의"],"a":3,"why":"acoustic = 음향의, 소리와 관련된.\nacoustic information = 소리 정보.\n돌고래는 소리 정보를 빠르게 처리한다는 뜻.","e":"콘서트홀의 소리 울림을 말할 때 쓰는 말.","tr":"돌고래들의 뇌는 반향 정위에 사용되는 특화된 구역들을 진화시켰고, 그것은 그것들이 음향 정보를 더 빠르게 그리고 더 적은 에너지로 처리하게 해 준다.","alt":"sound-related, auditory"},{"q":"Dolphins' brains have evolved <u>specialized</u> areas dedicated to echolocation.","ask":"specialized의 뜻으로 알맞은 것은?","ch":["특화된, 한 가지 일에 전문화된","일반적인","사라진","오래된","서로 비슷한"],"a":0,"why":"specialized = 특화된, 한 가지 기능에 맞게 전문화된.\n반의어는 general (일반적인).\n돌고래의 뇌에는 반향 정위에 특화된 구역이 있다는 뜻.","e":"수학만 가르치는 수학 전문 선생님처럼.","tr":"돌고래들의 뇌는 반향 정위에 사용되는 특화된 구역들을 진화시켰고, 그것은 그것들이 음향 정보를 더 빠르게 그리고 더 적은 에너지로 처리하게 해 준다.","alt":"particular, expert ↔ general"},{"q":"One key adaptation is the structure of the dolphin's auditory <u>pathway</u>.","ask":"pathway의 뜻으로 알맞은 것은?","ch":["장벽","경로, 길","증상","소음","경계"],"a":1,"why":"pathway = 길, 경로.\n귀에서 뇌까지 신호가 지나가는 길이라는 뜻.","e":"학교에서 교실까지 가는 복도.","tr":"한 가지 핵심적인 적응 구조는 돌고래의 청각 경로의 구조이다.","alt":"route, track, path"},{"q":"The auditory cortex is the brain region <u>responsible for</u> processing sound.","ask":"responsible for의 뜻으로 알맞은 것은?","ch":["~에 반대하는","~을 담당하는","~을 두려워하는","~에서 제외된","~을 놀라워하는"],"a":1,"why":"responsible for = ~을 담당하는, ~에 책임이 있는.\n소리를 처리하는 일을 맡은 뇌 영역이라는 뜻.","e":"청소 당번이 교실 청소를 맡는 것.","tr":"귀로부터의 신호들은 소리를 처리하는 것을 담당하는 뇌 영역인 청각 피질로 빠르게 전달된다.","alt":"in charge of, accountable for"},{"q":"Dolphins have a highly specialized auditory cortex with <u>distinct</u> areas dedicated to processing different aspects of echolocation signals.","ask":"distinct와 가까운 뜻은?","ch":["separate","similar","hidden","damaged","ordinary"],"a":0,"why":"distinct = 뚜렷이 구별되는, 서로 다른 (= separate).\n신호의 각 측면을 따로 처리하는 구역이 구별되어 있다는 뜻.","e":"서로 다른 색의 칸으로 나뉜 약통.","tr":"그러나, 많은 다른 포유류들과 달리, 돌고래는 반향 정위 신호들의 서로 다른 측면들을 처리하는 것에 사용되는 개별 구역들을 가진 고도로 특화된 청각 피질을 가지고 있다.","alt":"separate, different, individual"},{"q":"Some areas may be responsible for analyzing the timing of <u>echoes</u>.","ask":"echoes의 뜻으로 알맞은 것은?","ch":["속삭임","박수 소리","진동","반사음, 메아리","파도"],"a":3,"why":"echo = 메아리, 반사되어 돌아온 소리.\n반향 정위에서 돌아오는 소리의 타이밍을 분석하는 구역이 있다는 뜻.","e":"동굴에서 외친 소리가 돌아오는 것.","tr":"어떤 구역들은 반사파들의 타이밍을 분석하는 것을 담당할지도 모르지만 한편으로는 다른 구역들은 소리의 주파수 성분 또는 강도에 초점을 맞춘다.","alt":"reflected sounds, reverberations"},{"q":"This specialization allows the dolphin's brain to process echo information in parallel, rather than <u>sequentially</u>.","ask":"sequentially의 반의어로 알맞은 것은?","ch":["gradually","slowly","simultaneously","separately","exactly"],"a":2,"why":"sequentially = 차례대로, 순차적으로. 반의어는 simultaneously (동시에).\n병렬로 동시에 처리하는 것이 핵심이라는 뜻.","e":"한 줄로 하나씩 입장하는 것(순차)과 문이 여러 개라 한꺼번에 입장하는 것(동시).","tr":"이러한 특화는 돌고래의 뇌가 반사파 정보를 순차적이기보다 병렬로 처리하게 해 준다.","alt":"one after another ↔ at the same time"},{"q":"This parallel processing reduces the <u>cognitive</u> load associated with echolocation.","ask":"cognitive의 뜻으로 알맞은 것은?","ch":["신체적인","감정적인","경제적인","인지의, 생각하고 이해하는 것과 관련된","문화적인"],"a":3,"why":"cognitive = 인지의, 생각하고 이해하는 능력과 관련된.\ncognitive load = 뇌가 한 번에 처리해야 하는 부담.\n병렬 처리가 이 부담을 줄인다는 뜻.","e":"한꺼번에 많은 문제를 풀 때 머리가 무거워지는 느낌.","tr":"이러한 병렬 처리는 반향 정위와 연관된 인지 부하를 줄이고, 돌고래들이 자신의 환경에서의 변화들에 빠르게 반응하게 해 준다.","alt":"mental, thinking-related"}],"find":[{"s":"돌고래의 뇌는 반향 정위에 사용되는 특화된 구역을 진화시켜, 음향 정보를 더 빠르고 더 적은 에너지로 처리한다.","a":true,"why":"1문장: 특화된 구역 덕분에 음향 정보를 더 빠르게, 더 적은 에너지로 처리한다.","e":"전용 도구로 일하면 빠르고 힘이 덜 드는 것."},{"s":"돌고래의 청각 경로의 구조는 핵심적인 적응 중 하나가 아니다.","a":false,"why":"2문장: 돌고래의 청각 경로의 구조가 핵심 적응 중 하나다.\n“아니다”는 불일치.","e":"중요한 길이 바로 이 구조."},{"s":"귀에서 온 신호는 소리를 처리하는 뇌 영역인 청각 피질로 빠르게 전달된다.","a":true,"why":"3문장: 귀의 신호가 청각 피질로 빠르게 전달된다.","e":"귀에서 뇌의 소리 담당 구역으로 가는 길."},{"s":"돌고래의 청각 피질은 많은 다른 포유류와 마찬가지로 구역이 따로 나뉘어 있지 않다.","a":false,"why":"4문장: 많은 다른 포유류와 달리(unlike) 돌고래는 개별 구역을 가진 고도로 특화된 청각 피질을 가진다.\n“마찬가지”는 불일치.","e":"다른 동물은 한 방, 돌고래는 칸이 나뉜 방."},{"s":"돌고래의 어떤 구역은 반사파의 타이밍을 분석하고, 다른 구역은 소리의 주파수 성분이나 강도에 초점을 맞춘다.","a":true,"why":"5문장: 어떤 구역은 타이밍, 다른 구역은 주파수 성분이나 강도에 초점을 맞춘다.","e":"한 팀은 속도, 한 팀은 높낮이를 담당."},{"s":"이러한 특화 덕분에 돌고래의 뇌는 반사파 정보를 순차적으로 처리한다.","a":false,"why":"6문장: 특화 덕분에 병렬로(in parallel) 처리하며 순차적(sequentially)이 아니다.\n“순차적”은 불일치.","e":"한 줄로 서지 않고 여러 줄로 동시에 처리."},{"s":"글에서는 병렬 처리를 설명하기 위해 서로 다른 노동자가 서로 다른 일을 맡는 공장 조립 라인을 예로 든다.","a":true,"why":"7문장: 공장 조립 라인에서 서로 다른 노동자가 서로 다른 일을 맡는 것을 상상해 보라고 한다.","e":"한 사람은 조립, 한 사람은 포장."},{"s":"업무를 특화된 구역들에 나누면 뇌의 정보 처리 속도가 느려진다.","a":false,"why":"8문장: 업무를 나누면 정보를 훨씬 더 빠르고 효율적으로 처리할 수 있다.\n“느려진다”는 불일치.","e":"분업하면 속도가 빨라짐."},{"s":"병렬 처리는 반향 정위와 관련된 인지 부하를 줄여, 환경 변화에 빠르게 반응하게 한다.","a":true,"why":"9문장: 인지 부하를 줄이고 환경 변화에 빠르게 반응할 수 있게 한다.","e":"머리가 덜 복잡하면 빨리 움직일 수 있는 것."},{"s":"돌고래의 청각 피질에서는 한 구역이 반사파의 모든 측면을 혼자 담당한다.","a":false,"why":"4~5문장: 서로 다른 구역이 반향 정위 신호의 서로 다른 측면을 맡는다.\n“혼자 모두”는 불일치.","e":"한 사람이 모든 일을 다 하는 것이 아니라 나눠 맡음."},{"s":"돌고래의 청각 피질은 반향 정위 신호의 서로 다른 측면을 개별 구역에서 동시에 처리한다.","a":true,"why":"4문장과 6문장: 개별 구역이 서로 다른 측면을 맡고, 정보를 병렬(동시에)로 처리한다.","e":"각자 맡은 부분을 동시에 처리."},{"s":"병렬 처리는 인지 부하를 늘리지만 처리 속도는 빨라지게 한다.","a":false,"why":"9문장: 병렬 처리는 인지 부하를 줄인다.\n“늘린다”는 불일치.","e":"나누면 부담이 줄어듦."}],"eob":[{"s":"Dolphins' brains have evolved specialized areas dedicated to echolocation, ( ______ ) them to process acoustic information more quickly and with less energy.","ch":["allowed","allowing"],"a":1,"why":"앞 문장 전체를 받아 ‘~하게 해 주면서’라는 결과를 덧붙이는 분사구문이므로 allowing. 이미 앞에 동사(have evolved)가 있어 allowed를 동사로 쓸 수 없다.","tr":"돌고래들의 뇌는 반향 정위에 사용되는 특화된 구역들을 진화시켰고, 그것은 그것들이 음향 정보를 더 빠르게 그리고 더 적은 에너지로 처리하게 해 준다.","g":"한 문장에 동사가 이미 있으면, 덧붙이는 설명은 -ing(현재분사) 분사구문으로 써요.\n예) He left the room, closing the door. (그는 문을 닫으며 방을 나갔어.)"},{"s":"The signals from the ears ( ______ ) rapidly transmitted to the auditory cortex.","ch":["is","are"],"a":1,"why":"주어 signals는 복수이고 ‘전달된다’는 수동이므로 are transmitted. from the ears는 수식어구.","tr":"귀로부터의 신호들은 소리를 처리하는 것을 담당하는 뇌 영역인 청각 피질로 빠르게 전달된다.","g":"주어 뒤에 전치사구가 와도 동사는 진짜 주어(signals)에 맞춰요. 복수면 are예요.\n예) The books on the desk are mine. (책상 위의 책들은 내 거야.)"},{"s":"Some areas may be responsible for analyzing the timing of echoes, ( ______ ) others focus on the frequency content or the intensity of the sound.","ch":["while","during"],"a":0,"why":"뒤에 주어(others)와 동사(focus)가 있는 절이 오므로 접속사 while(~인 반면). during은 전치사라 명사만 뒤따른다.","tr":"어떤 구역들은 반사파들의 타이밍을 분석하는 것을 담당할지도 모르지만 한편으로는 다른 구역들은 소리의 주파수 성분 또는 강도에 초점을 맞춘다.","g":"while은 “~하는 동안, ~인 반면”을 뜻하는 접속사라 뒤에 문장이 와요. during 뒤에는 명사만 와요.\n예) Some like tea, while others like coffee. (차를 좋아하는 사람도 있고 커피를 좋아하는 사람도 있어.)"},{"s":"This specialization allows the dolphin's brain ( ______ ) echo information in parallel, rather than sequentially.","ch":["processing","to process"],"a":1,"why":"allow A to + 동사원형 구조 (A가 ~하는 것을 허락하다). allow는 목적격보어로 to부정사를 쓴다.","tr":"이러한 특화는 돌고래의 뇌가 반사파 정보를 순차적이기보다 병렬로 처리하게 해 준다.","g":"allow, enable, let처럼 “~하게 하다” 동사는 구조가 정해져 있어요. allow + 사람 + to + 동사원형이에요.\n예) My mom allows me to play. (엄마는 내가 노는 것을 허락해 줘.)"},{"s":"By ( ______ ) the work among specialized areas, the brain can process information much faster and more efficiently.","ch":["dividing","divide"],"a":0,"why":"전치사 by 뒤에는 동명사(-ing)가 온다. by + -ing = ~함으로써.","tr":"특화된 구역들 사이에서 업무를 분담함으로써, 뇌는 정보를 훨씬 더 빠르고 더 효율적으로 처리할 수 있다.","g":"전치사 by 뒤에는 동사원형이 아니라 동명사(-ing)를 써요. by -ing = ~함으로써예요.\n예) You can learn by doing. (해 봄으로써 배울 수 있어.)"}],"awk":[{"t":"Dolphins' brains have [[1|evolved]] specialized areas [[2|dedicated]] to echolocation, allowing them to process acoustic information [[3|more quickly]] and with [[4|more]] [[5|energy]].","a":4,"fix":"less","why":"원문은 “with less energy”(더 적은 에너지로). 특화의 장점은 효율이 좋아지는 것인데 more energy(더 많은 에너지)라 하면 모순.","sp":[{"b":"evolved","m":"진화시켰다","n":"have + 과거분사","y":"맞음. 뇌가 진화해 왔다.","e":"시간이 지나며 바뀐 것."},{"b":"dedicated","m":"전념하는","n":"dedicated to = ~에 쓰이는","y":"맞음. 반향 정위에 쓰이는 구역.","e":"한 가지에 쏟는 것."},{"b":"more quickly","m":"더 빠르게","n":"비교급 부사","y":"맞음. 더 빨리 처리한다.","e":"빠른 처리."},{"b":"more","m":"더 많은","n":"more energy","y":"어색함. 원문은 less. 특화되어 효율이 좋아졌다면 에너지는 더 적게 든다.","e":"전용 도구로 일하면 힘이 덜 듦."},{"b":"energy","m":"에너지","n":"명사","y":"맞음. 처리에 쓰는 에너지.","e":"힘."}]},{"t":"The signals from the ears are [[1|rapidly]] transmitted to the auditory cortex, the brain region responsible for [[2|processing]] sound. However, [[3|like]] many other mammals, dolphins have a highly specialized auditory cortex with [[4|distinct]] areas dedicated to processing different [[5|aspects]] of echolocation signals.","a":3,"fix":"unlike","why":"원문은 “unlike many other mammals”(다른 많은 포유류와 달리). However(그러나) 뒤에서 돌고래만의 특별함을 말하는데 like(~처럼)이면 모순.","sp":[{"b":"rapidly","m":"빠르게","n":"부사","y":"맞음. 신호가 빠르게 전달된다.","e":"빠른 전달."},{"b":"processing","m":"처리하는 것","n":"responsible for + -ing","y":"맞음. 소리를 처리하는 것을 담당.","e":"소리를 다루는 일."},{"b":"like","m":"~처럼","n":"전치사","y":"어색함. 원문은 unlike. However 뒤에는 앞과 대조되는 내용이 오는데, 다른 포유류와 같다고 하면 모순.","e":"다르다고 말하려는데 똑같다고 하는 꼴."},{"b":"distinct","m":"구별되는","n":"형용사","y":"맞음. 서로 구별되는 구역.","e":"따로 나뉜 칸."},{"b":"aspects","m":"측면","n":"복수명사","y":"맞음. 신호의 여러 측면.","e":"여러 면."}]},{"t":"Some areas may be [[1|responsible]] for analyzing the timing of echoes, while others [[2|ignore]] the [[3|frequency]] content or the [[4|intensity]] of the [[5|sound]].","a":2,"fix":"focus on","why":"원문은 “while others focus on the frequency content”(다른 구역은 주파수 성분에 초점을 맞춘다). ignore(무시하다)이면 ‘각 구역이 서로 다른 측면을 맡는다’는 특화의 설명과 모순.","sp":[{"b":"responsible","m":"담당하는","n":"be responsible for","y":"맞음. 타이밍 분석을 담당.","e":"맡은 일."},{"b":"ignore","m":"무시하다","n":"동사","y":"어색함. 원문은 focus on. 각 구역이 맡은 측면이 있다는 내용인데 무시한다고 하면 모순.","e":"맡은 일을 안 하는 구역."},{"b":"frequency","m":"주파수","n":"명사","y":"맞음. 소리의 높낮이를 정하는 성분.","e":"음의 높낮이."},{"b":"intensity","m":"강도","n":"명사","y":"맞음. 소리의 세기.","e":"소리의 크기."},{"b":"sound","m":"소리","n":"명사","y":"맞음. 처리하는 대상.","e":"귀로 듣는 것."}]},{"t":"This specialization allows the dolphin's brain to process echo information in [[1|parallel]], rather than [[2|simultaneously]]. Imagine a factory [[3|assembly]] line, where [[4|different]] workers are [[5|responsible]] for different tasks.","a":2,"fix":"sequentially","why":"원문은 “in parallel, rather than sequentially”(순차적이 아니라 병렬로). simultaneously(동시에)는 parallel과 같은 뜻이라 rather than으로 대조할 수 없어 모순.","sp":[{"b":"parallel","m":"병렬로","n":"in parallel","y":"맞음. 여러 구역이 동시에 처리하는 방식.","e":"여러 줄로 동시에."},{"b":"simultaneously","m":"동시에","n":"부사","y":"어색함. 원문은 sequentially. rather than 뒤에는 병렬의 반대인 순차적이 와야 한다.","e":"동시에 vs 동시에는 대조가 안 됨."},{"b":"assembly","m":"조립","n":"assembly line = 조립 라인","y":"맞음. 공장 조립 라인.","e":"차를 조립하는 줄."},{"b":"different","m":"서로 다른","n":"형용사","y":"맞음. 서로 다른 노동자.","e":"각자 다른 사람."},{"b":"responsible","m":"담당하는","n":"be responsible for","y":"맞음. 서로 다른 일을 맡는다.","e":"맡은 일."}]},{"t":"By [[1|dividing]] the work among specialized areas, the brain can process information much [[2|faster]] and more [[3|efficiently]]. This parallel processing [[4|increases]] the cognitive load associated with echolocation, allowing dolphins to react [[5|quickly]] to changes in their environment.","a":4,"fix":"reduces","why":"원문은 “reduces the cognitive load”(부담을 줄인다). increases(늘린다)이면 뒤의 ‘환경 변화에 빠르게 반응하게 해 준다’와 모순.","sp":[{"b":"dividing","m":"나누는 것","n":"by + -ing","y":"맞음. 업무를 나눈다.","e":"일을 나누기."},{"b":"faster","m":"더 빠르게","n":"비교급","y":"맞음. 훨씬 빨라짐.","e":"더 빠른 처리."},{"b":"efficiently","m":"효율적으로","n":"부사","y":"맞음. 낭비 없이 처리.","e":"적은 힘으로."},{"b":"increases","m":"늘리다","n":"동사","y":"어색함. 원문은 reduces. 부담이 늘면 빠르게 반응할 수 없다.","e":"짐이 무거우면 느려짐."},{"b":"quickly","m":"빠르게","n":"부사","y":"맞음. 빠르게 반응.","e":"재빠른 반응."}]}],"und":[{"q":"<u>allowing them to process acoustic information more quickly and with less energy</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["소리 정보를 느리지만 정확하게 처리하게 해 준다","소리 정보를 더 빠르게, 더 적은 에너지로 처리할 수 있게 해 준다","더 많은 에너지를 써서 소리를 크게 낼 수 있게 해 준다","소리 정보를 처리하지 않고 저장만 하게 해 준다","소리가 없는 곳에서도 에너지를 만들게 해 준다"],"a":1,"why":"allowing them to ~ = 그것들이 ~할 수 있게 해 준다.\nmore quickly (더 빠르게), less energy (더 적은 에너지) = 효율이 좋아졌다는 뜻.","e":"전용 가위로 자르면 빠르고 손도 덜 아픈 것.","tr":"돌고래들의 뇌는 반향 정위에 사용되는 특화된 구역들을 진화시켰고, 그것은 그것들이 음향 정보를 더 빠르게 그리고 더 적은 에너지로 처리하게 해 준다."},{"q":"<u>Some areas may be responsible for analyzing the timing of echoes, while others focus on the frequency content or the intensity of the sound.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["구역마다 반사파의 서로 다른 특성을 나눠 맡아 분석한다","모든 구역이 반사파의 타이밍만 똑같이 분석한다","반사파의 강도는 분석하지 않고 타이밍만 분석한다","구역이 하나뿐이라 모든 일을 혼자 처리한다","주파수와 강도는 사람의 귀가 분석해 준다"],"a":0,"why":"some ~ , while others … = 어떤 것은 ~, 다른 것은 …(대조).\n타이밍, 주파수 성분, 강도를 각각 다른 구역이 나눠 맡는다.","e":"한 팀은 박자, 한 팀은 음높이, 한 팀은 음량을 맡는 것.","tr":"어떤 구역들은 반사파들의 타이밍을 분석하는 것을 담당할지도 모르지만 한편으로는 다른 구역들은 소리의 주파수 성분 또는 강도에 초점을 맞춘다."},{"q":"<u>Imagine a factory assembly line, where different workers are responsible for different tasks.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["뇌의 구역들이 일을 나눠 맡아 함께 처리하는 모습을 공장 조립 라인에 비유한 것이다","돌고래가 공장에서 일하는 것처럼 반복 작업을 한다는 뜻이다","뇌가 한 가지 일만 천천히 하는 모습을 비유한 것이다","조립 라인은 한 사람이 모든 일을 하는 방식이다","돌고래가 공장 소리를 싫어한다는 뜻이다"],"a":0,"why":"공장 조립 라인에서는 사람마다 맡은 일이 달라서 동시에 일이 진행된다.\n뇌의 특화된 구역들이 병렬로 일하는 것과 같다는 비유.","e":"한 사람은 바퀴, 한 사람은 문을 맡아 차를 만드는 것.","tr":"공장 조립 라인을 상상해 보면, 그곳에서는 서로 다른 노동자들이 서로 다른 과업들을 담당한다."},{"q":"<u>This parallel processing reduces the cognitive load associated with echolocation, allowing dolphins to react quickly to changes in their environment.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["병렬 처리 때문에 뇌가 너무 바빠져 반응이 느려진다","돌고래는 환경 변화에 반응하지 않고 가만히 있는다","병렬 처리는 반향 정위를 못 하게 만든다","인지 부하가 늘어나서 정보를 더 많이 기억한다","일을 나눠 동시에 처리하니 뇌의 부담이 줄어 환경 변화에 빠르게 대응할 수 있다"],"a":4,"why":"reduces = 줄이다. cognitive load = 뇌의 부담.\nallowing ~ = 그래서 ~할 수 있게 해 준다.\n부담이 줄면 변화에 빠르게 반응할 수 있다는 흐름.","e":"숙제를 나눠 하면 덜 부담스럽고 빨리 끝나는 것.","tr":"이러한 병렬 처리는 반향 정위와 연관된 인지 부하를 줄이고, 돌고래들이 자신의 환경에서의 변화들에 빠르게 반응하게 해 준다."}]},"2610-41":{"voc":[{"q":"It is crucial to recognize that boredom can <u>give rise to</u> harmful emotions such as depression, despair, and irritation.","ask":"give rise to의 뜻으로 알맞은 것은?","ch":["~을 없애다","~을 숨기다","~을 따라가다","~을 놓치다","~을 일으키다, 생기게 하다"],"a":4,"why":"give rise to = ~을 일으키다, ~이 생기게 하다.\n무료함이 해로운 감정을 생기게 할 수 있다는 뜻.","e":"작은 불씨가 큰 불을 일으키는 것.","tr":"무료함이 적절하게 다뤄지지 않는다면 우울, 낙담, 그리고 짜증과 같은 해로운 감정들을 발생시킬 수 있다는 것을 인식하는 것은 중요하다.","alt":"cause, lead to, bring about"},{"q":"Boredom can give rise to harmful emotions such as depression, <u>despair</u>, and irritation.","ask":"despair의 뜻으로 알맞은 것은?","ch":["기쁨","호기심","자신감","절망, 낙담","감사"],"a":3,"why":"despair = 절망, 낙담.\n희망이 없다고 느끼는 마음.\n반의어는 hope (희망).","e":"시험 점수가 너무 낮아 아무것도 하기 싫은 마음.","tr":"무료함이 적절하게 다뤄지지 않는다면 우울, 낙담, 그리고 짜증과 같은 해로운 감정들을 발생시킬 수 있다는 것을 인식하는 것은 중요하다.","alt":"hopelessness ↔ hope"},{"q":"Boredom can give rise to harmful emotions if not <u>adequately</u> addressed.","ask":"adequately의 뜻으로 알맞은 것은?","ch":["우연히","빠르게","몰래","적절하게, 충분히","어색하게"],"a":3,"why":"adequately = 적절하게, 충분하게.\nadequate (충분한)의 부사형.\nnot adequately addressed = 제대로 다뤄지지 않으면.","e":"시험 범위를 충분히 공부했을 때 쓰는 말.","tr":"무료함이 적절하게 다뤄지지 않는다면 우울, 낙담, 그리고 짜증과 같은 해로운 감정들을 발생시킬 수 있다는 것을 인식하는 것은 중요하다.","alt":"properly, sufficiently"},{"q":"‘<u>Idle</u> time is the devil’s workshop’ implies that those with too much time on their hands may fill that time with troubling thoughts and behavior.","ask":"idle의 뜻으로 알맞은 것은?","ch":["바쁜","위험한","유명한","화가 난","아무것도 하지 않는, 한가한"],"a":4,"why":"idle = 하는 일이 없는, 한가한.\nidle time = 아무것도 안 하는 시간.\n반의어는 busy (바쁜).","e":"방학에 할 일 없이 누워 있는 시간.","tr":"‘아무것도 안 하는 시간은 악마의 작업장이다’라는 것은 자신의 손에 너무 많은 시간을 가진 사람들이 그 시간을 문제를 일으키는 생각들과 행동으로 채울 수 있다는 것을 암시한다고 일컬어진다.","alt":"inactive, unoccupied ↔ busy"},{"q":"Boredom is only an <u>indulgence</u> pastime in a safe zone.","ask":"indulgence의 뜻으로 알맞은 것은?","ch":["참음","의무","처벌","탐닉, 하고 싶은 대로 즐김","거절"],"a":3,"why":"indulgence = 탐닉, 마음껏 즐김.\n위험이 없는 안전한 곳에서나 누릴 수 있는 즐길 거리라는 뜻.","e":"주말에 마음껏 늦잠 자는 것.","tr":"무료함은 위험이 존재하는 곳에서는 존재하지 않는데, 왜냐하면 그것이 단지 안전지대 안에서의 탐닉 활동이기 때문이다.","alt":"pleasure, self-gratification"},{"q":"Boredom can be perceived as a <u>luxury</u> that typically manifests in safe and inactive situations.","ask":"luxury의 뜻으로 알맞은 것은?","ch":["필수품","사치, 여유 있어야 누리는 것","고통","빚","실수"],"a":1,"why":"luxury = 사치, 여유가 있어야 누릴 수 있는 것.\n무료함은 안전해야만 누릴 수 있는 사치라는 뜻.","e":"시험 걱정 없이 푹 쉬는 여유.","tr":"무료함은 안전하고 할 일이 없는 상황들에서 전형적으로 나타나는 사치로 인식될 수 있으며, 환경을 인식하고 이해할 기회를 제공한다.","alt":"extravagance, privilege"},{"q":"Boredom can be perceived as a luxury that typically <u>manifests</u> in safe and inactive situations.","ask":"manifests의 뜻으로 알맞은 것은?","ch":["사라지다","멈추다","숨다","나타나다, 드러나다","바뀌다"],"a":3,"why":"manifest = 나타나다, 분명히 드러나다.\n안전하고 할 일 없는 상황에서 무료함이 나타난다는 뜻.","e":"비가 그치자 무지개가 나타나는 것.","tr":"무료함은 안전하고 할 일이 없는 상황들에서 전형적으로 나타나는 사치로 인식될 수 있으며, 환경을 인식하고 이해할 기회를 제공한다.","alt":"appear, show up, emerge"},{"q":"In <u>hazardous</u> circumstances, the luxury of boredom is unavailable.","ask":"hazardous와 가까운 뜻은?","ch":["peaceful","ordinary","dangerous","private","valuable"],"a":2,"why":"hazardous = 위험한 (= dangerous).\nhazard = 위험 요소.\n위험한 상황에서는 무료함이라는 사치를 누릴 수 없다는 뜻.","e":"불이 난 건물 안 같은 곳.","tr":"위험한 상황들에서, 무료함이라는 사치는 손에 넣을 수 없다.","alt":"risky, perilous ↔ safe"},{"q":"Thus, it is <u>paramount</u> to utilize idle moments for profound self-reflection.","ask":"paramount와 가까운 뜻은?","ch":["extremely important","slightly useful","completely unknown","easily forgotten","rarely needed"],"a":0,"why":"paramount = 가장 중요한, 최고로 중요한 (= extremely important).\n아무것도 안 하는 순간을 자기 성찰에 쓰는 것이 가장 중요하다는 뜻.","e":"시험 전날 가장 먼저 해야 할 일.","tr":"따라서, 심오한 자기 성찰을 위해 아무것도 안 하는 순간들을 활용하는 것은 가장 중요하다.","alt":"supreme, essential, crucial"},{"q":"It should be regarded as an opportunity for personal development and constructive <u>contemplation</u>.","ask":"contemplation의 뜻으로 알맞은 것은?","ch":["논쟁","경쟁","깊은 생각, 사색","포기","낭비"],"a":2,"why":"contemplation = 깊이 생각하는 것, 사색.\n무료함을 개인적 발달과 건설적인 사색의 기회로 보라는 뜻.","e":"조용히 앉아 내 생각을 정리하는 시간.","tr":"무료함을 비생산적이라고 여기기보다, 그것은 개인적 발달과 건설적인 사유를 위한 기회로 여겨져야 한다.","alt":"deep thought, reflection"}],"find":[{"s":"무료함이 적절하게 다뤄지지 않으면 우울, 낙담, 짜증 같은 해로운 감정을 일으킬 수 있다.","a":true,"why":"1문장: 무료함이 제대로 다뤄지지 않으면 우울, 낙담, 짜증 같은 해로운 감정이 생길 수 있다.","e":"다루지 않으면 마음이 나빠질 수 있음."},{"s":"행복해지는 유일한 방법이 재미있는 활동을 찾는 것이라고 믿으면, 우리는 그 활동에서 벗어나 자유로워진다.","a":false,"why":"2문장: 그렇게 믿으면 그 활동에 의존하게 되고 부정적인 생각과 감정이 생긴다.\n“자유로워진다”는 불일치.","e":"재미에만 기대면 오히려 매이게 됨."},{"s":"‘Idle time is the devil’s workshop’은 시간이 너무 많은 사람이 그 시간을 문제를 일으키는 생각과 행동으로 채울 수 있다는 뜻이다.","a":true,"why":"3문장: 시간이 너무 많은 사람이 그 시간을 골치 아픈 생각과 행동으로 채울 수 있다는 것을 암시한다.","e":"할 일 없으면 쓸데없는 생각이 많아짐."},{"s":"균형을 잡는 방법은 무료한 시간을 낭비된 시간으로 여기는 것이다.","a":false,"why":"4문장: 무료한 시간을 낭비된 시간으로 보지 않고 자기 개선의 완벽한 시간으로 본다.\n“낭비된 시간으로 여긴다”는 불일치.","e":"낭비가 아니라 기회로 봄."},{"s":"무료한 시간은 자기 개선, 자기 발견, 긍정적인 성찰의 시간으로 볼 수 있다.","a":true,"why":"4문장: 자기 개선, 자기 발견, 긍정적 성찰 시간으로 볼 것을 제안한다.","e":"쉬는 시간을 나를 돌아보는 시간으로."},{"s":"글쓴이는 무료할 수 있다는 것을 불운한 일로 여겨야 한다고 말한다.","a":false,"why":"5문장: 우리가 무료할 수 있어서 정말 얼마나 운이 좋은가라고 말한다.\n“불운”은 불일치.","e":"무료할 수 있다는 건 안전하다는 뜻."},{"s":"무료함은 위험이 존재하는 곳에서는 존재하지 않는데, 안전지대에서의 탐닉 활동이기 때문이다.","a":true,"why":"6문장: 위험이 있는 곳에서는 무료함이 없고, 그것은 안전한 곳에서의 탐닉 활동이다.","e":"위험하면 지루할 틈도 없음."},{"s":"위험한 상황에서도 무료함이라는 사치를 쉽게 누릴 수 있다.","a":false,"why":"8문장: 위험한 상황에서는 무료함이라는 사치를 누릴 수 없다.\n“쉽게 누릴 수 있다”는 불일치.","e":"위험하면 여유가 없음."},{"s":"무료함은 안전하고 할 일이 없는 상황에서 전형적으로 나타나며, 환경을 이해할 기회를 준다.","a":true,"why":"7문장: 안전하고 활동이 없는 상황에서 나타나며 환경을 인식하고 이해할 기회를 제공한다.","e":"조용할 때 주변이 보임."},{"s":"따라서 아무것도 안 하는 순간은 최대한 빨리 다른 재미있는 활동으로 채우는 것이 가장 중요하다.","a":false,"why":"9문장: 아무것도 안 하는 순간을 심오한 자기 성찰에 활용하는 것이 가장 중요하다.\n“재미있는 활동으로 채운다”는 불일치.","e":"채우는 것이 아니라 성찰에 씀."},{"s":"무료한 시간은 표현하기 전에 경청하고, 관찰하고, 인식할 기회를 의미한다.","a":true,"why":"10문장: 표현하기 전에 경청하고, 관찰하고, 인식할 기회를 나타낸다.","e":"말하기 전에 듣고 보기."},{"s":"무료함은 비생산적이므로 개인적 발달과는 관계없는 시간으로 여겨져야 한다.","a":false,"why":"11문장: 무료함을 비생산적으로 보기보다 개인적 발달과 건설적 사색의 기회로 여겨야 한다.\n“관계없다”는 불일치.","e":"성장의 기회로 봄."},{"s":"무료함은 개인적 발달과 건설적인 사유를 위한 기회로 여겨져야 한다.","a":true,"why":"11문장: 개인적 발달과 건설적 사색의 기회로 여겨져야 한다.","e":"쉬는 시간도 성장에 쓸 수 있음."},{"s":"글에 따르면 무료함은 안전하지 않은 상황에서 더 자주 나타나는 감정이다.","a":false,"why":"6, 7문장: 무료함은 안전한 상황에서 나타나고, 위험한 상황에서는 누릴 수 없다.\n“안전하지 않은 상황”은 불일치.","e":"안전할 때 지루함도 생김."}],"eob":[{"s":"It is crucial to recognize ( ______ ) boredom can give rise to harmful emotions such as depression, despair, and irritation.","ch":["what","that"],"a":1,"why":"recognize의 목적어가 되는 완전한 문장(boredom can give rise to ...)이 뒤따르므로 접속사 that. what 뒤에는 명사가 빠진 불완전한 문장이 온다.","tr":"무료함이 적절하게 다뤄지지 않는다면 우울, 낙담, 그리고 짜증과 같은 해로운 감정들을 발생시킬 수 있다는 것을 인식하는 것은 중요하다.","g":"“~라는 것”으로 문장을 이끄는 that 뒤에는 완전한 문장이 와요. what 뒤에는 빠진 것이 있는 문장이 와요.\n예) I know that he is kind. (나는 그가 친절하다는 것을 알아.)"},{"s":"Boredom can give rise to harmful emotions if not adequately ( ______ ).","ch":["addressing","addressed"],"a":1,"why":"무료함이 ‘다뤄지는’ 것이므로 수동의 과거분사 addressed. if (it is) not adequately addressed에서 it is가 생략된 형태.","tr":"무료함이 적절하게 다뤄지지 않는다면 우울, 낙담, 그리고 짜증과 같은 해로운 감정들을 발생시킬 수 있다는 것을 인식하는 것은 중요하다.","g":"if, when 뒤에 ‘주어 + be’가 생략되고 과거분사만 남을 수 있어요. 주어가 ‘~되는’ 입장이면 과거분사예요.\n예) Keep it closed if not used. (사용하지 않으면 닫아 두세요.)"},{"s":"Then we become dependent ( ______ ) those activities, and negative thoughts and emotions arise.","ch":["of","on"],"a":1,"why":"dependent는 전치사 on과 함께 쓴다. be dependent on = ~에 의존하다.","tr":"우리가 행복해지는 유일한 방법이 재미있는 활동들을 찾는 것에 의해서만이라고 믿으면, 그때 우리는 그러한 활동들에 의존하게 되고, 부정적인 생각들과 감정들이 생긴다.","g":"dependent는 on과 짝이에요. depend on, be dependent on = ~에 의존하다.\n예) Kids are dependent on their parents. (아이들은 부모에게 의존해.)"},{"s":"Boredom can be perceived as a luxury that typically manifests in safe and inactive situations, ( ______ ) an occasion to appreciate and comprehend the environment.","ch":["provided","providing"],"a":1,"why":"앞 문장 전체를 받아 ‘~을 제공하면서’라는 뜻을 덧붙이는 분사구문이므로 providing. 이미 동사(can be perceived)가 있어 provided를 동사로 쓸 수 없다.","tr":"무료함은 안전하고 할 일이 없는 상황들에서 전형적으로 나타나는 사치로 인식될 수 있으며, 환경을 인식하고 이해할 기회를 제공한다.","g":"문장에 동사가 이미 있을 때 덧붙이는 설명은 -ing 분사구문으로 써요.\n예) She smiled, showing her teeth. (그녀는 이를 보이며 웃었어.)"},{"s":"In hazardous circumstances, the luxury of boredom ( ______ ) unavailable.","ch":["are","is"],"a":1,"why":"주어는 단수 the luxury이고 of boredom은 수식어구이므로 is.","tr":"위험한 상황들에서, 무료함이라는 사치는 손에 넣을 수 없다.","g":"주어 뒤에 of 전치사구가 와도 동사는 진짜 주어에 맞춰요. luxury가 단수라서 is예요.\n예) The color of the walls is white. (벽의 색은 하얀색이야.)"},{"s":"Rather than viewing boredom as unproductive, it should ( ______ ) regarded as an opportunity for personal development and constructive contemplation.","ch":["be","being"],"a":0,"why":"조동사 should 뒤에는 동사원형이 오고, 수동이므로 should be regarded.","tr":"무료함을 비생산적이라고 여기기보다, 그것은 개인적 발달과 건설적인 사유를 위한 기회로 여겨져야 한다.","g":"should, can, will 같은 조동사 뒤에는 동사원형을 써요. 수동이면 be + 과거분사예요.\n예) It should be done today. (그것은 오늘 되어야 해.)"}],"awk":[{"t":"It is [[1|crucial]] to recognize that boredom can give rise to [[2|pleasant]] emotions such as [[3|depression]], despair, and irritation if not [[4|adequately]] [[5|addressed]].","a":2,"fix":"harmful","why":"원문은 “harmful emotions”(해로운 감정). 뒤에 나오는 depression, despair, irritation은 모두 나쁜 감정이라 pleasant(즐거운)이면 모순.","sp":[{"b":"crucial","m":"중요한","n":"형용사","y":"맞음. 인식하는 것이 중요하다.","e":"꼭 필요한."},{"b":"pleasant","m":"즐거운","n":"형용사","y":"어색함. 원문은 harmful. 뒤의 예시가 우울, 낙담, 짜증이라 즐거운 감정일 수 없다.","e":"우울이 즐거울 수는 없음."},{"b":"depression","m":"우울","n":"명사","y":"맞음. 해로운 감정의 예.","e":"기운 없는 마음."},{"b":"adequately","m":"적절하게","n":"부사","y":"맞음. 제대로 다뤄지지 않으면이라는 뜻.","e":"충분히 잘."},{"b":"addressed","m":"다뤄진","n":"과거분사","y":"맞음. 무료함이 다뤄지는 것.","e":"해결하려고 신경 씀."}]},{"t":"When we [[1|believe]] that the [[2|only]] way to be happy is by searching for fun activities, then we become [[3|dependent]] on those activities, and [[4|positive]] thoughts and emotions [[5|arise]].","a":4,"fix":"negative","why":"원문은 “negative thoughts and emotions arise”(부정적인 생각과 감정이 생긴다). 재미에만 의존하는 문제점을 말하는 흐름이라 positive이면 모순.","sp":[{"b":"believe","m":"믿다","n":"동사","y":"맞음. 유일한 방법이라고 믿는 것.","e":"그렇다고 생각함."},{"b":"only","m":"유일한","n":"형용사","y":"맞음. 한 가지뿐이라는 뜻.","e":"단 하나."},{"b":"dependent","m":"의존하는","n":"be dependent on","y":"맞음. 활동에 기대게 된다.","e":"기대는 상태."},{"b":"positive","m":"긍정적인","n":"형용사","y":"어색함. 원문은 negative. 재미에 매달리는 것의 문제를 말하는 문장이다.","e":"문제를 말하는데 좋은 일이 생긴다고 하면 모순."},{"b":"arise","m":"생기다","n":"동사","y":"맞음. 생각과 감정이 생겨남.","e":"떠오름."}]},{"t":"The [[1|balance]] is to [[2|not]] see it as idle time, wasted time, or boredom but rather as a [[3|terrible]] time for [[4|self-improvement]], self-identification, and [[5|positive]] reflection time.","a":3,"fix":"perfect","why":"원문은 “a perfect time for self-improvement”(자기 개선을 위한 완벽한 시간). not A but rather B 구조에서 B는 긍정적이어야 하므로 terrible(끔찍한)이면 모순.","sp":[{"b":"balance","m":"균형점","n":"명사","y":"맞음. 균형을 잡는 방법.","e":"한쪽으로 기울지 않기."},{"b":"not","m":"~하지 않다","n":"부정어","y":"맞음. 낭비된 시간으로 보지 않는다.","e":"부정."},{"b":"terrible","m":"끔찍한","n":"형용사","y":"어색함. 원문은 perfect. but rather 뒤에는 긍정적인 관점이 와야 하고 self-improvement와도 어울리지 않는다.","e":"끔찍한 시간이 자기 개선일 수는 없음."},{"b":"self-improvement","m":"자기 개선","n":"명사","y":"맞음. 스스로를 나아지게 함.","e":"나를 키우기."},{"b":"positive","m":"긍정적인","n":"형용사","y":"맞음. 긍정적인 성찰 시간.","e":"좋은 쪽으로 돌아봄."}]},{"t":"Boredom [[1|doesn’t]] exist in the [[2|presence]] of [[3|danger]], as it is only an [[4|indulgence]] pastime in a [[5|dangerous]] zone.","a":5,"fix":"safe","why":"원문은 “a safe zone”(안전지대). 앞에서 위험이 있는 곳에는 무료함이 없다고 했으므로, 무료함이 위험한 곳의 활동이라고 하면 모순.","sp":[{"b":"doesn’t","m":"~하지 않는다","n":"부정","y":"맞음. 위험한 곳에는 무료함이 없다.","e":"없다."},{"b":"presence","m":"존재, 있음","n":"명사","y":"맞음. 위험이 있는 상황.","e":"있는 상태."},{"b":"danger","m":"위험","n":"명사","y":"맞음. 위험이 있는 곳.","e":"위험한 곳."},{"b":"indulgence","m":"탐닉","n":"명사","y":"맞음. 즐기는 활동이라는 뜻.","e":"마음껏 즐김."},{"b":"dangerous","m":"위험한","n":"형용사","y":"어색함. 원문은 safe. 위험한 곳에서는 무료함이 없다고 했으므로 모순.","e":"앞 문장과 정반대."}]},{"t":"In [[1|hazardous]] circumstances, the [[2|luxury]] of boredom is [[3|available]]. Thus, it is [[4|paramount]] to [[5|utilize]] idle moments for profound self-reflection.","a":3,"fix":"unavailable","why":"원문은 “the luxury of boredom is unavailable”(무료함이라는 사치는 누릴 수 없다). hazardous(위험한) 상황에서는 여유가 없으므로 available(누릴 수 있는)이면 모순.","sp":[{"b":"hazardous","m":"위험한","n":"형용사","y":"맞음. 위험한 상황.","e":"위험이 있는 곳."},{"b":"luxury","m":"사치","n":"명사","y":"맞음. 무료함은 여유 있어야 누리는 것.","e":"여유."},{"b":"available","m":"이용할 수 있는","n":"형용사","y":"어색함. 원문은 unavailable. 위험한 상황에서는 무료함을 누릴 수 없다.","e":"위험한데 여유가 있다는 모순."},{"b":"paramount","m":"가장 중요한","n":"형용사","y":"맞음. 매우 중요하다.","e":"최고로 중요."},{"b":"utilize","m":"활용하다","n":"동사","y":"맞음. 아무것도 안 하는 순간을 활용한다.","e":"잘 쓴다."}]},{"t":"Rather than viewing boredom as [[1|productive]], it should be [[2|regarded]] as an [[3|opportunity]] for personal [[4|development]] and [[5|constructive]] contemplation.","a":1,"fix":"unproductive","why":"원문은 “Rather than viewing boredom as unproductive”(무료함을 비생산적이라고 보기보다). rather than 뒤는 버려야 할 관점이고, 뒤의 기회로 보라는 흐름과 대조되므로 productive이면 모순.","sp":[{"b":"productive","m":"생산적인","n":"형용사","y":"어색함. 원문은 unproductive. 무료함을 생산적이라고 보는 것이 아니라 비생산적이라 보는 시각을 버리라는 흐름이다.","e":"버려야 할 생각이 ‘비생산적’."},{"b":"regarded","m":"여겨지다","n":"regard A as B","y":"맞음. 기회로 여겨져야 한다.","e":"~로 봄."},{"b":"opportunity","m":"기회","n":"명사","y":"맞음. 발달의 기회.","e":"찬스."},{"b":"development","m":"발달","n":"명사","y":"맞음. 개인적 성장.","e":"커 나감."},{"b":"constructive","m":"건설적인","n":"형용사","y":"맞음. 도움이 되는 사색.","e":"쓸모 있는."}]}],"und":[{"q":"<u>‘Idle time is the devil’s workshop’ implies that those with too much time on their hands may fill that time with troubling thoughts and behavior.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["악마를 만나려면 작업장에 가야 한다","시간이 많으면 훌륭한 작업을 할 수 있다","쉬는 시간은 반드시 운동으로 채워야 한다","할 일이 없는 시간이 많으면 나쁜 생각과 행동으로 시간을 채우기 쉽다","악마는 한가한 사람을 도와준다"],"a":3,"why":"idle time = 아무것도 안 하는 시간.\n시간이 너무 많은 사람은 골치 아픈 생각과 행동으로 시간을 채울 수 있다는 속담의 뜻.","e":"할 일이 없으면 괜히 사고를 치는 것.","tr":"‘아무것도 안 하는 시간은 악마의 작업장이다’라는 것은 자신의 손에 너무 많은 시간을 가진 사람들이 그 시간을 문제를 일으키는 생각들과 행동으로 채울 수 있다는 것을 암시한다고 일컬어진다."},{"q":"<u>The balance is to not see it as idle time, wasted time, or boredom but rather as a perfect time for self-improvement, self-identification, and positive reflection time.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["한가한 시간을 낭비로 보지 않고 자신을 키우고 돌아보는 기회로 보는 것이 균형이다","한가한 시간에는 아무 생각도 하지 않아야 한다","낭비된 시간은 다시 되돌릴 수 있다","자기 개선은 바쁠 때만 할 수 있다","무료함을 느끼면 즉시 재미있는 활동을 찾아야 한다"],"a":0,"why":"not A but rather B = A가 아니라 오히려 B.\n한가한 시간을 낭비가 아닌 자기 개선과 성찰의 완벽한 시간으로 본다는 뜻.","e":"쉬는 시간을 나를 키우는 시간으로 쓰는 것.","tr":"균형점은 그것을 아무것도 안 하는 시간, 낭비된 시간, 또는 무료함으로 보는 것이 아니라, 오히려 자기 개선, 자기 발견, 그리고 긍정적인 성찰 시간을 위한 완벽한시간으로 보는 것이다."},{"q":"<u>Reflecting, just how lucky are we to be bored?</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["무료한 사람은 모두 운이 나쁘다","무료함은 아무 의미가 없는 감정이다","운이 좋은 사람만 무료함을 느낄 수 없다","무료함을 느끼는 것은 위험하다는 신호이다","무료할 수 있다는 것은 그만큼 안전하다는 뜻이므로 매우 운이 좋은 일이다"],"a":4,"why":"Reflecting = 곰곰이 생각해 보면.\n무료함은 안전한 곳에서만 나타나므로, 무료할 수 있다는 것 자체가 행운이라는 수사적 질문.","e":"지루하다고 투덜대지만 사실은 평화롭다는 증거.","tr":"곰곰이 생각해 보면 우리가 무료할 수 있어서 정말 얼마나 행운인가?"},{"q":"<u>Boredom can be perceived as a luxury that typically manifests in safe and inactive situations, providing an occasion to appreciate and comprehend the environment.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["무료함은 위험할 때 더 자주 나타나는 감정이다","무료함은 안전하고 한가한 상황에서 누리는 여유이며 주변을 이해할 기회가 된다","무료함은 돈이 많은 사람만 느끼는 감정이다","무료함은 환경을 이해하는 것을 방해한다","무료함은 항상 활동적인 상황에서 생긴다"],"a":1,"why":"luxury = 여유가 있어야 누리는 것.\nmanifests in safe and inactive situations = 안전하고 활동이 없을 때 나타난다.\nproviding ~ = 그리고 ~할 기회를 준다.","e":"조용한 공원 벤치에서 주변을 둘러보는 시간.","tr":"무료함은 안전하고 할 일이 없는 상황들에서 전형적으로 나타나는 사치로 인식될 수 있으며, 환경을 인식하고 이해할 기회를 제공한다."},{"q":"<u>It represents an occasion to listen, observe, and appreciate before expressing.</u>","ask":"밑줄 친 부분이 글에서 의미하는 바로 가장 알맞은 것은?","ch":["무료한 시간에는 자기 의견을 바로 말해야 한다","무료한 시간은 말을 많이 하게 만든다","무료한 시간은 말하기 전에 듣고 관찰하며 이해할 기회가 된다","무료한 시간에는 아무것도 들을 수 없다","무료한 시간은 남의 말을 무시하는 시간이다"],"a":2,"why":"It = 무료한 순간(idle moments).\nbefore expressing = 표현하기 전에.\n듣고, 관찰하고, 인식하는 것이 먼저라는 뜻.","e":"말하기 전에 먼저 귀 기울이는 것.","tr":"그것은 표현하기 전에 경청하고, 관찰하고, 그리고 인식할 기회를 의미한다."}]}});
